lesson('5.1', ('El hit', 'The hit', '安打', 'ヒット'), ('Entender qué es un hit: un batazo bueno con el que el bateador llega a salvo a una base sin que la defensa haya fallado.', 'Understand what a hit is: a good batted ball that gets the batter safely to a base without the defense making a mistake.', '明白什么是安打：击出好球，在防守没有失误的情况下，击球员安全上垒。', 'ヒットとは何かを知ろう：守備のミスなしに、打ったバッターが安全に塁に着く、いい打球のこと。'), [('¡Llegó el momento de batear de verdad!', "It's time to really hit!", '真正击球的时候到了！', 'いよいよ本当に打つ時間だ！'), ('Cuando le pegas a la bola y llegas a salvo a una base, sin que la defensa haya fallado, eso es un hit.', "When you hit the ball and get safely to a base, without the defense making a mistake, that's a hit.", '你击中球，在防守没有失误的情况下安全上垒，这就是安打，英语叫 hit。', 'ボールを打って、守備のミスなしに安全に塁に着いたら、それがヒット。英語でも hit。'), ('La bola puede pasar por el suelo, entre los defensores, o caer en los jardines donde nadie la atrapa.', 'The ball can roll on the ground between the fielders, or land in the outfield where nobody catches it.', '球可以从地上穿过防守球员之间，也可以落在外野没人接到的地方。', 'ボールは守備の選手のあいだを地面で抜けても、だれもとれない外野に落ちてもいいよ。'), ('Si llegas a salvo, ¡tu batazo valió!', 'If you get there safely, your hit counts!', '只要你安全上垒，这一击就算数！', '安全に着いたら、その打球は成功だ！'), ('Y recuerda: tu base es tu lugar seguro, en inglés safe: parado sobre ella, nadie te puede hacer out.', "And remember: while you're standing on your base, you're safe. Nobody can get you out.", '还要记住：垒包是你的安全区，英语叫 safe：站在上面，谁也不能让你出局。', 'それから、塁は君の安全地帯。英語で safe（セーフ）。塁の上に立っていれば、だれもアウトにできないよ。')], {'1': act(('¿Qué es un hit?', 'What is a hit?', '什么是安打？', 'ヒットって何？'), ('¡Eso es! Hit.', "That's it! A hit.", '对了！安打。', 'そのとおり！ヒット。'), ('Un hit es cuando llegas a salvo con tu batazo.', 'A hit is when you hit the ball and reach base safely.', '安打就是你击球后安全上垒。', 'ヒットは、打って安全に塁に着くことだよ。'), opts={'a': ('Un batazo bueno con el que llegas a salvo', 'A batted ball that gets you on base safely', '击出好球，让你安全上垒', '安全に塁に着ける、いい打球'), 'b': ('Un batazo que atrapan en el aire', 'A batted ball that is caught in the air', '在空中被接住的击球', '空中でとられた打球'), 'c': ('Un lanzamiento malo', 'A bad pitch', '一个坏的投球', '悪い投球')}), '2': act(('Para que sea hit, la bola tiene que salir del campo', 'For it to be a hit, the ball has to leave the field', '要算安打，球必须飞出球场', 'ヒットになるには、ボールがグラウンドの外に出ないといけない'), ('¡Bien! Un hit puede ser cortito.', 'Good! A hit can be a short one.', '很好！安打也可以很短。', 'いいね！短いヒットもあるよ。'), ('Falso: basta con llegar a salvo.', 'False: you just need to reach base safely.', '错：只要安全上垒就行。', 'まちがい：安全に塁に着けばいいんだ。')), '3': act(('¿Cuál imagen muestra un hit?', 'Which picture shows a hit?', '哪张图是安打？', 'ヒットはどの絵？'), ('¡Correcto! Cayó donde nadie la atrapó.', 'Correct! It landed where nobody caught it.', '正确！球落在没人接到的地方。', '正解！だれもとれないところに落ちたね。'), ('Si la atrapan en el aire, es out, no hit.', "If it's caught in the air, it's an out, not a hit.", '如果在空中被接住，就是出局，不是安打。', '空中でとられたら、ヒットじゃなくてアウトだよ。'), opts={'a': ('La bola cae en los jardines y el bateador llega a primera', 'The ball lands in the outfield and the batter reaches first', '球落在外野，击球员跑上一垒', 'ボールが外野に落ちて、バッターが一塁に着く'), 'b': ('La bola es atrapada en el aire', 'The ball is caught in the air', '球在空中被接住', 'ボールを空中でとられる'), 'c': ('El bateador abanica y falla', 'The batter swings and misses', '击球员挥棒落空', 'バッターが空ぶりする')}), '4': act(('Llegaste a primera antes que el tiro. ¿Qué canta el umpire?', 'You reached first before the throw. What does the umpire call?', '你比传球先到一垒。裁判会判什么？', '送球より先に一塁に着いた。審判は何とコールする？'), ('¡Safe! Llegaste a salvo.', 'Safe! You got there safely.', '安全上垒！你安全到了。', 'セーフ！安全に着いたね。'), ('Safe significa a salvo: llegaste primero.', 'Safe means you made it: you got there first.', 'safe 就是安全：你先到了。', 'セーフは「安全」という意味。君が先に着いたんだ。'), opts={'a': ('¡Safe!', 'Safe!', '安全上垒！', 'セーフ！'), 'b': ('¡Out!', 'Out!', '出局！', 'アウト！'), 'c': ('¡Strike!', 'Strike!', '好球！', 'ストライク！')}), '5': act(('Bateaste un hit cortito. Toca la primera base a la que llegas', 'You hit a short one. Tap the base you reach first', '你打出一个短安打。点一下你最先到达的垒', '短いヒットを打った。最初に着く塁をタッチしよう'), ('¡Bien! Tu lugar seguro.', "Good! That's your safe spot.", '很好！那是你的安全区。', 'いいね！君の安全地帯。'), ('Todo hit empieza llegando a primera.', 'Every hit starts by reaching first.', '每个安打都从跑上一垒开始。', 'どのヒットも、まず一塁に着くことから始まるよ。'), answer=('Primera base', 'First base', '一垒', '一塁')), '6': act(('¿Cómo se dice «a salvo» en inglés?', "You reach the base before the ball. What's the word for that?", '“安全上垒”的英语怎么说？', '「安全」は英語で何という？'), ('¡Eso es! Safe.', "That's it! Safe.", '对了！Safe。', 'そのとおり！Safe。'), ('A salvo se dice safe.', "When you make it before the ball, you're safe.", '“安全”就是 safe。', '「安全」は safe だよ。'), opts={'a': ('Safe', 'Safe', 'Safe', 'Safe'), 'b': ('Out', 'Out', 'Out', 'Out'), 'c': ('Foul', 'Foul', 'Foul', 'Foul')})})
