lesson('5.2', ('Sencillo, doble y triple', 'Single, double and triple', '一垒安打、二垒安打和三垒安打', 'シングル、ツーベース、スリーベース'), ('Nombrar cada hit por las bases que vale: sencillo una, doble dos y triple tres, y frenar en la base correcta mirando la bola y al coach.', 'Name each hit by the bases it is worth: a single is one, a double two and a triple three, and stop at the right base by watching the ball and the coach.', '按照安打能跑几个垒来叫它的名字：一垒安打是一个垒，二垒安打两个，三垒安打三个；并且看着球和教练，在正确的垒停下。', 'ヒットの名前は進める塁の数で決まる：シングルヒットは1つ、ツーベースヒットは2つ、スリーベースヒットは3つ。ボールとコーチを見て、正しい塁で止まろう。'), [('Un hit se nombra según la base a la que llegas.', 'A hit is named by the bases you reach.', '安打的名字看你跑到哪个垒。', 'ヒットの名前は、着いた塁で決まるよ。'), ('Si llegas a primera: sencillo, en inglés single.', "If you reach first: it's a single.", '跑到一垒：一垒安打，英语叫 single。', '一塁まで行けたら：シングルヒット、英語で single。'), ('Si la bola llega lejos y llegas a segunda: doble, double.', "If the ball goes far and you reach second: it's a double.", '球飞得远，你跑到二垒：二垒安打，英语叫 double。', 'ボールが遠くまで飛んで二塁まで行けたら：ツーベースヒット、double。'), ('Y si corres, corres y llegas a tercera: ¡triple!', 'And if you run and run and reach third: a triple!', '如果你一直跑、一直跑，跑到了三垒：三垒安打，英语叫 triple！', 'そして走って走って三塁まで行けたら：スリーベースヒット、triple！'), ('El triple es el más difícil: hay que batear lejos y correr como el viento.', 'The triple is the hardest: you have to hit it far and run like the wind.', '三垒安打最难：要打得远，还要跑得像风一样快。', 'スリーベースヒットがいちばんむずかしい：遠くに打って、風のように走らないといけない。'), ('¿Sigues o te frenas? Mira la bola y escucha a tu coach: él ve todo el campo.', 'Keep going or stop? Watch the ball and listen to your coach: they can see the whole field.', '继续跑还是停下？看着球，听教练的：他能看到整个球场。', '走り続ける？止まる？ボールを見て、コーチの声を聞こう。コーチはグラウンドぜんぶが見えているよ。')], {'1': act(('Llegaste a primera con tu hit. ¿Qué bateaste?', 'You reached first with your hit. What did you hit?', '你靠安打跑到了一垒。你打出的是什么？', 'ヒットで一塁に着いた。何を打った？'), ('¡Eso es! Single.', "That's it! Single.", '对了！Single。', 'そのとおり！シングル。'), ('Una base: sencillo.', 'One base: a single.', '一个垒：一垒安打。', '1つの塁：シングルヒット。'), opts={'a': ('Un sencillo (single)', 'A single', '一垒安打 (single)', 'シングルヒット (single)'), 'b': ('Un triple', 'A triple', '三垒安打', 'スリーベースヒット'), 'c': ('Un jonrón', 'A home run', '本垒打', 'ホームラン')}), '2': act(('La bola cayó lejos en los jardines y llegaste a segunda. ¿Qué es?', 'The ball went far into the outfield and you reached second. What is it?', '球打到外野很远的地方，你跑到了二垒。这是什么？', 'ボールが外野の遠くまで飛んで、二塁まで行けた。これは何？'), ('¡Correcto! Double.', 'Correct! Double.', '正确！Double。', '正解！ツーベース。'), ('Dos bases: doble.', 'Two bases: a double.', '两个垒：二垒安打。', '2つの塁：ツーベースヒット。'), opts={'a': ('Un doble (double)', 'A double', '二垒安打 (double)', 'ツーベースヒット (double)'), 'b': ('Un sencillo', 'A single', '一垒安打', 'シングルヒット'), 'c': ('Un foul', 'A foul', '界外球', 'ファウル')}), '3': act(('Bateaste muy lejos y corriste hasta tercera. ¿Qué es?', 'You hit it really far and ran all the way to third. What is it?', '你打得很远，一直跑到了三垒。这是什么？', 'とても遠くに打って、三塁まで走った。これは何？'), ('¡Triple! El más emocionante.', 'Triple! The most exciting one.', '三垒安打！最刺激的一种。', 'スリーベース！いちばんワクワクするね。'), ('Tres bases: triple.', 'Three bases: a triple.', '三个垒：三垒安打。', '3つの塁：スリーベースヒット。'), opts={'a': ('Un triple', 'A triple', '三垒安打', 'スリーベースヒット'), 'b': ('Un sencillo', 'A single', '一垒安打', 'シングルヒット'), 'c': ('Un out', 'An out', '出局', 'アウト')}), '4': act(('Arrastra cada batazo a su base: sencillo, doble, triple', 'Drag each hit to its base: single, double, triple', '把每种安打拖到它的垒：一垒安打、二垒安打、三垒安打', 'それぞれのヒットを塁までドラッグしよう：シングル、ツーベース、スリーベース'), ('¡Perfecto! Una, dos y tres.', 'Perfect! One, two and three.', '完美！一、二、三。', 'パーフェクト！1つ、2つ、3つ。'), ('Cuenta las bases: 1 sencillo, 2 doble, 3 triple.', 'Count the bases: 1 single, 2 double, 3 triple.', '数一数垒：1 是一垒安打，2 是二垒安打，3 是三垒安打。', '塁を数えよう：1はシングル、2はツーベース、3はスリーベース。'), opts={'single': ('Sencillo', 'Single', '一垒安打', 'シングル'), 'double': ('Doble', 'Double', '二垒安打', 'ツーベース'), 'triple': ('Triple', 'Triple', '三垒安打', 'スリーベース'), 'first': ('first', 'first', 'first', 'first'), 'second': ('second', 'second', 'second', 'second'), 'third': ('third', 'third', 'third', 'third')}, answer=('Sencillo a primera, doble a segunda, triple a tercera', 'Single to first, double to second, triple to third', '一垒安打到一垒，二垒安打到二垒，三垒安打到三垒', 'シングルは一塁、ツーベースは二塁、スリーベースは三塁')), '5': act(('El triple es el hit más fácil de lograr', 'The triple is the easiest hit to get', '三垒安打是最容易打出的安打', 'スリーベースヒットはいちばんかんたんなヒット'), ('¡Bien! Es el más difícil.', "Good! It's the hardest.", '很好！它是最难的。', 'いいね！いちばんむずかしいんだ。'), ('Falso: el triple exige batear lejos y correr mucho.', 'False: a triple takes a long hit and a lot of running.', '错：三垒安打要打得远，还要跑很多。', 'まちがい：遠くに打って、たくさん走らないといけないよ。')), '6': act(('Vas corriendo hacia segunda y no sabes si seguir. ¿A quién miras?', "You're running to second and don't know whether to keep going. Who do you look at?", '你正跑向二垒，不知道要不要继续跑。你看谁？', '二塁に向かって走っていて、まだ走るか迷っている。だれを見る？'), ('¡Eso es! Ellos te guían.', "That's it! They guide you.", '对了！他们会指引你。', 'そのとおり！それが君を導くよ。'), ('Mira la bola y escucha al coach.', 'Watch the ball and listen to the coach.', '看着球，听教练的。', 'ボールを見て、コーチの声を聞こう。'), opts={'a': ('Al coach y a la bola', 'The coach and the ball', '教练和球', 'コーチとボール'), 'b': ('Al público', 'The crowd', '观众', 'お客さん'), 'c': ('A tus zapatos', 'Your shoes', '你的鞋子', '自分のくつ')})})
map_titles['5.2'] = ('Sencillo, doble y triple', 'Single, double and triple', '一垒安打、二垒安打和三垒安打', 'シングル、ツーベース、スリーベース')
lesson('5.3', ('El jonrón y el doble por regla', 'The home run and the ground rule double', '本垒打和场规二垒安打', 'ホームランとグラウンドルールダブル'), ('Entender el jonrón (la bola sale del campo en el aire por territorio fair: vuelta completa) y el doble por regla: si la bola pica en territorio fair y luego sale del campo, son dos bases para todos, no jonrón.', 'Understand the home run (the ball leaves the field in the air over fair territory: a full trip around) and the ground rule double: if a fair ball bounces and then leaves the field, everyone gets two bases, not a home run.', '明白本垒打（球在界内从空中飞出球场：跑完一整圈）和场规二垒安打：界内球先落地再弹出球场，所有人进两个垒，不是本垒打。', 'ホームラン（フェアのボールが空中でグラウンドの外に出る：ダイヤモンドを1周）と、グラウンドルールダブル（フェアのボールがはずんでから外に出たら、ホームランではなく全員2つ進む）を知ろう。'), [('El batazo más famoso: el jonrón, en inglés home run.', 'The most famous hit: the home run.', '最有名的击球：本垒打，英语叫 home run。', 'いちばん有名な打球：ホームラン、英語で home run。'), ('La bola sale volando del campo, por territorio fair, sin tocar el suelo: das la vuelta completa y anotas.', 'The ball flies out of the field, in fair territory, without touching the ground: you go all the way around and score.', '球在界内飞出球场，没有碰到地面：你跑完一整圈，得一分。', 'ボールがフェアゾーンで、地面にさわらずにグラウンドの外へ飛んでいく：1周走って得点だ。'), ('Pero ojo con su primo: si la bola pica en territorio fair y DESPUÉS salta fuera, no es jonrón.', 'But watch out for its cousin: if the ball bounces in fair territory and THEN goes over the fence, it is not a home run.', '但要小心它的“表亲”：如果球先在界内落地，然后才弹出去，就不是本垒打。', 'でも、そのいとこに気をつけて：ボールがフェアゾーンではずんで、そのあとで外に出たら、ホームランじゃない。'), ('Es un doble por regla, en inglés ground rule double: el bateador va a segunda y cada corredor avanza dos bases.', "It's a ground rule double: the batter goes to second and every runner moves up two bases.", '这是场规二垒安打，英语叫 ground rule double：击球员上二垒，每个跑垒员都进两个垒。', 'それはグラウンドルールダブル（認定二塁打）。英語で ground rule double：バッターは二塁へ、ランナーはみんな2つ進むよ。'), ('¿Salió en el aire? Jonrón. ¿Picó primero? Doble por regla.', 'Did it go out in the air? Home run. Did it bounce first? Ground rule double.', '在空中飞出去的？本垒打。先落地了？场规二垒安打。', '空中で出た？ホームラン。先にはずんだ？グラウンドルールダブル。')], {'1': act(('La bola sale del campo en el aire, por territorio fair. ¿Qué es?', 'The ball leaves the field in the air, in fair territory. What is it?', '球在界内从空中飞出球场。这是什么？', 'フェアのボールが空中でグラウンドの外に出た。これは何？'), ('¡Jonrón! Vuelta completa.', 'Home run! All the way around.', '本垒打！跑一整圈。', 'ホームラン！1周しよう。'), ('En el aire y fuera: jonrón.', 'In the air and out: a home run.', '在空中飞出去：本垒打。', '空中で外へ：ホームラン。'), opts={'a': ('Un jonrón (home run)', 'A home run', '本垒打 (home run)', 'ホームラン (home run)'), 'b': ('Un doble por regla', 'A ground rule double', '场规二垒安打', 'グラウンドルールダブル'), 'c': ('Un foul', 'A foul', '界外球', 'ファウル')}), '2': act(('La bola pica en el jardín y salta la valla. ¿Qué es?', 'The ball bounces in the outfield and goes over the fence. What is it?', '球在外野落地后弹过了围墙。这是什么？', 'ボールが外野ではずんで、フェンスをこえた。これは何？'), ('¡Eso es! Picó primero: dos bases.', "That's it! It bounced first: two bases.", '对了！先落地了：两个垒。', 'そのとおり！先にはずんだ：2つの塁。'), ('Si pica y sale, es doble por regla, no jonrón.', "If it bounces and goes out, it's a ground rule double, not a home run.", '先落地再出去，就是场规二垒安打，不是本垒打。', 'はずんでから出たら、ホームランじゃなくてグラウンドルールダブルだよ。'), opts={'a': ('Un doble por regla (ground rule double)', 'A ground rule double', '场规二垒安打 (ground rule double)', 'グラウンドルールダブル (ground rule double)'), 'b': ('Un jonrón', 'A home run', '本垒打', 'ホームラン'), 'c': ('Un triple', 'A triple', '三垒安打', 'スリーベースヒット')}), '3': act(('Con un doble por regla, el bateador anota carrera', 'On a ground rule double, the batter scores a run', '场规二垒安打时，击球员得一分', 'グラウンドルールダブルで、バッターは得点する'), ('¡Bien! Va a segunda, no anota.', "Good! They go to second, they don't score.", '很好！他上二垒，不得分。', 'いいね！二塁まで行くだけで、得点しない。'), ('Falso: con el doble por regla llega a segunda.', 'False: on a ground rule double they reach second.', '错：场规二垒安打只到二垒。', 'まちがい：グラウンドルールダブルでは二塁まで。')), '4': act(('La bola picó y salió del campo. ¿Cuántas bases da el umpire?', 'The ball bounced and left the field. How many bases does the umpire give?', '球落地后出了球场。裁判给几个垒？', 'ボールがはずんでグラウンドの外に出た。審判はいくつ塁をあたえる？'), ('¡Dos bases! Doble por regla.', 'Two bases! Ground rule double.', '两个垒！场规二垒安打。', '2つ！グラウンドルールダブル。'), ('Picó y salió: dos bases para todos.', 'It bounced and went out: two bases for everyone.', '落地后出去：每个人两个垒。', 'はずんで外へ：全員2つの塁。'), opts={'a': ('Dos bases', 'Two bases', '两个垒', '2つの塁'), 'b': ('La vuelta completa', 'All the way around', '跑一整圈', '1周ぜんぶ'), 'c': ('Una base', 'One base', '一个垒', '1つの塁')}), '5': act(('Con un jonrón, ¿cuántas bases recorres?', 'On a home run, how many bases do you run?', '打出本垒打时，你要跑几个垒？', 'ホームランでは、いくつの塁を回る？'), ('¡Correcto! Y anotas carrera.', 'Correct! And you score a run.', '正确！你还得一分。', '正解！そして得点するよ。'), ('El jonrón recorre todo el diamante.', 'A home run goes around the whole diamond.', '本垒打要跑完整个菱形球场。', 'ホームランはダイヤモンドを1周するんだ。'), opts={'a': ('Todas: vuelta completa hasta home', 'All of them: all the way around to home', '全部：跑一整圈回到本垒', 'ぜんぶ：1周してホームまで'), 'b': ('Solo dos', 'Only two', '只有两个', '2つだけ'), 'c': ('Solo una', 'Only one', '只有一个', '1つだけ')}), '6': act(('Arrastra cada batazo a su resultado: sale en el aire / pica y sale', 'Drag each hit to its result: out in the air / bounces and goes out', '把每种击球拖到它的结果：在空中飞出 / 落地后出去', 'それぞれの打球を結果までドラッグしよう：空中で外へ／はずんで外へ'), ('¡Perfecto! Esa es la diferencia.', "Perfect! That's the difference.", '完美！这就是区别。', 'パーフェクト！それがちがいだよ。'), ('Recuerda: el pique cambia todo.', 'Remember: the bounce changes everything.', '记住：落地改变一切。', 'おぼえておこう：はずむかどうかで、ぜんぶ変わるよ。'), opts={'air': ('Sale en el aire', 'Out in the air', '在空中飞出', '空中で外へ'), 'bounce': ('Pica y sale', 'Bounces and goes out', '落地后出去', 'はずんで外へ'), 'hr': ('Jonrón', 'Home run', '本垒打', 'ホームラン'), 'grd': ('Doble por regla', 'Ground rule double', '场规二垒安打', 'グラウンドルールダブル')}, answer=('En el aire: jonrón; pica y sale: doble por regla', 'In the air: home run; bounces and goes out: ground rule double', '在空中飞出：本垒打；落地后出去：场规二垒安打', '空中で外へ：ホームラン、はずんで外へ：グラウンドルールダブル'))})
map_titles['5.3'] = ('El jonrón y el doble por regla', 'The home run and the ground rule double', '本垒打和场规二垒安打', 'ホームランとグラウンドルールダブル')
lesson('5.4', ('Correr a primera', 'Running to first', '跑向一垒', '一塁へ走る'), ('Aprender que corriendo a primera puedes pasarte de largo sin volver enseguida, pero en segunda y tercera pasarte de largo te pone en peligro de out.', 'Learn that when running to first you can overrun the base without having to come right back, but at second and third, overrunning puts you in danger of an out.', '知道跑向一垒时可以冲过垒包，不用马上停下；但在二垒和三垒，冲过垒包就有被出局的危险。', '一塁へ走るときは、塁を走りぬけてもすぐにもどらなくていいけど、二塁と三塁で走りぬけるとアウトになる危険があることを知ろう。'), [('Corriste a primera y llegaste safe. ¡Bien!', 'You ran to first and got there safe. Nice!', '你跑向一垒，安全上垒。好样的！', '一塁まで走って、セーフ。いいね！'), ('En primera hay un regalo: puedes pasarte de largo, seguir corriendo un poco por zona de foul, y regresar tranquilo, sin que te puedan tocar para el out, mientras no intentes ir a segunda.', "First base has a special rule: you can run past it, keep running a little into foul territory, and come back calmly without being tagged out, as long as you don't try to go to second.", '一垒有个礼物：你可以冲过垒包，在界外区再跑一点，然后慢慢回来，不会被触杀，只要你不想跑向二垒。', '一塁にはプレゼントがある：走りぬけて、ファウルゾーンに少し走って、ゆっくりもどってきても、二塁へ行こうとしなければ、タッチされてアウトにはならない。'), ('Pero cuidado: en segunda y en tercera no hay regalo.', "But careful: second and third don't have that rule.", '但要小心：二垒和三垒没有这个礼物。', 'でも気をつけて：二塁と三塁にはプレゼントはないよ。'), ('Si te pasas de largo, te pueden tocar con la bola y eres out.', 'If you run past the base, they can tag you with the ball and you are out.', '如果你冲过垒包，对方可以拿球触到你，你就出局了。', '走りぬけたら、ボールでタッチされてアウトになるよ。'), ('Primera perdona; las demás, no.', 'First base forgives; the others do not.', '一垒会原谅你；其他垒不会。', '一塁はゆるしてくれる。ほかの塁はゆるしてくれない。')], {'1': act(('¿En qué base puedes pasarte de largo y volver sin peligro?', 'At which base can you run past and come back safely?', '在哪个垒你可以冲过去再安全回来？', 'どの塁なら、走りぬけて安全にもどれる？'), ('¡Eso es! Solo primera.', "That's it! Only first.", '对了！只有一垒。', 'そのとおり！一塁だけ。'), ('El regalo es solo en primera.', 'Only first base lets you do that.', '这个礼物只在一垒。', 'プレゼントは一塁だけだよ。'), opts={'a': ('En primera', 'At first', '一垒', '一塁'), 'b': ('En segunda', 'At second', '二垒', '二塁'), 'c': ('En tercera', 'At third', '三垒', '三塁')}), '2': act(('Si te pasas de largo en segunda, tampoco te pueden hacer out', "If you run past second, they can't get you out either", '如果你冲过二垒，对方也不能让你出局', '二塁を走りぬけても、アウトにはならない'), ('¡Bien! En segunda sí te tocan.', 'Good! At second they can tag you.', '很好！在二垒对方可以触杀你。', 'いいね！二塁ではタッチされるよ。'), ('Falso: fuera de primera, pasarte es peligro.', 'False: away from first, running past is dangerous.', '错：除了一垒，冲过垒包都很危险。', 'まちがい：一塁以外で走りぬけるのはあぶないんだ。')), '3': act(('Te pasaste de largo en primera y giras como para ir a segunda. ¿Qué pasa?', 'You ran past first and turn as if to go to second. What happens?', '你冲过一垒，又转身好像要跑向二垒。会怎样？', '一塁を走りぬけて、二塁へ行くように体を向けた。どうなる？'), ('¡Correcto! Si intentas avanzar, el juego sigue.', 'Correct! If you try to advance, the play is on.', '正确！你想进垒，比赛就继续。', '正解！進もうとしたら、プレーは続くんだ。'), ('Primera perdona el paso de largo, no el intento de avanzar.', 'First forgives running past, not trying to advance.', '一垒原谅冲过垒包，不原谅想进垒。', '一塁がゆるすのは走りぬけることで、進もうとすることじゃないよ。'), opts={'a': ('La defensa sí te puede hacer out', 'The defense can get you out', '防守可以让你出局', '守備にアウトにされることがある'), 'b': ('Nada, primera siempre perdona', 'Nothing, first always forgives', '没事，一垒总会原谅你', '何もない、一塁はいつもゆるしてくれる'), 'c': ('Anotas carrera', 'You score a run', '你得一分', '得点する')}), '4': act(('Toca la base donde puedes pasarte de largo al llegar corriendo', 'Tap the base you can run past when you get there', '点一下你跑到时可以冲过去的垒', '走ってきて、走りぬけてもいい塁をタッチしよう'), ('¡Bien! Esa es.', "Good! That's the one.", '很好！就是它。', 'いいね！それだ。'), ('Solo primera tiene ese regalo.', 'Only first base lets you run past it.', '只有一垒有这个礼物。', 'そのプレゼントは一塁だけだよ。'), answer=('Primera base', 'First base', '一垒', '一塁')), '5': act(('¿Cuál corredor está en peligro?', 'Which runner is in danger?', '哪个跑垒员有危险？', 'あぶないのはどのランナー？'), ('¡Eso es! En segunda no hay perdón.', "That's it! Second doesn't forgive.", '对了！二垒不原谅。', 'そのとおり！二塁はゆるしてくれない。'), ('Segunda no perdona el paso de largo.', "Second doesn't forgive running past.", '二垒不原谅冲过垒包。', '二塁は走りぬけをゆるさないよ。'), opts={'a': ('El que se pasó de largo en segunda', 'The one who ran past second', '冲过二垒的那个', '二塁を走りぬけたランナー'), 'b': ('El que se pasó de largo en primera y regresa', 'The one who ran past first and is coming back', '冲过一垒正在回来的那个', '一塁を走りぬけて、もどってくるランナー'), 'c': ('El que está parado en su base', 'The one standing on their base', '站在垒包上的那个', '塁の上に立っているランナー')}), '6': act(('Llegaste a primera, te pasaste un poco y regresaste derecho. ¿Qué canta el umpire?', 'You reached first, ran past a little and came straight back. What does the umpire call?', '你到了一垒，冲过一点，然后直接回来。裁判会判什么？', '一塁に着いて、少し走りぬけて、まっすぐもどった。審判は何とコールする？'), ('¡Safe! Primera perdona.', 'Safe! First forgives.', '安全上垒！一垒原谅你。', 'セーフ！一塁はゆるしてくれる。'), ('Regresaste derecho: safe.', 'You came straight back: safe.', '你直接回来了：安全上垒。', 'まっすぐもどった：セーフ。'), opts={'a': ('¡Safe!', 'Safe!', '安全上垒！', 'セーフ！'), 'b': ('¡Out!', 'Out!', '出局！', 'アウト！'), 'c': ('¡Foul!', 'Foul!', '界外球！', 'ファウル！')})})
map_titles['5.4'] = ('Correr a primera', 'Running to first', '跑向一垒', '一塁へ走る')
lesson('5.5', ('El toque de bola', 'The bunt', '触击', 'バント'), ('Entender el toque (bunt): sostener el bate sin swing para dejar caer la bola suave, y que un foul de toque con dos strikes sí es tercer strike.', 'Understand the bunt: holding the bat without swinging to let the ball drop softly, and that a foul bunt with two strikes is strike three.', '明白触击：拿住球棒不挥棒，让球轻轻落下；还要知道两好球时触击成界外球，就是第三个好球。', 'バントを知ろう：バットをふらずに持って、ボールをやさしく落とすこと。2ストライクでバントがファウルになったら、3つ目のストライクになるよ。'), [('No todo batazo busca la valla.', 'Not every hit is aiming for the fence.', '不是每次击球都要打到围墙。', 'どの打球もフェンスをねらうわけじゃない。'), ('El toque de bola, en inglés bunt, es sostener el bate firme, sin hacer swing, y dejar que la bola caiga suavecita delante de home.', 'A bunt means holding the bat firmly, without swinging, and letting the ball drop softly in front of home plate.', '触击，英语叫 bunt，就是稳稳拿住球棒，不挥棒，让球轻轻落在本垒前面。', 'バント、英語で bunt は、バットをしっかり持って、ふらずに、ボールをホームプレートの前にやさしく落とすこと。'), ('Sirve para sorprender o para avanzar a un compañero.', 'It can surprise the defense or move a teammate up.', '它可以出其不意，或者帮队友进垒。', '相手をおどろかせたり、仲間を進めたりできるよ。'), ('Y aprende esta, que es especial: si tocas de foul con dos strikes, ese foul SÍ cuenta como tercer strike y eres out.', 'And learn this one, because it is special: if you bunt foul with two strikes, that foul DOES count as strike three and you are out.', '还要学这个特别的：两好球时触击成界外球，这个界外球“算”第三个好球，你就出局了。', 'そしてこれは特別だからおぼえよう：2ストライクでバントがファウルになったら、そのファウルは3つ目のストライクになって、アウトだよ。'), ('En el Nivel 4 aprendiste que el foul con dos strikes no poncha; con el toque, la historia cambia.', 'In Level 4 you learned that a foul with two strikes is not a strikeout; with a bunt, the story changes.', '在第 4 级你学过两好球时的界外球不会三振；触击就不一样了。', 'レベル4では、2ストライクのファウルは三振じゃないと習ったね。バントだと話が変わるんだ。')], {'1': act(('¿Qué es un toque de bola (bunt)?', 'What is a bunt?', '什么是触击 (bunt)？', 'バント (bunt) って何？'), ('¡Eso es! Bunt.', "That's it! Bunt.", '对了！触击。', 'そのとおり！バント。'), ('Toque: bate quieto y bola suave.', 'Bunt: the bat stays still and the ball goes soft.', '触击：球棒不动，球轻轻的。', 'バント：バットは動かさず、ボールはやさしく。'), opts={'a': ('Dejar caer la bola suave sosteniendo el bate, sin swing', 'Letting the ball drop softly by holding the bat, without swinging', '拿住球棒不挥棒，让球轻轻落下', 'バットを持ったまま、ふらずにボールをやさしく落とす'), 'b': ('Un swing muy fuerte', 'A really hard swing', '用力挥棒', 'とても強いスイング'), 'c': ('Un lanzamiento del pitcher', "A pitcher's pitch", '投手的投球', 'ピッチャーの投球')}), '2': act(('En el toque se hace el swing más fuerte del juego', 'On a bunt you take the hardest swing of the game', '触击时要挥出比赛中最用力的一棒', 'バントでは、試合でいちばん強いスイングをする'), ('¡Bien! Sin swing.', 'Good! No swing.', '很好！不挥棒。', 'いいね！スイングしない。'), ('Falso: el bate se sostiene, no se mueve con fuerza.', "False: you hold the bat, you don't swing it hard.", '错：拿住球棒，不用力挥。', 'まちがい：バットは持つだけで、強くふらないよ。')), '3': act(('Tocas de foul con dos strikes. ¿Qué pasa?', 'You bunt foul with two strikes. What happens?', '两好球时你触击成界外球。会怎样？', '2ストライクでバントがファウルになった。どうなる？'), ('¡Correcto! Esa es la excepción del toque.', "Correct! That's the bunt exception.", '正确！这是触击的例外。', '正解！それがバントの例外だよ。'), ('Foul de toque con dos strikes: ponche.', 'Foul bunt with two strikes: strikeout.', '两好球时触击界外：三振。', '2ストライクでバントのファウル：三振。'), opts={'a': ('Es tercer strike: out', "It's strike three: out", '是第三个好球：出局', '3つ目のストライク：アウト'), 'b': ('Nada, el foul nunca cuenta', 'Nothing, a foul never counts', '没事，界外球从来不算', '何もない、ファウルは数えない'), 'c': ('Es bola', "It's a ball", '是坏球', 'ボール')}), '4': act(('¿Cuál imagen muestra un toque?', 'Which picture shows a bunt?', '哪张图是触击？', 'バントはどの絵？'), ('¡Eso es! Bate firme y quieto.', "That's it! Bat firm and still.", '对了！球棒稳稳不动。', 'そのとおり！バットはしっかり止める。'), ('Así se ve un bunt.', 'This is what a bunt looks like.', '触击就是这个样子。', 'バントはこういう形だよ。'), opts={'a': ('El bate sostenido en cruz, sin swing', 'The bat held across, with no swing', '球棒横着拿住，不挥棒', 'バットを横にかまえて、ふらない'), 'b': ('El bate girando con todo', 'The bat swinging all the way', '球棒用力挥动', 'バットを思いきりふる'), 'c': ('El bate en el suelo', 'The bat on the ground', '球棒放在地上', 'バットが地面にある')}), '5': act(('El toque salió de foul con dos strikes. ¿Qué canta el umpire?', 'The bunt went foul with two strikes. What does the umpire call?', '两好球时触击成了界外球。裁判会判什么？', '2ストライクでバントがファウルになった。審判は何とコールする？'), ('¡Out! Regla especial del toque.', 'Out! The special bunt rule.', '出局！触击的特别规则。', 'アウト！バントの特別ルール。'), ('Con toque no hay foul gratis con dos strikes.', 'With a bunt there is no free foul on two strikes.', '触击时，两好球后没有“免费”的界外球。', 'バントでは、2ストライクのファウルはゆるされないよ。'), opts={'a': ('¡Out! Tercer strike', 'Out! Strike three', '出局！第三个好球', 'アウト！3つ目のストライク'), 'b': ('¡Foul, sigue bateando!', 'Foul, keep batting!', '界外球，继续击球！', 'ファウル、打ち続けて！'), 'c': ('¡Safe!', 'Safe!', '安全上垒！', 'セーフ！')}), '6': act(('¿Para qué sirve un toque sorpresa?', 'What is a surprise bunt for?', '出其不意的触击有什么用？', 'おどろかせるバントは何のため？'), ('¡Correcto! La sorpresa ayuda.', 'Correct! Surprise helps.', '正确！出其不意很有用。', '正解！おどろかせると役に立つ。'), ('Defensa lejos: el toque puede ser hit.', 'Defense far back: the bunt can be a hit.', '防守站得远：触击可能变成安打。', '守備がうしろにいたら、バントがヒットになることもあるよ。'), opts={'a': ('Para llegar a primera cuando la defensa está lejos', 'To reach first when the defense is far back', '在防守站得远的时候跑上一垒', '守備がうしろにいるときに一塁に着くため'), 'b': ('Para lanzar la bola', 'To throw the ball', '为了投球', 'ボールを投げるため'), 'c': ('Para terminar la entrada', 'To end the inning', '为了结束这一局', 'イニングを終わらせるため')})})
map_titles['5.5'] = ('El toque de bola', 'The bunt', '触击', 'バント')
exams_v3['5'] = {'1': {'q': ('¿Qué es un hit?', 'What is a hit?', '什么是安打？', 'ヒットって何？'), 'opts': {'a': ('Un batazo con el que llegas a salvo', 'A batted ball that gets you on base safely', '让你安全上垒的击球', '安全に塁に着ける打球'), 'b': ('Un tiro del pitcher', "A pitcher's throw", '投手的投球', 'ピッチャーの投球'), 'c': ('Una bola atrapada', 'A caught ball', '被接住的球', 'とられたボール')}}, '2': {'q': ('La bola cae en los jardines, lejos de todos, y llegas a primera. ¿Qué es?', 'The ball lands in the outfield, far from everyone, and you reach first. What is it?', '球落在外野，离大家都很远，你跑上了一垒。这是什么？', 'ボールがみんなから遠い外野に落ちて、一塁に着いた。これは何？'), 'opts': {'a': ('Un hit', 'A hit', '安打', 'ヒット'), 'b': ('Un out', 'An out', '出局', 'アウト'), 'c': ('Un foul', 'A foul', '界外球', 'ファウル')}}, '3': {'q': ('¿Qué canta el umpire cuando llegas antes que el tiro?', 'What does the umpire call when you get there before the throw?', '你比传球先到时，裁判会判什么？', '送球より先に着いたら、審判は何とコールする？'), 'opts': {'a': ('¡Safe!', 'Safe!', '安全上垒！', 'セーフ！'), 'b': ('¡Strike!', 'Strike!', '好球！', 'ストライク！'), 'c': ('¡Balk!', 'Balk!', '投手犯规！', 'ボーク！')}}, '4': {'q': ('Toca la base que es tu lugar seguro al llegar de un hit cortito', 'Tap the base you reach on a short hit', '点一下短安打时你到达的安全区', '短いヒットで着いたときの、君の安全地帯の塁をタッチしよう'), 'answer': ('Primera base', 'First base', '一垒', '一塁')}, '5': {'q': ('¿Cómo se dice «sencillo» en inglés?', "What's a hit that gets you to first base called?", '一垒安打的英语怎么说？', 'シングルヒットは英語で何という？'), 'opts': {'a': ('Single', 'Single', 'Single', 'Single'), 'b': ('Balk', 'Balk', 'Balk', 'Balk'), 'c': ('Lead', 'Lead', 'Lead', 'Lead')}}, '6': {'q': ('Llegas a segunda con tu batazo. ¿Qué hit es?', 'You reach second on your hit. What kind of hit is it?', '你击球后跑到了二垒。这是哪种安打？', '打って二塁まで行けた。何のヒット？'), 'opts': {'a': ('Un doble', 'A double', '二垒安打', 'ツーベースヒット'), 'b': ('Un sencillo', 'A single', '一垒安打', 'シングルヒット'), 'c': ('Un triple', 'A triple', '三垒安打', 'スリーベースヒット')}}, '7': {'q': ('La bola sale volando del campo sin tocar el suelo, en territorio fair. ¿Qué es?', 'The ball flies out of the park without touching the ground, in fair territory. What is it?', '球在界内没落地就飞出了球场。这是什么？', 'ボールがフェアゾーンで、地面にさわらずにグラウンドの外へ飛んでいった。これは何？'), 'opts': {'a': ('Un jonrón', 'A home run', '本垒打', 'ホームラン'), 'b': ('Un doble por regla', 'A ground rule double', '场规二垒安打', 'グラウンドルールダブル'), 'c': ('Un foul', 'A foul', '界外球', 'ファウル')}}, '8': {'q': ('Verdadero o falso: si la bola pica en territorio fair y después salta la valla, es jonrón', "True or false: if the ball bounces in fair territory and then goes over the fence, it's a home run", '对还是错：球在界内落地后弹过围栏，就是本垒打', '○か×か：フェアゾーンでバウンドしてからフェンスをこえたら、ホームラン')}, '9': {'q': ('Verdadero o falso: al correr a primera puedes pasarte de largo y volver sin peligro', 'True or false: when you run to first, you can run past the base and come back safely', '对还是错：跑向一垒时，你可以跑过垒包，再安全地回来', '○か×か：一塁へ走るときは、通りすぎても安全にもどれる')}, '10': {'q': ('Te pasas de largo en segunda y te tocan con la bola fuera de la base. ¿Qué pasa?', 'You run past second and get tagged with the ball off the base. What happens?', '你跑过了二垒，离开垒包时被球触到。会怎样？', '二塁を通りすぎて、塁の外でボールでタッチされた。どうなる？'), 'opts': {'a': ('Eres out', "You're out", '你出局', 'アウト'), 'b': ('Eres safe', "You're safe", '你安全上垒', 'セーフ'), 'c': ('No pasa nada', 'Nothing happens', '什么都不会发生', '何も起きない')}}, '11': {'q': ('¿Qué es un toque de bola (bunt)?', 'What is a bunt?', '什么是触击（bunt）？', 'バントって何？'), 'opts': {'a': ('Sostener el bate sin swing y dejar caer la bola suave', 'Holding the bat still, with no swing, and letting the ball drop softly', '握住球棒不挥棒，让球轻轻落下', 'バットをふらずにかまえて、ボールをやわらかく落とす'), 'b': ('El swing más fuerte del juego', 'The hardest swing in the game', '比赛中最用力的挥棒', 'いちばん強いスイング'), 'c': ('Un lanzamiento del pitcher', "A pitcher's throw", '投手的投球', 'ピッチャーの投球')}}, '12': {'q': ('Con dos strikes, tu toque sale de foul. ¿Qué pasa?', 'With two strikes, your bunt goes foul. What happens?', '两好球时，你的触击打成界外球。会怎样？', '2ストライクでバントがファウルになった。どうなる？'), 'opts': {'a': ('Es el tercer strike: ponche', "It's strike three: you're out", '这是第三个好球：三振', '3つ目のストライク：三振'), 'b': ('Sigues bateando', 'You keep batting', '你继续击球', '打ち続ける'), 'c': ('Es bola', "It's a ball", '这是坏球', 'ボール')}}}
