levels['6'] = dict(title=('Cómo se hacen outs', 'How outs are made', '怎样制造出局', 'アウトのとり方'), badge=('Guante de Oro', 'Gold Glove', '金手套', 'ゴールドグラブ'))
lesson('6.1', ('Elevado atrapado', 'The caught fly ball', '接住高飞球', 'フライをとる'), ('Reforzar que todo batazo atrapado en el aire, antes de tocar el suelo, es out del bateador: elevado, línea y también elevado en zona de foul.', 'Reinforce that any batted ball caught in the air, before it touches the ground, is an out for the batter: a fly ball, a line drive and even a fly ball in foul territory.', '巩固这一点：任何击出的球在落地前被空中接住，击球员就出局：高飞球、平直球，甚至界外区的高飞球都一样。', '地面に落ちる前に空中でとられた打球は、どれもバッターのアウトだと確かめよう：フライも、ライナーも、ファウルゾーンのフライも。'), [('La regla más rápida del béisbol: si el batazo es atrapado en el aire, antes de picar, el bateador es out.', "Baseball's fastest rule: if the batted ball is caught in the air, before it bounces, the batter is out.", '棒球里最快的规则：击出的球在落地前被空中接住，击球员就出局。', '野球でいちばん早いルール：打球が地面に落ちる前に空中でとられたら、バッターはアウト。'), ('No importa si es un elevado alto a los jardines, en inglés fly ball, o una línea durísima, line drive: atrapada es atrapada.', "It doesn't matter if it's a high fly ball to the outfield or a hard line drive: a catch is a catch.", '不管是飞向外野的高飞球，英语叫 fly ball，还是很猛的平直球，line drive：接住就是接住。', '外野への高いフライ（fly ball）でも、すごく強いライナー（line drive）でも同じ。とったら、とったんだ。'), ('Hasta en zona de foul vale, si el defensor la atrapa en el aire.', 'It even counts in foul territory, if the fielder catches it in the air.', '就算在界外区也算，只要防守球员在空中接住。', 'ファウルゾーンでも、空中でとればアウトだよ。'), ('Pero si pica primero, ya nadie la puede «atrapar» para el out: hay que jugarla del suelo.', "But if it bounces first, nobody can 'catch' it for the out anymore: you have to play it off the ground.", '但如果球先落地，就没人能“接住”它让人出局了：得从地上处理这个球。', 'でも先に地面に落ちたら、もう「とって」アウトにはできない。地面から処理するんだ。')], {'1': act(('El jardinero atrapa tu elevado en el aire. ¿Qué pasa?', 'The outfielder catches your fly ball in the air. What happens?', '外野手在空中接住了你的高飞球。会怎样？', '外野手が君のフライを空中でとった。どうなる？'), ('¡Correcto! Atrapada en el aire: out.', 'Correct! Caught in the air: out.', '正确！空中接住：出局。', '正解！空中でとったらアウト。'), ('Bola en el aire atrapada, bateador out.', 'Ball caught in the air: batter out.', '空中接住的球：击球员出局。', '空中でとった打球：バッターはアウト。'), opts={'a': ('Eres out', "You're out", '你出局了', 'アウト'), 'b': ('Es hit', "It's a hit", '是安打', 'ヒット'), 'c': ('Es foul', "It's a foul", '是界外球', 'ファウル')}), '2': act(('Una línea atrapada en el aire también es out', 'A line drive caught in the air is also an out', '在空中接住的平直球也算出局', '空中でとったライナーもアウト'), ('¡Sí! Línea o elevado, igual.', 'Yes! Line drive or fly ball, same thing.', '对！平直球和高飞球一样。', 'そう！ライナーもフライも同じ。'), ('Verdadero: lo que manda es atraparla en el aire.', 'True: what matters is catching it in the air.', '这是对的：关键是在空中接住。', '正しいよ：大事なのは空中でとること。')), '3': act(('La bola pica en el jardín y después el jardinero la recoge. ¿Hubo atrapada para out?', 'The ball bounces in the outfield and then the outfielder picks it up. Was it caught for an out?', '球在外野落地后，外野手才捡起来。这算接住出局吗？', 'ボールが外野ではずんでから、外野手がひろった。アウトになるキャッチだった？'), ('¡Eso es! Picó: ya no hay atrapada.', "That's it! It bounced: no catch.", '对了！落地了：不算接住。', 'そのとおり！はずんだらキャッチじゃない。'), ('Para el out en el aire, no puede picar.', "For an out in the air, it can't bounce.", '要空中接住出局，球不能落地。', '空中でとってアウトにするには、はずんではいけないよ。'), opts={'a': ('No, ya picó', 'No, it already bounced', '不算，已经落地了', 'ちがう、もうはずんだ'), 'b': ('Sí, igual cuenta', 'Yes, it still counts', '算，照样算', 'うん、それでもアウト'), 'c': ('Solo si corre', 'Only if he runs', '只有他跑起来才算', '走ったときだけ')}), '4': act(('¿Cuál batazo es out seguro si se atrapa?', 'Which batted ball is a sure out if caught?', '哪种击球被接住就一定出局？', 'どの打球なら、とればアウトまちがいなし？'), ('¡Correcto! Ese se atrapa en el aire.', 'Correct! That one is caught in the air.', '正确！那种球是在空中接的。', '正解！それは空中でとるボール。'), ('El elevado se busca en el aire.', 'You go for the fly ball in the air.', '高飞球要在空中接。', 'フライは空中でとりにいくんだ。'), opts={'a': ('Un elevado alto a los jardines', 'A high fly ball to the outfield', '飞向外野的高飞球', '外野への高いフライ'), 'b': ('Un rolling por el suelo', 'A ground ball', '滚地球', 'ゴロ'), 'c': ('Un toque suave', 'A soft bunt', '轻轻的触击', 'やさしいバント')}), '5': act(('El campocorto atrapa una línea durísima. ¿Qué canta el umpire para el bateador?', 'The shortstop catches a screaming line drive. What does the umpire call for the batter?', '游击手接住了一个很猛的平直球。裁判对击球员判什么？', '遊撃手がすごく強いライナーをとった。審判はバッターに何とコールする？'), ('¡Out! Línea atrapada, out.', 'Out! Line drive caught: out.', '出局！平直球被接住：出局。', 'アウト！ライナーをとったらアウト。'), ('Atrapada en el aire siempre es out.', 'Caught in the air is always an out.', '空中接住永远是出局。', '空中でとったら、いつもアウト。'), opts={'a': ('¡Out!', 'Out!', '出局！', 'アウト！'), 'b': ('¡Safe!', 'Safe!', '安全上垒！', 'セーフ！'), 'c': ('¡Strike!', 'Strike!', '好球！', 'ストライク！')}), '6': act(('Un elevado de foul atrapado en el aire es out', 'A foul fly ball caught in the air is an out', '在空中接住的界外高飞球是出局', '空中でとったファウルフライはアウト'), ('¡Bien! En foul también vale atraparla.', 'Good! In foul territory catching it counts too.', '很好！在界外区接住也算。', 'いいね！ファウルゾーンでとってもアウト。'), ('Verdadero: la atrapada en zona de foul cuenta.', 'True: a catch in foul territory counts.', '这是对的：在界外区接住也算。', '正しいよ：ファウルゾーンでのキャッチもアウト。'))})
map_titles['6.1'] = ('Elevado atrapado', 'The caught fly ball', '接住高飞球', 'フライをとる')
lesson('6.2', ('Out forzado', 'The force out', '封杀', 'フォースアウト'), ('Entender el out forzado: si el corredor está obligado a avanzar, basta que un defensor con la bola pise la base antes que él.', 'Understand the force out: if the runner has to move up, a fielder with the ball only needs to step on the base before the runner gets there.', '明白封杀：如果跑垒员必须前进，防守球员只要拿着球在他到达之前踩到垒包就行。', 'フォースアウトを知ろう：ランナーが進まないといけないときは、ボールを持った守備の選手が、ランナーより先に塁をふめばアウト。'), [('Imagina una fila que empuja.', 'Imagine a line that pushes.', '想象一排人在往前推。', '前へおしていく列を想像して。'), ('Cuando el bateador conecta y tiene que ir a primera, todos los de atrás empujan: el de primera está obligado a ir a segunda.', 'When the batter makes contact and has to go to first, everyone behind pushes: the runner on first has to go to second.', '击球员击中球，必须跑向一垒，后面的人就会往前推：一垒上的跑垒员必须跑向二垒。', 'バッターが打って一塁へ行かないといけないとき、うしろからおされる：一塁のランナーは二塁へ行かないといけない。'), ('Ese corredor está forzado, en inglés forced.', 'That runner is forced.', '这个跑垒员被“封”了，英语叫 forced。', 'そのランナーは「フォース」の状態、英語で forced。'), ('Y hay un regalo para la defensa: no hay que tocarlo.', "And here's the good news for the defense: they don't have to tag him.", '防守方还有个礼物：不用触碰他。', 'そして守備にはプレゼントがある：タッチしなくていいんだ。'), ('Basta pisar su base con la bola antes de que él llegue: out forzado, force out. Pisar y listo.', "They just step on his base with the ball before he gets there: a force out. Step on it and that's it.", '只要拿着球在他到达之前踩到他要去的垒：封杀，force out。踩一下就行。', 'ボールを持って、ランナーより先にその塁をふめばいい：フォースアウト、force out。ふめばおしまい。')], {'1': act(('¿Qué es un out forzado?', 'What is a force out?', '什么是封杀？', 'フォースアウトって何？'), ('¡Eso es! Force out.', "That's it! Force out.", '对了！封杀，force out。', 'そのとおり！フォースアウト。'), ('Forzado: se pisa la base con la bola.', 'Forced: you step on the base with the ball.', '封杀：拿着球踩垒包。', 'フォース：ボールを持って塁をふむんだ。'), opts={'a': ('Pisar la base con la bola antes que el corredor obligado', 'Stepping on the base with the ball before the forced runner', '拿着球比被迫前进的跑垒员先踩到垒包', 'ボールを持って、進まないといけないランナーより先に塁をふむ'), 'b': ('Tocar al corredor con el guante vacío', 'Tagging the runner with an empty glove', '用空手套碰跑垒员', 'からのグラブでランナーにタッチする'), 'c': ('Gritar «out»', 'Yelling "out"', '大喊“出局”', '「アウト」とさけぶ')}), '2': act(('En el out forzado hay que tocar al corredor con la bola', 'On a force out you have to tag the runner with the ball', '封杀时必须拿球触碰跑垒员', 'フォースアウトでは、ランナーにボールでタッチしないといけない'), ('¡Bien! Basta pisar la base.', 'Good! Stepping on the base is enough.', '很好！踩垒包就够了。', 'いいね！塁をふめば十分。'), ('Falso: pisar la base alcanza.', 'False: stepping on the base is enough.', '错：踩到垒包就够了。', 'まちがい：塁をふめば十分だよ。')), '3': act(('Corredor en primera, rolling al campocorto. El campocorto pisa segunda con la bola antes que el corredor. ¿Qué pasa?', 'Runner on first, ground ball to the shortstop. The shortstop steps on second with the ball before the runner. What happens?', '一垒有跑垒员，滚地球打向游击手。游击手拿着球比跑垒员先踩到二垒。会怎样？', '一塁にランナー、遊撃手へのゴロ。遊撃手がボールを持ってランナーより先に二塁をふんだ。どうなる？'), ('¡Correcto! Estaba obligado a correr.', 'Correct! He had to run.', '正确！他必须跑。', '正解！ランナーは走らないといけなかった。'), ('Venía empujado de primera: forzado.', 'He was pushed from first: forced.', '他被从一垒推着走：被封。', '一塁からおされていた：フォース。'), opts={'a': ('Out forzado en segunda', 'Force out at second', '二垒封杀', '二塁でフォースアウト'), 'b': ('Nada', 'Nothing', '没事', '何もない'), 'c': ('El corredor anota', 'The runner scores', '跑垒员得分', 'ランナーが得点')}), '4': act(('Corredor forzado corriendo a segunda. Toca la base que debe pisar el defensor con la bola', 'Forced runner running to second. Tap the base the fielder must step on with the ball', '被迫前进的跑垒员正跑向二垒。点一下防守球员要拿球踩的垒', 'フォースのランナーが二塁へ走っている。守備の選手がボールを持ってふむ塁をタッチしよう'), ('¡Bien! Pisa segunda y es out.', "Good! Step on second and he's out.", '很好！踩二垒就出局。', 'いいね！二塁をふめばアウト。'), ('La base del corredor forzado es el blanco.', "The forced runner's base is the target.", '目标是被封跑垒员要去的垒。', 'ねらうのは、フォースのランナーが向かう塁だよ。'), answer=('Segunda base', 'Second base', '二垒', '二塁')), '5': act(('El defensor pisó la base con la bola antes que el corredor obligado. ¿Qué canta?', 'The fielder stepped on the base with the ball before the forced runner. What does the umpire call?', '防守球员拿着球比被迫前进的跑垒员先踩到垒包。裁判会判什么？', '守備の選手がボールを持って、フォースのランナーより先に塁をふんだ。審判は何とコールする？'), ('¡Out! Force out.', 'Out! Force out.', '出局！封杀。', 'アウト！フォースアウト。'), ('Llegó primero la bola a la base: out.', 'The ball got to the base first: out.', '球先到垒：出局。', 'ボールが先に塁に着いた：アウト。'), opts={'a': ('¡Out!', 'Out!', '出局！', 'アウト！'), 'b': ('¡Safe!', 'Safe!', '安全上垒！', 'セーフ！'), 'c': ('¡Foul!', 'Foul!', '界外球！', 'ファウル！')}), '6': act(('¿Por qué se dice que el corredor está «forzado»?', 'Why do we say the runner is "forced"?', '为什么说跑垒员被“封”了？', 'なぜランナーは「フォース」だというの？'), ('¡Eso es! La fila empuja.', "That's it! The line pushes.", '对了！是后面的人在推。', 'そのとおり！列がおすんだ。'), ('El bateador-corredor lo empuja desde atrás.', 'The batter-runner pushes him from behind.', '击跑员从后面推着他。', 'うしろからバッターランナーがおしているんだ。'), opts={'a': ('Porque el de atrás lo empuja: no puede quedarse', "Because the one behind pushes him: he can't stay", '因为后面的人推着他：他不能留在原地', 'うしろの人におされて、とどまれないから'), 'b': ('Porque corre muy rápido', 'Because he runs really fast', '因为他跑得很快', 'とても速く走るから'), 'c': ('Porque el coach lo obliga a robar', 'Because the coach makes him steal', '因为教练让他盗垒', 'コーチが盗塁させるから')})})
map_titles['6.2'] = ('Out forzado', 'The force out', '封杀', 'フォースアウト')
lesson('6.3', ('Out tocando al corredor', 'Tagging the runner out', '触杀跑垒员', 'ランナーにタッチしてアウト'), ('Entender el out de toque (tag out): cuando el corredor no está forzado, hay que tocarlo con la bola — o con el guante que tiene la bola — mientras está fuera de su base.', "Understand the tag out: when the runner isn't forced, you have to touch him with the ball, or with the glove holding the ball, while he is off his base.", '明白触杀：跑垒员没有被封时，要在他离开垒包时，用球或拿着球的手套碰到他。', 'タッチアウトを知ろう：ランナーがフォースでないときは、塁をはなれているあいだに、ボールかボールが入ったグラブでタッチしないといけない。'), [('Y si el corredor NO está obligado a correr, pisar la base no sirve.', "And if the runner does NOT have to run, stepping on the base doesn't work.", '如果跑垒员“不是”被迫要跑，踩垒包就没用。', 'ランナーが走らなくてもいいときは、塁をふんでもだめ。'), ('Hay que tocarlo: out de toque, en inglés tag out.', 'You have to touch him: a tag out.', '必须碰到他：触杀，英语叫 tag out。', 'タッチしないといけない：タッチアウト、英語で tag out。'), ('Se toca con la bola, o con el guante si la bola está dentro del guante, bien agarrada.', 'You touch him with the ball, or with the glove if the ball is inside it, held tight.', '用球碰，或者用手套碰，但球要牢牢握在手套里。', 'ボールでタッチするか、ボールがしっかり入ったグラブでタッチするんだ。'), ('Y solo vale mientras el corredor está fuera de su base: su base es su lugar seguro.', "And it only counts while the runner is off his base: on his base, he's safe.", '而且只有跑垒员离开垒包时才算：垒包是他的安全区。', 'それも、ランナーが塁をはなれているあいだだけ。塁はランナーの安全地帯なんだ。'), ('Si está parado sobre ella, tocarlo no hace nada.', "If he's standing on it, tagging him does nothing.", '如果他站在垒包上，碰他也没用。', '塁の上に立っていたら、タッチしても何も起きないよ。')], {'1': act(('¿Qué es un out de toque (tag out)?', 'What is a tag out?', '什么是触杀 (tag out)？', 'タッチアウト (tag out) って何？'), ('¡Eso es! Tag out.', "That's it! Tag out.", '对了！触杀。', 'そのとおり！タッチアウト。'), ('Si no está forzado, hay que tocar al corredor.', "If he isn't forced, you have to tag the runner.", '如果不是封杀，就要触碰跑垒员。', 'フォースでなければ、ランナーにタッチしないといけない。'), opts={'a': ('Tocar al corredor con la bola fuera de su base', 'Touching the runner with the ball while off his base', '在跑垒员离开垒包时用球碰他', '塁をはなれたランナーにボールでタッチする'), 'b': ('Pisar cualquier base', 'Stepping on any base', '踩任何一个垒', 'どれかの塁をふむ'), 'c': ('Gritar su nombre', 'Yelling his name', '大喊他的名字', '名前をさけぶ')}), '2': act(('Tocar al corredor con el guante vacío, sin la bola, es out', 'Tagging the runner with an empty glove, without the ball, is an out', '用没有球的空手套碰跑垒员，算出局', 'ボールが入っていないからのグラブでタッチしても、アウト'), ('¡Bien! La bola manda.', 'Good! The ball is what counts.', '很好！关键是球。', 'いいね！大事なのはボール。'), ('Falso: sin bola no hay toque que valga.', "False: without the ball there's no tag.", '错：没有球，碰了也不算。', 'まちがい：ボールがなければタッチにならないよ。')), '3': act(('El corredor está parado sobre su base y lo tocan con la bola. ¿Es out?', 'The runner is standing on his base and gets tagged with the ball. Is he out?', '跑垒员站在垒包上，被球碰到了。他出局吗？', 'ランナーが塁の上に立っていて、ボールでタッチされた。アウト？'), ('¡Correcto! Sobre la base está a salvo.', "Correct! On the base he's safe.", '正确！在垒包上他是安全的。', '正解！塁の上ならセーフ。'), ('En su lugar seguro no hay out.', "On his base, he's safe.", '在安全区里不会出局。', '安全地帯ではアウトにならないよ。'), opts={'a': ('No, su base es su lugar seguro', "No, on his base he's safe", '不，垒包是他的安全区', 'ちがう、塁は安全地帯'), 'b': ('Sí, siempre', 'Yes, always', '是，一直都是', 'うん、いつもアウト'), 'c': ('Solo si es tercera', 'Only if it is third', '只有在三垒才是', '三塁のときだけ')}), '4': act(('El corredor se despegó de segunda y está fuera de la base. Señala al corredor que hay que tocar con la bola', 'The runner stepped off second and is away from the base. Tap the runner who has to be tagged with the ball', '跑垒员离开了二垒，不在垒包上。点一下要用球去触碰的跑垒员', 'ランナーが二塁をはなれている。ボールでタッチしないといけないランナーをタッチしよう'), ('¡Bien! A él, con la bola.', 'Good! Him, with the ball.', '很好！就是他，用球碰。', 'いいね！ボールで、そのランナーに。'), ('Fuera de la base, el toque es sobre el corredor.', 'Off the base, you tag the runner.', '离开垒包时，要碰跑垒员本人。', '塁をはなれていたら、ランナーにタッチするんだ。'), answer=('Al corredor fuera de su base', 'The runner off his base', '离开垒包的跑垒员', '塁をはなれたランナー')), '5': act(('¿Cuál toque vale para out?', 'Which tag counts for an out?', '哪种触碰算出局？', 'どのタッチならアウト？'), ('¡Eso es! Bola agarrada y toque.', "That's it! Ball held tight and tag.", '对了！握紧球再触碰。', 'そのとおり！ボールをしっかり持ってタッチ。'), ('La bola debe estar segura en el guante.', 'The ball has to be secure in the glove.', '球必须牢牢在手套里。', 'ボールはグラブの中にしっかりないといけない。'), opts={'a': ('El guante con la bola bien agarrada toca al corredor', 'The glove holding the ball tight touches the runner', '牢牢握着球的手套碰到跑垒员', 'ボールをしっかり持ったグラブがランナーにさわる'), 'b': ('El guante vacío roza al corredor', 'An empty glove brushes the runner', '空手套擦到跑垒员', 'からのグラブがランナーにふれる'), 'c': ('La mano sin bola toca al corredor', 'A hand with no ball touches the runner', '没拿球的手碰到跑垒员', 'ボールを持っていない手がランナーにさわる')}), '6': act(('Tocaron al corredor con la bola a mitad de camino entre bases. ¿Qué canta el umpire?', 'They tagged the runner with the ball halfway between bases. What does the umpire call?', '跑垒员在两个垒之间被球碰到。裁判会判什么？', '塁と塁のあいだでランナーがボールでタッチされた。審判は何とコールする？'), ('¡Out! Tag out.', 'Out! Tag out.', '出局！触杀。', 'アウト！タッチアウト。'), ('Fuera de su lugar seguro y tocado: out.', 'Off his base and tagged: out.', '离开安全区又被碰到：出局。', '安全地帯の外でタッチされた：アウト。'), opts={'a': ('¡Out!', 'Out!', '出局！', 'アウト！'), 'b': ('¡Safe!', 'Safe!', '安全上垒！', 'セーフ！'), 'c': ('¡Bola!', 'Ball!', '坏球！', 'ボール！')})})
map_titles['6.3'] = ('Out tocando al corredor', 'Tagging the runner out', '触杀跑垒员', 'ランナーにタッチしてアウト')
lesson('6.4', ('¿Forzado o no?', 'Forced or not?', '是封杀还是不是？', 'フォース？それともちがう？'), ('Decidir, según quién viene detrás, si un corredor está forzado (basta pisar la base) o no (hay que tocarlo). La clave: si la base de atrás quedó ocupada por alguien que lo empuja.', 'Decide, based on who is behind, whether a runner is forced (just step on the base) or not (you have to tag him). The key: whether the base behind is taken by someone pushing him.', '根据后面有谁，判断跑垒员是不是被封（踩垒包就行）还是没被封（要触碰他）。关键是：后面的垒上有没有人在推他。', 'うしろにだれがいるかで、ランナーがフォースか（塁をふめばいい）、ちがうか（タッチしないといけない）を決めよう。ポイントは、うしろの塁に、おしてくる人がいるかどうか。'), [('Antes de jugar, pregúntate: ¿este corredor está forzado o no?', 'Before you play, ask yourself: is this runner forced or not?', '防守前先问自己：这个跑垒员是不是被封了？', 'プレーの前に考えよう：このランナーはフォース？ちがう？'), ('La clave es mirar atrás.', 'The key is to look behind.', '关键是往后看。', 'ポイントは、うしろを見ること。'), ('Si detrás de él viene otro que necesita su base, está forzado y basta pisar la base.', "If someone behind him needs his base, he's forced and you just step on the base.", '如果他后面有人需要他的垒，他就被封了，踩垒包就行。', 'うしろから、その塁が必要な人が来ていたら、フォース。塁をふめばいい。'), ('Si detrás no viene nadie, no está forzado: hay que tocarlo.', "If nobody is coming behind, he's not forced: you have to tag him.", '如果后面没有人，他就没被封：要触碰他。', 'うしろにだれもいなければ、フォースじゃない：タッチしないといけない。'), ('Ejemplo: corredor solo en segunda. Nadie lo empuja — el de primera no existe — así que para sacarlo hay que tocarlo con la bola.', "Example: a runner alone on second. Nobody pushes him (there's no runner on first), so to get him out you have to tag him with the ball.", '例如：只有二垒有跑垒员。没人推他——一垒上没有人——所以要让他出局，就要用球碰他。', 'たとえば、二塁だけにランナー。おす人はいない（一塁にはだれもいない）から、アウトにするにはボールでタッチするんだ。'), ('Mira atrás y sabrás qué hacer.', "Look behind and you'll know what to do.", '往后看，你就知道该怎么做。', 'うしろを見れば、どうすればいいかわかるよ。')], {'1': act(('Corredor solo en segunda, rolling al cuadro. ¿Está forzado a ir a tercera?', 'Runner alone on second, ground ball to the infield. Is he forced to go to third?', '只有二垒有跑垒员，滚地球打向内野。他被迫要跑三垒吗？', '二塁だけにランナー、内野へのゴロ。三塁へ行かないといけない？'), ('¡Correcto! Nadie viene detrás.', 'Correct! Nobody is behind him.', '正确！他后面没有人。', '正解！うしろにだれもいない。'), ('Sin nadie en primera, el de segunda no está forzado.', "With nobody on first, the runner on second isn't forced.", '一垒没人，二垒的跑垒员就不是被封杀。', '一塁にだれもいなければ、二塁のランナーはフォースじゃない。'), opts={'a': ('No, nadie lo empuja', 'No, nobody pushes him', '不，没人推他', 'ちがう、だれもおしていない'), 'b': ('Sí, siempre', 'Yes, always', '是，一直都是', 'うん、いつも'), 'c': ('Solo con dos outs', 'Only with two outs', '只有两出局时', '2アウトのときだけ')}), '2': act(('Corredores en primera y segunda, rolling. ¿El de segunda está forzado?', 'Runners on first and second, ground ball. Is the runner on second forced?', '一垒和二垒有跑垒员，滚地球。二垒的跑垒员被封了吗？', '一塁と二塁にランナー、ゴロ。二塁のランナーはフォース？'), ('¡Eso es! La fila completa empuja.', "That's it! The whole line pushes.", '对了！整排人都在推。', 'そのとおり！列ぜんぶがおすんだ。'), ('Con primera ocupada, el de segunda también está forzado.', 'With first taken, the runner on second is forced too.', '一垒有人，二垒的跑垒员也被封了。', '一塁にランナーがいれば、二塁のランナーもフォースだよ。'), opts={'a': ('Sí, lo empujan el de primera y el bateador', 'Yes, the runner on first and the batter push him', '是，一垒的跑垒员和击球员在推他', 'うん、一塁のランナーとバッターがおしている'), 'b': ('No', 'No', '不是', 'ちがう'), 'c': ('Solo si corre rápido', 'Only if he runs fast', '只有他跑得快才是', '速く走るときだけ')}), '3': act(('Para saber si un corredor está forzado, hay que mirar si la base de atrás está ocupada', 'To know if a runner is forced, you look at whether the base behind him is taken', '要知道跑垒员是不是被封杀，就看他后面的垒上有没有人', 'ランナーがフォースかどうかは、うしろの塁にランナーがいるかを見ればわかる'), ('¡Bien! Esa es la clave.', "Good! That's the key.", '很好！这就是关键。', 'いいね！それがポイント。'), ('Verdadero: mira atrás.', 'True: look behind.', '这是对的：往后看。', '正しいよ：うしろを見よう。')), '4': act(('Corredor solo en tercera. Para hacerlo out entre bases hay que:', 'Runner alone on third. To get him out between bases you have to:', '只有三垒有跑垒员。要在两垒之间让他出局，你要：', '三塁だけにランナー。塁のあいだでアウトにするには：'), ('¡Correcto! Nunca está forzado.', "Correct! He's never forced.", '正确！他永远不会被封。', '正解！フォースになることはない。'), ('El de tercera jamás está forzado: se toca.', 'The runner on third alone is never forced: you tag him.', '单独在三垒的跑垒员不会被封：要碰他。', '三塁だけのランナーはフォースにならない：タッチするんだ。'), opts={'a': ('Tocarlo con la bola', 'Tag him with the ball', '用球碰他', 'ボールでタッチする'), 'b': ('Pisar tercera', 'Step on third', '踩三垒', '三塁をふむ'), 'c': ('Pisar home', 'Step on home', '踩本垒', 'ホームをふむ')}), '5': act(('Corredores en primera y segunda. Toca al corredor que está forzado a ir a tercera', 'Runners on first and second. Tap the runner who is forced to go to third', '一垒和二垒有跑垒员。点一下被迫要跑向三垒的跑垒员', '一塁と二塁にランナー。三塁へ行かないといけないランナーをタッチしよう'), ('¡Bien! Lo empuja la fila.', 'Good! The line pushes him.', '很好！后面的人在推他。', 'いいね！列がおしている。'), ('El de segunda, empujado por el de primera.', 'The one on second, pushed by the runner on first.', '二垒的那个，被一垒的跑垒员推着。', '一塁のランナーにおされている、二塁のランナーだよ。'), answer=('El corredor de segunda', 'The runner on second', '二垒的跑垒员', '二塁のランナー')), '6': act(('Corredor solo en segunda: el defensor pisa tercera con la bola, pero no tocó al corredor, que volvió a segunda. ¿Qué canta?', "Runner alone on second: the fielder steps on third with the ball but doesn't tag the runner, who goes back to second. What does the umpire call?", '只有二垒有跑垒员：防守球员拿着球踩了三垒，但没有碰跑垒员，跑垒员回到了二垒。裁判会判什么？', '二塁だけにランナー。守備の選手がボールを持って三塁をふんだけど、ランナーにタッチせず、ランナーは二塁にもどった。審判は何とコールする？'), ('¡Safe! Había que tocarlo.', 'Safe! He had to be tagged.', '安全上垒！本来要碰他才行。', 'セーフ！タッチしないといけなかった。'), ('Si no está forzado, pisar la base no sirve.', "If he isn't forced, stepping on the base doesn't work.", '如果不是封杀，踩垒包没用。', 'フォースでなければ、塁をふんでもだめ。'), opts={'a': ('¡Safe! No estaba forzado', "Safe! He wasn't forced", '安全上垒！他不是被封杀', 'セーフ！フォースじゃなかった'), 'b': ('¡Out!', 'Out!', '出局！', 'アウト！'), 'c': ('¡Foul!', 'Foul!', '界外球！', 'ファウル！')})})
map_titles['6.4'] = ('¿Forzado o no?', 'Forced or not?', '是封杀还是不是？', 'フォース？それともちがう？')
lesson('6.5', ('El doble play y la jugada de selección', "The double play and the fielder's choice", '双杀和野手选择', 'ダブルプレーとフィールダースチョイス'), ('Entender el doble play (dos outs en una jugada, casi siempre segunda y primera) y la jugada de selección: la defensa elige buscar otro out y el bateador llega a primera sin hit.', "Understand the double play (two outs on one play, usually at second and first) and the fielder's choice: the defense chooses to go for another out and the batter reaches first without a hit.", '明白双杀（一次防守制造两个出局，通常在二垒和一垒）和野手选择：防守选择去抓另一个出局，击球员没有安打也上了一垒。', 'ダブルプレー（1つのプレーで2つアウト、ふつうは二塁と一塁）と、フィールダースチョイス（守備がほかのアウトをねらって、バッターがヒットなしで一塁に着く）を知ろう。'), [('¿Dos outs con un solo batazo? Se llama doble play, en inglés double play.', "Two outs with a single batted ball? It's called a double play.", '一次击球两个出局？这叫双杀，英语叫 double play。', '1つの打球で2つアウト？ダブルプレー、英語で double play というよ。'), ('La receta: corredor en primera, rolling al cuadro, tiro a segunda para el primer out y ¡tiro a primera para el segundo!', 'The recipe: runner on first, ground ball to the infield, throw to second for the first out and a throw to first for the second!', '配方是：一垒有跑垒员，滚地球打到内野，传二垒造成第一个出局，再传一垒造成第二个！', 'つくり方：一塁にランナー、内野へのゴロ、二塁に投げて1つ目のアウト、そして一塁に投げて2つ目！'), ('Por eso se anota 6-4-3 y cosas así, como verás en el Nivel 8.', "That's why it's scored 6-4-3 and things like that, as you'll see in Level 8.", '所以记录时会写 6-4-3 之类的，你会在第 8 级看到。', 'だから 6-4-3 のように記録するんだ。レベル8で見るよ。'), ('Y escucha esta otra: a veces la defensa elige tirar a otra base y el bateador llega a primera.', 'And listen to this one: sometimes the defense chooses to throw to another base and the batter reaches first.', '再听这个：有时防守选择传向另一个垒，击球员就上了一垒。', 'それからこれも聞いて：守備がほかの塁に投げることを選んで、バッターが一塁に着くことがある。'), ("Eso no es hit ni error: es jugada de selección, en inglés fielder's choice.", "That's not a hit or an error: it's a fielder's choice.", "这不是安打，也不是失误：这是野手选择，英语叫 fielder's choice。", "それはヒットでもエラーでもない：フィールダースチョイス、英語で fielder's choice。"), ('La defensa eligió, y le salió o no le salió.', "The defense made a choice, and it worked or it didn't.", '防守做了选择，成功或者没成功。', '守備が選んだ。うまくいくこともあれば、いかないこともある。')], {'1': act(('¿Qué es un doble play?', 'What is a double play?', '什么是双杀？', 'ダブルプレーって何？'), ('¡Eso es! Double play.', "That's it! Double play.", '对了！双杀。', 'そのとおり！ダブルプレー。'), ('Dos outs, una jugada.', 'Two outs, one play.', '两个出局，一次防守。', '2つアウト、1つのプレー。'), opts={'a': ('Dos outs en una misma jugada', 'Two outs on the same play', '同一次防守中两个出局', '1つのプレーで2つアウト'), 'b': ('Dos jonrones', 'Two home runs', '两个本垒打', 'ホームラン2本'), 'c': ('Dos lanzamientos', 'Two pitches', '两次投球', '投球2回')}), '2': act(('Receta clásica del doble play: corredor en primera y rolling. La defensa tira:', 'Classic double play recipe: runner on first and a ground ball. The defense throws:', '经典双杀配方：一垒有跑垒员，滚地球。防守传球：', 'ダブルプレーの基本：一塁にランナーとゴロ。守備が投げるのは：'), ('¡Correcto! Segunda, primera: dos outs.', 'Correct! Second, first: two outs.', '正确！二垒、一垒：两个出局。', '正解！二塁、一塁：2つアウト。'), ('El camino corto: 6-4-3.', 'The short way: 6-4-3.', '最短的路线：6-4-3。', '近い道：6-4-3。'), opts={'a': ('A segunda y después a primera', 'To second and then to first', '先传二垒再传一垒', '二塁へ、そのあと一塁へ'), 'b': ('Dos veces a home', 'Twice to home', '两次传本垒', 'ホームへ2回'), 'c': ('A los jardines', 'To the outfield', '传向外野', '外野へ')}), '3': act(('La defensa tira a segunda buscando un out y el bateador llega a primera. Llegó por:', 'The defense throws to second going for an out and the batter reaches first. He got there on:', '防守传二垒去抓出局，击球员上了一垒。他是靠什么上垒的：', '守備がアウトをねらって二塁に投げ、バッターは一塁に着いた。バッターが着いたのは：'), ('¡Eso es! La defensa eligió.', "That's it! The defense chose.", '对了！是防守做了选择。', 'そのとおり！守備が選んだ。'), ("Fielder's choice: eligieron otro out.", "Fielder's choice: they chose another out.", '野手选择：他们选择抓另一个出局。', 'フィールダースチョイス：ほかのアウトを選んだんだ。'), opts={'a': ("Jugada de selección (fielder's choice)", "A fielder's choice", "野手选择 (fielder's choice)", "フィールダースチョイス (fielder's choice)"), 'b': ('Un hit limpio', 'A clean hit', '干净的安打', 'きれいなヒット'), 'c': ('Un error siempre', 'Always an error', '一定是失误', 'いつもエラー')}), '4': act(('Para un doble play por el suelo casi siempre hace falta un corredor forzado', 'A double play on the ground almost always needs a forced runner', '滚地球双杀几乎总是需要一个被封的跑垒员', 'ゴロのダブルプレーには、ほとんどいつもフォースのランナーが必要'), ('¡Bien! Sin corredor forzado no hay receta.', 'Good! No forced runner, no recipe.', '很好！没有被封杀的跑垒员，就没有这个配方。', 'いいね！フォースのランナーがいなければ、つくれない。'), ('Verdadero: el doble play nace del corredor forzado.', 'True: the double play starts with a forced runner.', '这是对的：双杀来自被封杀的跑垒员。', '正しいよ：ダブルプレーはフォースのランナーから生まれるんだ。')), '5': act(('Tiro a segunda: out. Tiro a primera: out. ¿Cuántos outs cantó el umpire en la jugada?', 'Throw to second: out. Throw to first: out. How many outs did the umpire call on the play?', '传二垒：出局。传一垒：出局。这次防守裁判判了几个出局？', '二塁へ送球：アウト。一塁へ送球：アウト。このプレーで審判は何回アウトとコールした？'), ('¡Doble play! Dos outs.', 'Double play! Two outs.', '双杀！两个出局。', 'ダブルプレー！2つアウト。'), ('Dos cantos de out en una jugada.', 'Two out calls on one play.', '一次防守判了两个出局。', '1つのプレーで2回のアウト。'), opts={'a': ('Dos outs', 'Two outs', '两个出局', '2つ'), 'b': ('Un out', 'One out', '一个出局', '1つ'), 'c': ('Ninguno', 'None', '没有', 'なし')}), '6': act(('En la jugada de selección, el bateador llega a primera porque:', "On a fielder's choice, the batter reaches first because:", '野手选择时，击球员能上一垒是因为：', 'フィールダースチョイスでバッターが一塁に着くのは：'), ('¡Correcto! Elección de la defensa.', "Correct! The defense's choice.", '正确！是防守的选择。', '正解！守備の選択。'), ('No es hit: la defensa eligió.', "It's not a hit: the defense chose.", '这不是安打：是防守做了选择。', 'ヒットじゃない：守備が選んだんだ。'), opts={'a': ('La defensa prefirió buscar otro out', 'The defense chose to go for another out', '防守选择去抓另一个出局', '守備がほかのアウトをねらったから'), 'b': ('La bola salió del campo', 'The ball left the field', '球飞出了球场', 'ボールがグラウンドの外に出たから'), 'c': ('El pitcher lo dejó', 'The pitcher let him', '投手让他上的', 'ピッチャーが行かせたから')})})
map_titles['6.5'] = ('El doble play y la jugada de selección', "The double play and the fielder's choice", '双杀和野手选择', 'ダブルプレーとフィールダースチョイス')
exams_v3['6'] = {'1': {'q': ('Batazo atrapado en el aire antes de picar:', 'Batted ball caught in the air before it bounces:', '击出的球在落地前被空中接住：', '地面に落ちる前に空中でとった打球は：'), 'opts': {'a': ('Out del bateador', 'The batter is out', '击球员出局', 'バッターのアウト'), 'b': ('Hit', 'Hit', '安打', 'ヒット'), 'c': ('Bola', 'Ball', '坏球', 'ボール')}}, '2': {'q': ('La bola pica primero y luego la toman. ¿Es atrapada para out?', 'The ball bounces first and then they pick it up. Is it a catch for an out?', '球先落地，然后被捡起来。这算接住出局吗？', 'ボールが先にはずんで、そのあとひろった。アウトになるキャッチ？'), 'opts': {'a': ('No', 'No', '不算', 'ちがう'), 'b': ('Sí', 'Yes', '算', 'うん'), 'c': ('A veces', 'Sometimes', '有时候算', 'ときどき')}}, '3': {'q': ('Toca al jugador que atrapa un elevado lejos, en los jardines', 'Tap the player who catches a long fly ball, in the outfield', '点一下在外野接远处高飞球的球员', '外野で遠いフライをとる選手をタッチしよう'), 'answer': ('Un jardinero', 'An outfielder', '外野手', '外野手')}, '4': {'q': ('Verdadero o falso: si la bola te rebota en el guante y cae al suelo, igual es out', "True or false: if the ball bounces off your glove and falls to the ground, it's still an out", '对还是错：球从你的手套弹出掉到地上，照样出局', '○か×か：ボールがグラブではねて地面に落ちても、アウトになる')}, '5': {'q': ('Corredor en primera y batazo por el suelo. El defensor con la bola pisa segunda antes que el corredor. ¿Qué pasa?', 'Runner on first and a ground ball. The fielder with the ball steps on second before the runner gets there. What happens?', '一垒有人，击出地滚球。拿着球的防守球员在跑垒员之前踩到二垒。会怎样？', '一塁にランナー、打球はゴロ。ボールを持った守備の選手が、ランナーより先に二塁をふんだ。どうなる？'), 'opts': {'a': ('Out forzado', 'Force out', '封杀出局', 'フォースアウト'), 'b': ('Safe', 'Safe', '安全上垒', 'セーフ'), 'c': ('No pasa nada', 'Nothing happens', '什么都不会发生', '何も起きない')}}, '6': {'q': ('Verdadero o falso: en un out forzado hay que tocar al corredor con la bola', 'True or false: on a force out, you have to tag the runner with the ball', '对还是错：封杀时必须用球触碰跑垒员', '○か×か：フォースアウトでは、ランナーにボールでタッチしないといけない')}, '7': {'q': ('El corredor no está obligado a correr. ¿Cómo lo sacas out?', "The runner isn't forced to run. How do you get him out?", '跑垒员不是被迫跑垒。你怎么让他出局？', 'ランナーは走らなくてもいい。どうやってアウトにする？'), 'opts': {'a': ('Tocándolo con la bola', 'Tag him with the ball', '用球触碰他', 'ボールでタッチする'), 'b': ('Pisando cualquier base', 'Step on any base', '随便踩一个垒', 'どこかの塁をふむ'), 'c': ('Gritando «¡out!»', 'Yell "Out!"', '大喊“出局！”', '「アウト！」とさけぶ')}}, '8': {'q': ('Verdadero o falso: si el corredor está parado sobre su base, tocarlo no lo saca out', "True or false: if the runner is standing on his base, tagging him doesn't get him out", '对还是错：跑垒员站在垒包上时，触碰他不会让他出局', '○か×か：ランナーが塁の上に立っていたら、タッチしてもアウトにならない')}, '9': {'q': ('Hay corredor en primera y batean un rolling. ¿El corredor de primera está forzado a correr?', "There's a runner on first and the batter hits a grounder. Is the runner on first forced to run?", '一垒有跑垒员，打者击出地滚球。一垒跑垒员是被迫跑垒吗？', '一塁にランナーがいて、打球はゴロ。一塁ランナーはフォースで走らないといけない？'), 'opts': {'a': ('Sí, porque el bateador viene detrás', 'Yes, because the batter is coming behind him', '是，因为击球员在后面跑过来', 'うん、うしろからバッターが来るから'), 'b': ('No, nunca', 'No, never', '不是，从来不是', 'ううん、ぜったいちがう'), 'c': ('Solo si él quiere', 'Only if he wants to', '只有他想跑才跑', '走りたいときだけ')}}, '10': {'q': ('Corredor solo en segunda, primera vacía, y batean un rolling. Para sacarlo out en tercera hay que:', 'Runner only on second, first base empty, and a ground ball. To get him out at third, you have to:', '只有二垒有跑垒员，一垒空着，打者击出地滚球。要在三垒让他出局，必须：', '二塁だけにランナー、一塁はあいていて、打球はゴロ。三塁でアウトにするには：'), 'opts': {'a': ('Tocarlo con la bola', 'Tag him with the ball', '用球触碰他', 'ボールでタッチする'), 'b': ('Pisar tercera', 'Step on third', '踩三垒', '三塁をふむ'), 'c': ('Pisar segunda', 'Step on second', '踩二垒', '二塁をふむ')}}, '11': {'q': ('¿Qué es un doble play?', 'What is a double play?', '什么是双杀？', 'ダブルプレーって何？'), 'opts': {'a': ('Dos outs en una sola jugada', 'Two outs on one play', '一次比赛动作拿到两个出局', '1つのプレーで2つのアウト'), 'b': ('Dos hits seguidos', 'Two hits in a row', '连续两支安打', '2本続けてのヒット'), 'c': ('Dos strikes', 'Two strikes', '两个好球', '2ストライク')}}, '12': {'q': ('La defensa elige sacar out a otro corredor y el bateador llega a primera. ¿Es hit?', 'The defense chooses to get another runner out, and the batter reaches first. Is it a hit?', '防守方选择让另一名跑垒员出局，击球员上了一垒。这算安打吗？', '守備がほかのランナーをアウトにすることを選んで、バッターは一塁に着いた。これはヒット？'), 'opts': {'a': ('No, es jugada de selección', "No, it's a fielder's choice", '不算，是野手选择', 'ちがう、フィルダースチョイス'), 'b': ('Sí, es hit', "Yes, it's a hit", '算，是安打', 'うん、ヒット'), 'c': ('Es error', "It's an error", '是失误', 'エラー')}}}
