levels['7'] = dict(title=('El corredor en base', 'The runner on base', '垒上的跑垒员', '塁上のランナー'), badge=('Pies Rápidos', 'Fast Feet', '飞毛腿', 'はやあし'))
lesson('7.1', ('Safe en la base: tu lugar seguro', 'Safe on the base: your safe spot', '在垒上安全：你的安全区', '塁の上はセーフ：君の安全地帯'), ('Entender que parado sobre su base el corredor está a salvo, que en una base solo puede haber un corredor y qué pasa si dos coinciden en la misma.', 'Understand that standing on the base the runner is safe, that only one runner can be on a base and what happens if two end up on the same one.', '明白站在垒包上的跑垒员是安全的，一个垒包上只能有一个跑垒员，以及两个跑垒员到了同一个垒会怎样。', '塁の上に立っていればランナーはセーフ、1つの塁にはランナーは1人だけ、2人が同じ塁に来たらどうなるかを知ろう。'), [('Tu base es tu lugar seguro.', 'Your base is your safe spot.', '垒包是你的安全区。', '塁は君の安全地帯。'), ('Parado sobre ella, con la bola viva, nadie te puede hacer out tocándote.', 'Standing on it, with the ball live, nobody can tag you out.', '站在上面，就算是活球，谁也不能碰你让你出局。', 'その上に立っていれば、ボールインプレーでも、タッチでアウトにはできないよ。'), ('Pero la base es para uno solo: en una base no pueden vivir dos corredores.', "But it only has room for one: two runners can't share a base.", '但一个垒只能有一个人：一个垒包上不能有两个跑垒员。', 'でも塁は1人用：1つの塁に2人のランナーは住めない。'), ('Si el de atrás te alcanza en la misma base, uno de los dos sobra, y casi siempre el que llegó de atrás es el que está en peligro, porque el de adelante ya era dueño de esa base.', 'If the runner behind catches you on the same base, one of you is extra, and almost always the one who came from behind is in danger, because the runner ahead already owned that base.', '如果后面的跑垒员追上你，到了同一个垒，就多出一个人，而且几乎总是后来的那个有危险，因为前面的人本来就是这个垒的主人。', 'うしろのランナーが同じ塁に来たら、1人よけい。たいてい、あぶないのはあとから来たランナー。前のランナーがもうその塁の持ち主だからね。'), ('Una base, un corredor.', 'One base, one runner.', '一个垒，一个跑垒员。', '1つの塁に、ランナー1人。')], {'1': act(('Parado sobre tu base, ¿te pueden hacer out tocándote con la bola?', 'Standing on your base, can they get you out by tagging you with the ball?', '站在你的垒包上，对方能用球碰你让你出局吗？', '自分の塁の上に立っていたら、ボールでタッチされてアウトになる？'), ('¡Eso es! Casa segura.', "That's it! Your safe spot.", '对了！安全区。', 'そのとおり！安全地帯。'), ('Sobre tu base estás a salvo.', "On your base you're safe.", '在你的垒包上你是安全的。', '塁の上ならセーフだよ。'), opts={'a': ('No, es mi lugar seguro', "No, it's my safe spot", '不能，这是我的安全区', 'ならない、ぼくの安全地帯だから'), 'b': ('Sí, siempre', 'Yes, always', '能，一直都能', 'なる、いつも'), 'c': ('Solo el pitcher', 'Only the pitcher can', '只有投手能', 'ピッチャーだけできる')}), '2': act(('En una base pueden estar dos corredores a la vez sin problema', 'Two runners can be on one base at the same time without a problem', '两个跑垒员可以同时在一个垒包上，没问题', '1つの塁に2人のランナーが同時にいても問題ない'), ('¡Bien! Una base, un corredor.', 'Good! One base, one runner.', '很好！一个垒，一个跑垒员。', 'いいね！1つの塁に1人。'), ('Falso: la base es para uno solo.', 'False: one base, one runner.', '错：一个垒只能有一个跑垒员。', 'まちがい：塁は1人用だよ。')), '3': act(('Dos corredores coinciden en segunda. ¿Quién está en peligro?', 'Two runners end up on second. Who is in danger?', '两个跑垒员到了二垒。谁有危险？', '2人のランナーが二塁に来た。あぶないのはどっち？'), ('¡Correcto! El dueño era el primero.', 'Correct! The first one owned it.', '正确！先到的才是主人。', '正解！先にいたほうが持ち主。'), ('El de atrás no tenía lugar ahí.', 'That base already belonged to the runner ahead.', '后来的跑垒员在那里没有位置。', 'あとから来たランナーには、そこに場所がなかったんだ。'), opts={'a': ('El que llegó de atrás', 'The one who came from behind', '后来的那个', 'あとから来たランナー'), 'b': ('El que ya estaba', 'The one who was already there', '本来就在那里的那个', 'もともといたランナー'), 'c': ('Ninguno', 'Neither', '两个都没有', 'どちらでもない')}), '4': act(('Toca el lugar seguro del corredor que está en tercera', 'Tap the safe spot of the runner on third', '点一下三垒跑垒员的安全区', '三塁にいるランナーの安全地帯をタッチしよう'), ('¡Bien! Esa es su base.', "Good! That's his base.", '很好！那是他的垒。', 'いいね！そこが彼の塁だ。'), ('Parado ahí, está a salvo.', "Standing there, he's safe.", '站在那里，他是安全的。', 'そこに立っていればセーフ。'), answer=('Tercera base', 'Third base', '三垒', '三塁')), '5': act(('Estás parado en tu base y te tocan con la bola. ¿Qué canta el umpire?', "You're standing on your base and they tag you with the ball. What does the umpire call?", '你站在垒包上，被球碰到。裁判会判什么？', '自分の塁に立っていて、ボールでタッチされた。審判は何とコールする？'), ('¡Safe! Casa segura.', "Safe! You're on your base.", '安全上垒！安全区。', 'セーフ！安全地帯。'), ('En tu base no hay out por toque.', 'On your base there is no tag out.', '在你的垒包上，碰到也不会出局。', '塁の上ではタッチアウトにならないよ。'), opts={'a': ('¡Safe!', 'Safe!', '安全上垒！', 'セーフ！'), 'b': ('¡Out!', 'Out!', '出局！', 'アウト！'), 'c': ('¡Balk!', 'Balk!', '投手犯规！', 'ボーク！')}), '6': act(('Sales de tu base a mitad de camino y te tocan con la bola. ¿Qué pasa?', 'You leave your base, get halfway, and they tag you with the ball. What happens?', '你离开垒包跑到一半，被球碰到了。会怎样？', '塁をはなれて途中まで行き、ボールでタッチされた。どうなる？'), ('¡Correcto! Fuera de la base hay peligro.', "Correct! Off your base, you're in danger.", '正确！离开垒包就有危险。', '正解！塁の外はあぶない。'), ('Fuera de tu base, el toque sí es out.', 'Away from your base, the tag is an out.', '离开垒包，被碰到就出局。', '塁の外でタッチされたらアウトだよ。'), opts={'a': ('Out: saliste de tu lugar seguro', 'Out: you left your safe spot', '出局：你离开了安全区', 'アウト：安全地帯を出たから'), 'b': ('Nada', 'Nothing', '没事', '何もない'), 'c': ('Anotas', 'You score', '你得分', '得点')})})
map_titles['7.1'] = ('Safe en la base: tu lugar seguro', 'Safe on the base: your safe spot', '在垒上安全：你的安全区', '塁の上はセーフ：君の安全地帯')
lesson('7.2', ('Pisa y corre', 'Tag up', '触垒后起跑', 'タッチアップ'), ('Entender el pisa y corre (tag up): con un elevado atrapado, el corredor debe estar tocando su base al momento de la atrapada y solo entonces puede correr; si sale antes, puede ser out en apelación.', "Understand tagging up: on a caught fly ball, the runner has to be touching his base when it's caught and only then can run; if he leaves early, he can be called out on appeal.", '明白触垒后起跑：高飞球被接住时，跑垒员必须踩着自己的垒包，之后才能跑；如果提前离开，对方申诉就可能出局。', 'タッチアップを知ろう：フライがとられたとき、ランナーは自分の塁にふれていないといけない。それから走れる。早く出たら、アピールでアウトになることがある。'), [('Sale un elevado y tú estás en base.', "A fly ball goes up and you're on base.", '打出一个高飞球，你在垒上。', 'フライが上がって、君は塁にいる。'), ('Tu primer impulso es correr. ¡No!', 'Your first instinct is to run. No!', '你的第一反应是跑。不行！', 'まず走りたくなるよね。でもだめ！'), ('Si atrapan la bola y tú ya saliste, la defensa puede devolver la bola a tu base y eres out.', "If they catch the ball and you've already left, the defense can throw the ball back to your base and you're out.", '如果球被接住而你已经离开，防守可以把球传回你的垒，你就出局了。', 'ボールがとられて、君がもう出ていたら、守備がボールを君の塁にもどして、アウトになる。'), ('La jugada correcta se llama pisa y corre, en inglés tag up: te quedas tocando tu base, esperas la atrapada, y en el instante en que la bola toca el guante, ¡arrancas!', 'The right play is called tagging up: you stay touching your base, wait for the catch, and the instant the ball touches the glove, you go!', '正确的做法叫触垒后起跑，英语叫 tag up：你踩着自己的垒包，等球被接住，就在球碰到手套的那一刻，起跑！', '正しいプレーはタッチアップ、英語で tag up：塁にふれたままキャッチを待って、ボールがグラブにさわった瞬間に、スタート！'), ('Pisa, espera la atrapada y corre.', 'Touch, wait for the catch and run.', '踩垒，等接球，再跑。', 'ふんで、キャッチを待って、走る。')], {'1': act(('¿Qué es el pisa y corre (tag up)?', 'What is tagging up?', '什么是触垒后起跑 (tag up)？', 'タッチアップ (tag up) って何？'), ('¡Eso es! Tag up.', "That's it! Tag up.", '对了！触垒后起跑。', 'そのとおり！タッチアップ。'), ('Primero la atrapada, después tu arranque.', 'First the catch, then you go.', '先接球，再起跑。', 'まずキャッチ、それからスタート。'), opts={'a': ('Esperar tocando tu base la atrapada y arrancar después', 'Waiting on your base for the catch and running after', '踩着垒包等球被接住，然后再跑', '塁にふれてキャッチを待ち、そのあと走る'), 'b': ('Salir corriendo antes del batazo', 'Running off before the hit', '击球前就跑', '打つ前に走りだす'), 'c': ('Correr hacia atrás', 'Running backwards', '往回跑', 'うしろに走る')}), '2': act(('Puedes salir de tu base en cuanto el bateador hace swing', 'You can leave your base as soon as the batter swings', '击球员一挥棒，你就可以离开垒包', 'バッターがふったらすぐ、塁をはなれていい'), ('¡Bien! Hay que esperar la atrapada.', 'Good! You have to wait for the catch.', '很好！要等球被接住。', 'いいね！キャッチを待たないといけない。'), ('Falso: salir antes te pone en peligro.', 'False: leaving early puts you in danger.', '错：提前离开会让你有危险。', 'まちがい：早く出るとあぶないよ。')), '3': act(('Saliste antes de la atrapada y la bola fue atrapada. La defensa devuelve la bola a tu base. ¿Qué pasa?', 'You left before the catch and the ball was caught. The defense throws the ball back to your base. What happens?', '你在接球前离开了，球被接住。防守把球传回你的垒。会怎样？', 'キャッチの前に出て、ボールがとられた。守備がボールを君の塁にもどした。どうなる？'), ('¡Correcto! Salida temprana castigada.', 'Correct! Leaving early gets punished.', '正确！提前离开会受罚。', '正解！早く出るとアウトになる。'), ('Por eso se pisa y se espera.', "That's why you touch and wait.", '所以要踩垒等待。', 'だから、ふんで待つんだ。'), opts={'a': ('Eres out', "You're out", '你出局了', 'アウト'), 'b': ('Nada', 'Nothing', '没事', '何もない'), 'c': ('Anotas carrera', 'You score a run', '你得一分', '得点')}), '4': act(('Estás en tercera y sale un elevado a los jardines. Toca dónde debes estar al momento de la atrapada', "You're on third and a fly ball goes to the outfield. Tap where you have to be when it's caught", '你在三垒，打出一个飞向外野的高飞球。点一下接球时你应该在的地方', '君は三塁にいて、外野へフライが上がった。キャッチのときにいるべき場所をタッチしよう'), ('¡Bien! Pisando tercera, listo para arrancar.', 'Good! Touching third, ready to go.', '很好！踩着三垒，准备起跑。', 'いいね！三塁にふれて、スタートのじゅんび。'), ('Tu pie en la base hasta la atrapada.', 'Your foot stays on the base until the catch.', '接球前你的脚要留在垒包上。', 'キャッチまで足は塁の上だよ。'), answer=('Tercera base', 'Third base', '三垒', '三塁')), '5': act(('Atraparon el elevado y arrancaste justo al caer la bola en el guante, y llegaste a home. ¿Qué canta?', 'They caught the fly ball, you took off right as the ball landed in the glove, and you reached home. What does the umpire call?', '高飞球被接住，你在球落进手套的一瞬间起跑，跑回了本垒。裁判会判什么？', 'フライがとられて、ボールがグラブに入った瞬間にスタートし、ホームに着いた。審判は何とコールする？'), ('¡Safe! Pisa y corre perfecto.', 'Safe! Perfect tag up.', '安全上垒！完美的触垒后起跑。', 'セーフ！完ぺきなタッチアップ。'), ('Esperaste la atrapada: jugada legal.', 'You waited for the catch: a legal play.', '你等到接球了：合法的跑垒。', 'キャッチを待った：ルールどおりのプレー。'), opts={'a': ('¡Safe! Carrera válida', 'Safe! The run counts', '安全上垒！得分有效', 'セーフ！得点は有効'), 'b': ('¡Out!', 'Out!', '出局！', 'アウト！'), 'c': ('¡Foul!', 'Foul!', '界外球！', 'ファウル！')}), '6': act(('¿En qué instante exacto puedes arrancar en el pisa y corre?', 'At exactly what moment can you take off when tagging up?', '触垒后起跑时，你到底什么时候可以起跑？', 'タッチアップでスタートしていいのは、正確にはいつ？'), ('¡Correcto! Ese es el momento.', "Correct! That's the moment.", '正确！就是那一刻。', '正解！その瞬間だ。'), ('Bola en el guante: ¡a correr!', 'Ball in the glove: go!', '球进手套：跑！', 'ボールがグラブに入ったら：走れ！'), opts={'a': ('Cuando la bola toca el guante del defensor', "When the ball touches the fielder's glove", '球碰到防守球员手套的时候', 'ボールが守備の選手のグラブにさわったとき'), 'b': ('Cuando el bateador hace swing', 'When the batter swings', '击球员挥棒的时候', 'バッターがふったとき'), 'c': ('Cuando el público grita', 'When the crowd yells', '观众大喊的时候', 'お客さんがさけんだとき')})})
map_titles['7.2'] = ('Pisa y corre', 'Tag up', '触垒后起跑', 'タッチアップ')
lesson('7.3', ('Si la bola bateada te pega', 'If the batted ball hits you', '如果击出的球打到你', '打球が当たったら'), ('Aprender que si una bola bateada en territorio fair toca a un corredor antes de pasar a un defensor, el corredor es out y la bola queda muerta; y la excepción: si la bola ya pasó a un defensor (menos al pitcher) y ya nadie más puede jugarla, el corredor no es out y el juego sigue.', 'Learn that if a fair batted ball touches a runner before passing a fielder, the runner is out and the ball is dead; and the exception: if the ball has already passed a fielder (other than the pitcher) and no other fielder can play it, the runner is not out and play goes on.', '知道如果界内击球在经过防守球员之前碰到跑垒员，跑垒员出局，球成为死球（比赛停止）；还有例外：如果球已经经过了一名防守球员（投手除外），而且没有其他防守球员能处理，跑垒员就不出局，比赛继续。', 'フェアの打球が守備の選手を通りすぎる前にランナーにさわったら、ランナーはアウトでボールデッド。例外：ボールがもう守備の選手（ピッチャー以外）を通りすぎて、ほかにだれもとれないなら、ランナーはアウトにならず、プレーは続くことを知ろう。'), [('Vas corriendo y la bola bateada te pega.', "You're running and the batted ball hits you.", '你正在跑，击出的球打到了你。', '走っていたら、打球が当たった。'), ('Casi siempre es malo para ti: si la bola bateada en territorio fair te toca antes de pasar a un defensor, eres out y la bola queda muerta ahí mismo.', "It's almost always bad for you: if the fair ball touches you before passing a fielder, you're out and the ball is dead right there.", '这几乎总是对你不利：如果界内球在经过防守球员之前碰到你，你就出局，球当场成为死球（比赛停止）。', 'たいていは君に悪いこと：フェアのボールが守備の選手を通りすぎる前に君にさわったら、アウトで、その場でボールデッド。'), ('Pero hay una excepción que los grandes conocen: si la bola ya pasó a un defensor — que no sea el pitcher — y ya ningún otro defensor puede atraparla, y entonces te pega, no es tu culpa: no eres out y el juego sigue.', "But there's an exception the pros know: if the ball has already passed a fielder (not the pitcher) and no other fielder can catch it, and then it hits you, it's not your fault: you're not out and the game goes on.", '但有一个高手都知道的例外：如果球已经经过了一名防守球员（不能是投手），而且其他防守球员都接不到，这时才打到你，那不是你的错：你不出局，比赛继续。', 'でも、上手な人が知っている例外がある：ボールがもう守備の選手（ピッチャー以外）を通りすぎて、ほかのだれもとれないときに当たったら、君のせいじゃない。アウトにならず、プレーは続くよ。'), ('¿La bola venía «limpia» hacia ti? Out.', "Was the ball coming 'clean' at you? Out.", '球是“直接”冲你来的？出局。', 'ボールがまっすぐ君に来た？アウト。'), ('¿Ya había pasado a la defensa? Sigue jugando.', 'Had it already passed the defense? Keep playing.', '球已经过了防守？继续比赛。', 'もう守備を通りすぎていた？プレー続行。')], {'1': act(('La bola bateada te pega en el pie viniendo directa del bate, sin tocar a ningún defensor. ¿Qué pasa?', 'The batted ball hits your foot coming straight off the bat, without touching any fielder. What happens?', '击出的球直接从球棒飞来打到你的脚，没有碰到任何防守球员。会怎样？', '打球がバットからまっすぐ来て、守備のだれにもさわらずに君の足に当たった。どうなる？'), ('¡Correcto! Esa es la regla general.', "Correct! That's the general rule.", '正确！这是一般规则。', '正解！それがふつうのルール。'), ('Bola directa al corredor: out.', 'Ball straight at the runner: out.', '球直接打到跑垒员：出局。', 'まっすぐランナーに当たったら：アウト。'), opts={'a': ('Eres out y la bola queda muerta', "You're out and the ball is dead", '你出局，球成为死球（比赛停止）', 'アウトで、ボールデッド'), 'b': ('Nada, sigo corriendo', 'Nothing, I keep running', '没事，我继续跑', '何もない、走り続ける'), 'c': ('Anotas', 'You score', '你得分', '得点')}), '2': act(('La bola pasó rodando junto al campocorto, ya nadie puede jugarla, y después roza al corredor. ¿Qué pasa?', 'The ball rolled past the shortstop, nobody can play it, and then it brushes the runner. What happens?', '球从游击手身边滚过，没人能处理了，然后擦到跑垒员。会怎样？', 'ボールが遊撃手の横を通りすぎて、だれもとれなくなってから、ランナーにふれた。どうなる？'), ('¡Eso es! La excepción.', "That's it! The exception.", '对了！就是例外。', 'そのとおり！例外だ。'), ('Ya pasó a un defensor: no es culpa del corredor.', "It had already passed a fielder: not the runner's fault.", '球已经经过防守球员：不是跑垒员的错。', 'もう守備を通りすぎていた：ランナーのせいじゃない。'), opts={'a': ('No es out: el juego sigue', "It's not an out: play goes on", '不出局：比赛继续', 'アウトにならない：プレー続行'), 'b': ('Out automático', 'Automatic out', '自动出局', '自動的にアウト'), 'c': ('Balk', 'Balk', '投手犯规', 'ボーク')}), '3': act(('Si la bola bateada le pega al corredor, siempre es out sin excepción', 'If the batted ball hits the runner, it is always an out, with no exception', '如果击出的球打到跑垒员，总是出局，没有例外', '打球がランナーに当たったら、例外なくいつもアウト'), ('¡Bien! Existe la excepción.', 'Good! There is an exception.', '很好！有例外。', 'いいね！例外があるんだ。'), ('Falso: si ya pasó a un defensor, sigue el juego.', 'False: if it already passed a fielder, play goes on.', '错：如果已经经过防守球员，比赛继续。', 'まちがい：もう守備を通りすぎていたら、プレーは続くよ。')), '4': act(('Si la bola solo pasó junto a este defensor, la excepción NO vale. ¿Quién es?', 'If the ball only went past this fielder, the exception does NOT apply. Who is it?', '如果球只是经过这位防守球员，例外就不算数。是谁？', 'ボールがこの選手のそばを通っただけなら、例外にならない。だれ？'), ('¡Correcto! El pitcher no cuenta para la excepción.', "Correct! The pitcher doesn't count for the exception.", '正确！投手不算在例外里。', '正解！ピッチャーは例外に入らない。'), ('Si solo pasó al pitcher, el corredor igual es out si la bola le pega.', 'If it only passed the pitcher, the runner is still out if it hits him.', '如果球只经过了投手，打到跑垒员仍然出局。', 'ピッチャーを通りすぎただけなら、当たったランナーはやっぱりアウトだよ。'), opts={'a': ('El pitcher', 'The pitcher', '投手', 'ピッチャー'), 'b': ('El campocorto', 'The shortstop', '游击手', '遊撃手'), 'c': ('El segunda base', 'The second baseman', '二垒手', '二塁手')}), '5': act(('La bola le pegó al corredor antes de que cualquier defensor la tocara. ¿Qué canta el umpire?', 'The ball hit the runner before any fielder touched it. What does the umpire call?', '球在任何防守球员碰到之前打到了跑垒员。裁判会判什么？', 'どの守備の選手もさわる前に、ボールがランナーに当たった。審判は何とコールする？'), ('¡Out! Bola muerta en ese instante.', 'Out! Dead ball at that moment.', '出局！那一刻比赛停止。', 'アウト！その瞬間ボールデッド。'), ('Directa al corredor: out y todo se detiene.', 'Straight at the runner: out and everything stops.', '直接打到跑垒员：出局，一切停止。', 'まっすぐランナーに：アウトで、プレーは止まる。'), opts={'a': ('¡Out! Y bola muerta', 'Out! And dead ball', '出局！球成为死球（比赛停止）', 'アウト！そしてボールデッド'), 'b': ('¡Safe!', 'Safe!', '安全上垒！', 'セーフ！'), 'c': ('¡Foul!', 'Foul!', '界外球！', 'ファウル！')}), '6': act(('La bola ya pasó al segunda base y sigue rodando hacia el jardín. Toca por dónde sigue viva la jugada', 'The ball already passed the second baseman and keeps rolling into the outfield. Tap where the play is still alive', '球已经经过了二垒手，继续滚向外野。点一下比赛还在继续的地方', 'ボールがもう二塁手を通りすぎて、外野へ転がっている。プレーが続いている場所をタッチしよう'), ('¡Bien! Ahí la bola sigue viva.', 'Good! The ball is still alive there.', '很好！球在那里还是活球。', 'いいね！そこではボールはまだ生きている。'), ('Pasó al defensor: la jugada continúa hacia los jardines.', 'It passed the fielder: the play goes on toward the outfield.', '球经过了防守球员：比赛朝外野继续。', '守備を通りすぎた：プレーは外野へ続くよ。'), answer=('Los jardines, detrás del cuadro', 'The outfield, behind the infield', '外野，内野后面', '外野、内野のうしろ'))})
map_titles['7.3'] = ('Si la bola bateada te pega', 'If the batted ball hits you', '如果击出的球打到你', '打球が当たったら')
lesson('7.4', ('No pasar al de adelante: la fila', "Don't pass the runner ahead: the line", '不能超过前面的跑垒员：排队', '前のランナーを追いこさない：列'), ('Aprender que los corredores son una fila: nunca se puede pasar al corredor de adelante; pasar a otro corredor es out del que pasa.', 'Learn that runners are a line: you can never pass the runner ahead of you; passing another runner is an out for the one who passes.', '知道跑垒员是一排：永远不能超过前面的跑垒员；超过别的跑垒员，超过的人出局。', 'ランナーは列だと知ろう：前のランナーを追いこしてはいけない。追いこしたら、追いこしたランナーがアウト。'), [('Piensa en una fila en la tienda: nadie se cuela.', 'Think of a line at the store: nobody cuts in.', '想想商店里排队：没人能插队。', 'お店の列を思いうかべて：だれも横入りしない。'), ('En las bases es igual: los corredores son una fila: nadie se adelanta.', "On the bases it's the same: the runners are a line, nobody gets ahead.", '在垒上也一样：跑垒员是一排，不能超车。', '塁でも同じ：ランナーは列。追いこしはなし。'), ('Si el de adelante se frenó y tú llegas corriendo y lo pasas, el out eres tú, el que pasó.', "If the runner ahead stopped and you come running and pass him, you're the out, the one who passed.", '如果前面的人停下了，你跑过来超过了他，出局的是你，超车的那个。', '前のランナーが止まって、君が走ってきて追いこしたら、アウトは君。追いこしたほうだ。'), ('Por eso el corredor de atrás debe mirar siempre al de adelante: si él se detiene, tú también te detienes o regresas.', 'That is why the runner behind always has to watch the runner ahead: if he stops, you stop too or go back.', '所以后面的跑垒员要一直看着前面的人：他停，你也停，或者往回跑。', 'だから、うしろのランナーはいつも前のランナーを見る：前が止まったら、君も止まるか、もどるんだ。'), ('Una fila, en orden, sin colarse.', 'One line, in order, no cutting in.', '一排，按顺序，不插队。', '1つの列、順番どおり、横入りなし。')], {'1': act(('¿Qué pasa si pasas al corredor que va adelante de ti?', 'What happens if you pass the runner ahead of you?', '如果你超过了前面的跑垒员，会怎样？', '前のランナーを追いこしたら、どうなる？'), ('¡Correcto! Nada de colarse.', 'Correct! No cutting in.', '正确！不能插队。', '正解！横入りはだめ。'), ('En la fila nadie se adelanta: out el que pasa.', 'Nobody gets ahead in line: the one who passes is out.', '排队不能超车：超车的人出局。', '列は追いこせない：追いこした人がアウト。'), opts={'a': ('Eres out tú, el que pasó', "You're out, the one who passed", '你出局，超车的那个', 'アウトは君、追いこしたほう'), 'b': ('Es out el de adelante', 'The runner ahead is out', '前面的跑垒员出局', '前のランナーがアウト'), 'c': ('Nada', 'Nothing', '没事', '何もない')}), '2': act(('Los corredores pueden pasarse entre sí si uno es más rápido', 'Runners can pass each other if one is faster', '如果一个跑垒员更快，跑垒员之间可以互相超越', '速いランナーなら、ほかのランナーを追いこしてもいい'), ('¡Bien! La fila se respeta.', 'Good! The line is respected.', '很好！要守排队的规矩。', 'いいね！列を守ろう。'), ('Falso: ni el más rápido se cuela.', 'False: not even the fastest cuts in.', '错：再快也不能插队。', 'まちがい：いちばん速くても横入りはだめ。')), '3': act(('El corredor de adelante se frenó en tercera y tú vienes de segunda con todo. ¿Qué haces?', 'The runner ahead stopped at third and you are coming from second at full speed. What do you do?', '前面的跑垒员停在三垒，你正全速从二垒跑来。你怎么做？', '前のランナーが三塁で止まって、君は二塁から全力で来ている。どうする？'), ('¡Eso es! Mira siempre adelante.', "That's it! Always look ahead.", '对了！一直往前看。', 'そのとおり！いつも前を見よう。'), ('El de adelante manda tu velocidad.', 'The runner ahead sets your speed.', '前面的跑垒员决定你的速度。', '前のランナーが君のスピードを決めるんだ。'), opts={'a': ('Me detengo o regreso a segunda', 'I stop or go back to second', '我停下或者回二垒', '止まるか、二塁にもどる'), 'b': ('Lo paso y sigo a home', 'I pass him and keep going home', '我超过他，继续跑本垒', '追いこして、ホームへ'), 'c': ('Lo empujo', 'I push him', '我推他', '前のランナーをおす')}), '4': act(('Hay corredores en primera y segunda. Toca al corredor de adelante, el que manda en la fila', 'There are runners on first and second. Tap the runner ahead, the one who leads the line', '一垒和二垒有跑垒员。点一下前面的跑垒员，排在最前面的那个', '一塁と二塁にランナー。列の先頭の、前のランナーをタッチしよう'), ('¡Bien! Él va adelante.', 'Good! He is ahead.', '很好！他在前面。', 'いいね！そのランナーが前。'), ('El de segunda lidera la fila.', 'The runner on second leads the line.', '二垒的跑垒员排在最前面。', '二塁のランナーが列の先頭だよ。'), answer=('El corredor de segunda', 'The runner on second', '二垒的跑垒员', '二塁のランナー')), '5': act(('Pasaste al compañero que estaba frenado entre bases. ¿Qué canta el umpire para ti?', 'You passed your teammate who had stopped between bases. What does the umpire call for you?', '你超过了停在两垒之间的队友。裁判对你判什么？', '塁のあいだで止まっていた仲間を追いこした。審判は君に何とコールする？'), ('¡Out! Te colaste en la fila.', 'Out! You cut in line.', '出局！你插队了。', 'アウト！横入りしたね。'), ('Pasar a un corredor es out.', 'Passing a runner is an out.', '超过跑垒员就是出局。', 'ランナーを追いこすとアウト。'), opts={'a': ('¡Out!', 'Out!', '出局！', 'アウト！'), 'b': ('¡Safe!', 'Safe!', '安全上垒！', 'セーフ！'), 'c': ('¡Foul!', 'Foul!', '界外球！', 'ファウル！')}), '6': act(('¿Cuál imagen muestra la fila correcta?', 'Which picture shows the right line?', '哪张图是正确的排队？', '正しい列はどの絵？'), ('¡Correcto! En fila y en orden.', 'Correct! In line and in order.', '正确！排成一排，按顺序。', '正解！列になって、順番どおり。'), ('La fila se mantiene siempre.', 'The line always stays.', '一直要保持排队。', '列はいつも守るんだ。'), opts={'a': ('Dos corredores en orden, sin pasarse', 'Two runners in order, not passing', '两个跑垒员按顺序，没有超越', '2人のランナーが順番どおり、追いこしなし'), 'b': ('Un corredor pasando a otro', 'One runner passing another', '一个跑垒员超过另一个', '1人がもう1人を追いこしている'), 'c': ('Un corredor corriendo al revés', 'A runner running backwards', '一个跑垒员往回跑', '逆向きに走るランナー')})})
map_titles['7.4'] = ('No pasar al de adelante: la fila', "Don't pass the runner ahead: the line", '不能超过前面的跑垒员：排队', '前のランナーを追いこさない：列')
lesson('7.5', ('Cuándo correr: según los outs', 'When to run: it depends on the outs', '什么时候跑：根据出局数', 'いつ走る？アウトカウント次第'), ('Aprender a correr leyendo los outs: con dos outs se corre al contacto con cualquier batazo bueno; con menos de dos outs y un elevado, primero hay que mirar si lo atrapan.', "Learn to run by reading the outs: with two outs you run on contact with any fair ball; with fewer than two outs and a fly ball, first you have to see if it's caught.", '学会看出局数来跑垒：两出局时，任何界内击球一触球就跑；不到两出局又是高飞球时，要先看球有没有被接住。', 'アウトカウントを見て走ろう：2アウトなら、フェアの打球を打った瞬間に走る。2アウトより少なくてフライなら、まずとられるかを見る。'), [('No se corre igual siempre: depende de los outs.', "You don't always run the same way: it depends on the outs.", '跑垒不是每次都一样：要根据出局数。', 'いつも同じように走るわけじゃない：アウトカウント次第だよ。'), ('Con dos outs, corre al sonar el bate: si atrapan la bola, la entrada igual terminó, así que no pierdes nada corriendo con todo desde el batazo.', 'With two outs, run at the crack of the bat: if they catch the ball, the inning is over anyway, so you lose nothing by running all out from the hit.', '两出局时，球棒一响就跑：如果球被接住，这一局反正结束了，所以从击球开始全力跑，你什么也不会损失。', '2アウトなら、バットの音で走ろう：ボールがとられても、どうせイニングは終わり。だから打った瞬間から全力で走っても、何も損しない。'), ('Con menos de dos outs es distinto: si sale un elevado, primero mira si lo atrapan, porque si sales corriendo y lo atrapan, te pueden doblar en tu base.', "With fewer than two outs it's different: if there's a fly ball, first see if they catch it, because if you run and they catch it, they can double you off at your base.", '不到两出局就不一样了：如果是高飞球，先看有没有被接住，因为如果你跑了而球被接住，对方可以在你的垒上让你出局。', '2アウトより少ないときはちがう：フライなら、まずとられるかを見よう。走りだしてとられたら、自分の塁でアウトにされてしまうからね。'), ('¿Cuántos outs hay? Esa pregunta se hace antes de cada lanzamiento.', 'How many outs are there? You ask that before every pitch.', '现在几出局？每一球投出前都要问这个问题。', 'いま何アウト？その質問は、1球ごとに投げる前にするんだ。')], {'1': act(('Con dos outs, en cuanto el bateador conecta un batazo bueno, el corredor debe:', 'With two outs, as soon as the batter makes contact on a fair ball, the runner must:', '两出局时，击球员一打出界内球，跑垒员必须：', '2アウトで、バッターがフェアの打球を打ったら、ランナーは：'), ('¡Eso es! Con dos outs no hay nada que cuidar.', "That's it! With two outs there is nothing to protect.", '对了！两出局时没什么要顾忌的。', 'そのとおり！2アウトなら守るものはない。'), ('Dos outs: a correr al contacto.', 'Two outs: run on contact.', '两出局：一触球就跑。', '2アウト：打った瞬間に走る。'), opts={'a': ('Correr con todo desde el contacto', 'Run all out from contact', '从触球开始全力跑', '打った瞬間から全力で走る'), 'b': ('Esperar en la base', 'Wait on the base', '留在垒上等', '塁で待つ'), 'c': ('Caminar', 'Walk', '慢慢走', '歩く')}), '2': act(('Con un out y un elevado a los jardines, el corredor primero debe:', 'With one out and a fly ball to the outfield, the runner must first:', '一出局时打出飞向外野的高飞球，跑垒员要先：', '1アウトで外野へフライ。ランナーがまずすることは：'), ('¡Correcto! Puede haber pisa y corre.', 'Correct! There might be a tag up.', '正确！可能要触垒后起跑。', '正解！タッチアップかもしれない。'), ('Sin dos outs, el elevado se mira primero.', 'Without two outs, you watch the fly ball first.', '不到两出局，先看高飞球。', '2アウトでなければ、まずフライを見る。'), opts={'a': ('Mirar si lo atrapan antes de arrancar', 'See if it is caught before taking off', '起跑前先看有没有被接住', 'スタートする前に、とられるかを見る'), 'b': ('Salir corriendo sin mirar', 'Run without looking', '不看就跑', '見ずに走りだす'), 'c': ('Volver al dugout', 'Go back to the dugout', '回休息区', 'ダグアウトにもどる')}), '3': act(('Con dos outs, si atrapan el elevado, la entrada termina igual aunque el corredor se haya quedado', 'With two outs, if they catch the fly ball, the inning ends anyway even if the runner stayed', '两出局时，如果高飞球被接住，即使跑垒员没动，这一局也照样结束', '2アウトでフライがとられたら、ランナーが塁にいても、どうせイニングは終わる'), ('¡Bien! Por eso se corre.', "Good! That's why you run.", '很好！所以要跑。', 'いいね！だから走るんだ。'), ('Verdadero: la atrapada es el tercer out de todos modos.', 'True: the catch is the third out anyway.', '这是对的：接住反正就是第三个出局。', '正しいよ：キャッチはどうせ3つ目のアウト。')), '4': act(('Con dos outs saliste corriendo, anotaste, pero el jardinero atrapó el elevado un segundo antes. ¿Qué pasa con tu carrera?', 'With two outs you ran, you scored, but the outfielder caught the fly ball a second earlier. What happens to your run?', '两出局时你跑了，也跑回本垒，但外野手早一秒接住了高飞球。你的得分算吗？', '2アウトで走って得点したけど、外野手が1秒前にフライをとっていた。君の得点は？'), ('¡Exacto! El tercer out manda.', 'Exactly! The third out rules.', '没错！第三个出局说了算。', 'そのとおり！3つ目のアウトが優先。'), ('Si la atrapada llegó primero, la carrera no vale.', "If the catch came first, the run doesn't count.", '如果先接住了球，这一分就不算。', 'キャッチが先なら、得点は入らないよ。'), opts={'a': ('No cuenta: la atrapada fue el tercer out', "It doesn't count: the catch was the third out", '不算：接住的那一刻就是第三个出局', '入らない：キャッチが3つ目のアウト'), 'b': ('Cuenta igual', 'It counts anyway', '照样算', 'それでも入る'), 'c': ('Cuenta la mitad', 'It counts half', '算一半', '半分入る')}), '5': act(('Con dos outs y corredor en segunda, sale un rolling al jardín. Toca hasta dónde debe intentar llegar el corredor', 'With two outs and a runner on second, a ground ball goes into the outfield. Tap how far the runner should try to get', '两出局，二垒有跑垒员，滚地球打进外野。点一下跑垒员应该努力跑到的地方', '2アウトで二塁にランナー、ゴロが外野へ。ランナーがめざす場所をタッチしよう'), ('¡Bien! Con dos outs va por la carrera.', 'Good! With two outs he goes for the run.', '很好！两出局时他要去得分。', 'いいね！2アウトなら得点をねらう。'), ('Dos outs: de segunda a anotar.', 'Two outs: from second, go score.', '两出局：从二垒跑回去得分。', '2アウト：二塁から得点へ。'), answer=('Home', 'Home', '本垒', 'ホーム')), '6': act(('Antes de cada lanzamiento, el corredor inteligente se pregunta:', 'Before every pitch, the smart runner asks:', '每一球投出前，聪明的跑垒员会问：', '1球ごとに投げる前、かしこいランナーが考えるのは：'), ('¡Eso es! Todo depende de los outs.', "That's it! It all depends on the outs.", '对了！一切都看出局数。', 'そのとおり！ぜんぶアウトカウント次第。'), ('Los outs deciden cómo corres.', 'The outs decide how you run.', '出局数决定你怎么跑。', 'アウトカウントが走り方を決めるんだ。'), opts={'a': ('¿Cuántos outs hay?', 'How many outs are there?', '现在几出局？', 'いま何アウト？'), 'b': ('¿Qué hora es?', 'What time is it?', '现在几点？', 'いま何時？'), 'c': ('¿Quién mira?', "Who's watching?", '谁在看？', 'だれが見ている？')})})
map_titles['7.5'] = ('Cuándo correr: según los outs', 'When to run: it depends on the outs', '什么时候跑：根据出局数', 'いつ走る？アウトカウント次第')
exams_v3['7'] = {'1': {'q': ('Parado en tu base estás:', 'Standing on your base you are:', '站在你的垒包上，你是：', '自分の塁の上に立っていると：'), 'opts': {'a': ('A salvo (safe)', 'Safe', '安全 (safe)', 'セーフ (safe)'), 'b': ('Out', 'Out', '出局', 'アウト'), 'c': ('En foul', 'In foul territory', '在界外区', 'ファウルゾーン')}}, '2': {'q': ('¿Cuántos corredores pueden ocupar una base?', 'How many runners can be on one base?', '一个垒包上可以有几个跑垒员？', '1つの塁にランナーは何人いられる？'), 'opts': {'a': ('Uno', 'One', '一个', '1人'), 'b': ('Dos', 'Two', '两个', '2人'), 'c': ('Tres', 'Three', '三个', '3人')}}, '3': {'q': ('Si dos corredores llegan a la misma base, está en peligro:', 'If two runners reach the same base, the one in danger is:', '如果两个跑垒员到了同一个垒，有危险的是：', '2人のランナーが同じ塁に来たら、あぶないのは：'), 'opts': {'a': ('El que llegó de atrás', 'The one who came from behind', '后来的那个', 'あとから来たランナー'), 'b': ('El de adelante', 'The one ahead', '前面的那个', '前のランナー'), 'c': ('El más alto', 'The tallest one', '最高的那个', '背が高いほう')}}, '4': {'q': ('Toca el lugar seguro de un corredor en primera', 'Tap the safe spot of a runner on first', '点一下一垒跑垒员的安全区', '一塁のランナーの安全地帯をタッチしよう'), 'answer': ('Primera base', 'First base', '一垒', '一塁')}, '5': {'q': ('Con menos de dos outs, atrapan un elevado. ¿Cuándo puede correr el corredor a la siguiente base?', 'With fewer than two outs, a fly ball is caught. When can the runner go to the next base?', '少于两出局时，高飞球被接住了。跑垒员什么时候可以跑向下一个垒？', '2アウト未満でフライがとられた。ランナーはいつ次の塁へ走れる？'), 'opts': {'a': ('Después de la atrapada, tocando primero su base', 'After the catch, touching his base first', '球被接住以后，先踩住自己的垒', 'とったあと、まず自分の塁にふれてから'), 'b': ('Apenas batean', 'As soon as the ball is hit', '球一被击出就跑', '打った瞬間'), 'c': ('Nunca', 'Never', '永远不行', 'ぜったい走れない')}}, '6': {'q': ('Verdadero o falso: si el corredor sale antes de la atrapada, la defensa puede pedir el out en apelación', 'True or false: if the runner leaves before the catch, the defense can appeal for the out', '对还是错：如果跑垒员在接球前就离垒，防守方可以申诉让他出局', '○か×か：ランナーがキャッチの前に塁をはなれたら、守備はアピールでアウトにできる')}, '7': {'q': ('Una bola bateada en territorio fair le pega al corredor antes de pasar a un defensor. ¿Qué pasa?', 'A fair batted ball hits the runner before it gets past a fielder. What happens?', '界内击球在经过防守球员之前打到了跑垒员。会怎样？', 'フェアの打球が、守備の選手を通りすぎる前にランナーに当たった。どうなる？'), 'opts': {'a': ('El corredor es out', 'The runner is out', '跑垒员出局', 'ランナーはアウト'), 'b': ('Es hit', "It's a hit", '是安打', 'ヒット'), 'c': ('Es foul', "It's a foul", '是界外球', 'ファウル')}}, '8': {'q': ('Verdadero o falso: si la bola ya pasó junto al campocorto y nadie más puede jugarla, el corredor no es out si le pega', "True or false: if the ball already went past the shortstop and nobody else can play it, the runner isn't out if it hits him", '对还是错：如果球已经越过游击手，其他人也接不到，这时球打到跑垒员，他不出局', '○か×か：ボールがもう遊撃手を通りすぎて、ほかにだれもとれないなら、ランナーに当たってもアウトにならない')}, '9': {'q': ('Vas corriendo y pasas al corredor que va delante de ti. ¿Qué pasa?', "You're running and you pass the runner ahead of you. What happens?", '你在跑垒时超过了前面的跑垒员。会怎样？', '走っていて、前のランナーを追いこした。どうなる？'), 'opts': {'a': ('Tú eres out', "You're out", '你出局', '君がアウト'), 'b': ('Él es out', "He's out", '他出局', 'その人がアウト'), 'c': ('No pasa nada', 'Nothing happens', '什么都不会发生', '何も起きない')}}, '10': {'q': ('El corredor de adelante se detuvo. ¿Qué haces tú?', 'The runner ahead of you stopped. What do you do?', '前面的跑垒员停下来了。你怎么做？', '前のランナーが止まった。君はどうする？'), 'opts': {'a': ('Me detengo o regreso', 'I stop or go back', '我也停下或者跑回去', '止まるか、もどる'), 'b': ('Lo paso', 'I pass him', '我超过他', '追いこす'), 'c': ('Corro a home', 'I run home', '我跑回本垒', 'ホームへ走る')}}, '11': {'q': ('Hay dos outs y el bateador le pega a la bola. ¿Qué hace el corredor?', 'There are two outs and the batter hits the ball. What does the runner do?', '两出局时击球员击中了球。跑垒员怎么做？', '2アウトでバッターが打った。ランナーはどうする？'), 'opts': {'a': ('Corre enseguida, apenas hay contacto', 'Runs right away, as soon as the ball is hit', '球一被击中就马上跑', '打った瞬間にすぐ走る'), 'b': ('Espera a ver si la atrapan', "Waits to see if it's caught", '等着看球会不会被接住', 'とられるか見て待つ'), 'c': ('Se queda en su base', 'Stays on his base', '待在自己的垒上', '自分の塁にいる')}}, '12': {'q': ('Hay un out y batean un elevado. ¿Qué hace primero el corredor?', "There's one out and the batter hits a fly ball. What does the runner do first?", '一出局时打者击出高飞球。跑垒员先做什么？', '1アウトでフライが上がった。ランナーはまず何をする？'), 'opts': {'a': ('Mira si lo atrapan', "Watches to see if it's caught", '看球会不会被接住', 'とられるか見る'), 'b': ('Corre sin mirar', 'Runs without looking', '不看就跑', '見ないで走る'), 'c': ('Se sienta', 'Sits down', '坐下', 'すわる')}}}
