levels['8'] = dict(title=('Los números del juego', 'The numbers of the game', '比赛中的数字', '試合の数字'), badge=('Anotador Oficial', 'Official Scorer', '正式记录员', '公式記録員'))
lesson('8.1', ('Hit o error', 'Hit or error', '安打还是失误', 'ヒットかエラーか'), ('Distinguir con ejemplos simples: hit (llegas por tu buen batazo, sin que la defensa falle) de error (llegas o avanzas porque la defensa falló una jugada normal).', 'Tell apart, with simple examples: a hit (you get there with your good batted ball, without the defense failing) from an error (you get there or move up because the defense messed up a normal play).', '用简单的例子分清：安打（靠你的好球上垒，防守没有失误）和失误（因为防守没处理好一个普通的球，你才上垒或进垒）。', 'かんたんな例で見分けよう：ヒット（守備のミスなしに、いい打球で塁に着く）と、エラー（守備がふつうのプレーをミスしたから、塁に着いたり進んだりする）。'), [('Llegaste a primera y el anotador debe decidir: ¿fue hit o fue error?', 'You reached first and the scorer has to decide: was it a hit or an error?', '你上了一垒，记录员要决定：是安打还是失误？', '一塁に着いた。記録員が決める：ヒット？それともエラー？'), ('Si tu batazo pasó limpio, sin que nadie fallara, es hit, tuyo y merecido.', "If your batted ball went through clean, without anyone failing, it's a hit, and you earned it.", '如果你的球干净利落地穿过，没有人失误，就是安打，是你自己挣来的。', '打球がきれいに抜けて、だれもミスしていなければ、ヒット。君の力でとったものだ。'), ('Si el defensor dejó caer una bola fácil, o tiró muy mal una jugada normal, es error, en inglés error: llegaste con ayuda de la defensa.', "If the fielder dropped an easy ball, or threw very badly on a normal play, it's an error: you got there with help from the defense.", '如果防守球员漏接了一个容易的球，或者普通的球传得很差，就是失误，英语叫 error：你是靠防守“帮忙”上垒的。', '守備がかんたんなボールを落としたり、ふつうのプレーでひどい送球をしたら、エラー、英語で error：守備に助けられて着いたんだ。'), ('La pregunta del anotador es una sola: ¿un defensor normal habría hecho esa jugada?', 'The scorer asks just one question: would a normal fielder have made that play?', '记录员只问一个问题：一个普通的防守球员能处理好这个球吗？', '記録員が考えることは1つだけ：ふつうの守備の選手なら、そのプレーができた？'), ('Si sí y falló, error. Si tu batazo era imposible, hit.', 'If yes and he failed: error. If your batted ball was impossible: hit.', '能处理却没处理好：失误。你的球根本接不到：安打。', 'できたのにミスしたら、エラー。とれない打球だったら、ヒット。')], {'1': act(('Tu batazo pasó entre dos defensores que ni lo tocaron y llegaste a salvo. ¿Hit o error?', 'Your batted ball went between two fielders who never touched it and you got there safely. Hit or error?', '你的球从两名防守球员之间穿过，他们都没碰到，你安全上垒。安打还是失误？', '打球が2人の守備のあいだを、さわられずに抜けて、安全に着いた。ヒット？エラー？'), ('¡Eso es! Batazo limpio, hit.', "That's it! Clean hit.", '对了！干净的安打。', 'そのとおり！きれいなヒット。'), ('Sin falla de la defensa: hit.', 'No failure by the defense: hit.', '防守没有失误：安打。', '守備のミスなし：ヒット。'), opts={'a': ('Hit', 'Hit', '安打', 'ヒット'), 'b': ('Error', 'Error', '失误', 'エラー'), 'c': ('Foul', 'Foul', '界外球', 'ファウル')}), '2': act(('El jardinero dejó caer un elevado altísimo y fácil, y llegaste a segunda. ¿Hit o error?', 'The outfielder dropped a very high, easy fly ball and you reached second. Hit or error?', '外野手漏接了一个很高、很容易的高飞球，你跑到了二垒。安打还是失误？', '外野手がとても高くてかんたんなフライを落として、二塁まで行けた。ヒット？エラー？'), ('¡Correcto! Era una jugada normal.', 'Correct! It was a normal play.', '正确！那是一个普通的球。', '正解！ふつうのプレーだった。'), ('Bola fácil caída: error.', 'An easy ball dropped: error.', '容易的球没接住：失误。', 'かんたんなボールを落とした：エラー。'), opts={'a': ('Error', 'Error', '失误', 'エラー'), 'b': ('Hit', 'Hit', '安打', 'ヒット'), 'c': ('Jonrón', 'Home run', '本垒打', 'ホームラン')}), '3': act(('Un tiro muy desviado que deja llegar al bateador puede ser error', 'A very wild throw that lets the batter reach can be an error', '一个偏得很厉害、让击球员上垒的传球，可以算失误', '大きくそれた送球でバッターが塁に着いたら、エラーになることがある'), ('¡Bien! Tirar mal también es error.', 'Good! A bad throw is also an error.', '很好！传球不好也是失误。', 'いいね！悪い送球もエラー。'), ('Verdadero: el mal tiro cuenta como error.', 'True: the bad throw counts as an error.', '这是对的：坏传球算失误。', '正しいよ：悪い送球はエラーになる。')), '4': act(('¿Cuál imagen muestra un error?', 'Which picture shows an error?', '哪张图是失误？', 'エラーはどの絵？'), ('¡Eso es! Falla en jugada normal.', "That's it! A failure on a normal play.", '对了！普通的球没处理好。', 'そのとおり！ふつうのプレーのミス。'), ('Esa caída es el error clásico.', 'That drop is the classic error.', '那种漏接就是典型的失误。', 'その落球がエラーの代表だよ。'), opts={'a': ('Un defensor dejando caer un elevado fácil', 'A fielder dropping an easy fly ball', '防守球员漏接一个容易的高飞球', 'かんたんなフライを落とす守備の選手'), 'b': ('Una bola pasando limpia al jardín', 'A ball going clean into the outfield', '球干净地穿过到外野', 'きれいに外野へ抜けるボール'), 'c': ('Un jonrón sobre la valla', 'A home run over the fence', '飞过围墙的本垒打', 'フェンスをこえるホームラン')}), '5': act(('El anotador pregunta: el batazo era durísimo, pegó en el guante del campocorto y siguió. ¿Hit o error?', "The scorer asks: the ball was hit really hard, hit the shortstop's glove and kept going. Hit or error?", '记录员在问：这个球打得非常猛，打到游击手的手套后继续滚。安打还是失误？', '記録員が考える：とても強い打球が遊撃手のグラブに当たって、そのまま抜けた。ヒット？エラー？'), ('¡Correcto! Jugada imposible no es error.', "Correct! An impossible play isn't an error.", '正确！接不到的球不是失误。', '正解！とれないプレーはエラーじゃない。'), ('Si ni un experto la hacía, es hit.', "If not even an expert could make it, it's a hit.", '如果连高手都接不到，就是安打。', '上手な人でもとれないなら、ヒットだよ。'), opts={'a': ('Hit: era demasiado difícil', 'Hit: it was too hard', '安打：太难接了', 'ヒット：むずかしすぎた'), 'b': ('Error siempre', 'Always an error', '一定是失误', 'いつもエラー'), 'c': ('Nadie sabe', 'Nobody knows', '没人知道', 'だれにもわからない')}), '6': act(('La pregunta del anotador es:', "The scorer's question is:", '记录员要问的问题是：', '記録員が考えることは：'), ('¡Eso es! Así se decide.', "That's it! That's how it's decided.", '对了！就是这样决定的。', 'そのとおり！そうやって決めるんだ。'), ('Esa pregunta separa hit de error.', 'That question separates a hit from an error.', '这个问题能分清安打和失误。', 'その質問で、ヒットとエラーを分けるんだ。'), opts={'a': ('¿Un defensor normal habría hecho la jugada?', 'Would a normal fielder have made the play?', '一个普通的防守球员能处理好这个球吗？', 'ふつうの守備の選手なら、そのプレーができた？'), 'b': ('¿Quién gritó más?', 'Who yelled the loudest?', '谁喊得最大声？', 'だれがいちばん大きな声を出した？'), 'c': ('¿De qué color era la bola?', 'What color was the ball?', '球是什么颜色？', 'ボールは何色だった？')})})
map_titles['8.1'] = ('Hit o error', 'Hit or error', '安打还是失误', 'ヒットかエラーか')
lesson('8.2', ('Carrera impulsada', 'Run batted in', '打点', '打点'), ('Entender la carrera impulsada (RBI): cuando tu batazo, tu base por bolas con bases llenas o tu toque/elevado de sacrificio hace anotar a un compañero, esa carrera se te apunta a ti como impulsada.', 'Understand the run batted in (RBI): when your hit, your walk with the bases loaded or your sacrifice bunt or fly makes a teammate score, that run is credited to you as batted in.', '明白打点（RBI）：当你的安打、满垒时的四坏球保送，或者你的牺牲触击、牺牲高飞球让队友得分时，这一分就记在你名下，算作打点。', '打点（RBI）を知ろう：君のヒット、満塁での四球、犠牲バントや犠牲フライで仲間が得点したら、その得点は君の打点になる。'), [('Detrás de casi cada carrera hay alguien que la empujó.', 'Behind almost every run there is someone who drove it in.', '几乎每一分背后，都有人把它“推”回来。', 'ほとんどの得点のうしろには、それをおしこんだ人がいる。'), ('Si tu compañero anota gracias a tu batazo, esa carrera es tu carrera impulsada, en inglés run batted in, y se escribe RBI.', 'If your teammate scores thanks to your batted ball, that run is your run batted in, written RBI.', '如果你的队友靠你的击球得分，这一分就是你的打点，英语叫 run batted in，写作 RBI。', '仲間が君の打球のおかげで得点したら、それは君の打点。英語で run batted in、RBI と書くよ。'), ('Un sencillo que trae a un compañero: un RBI.', 'A single that brings in a teammate: one RBI.', '一个一垒安打送回一名队友：一个打点。', '仲間を1人かえすシングルヒット：打点1。'), ('Un jonrón con dos compañeros en base: tres RBI — y sí, tu propia carrera del jonrón también cuenta.', 'A home run with two teammates on base: three RBI — and yes, your own run counts too.', '两名队友在垒上时打出本垒打：三个打点——没错，你自己的那一分也算。', '2人の仲間が塁にいてホームラン：打点3。そう、ホームランの君自身の得点も数えるよ。'), ('Empujar carreras es el trabajo más querido del bateador.', "Driving in runs is the batter's favorite job.", '打回分数是击球员最喜欢的工作。', '得点をおしこむのは、バッターのいちばんうれしい仕事。')], {'1': act(('¿Qué es un RBI?', 'What is an RBI?', '什么是打点 (RBI)？', '打点 (RBI) って何？'), ('¡Eso es! Run batted in.', "That's it! Run batted in.", '对了！打点。', 'そのとおり！打点。'), ('RBI: carrera empujada por ti.', 'RBI: a run you drove in.', 'RBI：你打回来的分。', 'RBI：君がおしこんだ得点。'), opts={'a': ('Una carrera que anota un compañero gracias a tu bateo', 'A run a teammate scores thanks to your hitting', '因为你的击球，队友跑回来的一分', '君の打撃のおかげで仲間がとった得点'), 'b': ('Un tipo de guante', 'A kind of glove', '一种手套', 'グラブの種類'), 'c': ('Un lanzamiento', 'A pitch', '一种投球', '投球')}), '2': act(('Das un sencillo y tu compañero anota desde segunda. ¿Cuántos RBI?', 'You hit a single and your teammate scores from second. How many RBI?', '你打出一垒安打，队友从二垒跑回得分。几个打点？', 'シングルヒットを打って、仲間が二塁から得点した。打点はいくつ？'), ('¡Correcto! Un compañero, un RBI.', 'Correct! One teammate, one RBI.', '正确！一名队友，一个打点。', '正解！仲間1人で打点1。'), ('Cada compañero que traes es un RBI.', 'Each teammate you bring home is an RBI.', '你每送回一名队友，就是一个打点。', 'かえした仲間1人ごとに打点1だよ。'), opts={'a': ('Uno', 'One', '一个', '1'), 'b': ('Cero', 'Zero', '零个', '0'), 'c': ('Cinco', 'Five', '五个', '5')}), '3': act(('Con un jonrón solitario, el bateador también se apunta un RBI por su propia carrera', 'On a solo home run, the batter also gets an RBI for his own run', '打出个人本垒打（垒上没人）时，击球员自己的那一分也算一个打点', 'ソロホームランでも、バッター自身の得点で打点1がつく'), ('¡Bien! Su carrera también cuenta.', 'Good! His run counts too.', '很好！他自己的分也算。', 'いいね！自分の得点も数える。'), ('Verdadero: en el jonrón cuentas tú también.', 'True: on a home run you count too.', '这是对的：本垒打时你自己也算。', '正しいよ：ホームランでは君も数えるんだ。')), '4': act(('Jonrón con compañeros en primera y segunda. ¿Cuántos RBI?', 'Home run with teammates on first and second. How many RBI?', '一垒和二垒有队友时打出本垒打。几个打点？', '一塁と二塁に仲間がいてホームラン。打点はいくつ？'), ('¡Eso es! Tres carreras empujadas.', "That's it! Three runs driven in.", '对了！三个打点。', 'そのとおり！3点おしこんだ。'), ('Dos compañeros más tu carrera: tres.', 'Two teammates plus your run: three.', '两名队友加上你自己：三个。', '2人の仲間と君の得点：3。'), opts={'a': ('Tres: los dos compañeros y tú', 'Three: the two teammates and you', '三个：两名队友加上你', '3：2人の仲間と君'), 'b': ('Dos', 'Two', '两个', '2'), 'c': ('Uno', 'One', '一个', '1')}), '5': act(('Con bases llenas recibes base por bolas y un compañero anota empujado. El anotador te apunta:', 'With the bases loaded you get a walk and a teammate is forced home. The scorer credits you with:', '满垒时你被四坏球保送，一名队友被挤回本垒。记录员给你记：', '満塁で四球を選んで、仲間がおし出されて得点した。記録員が君につけるのは：'), ('¡Correcto! También empujaste esa carrera.', 'Correct! You drove that run in too.', '正确！那一分也是你打回来的。', '正解！その得点も君がおしこんだ。'), ('La base por bolas con bases llenas da RBI.', 'A walk with the bases loaded gives an RBI.', '满垒时的四坏球保送也算打点。', '満塁での四球も打点になるよ。'), opts={'a': ('Un RBI', 'One RBI', '一个打点', '打点1'), 'b': ('Un error', 'An error', '一个失误', 'エラー'), 'c': ('Nada', 'Nothing', '什么都不记', '何もなし')}), '6': act(('Tu sencillo trae a un compañero desde segunda. Toca la base donde anota ese compañero', 'Your single brings a teammate home from second. Tap the base where that teammate scores', '你的一垒安打把队友从二垒送回。点一下这名队友得分的垒', '君のシングルヒットで、仲間が二塁から帰ってくる。その仲間が得点する塁をタッチしよう'), ('¡Bien! Ahí se anota y nace tu RBI.', "Good! That's where the run scores and your RBI is born.", '很好！在那里得分，你的打点就诞生了。', 'いいね！そこで得点して、君の打点がうまれる。'), ('La carrera se anota pisando home.', 'The run scores by touching home.', '踩到本垒才算得分。', '得点はホームをふんで入るんだ。'), answer=('Home', 'Home', '本垒', 'ホーム'))})
map_titles['8.2'] = ('Carrera impulsada', 'Run batted in', '打点', '打点')
lesson('8.3', ('Leer el conteo: quién va ganando', "Reading the count: who's winning", '读懂球数：谁占上风', 'カウントを読む：どっちが有利？'), ('Leer el conteo como una historia: con ventaja del bateador (conteo de bateador, como 2-0 o 3-1) viene una recta por la zona; con ventaja del pitcher (conteo de pitcher, como 0-2 o 1-2) el bateador debe proteger. El conteo del pitcher (pitch count) es otra cosa: cuántos lanzamientos lleva, y solo importa para cuidar su brazo.', "Read the count as a story: when the batter is ahead (a hitter's count, like 2-0 or 3-1) a fast pitch comes through the zone; when the pitcher is ahead (a pitcher's count, like 0-2 or 1-2) the batter has to protect. The pitch count is something else: how many pitches the pitcher has thrown, and it only matters for taking care of his arm.", '把球数当成一个故事来读：击球员占上风（对打者有利的球数，比如 2-0 或 3-1）时，投手会把快球投进好球带；投手占上风（对投手有利的球数，比如 0-2 或 1-2）时，击球员要护好好球带。投球数是另一回事：投手投了多少球，只和保护他的手臂有关。', 'カウントを物語として読もう：バッターが有利（バッターカウント、2-0や3-1）なら、速い球がゾーンに来る。ピッチャーが有利（ピッチャーズカウント、0-2や1-2）なら、バッターはゾーンを守る。ピッチカウントは別のもの：ピッチャーが投げた球の数で、腕を守るためだけに使う。'), [('El conteo cuenta una historia: quién va ganando la pelea.', "The count tells a story: who's winning the battle.", '球数讲的是一个故事：谁在这场对决中占上风。', 'カウントは物語を語る：どっちが勝負で勝っているか。'), ("Si hay más bolas que strikes, como dos bolas y cero strikes, es un conteo de bateador, en inglés hitter's count: el pitcher necesita un strike y casi seguro tirará su mejor lanzamiento por la zona.", "If there are more balls than strikes, like two balls and no strikes, it's a hitter's count: the pitcher needs a strike and will almost surely throw his best pitch through the zone.", "如果坏球比好球多，比如两坏球零好球，就是对打者有利的球数，英语叫 hitter's count：投手需要一个好球，几乎一定会把他最好的球投进好球带。", "ボールがストライクより多い、たとえば2ボール0ストライクなら、バッターカウント、英語で hitter's count：ピッチャーはストライクがほしいから、きっといちばんいい球をゾーンに投げてくる。"), ("Si hay más strikes, como cero bolas y dos strikes, es un conteo de pitcher, pitcher's count: el bateador debe cuidar la zona y pelear cada lanzamiento.", "If there are more strikes, like no balls and two strikes, it's a pitcher's count: the batter has to protect the zone and battle every pitch.", "如果好球比较多，比如零坏球两好球，就是对投手有利的球数，pitcher's count：击球员要护好好球带，每一球都要拼。", "ストライクが多い、たとえば0ボール2ストライクなら、ピッチャーズカウント、pitcher's count：バッターはゾーンを守って、1球1球たたかうんだ。"), ('Y ojo, no confundas: el pitch count no es este conteo.', "And careful, don't mix it up: the pitch count is not this count.", '还要注意，别搞混了：投球数（pitch count）不是这个球数。', 'それから、まちがえないで：ピッチカウントは、このカウントじゃない。'), ('El pitch count es cuántos lanzamientos lleva el pitcher en el juego, y sirve para cuidar su brazo, como verás en el Nivel 11.', "The pitch count is how many pitches the pitcher has thrown in the game, and it's for taking care of his arm, as you'll see in Level 11.", '投球数是投手在这场比赛里投了多少球，用来保护他的手臂，你会在第 11 级看到。', 'ピッチカウントは、ピッチャーがその試合で投げた球の数。腕を守るために使うよ。レベル11で見よう。')], {'1': act(('Conteo 3-1, con ventaja de bolas. Es un conteo de:', 'A 3-1 count, ahead in balls. It is a count for the:', '球数 3-1，坏球领先。这是谁有利的球数：', 'カウント3-1、ボールが多い。これはだれのカウント？'), ('¡Eso es! Ventaja del bateador.', "That's it! The batter is ahead.", '对了！击球员占上风。', 'そのとおり！バッターが有利。'), ('Más bolas: conteo de bateador.', "More balls: a hitter's count.", '坏球多：对打者有利的球数。', 'ボールが多い：バッターカウント。'), opts={'a': ("Bateador (hitter's count)", "Batter (hitter's count)", '击球员（对打者有利的球数）', 'バッター（バッターカウント）'), 'b': ('Pitcher', 'Pitcher', '投手', 'ピッチャー'), 'c': ('Nadie', 'Nobody', '谁都不是', 'だれでもない')}), '2': act(('Conteo 0-2, sin bolas y con dos strikes. Es un conteo de:', 'A 0-2 count, no balls and two strikes. It is a count for the:', '球数 0-2，零坏球两好球。这是谁有利的球数：', 'カウント0-2、ボールなしで2ストライク。これはだれのカウント？'), ('¡Correcto! El bateador está contra la pared.', 'Correct! The batter is in a tough spot.', '正确！击球员被逼到墙角了。', '正解！バッターは追いこまれている。'), ('Dos strikes: ventaja del pitcher.', 'Two strikes: the pitcher is ahead.', '两好球：投手占上风。', '2ストライク：ピッチャーが有利。'), opts={'a': ("Pitcher (pitcher's count)", "Pitcher (pitcher's count)", '投手（对投手有利的球数）', 'ピッチャー（ピッチャーズカウント）'), 'b': ('Bateador', 'Batter', '击球员', 'バッター'), 'c': ('Empate', 'Tie', '平手', '引き分け')}), '3': act(('Pitch count y conteo del turno (bolas y strikes) son lo mismo', 'The pitch count and the count of the at-bat (balls and strikes) are the same thing', '投球数和这次打击的球数（坏球和好球）是同一回事', 'ピッチカウントと、打席のカウント（ボールとストライク）は同じもの'), ('¡Bien! Son dos cosas distintas.', 'Good! They are two different things.', '很好！它们是两回事。', 'いいね！2つは別のもの。'), ('Falso: pitch count cuenta los lanzamientos de todo el juego.', 'False: the pitch count counts the pitches of the whole game.', '错：投球数是整场比赛投的球数。', 'まちがい：ピッチカウントは試合ぜんぶの投球の数だよ。')), '4': act(('En un conteo de bateador, el pitcher casi seguro:', "In a hitter's count, the pitcher will almost surely:", '在对打者有利的球数时，投手几乎一定会：', 'バッターカウントのとき、ピッチャーはきっと：'), ('¡Correcto! Necesita un strike.', 'Correct! He needs a strike.', '正确！他需要一个好球。', '正解！ストライクがほしいんだ。'), ('Ventaja del bateador: viene un lanzamiento por la zona.', 'Batter ahead: the pitch comes through the zone.', '击球员占上风：球会进好球带。', 'バッターが有利：ゾーンに球が来る。'), opts={'a': ('Buscará la zona con su mejor lanzamiento', 'Go for the zone with his best pitch', '用他最好的球去投好球带', 'いちばんいい球でゾーンをねらう'), 'b': ('Lanzará a propósito muy lejos', 'Throw way outside on purpose', '故意投得很远', 'わざと大きく外す'), 'c': ('Pedirá salir del juego', 'Ask to leave the game', '要求下场', '試合から出たいと言う')}), '5': act(('Con dos strikes en contra, el bateador inteligente:', 'With two strikes against him, the smart batter:', '两好球被逼时，聪明的击球员会：', '2ストライクに追いこまれたら、かしこいバッターは：'), ('¡Eso es! A pelear cada lanzamiento.', "That's it! Battle every pitch.", '对了！每一球都要拼。', 'そのとおり！1球1球たたかう。'), ('Con dos strikes se protege, no se elige.', "With two strikes you protect, you don't pick.", '两好球时要护球，不能挑。', '2ストライクでは、選ぶより守るんだ。'), opts={'a': ('Protege la zona: batea también lo que vaya cerca', 'Protects the zone: also swings at what is close', '护好好球带：接近的球也打', 'ゾーンを守る：近い球も打つ'), 'b': ('Hace swing solo a la perfecta', 'Only swings at the perfect one', '只打完美的球', 'かんぺきな球だけふる'), 'c': ('Se rinde', 'Gives up', '放弃', 'あきらめる')}), '6': act(('El marcador dice 2 bolas y 2 strikes. Ese conteo se llama:', 'The scoreboard says 2 balls and 2 strikes. That count is called:', '记分牌显示 2 坏球 2 好球。这个球数叫：', 'スコアボードは2ボール2ストライク。このカウントは：'), ('¡Correcto! Dos y dos, nadie manda.', 'Correct! Two and two, nobody is in charge.', '正确！二和二，谁也不占上风。', '正解！2-2、どちらも有利じゃない。'), ('Completo es 3 y 2, como viste en el Nivel 4.', 'Full is 3 and 2, as you saw in Level 4.', '满球数是 3 和 2，你在第 4 级学过。', 'フルカウントは3-2。レベル4で見たね。'), opts={'a': ('Conteo parejo, dos y dos', 'An even count, two and two', '平手球数，二和二', '五分のカウント、2-2'), 'b': ('Conteo completo', 'A full count', '满球数', 'フルカウント'), 'c': ('Conteo de jonrón', 'A home run count', '本垒打球数', 'ホームランカウント')})})
map_titles['8.3'] = ('Leer el conteo: quién va ganando', "Reading the count: who's winning", '读懂球数：谁占上风', 'カウントを読む：どっちが有利？')
lesson('8.4', ('Anotar con números', 'Scoring with numbers', '用数字记录', '数字で記録する'), ('Leer jugadas escritas con los números de posición del Nivel 2 (un doble play 6-4-3), la K del ponche con swing y la K al revés del ponche mirando, y la E del error.', 'Read plays written with the Level 2 position numbers (a 6-4-3 double play), the K for a strikeout swinging and the backwards K for a strikeout looking, and the E for an error.', '读懂用第 2 级的守备位置号码写的记录（6-4-3 双杀）、表示挥棒三振的 K、表示看着三振的反写 K，以及表示失误的 E。', 'レベル2のポジション番号で書いたプレー（6-4-3のダブルプレー）、空ぶり三振のK、見のがし三振の逆さK、エラーのEを読もう。'), [('¿Recuerdas los números de las posiciones del Nivel 2?', 'Remember the position numbers from Level 2?', '还记得第 2 级的守备位置号码吗？', 'レベル2のポジション番号をおぼえてる？'), ('Los anotadores los usan para escribir jugadas sin palabras.', 'Scorers use them to write plays without words.', '记录员用它们来记录比赛，不用文字。', '記録員はそれを使って、言葉なしでプレーを書くんだ。'), ('Un doble play 6-4-3 significa: campocorto a segunda base, segunda base a primera: ¡dos outs!', 'A 6-4-3 double play means: shortstop to second base, second base to first: two outs!', '6-4-3 双杀的意思是：游击手传二垒手，二垒手传一垒：两个出局！', '6-4-3のダブルプレーは：遊撃手から二塁手、二塁手から一塁へ。2つアウト！'), ('La K es la letra del ponche: K normal si el bateador se ponchó abanicando, y K al revés si se ponchó mirando, sin hacer swing.', 'K is the strikeout letter: a regular K means the batter struck out swinging, and a backwards K means he struck out looking, without swinging.', 'K 是三振的字母：击球员挥棒落空三振，写正的 K；没有挥棒、看着三振，写反过来的 K。', 'Kは三振の文字：空ぶりで三振ならふつうのK、ふらずに見のがして三振なら逆さのK。'), ('Y la E es la marca del error: E6 significa error del campocorto.', 'And E is the mark for an error: E6 means an error by the shortstop.', 'E 是失误的记号：E6 表示游击手失误。', 'そしてEはエラーのしるし：E6は遊撃手のエラー。'), ('Leer estos códigos es leer el juego en secreto.', 'Reading these codes is reading the game in secret.', '读懂这些代码，就是在偷偷读懂比赛。', 'この暗号を読むのは、試合をこっそり読むことなんだ。')], {'1': act(('En un 6-4-3, ¿quién recibe primero la bola?', 'In a 6-4-3, who gets the ball first?', '在 6-4-3 里，谁先接到球？', '6-4-3で、最初にボールを受けるのはだれ？'), ('¡Correcto! Del 6 al 4.', 'Correct! From 6 to 4.', '正确！从 6 到 4。', '正解！6から4へ。'), ('El orden se lee en cadena: 6, 4, 3.', 'You read the chain in order: 6, 4, 3.', '按顺序读这串数字：6、4、3。', '順番に読もう：6、4、3。'), opts={'a': ('El segunda base (4)', 'The second baseman (4)', '二垒手 (4)', '二塁手 (4)'), 'b': ('El primera base (3)', 'The first baseman (3)', '一垒手 (3)', '一塁手 (3)'), 'c': ('El catcher (2)', 'The catcher (2)', '捕手 (2)', 'キャッチャー (2)')}), '2': act(('¿Qué jugada es un 6-4-3 clásico?', 'What play is a classic 6-4-3?', '经典的 6-4-3 是什么？', '基本の6-4-3はどんなプレー？'), ('¡Eso es! Dos outs escritos en números.', "That's it! Two outs written in numbers.", '对了！用数字写的两个出局。', 'そのとおり！数字で書いた2つのアウト。'), ('6-4-3: la receta del doble play.', '6-4-3: the double play recipe.', '6-4-3：双杀的配方。', '6-4-3：ダブルプレーのつくり方。'), opts={'a': ('Un doble play', 'A double play', '双杀', 'ダブルプレー'), 'b': ('Un jonrón', 'A home run', '本垒打', 'ホームラン'), 'c': ('Un robo', 'A steal', '盗垒', '盗塁')}), '3': act(('La K en la hoja de anotación significa ponche', 'The K on the scoresheet means strikeout', '记录表上的 K 表示三振', 'スコアブックのKは三振のこと'), ('¡Bien! K igual a ponche.', 'Good! K equals strikeout.', '很好！K 就是三振。', 'いいね！K＝三振。'), ('Verdadero: la K es el ponche.', 'True: the K is the strikeout.', '这是对的：K 就是三振。', '正しいよ：Kは三振。')), '4': act(('E6 en la hoja significa:', 'E6 on the scoresheet means:', '记录表上的 E6 表示：', 'スコアブックのE6は：'), ('¡Correcto! E de error, 6 del campocorto.', 'Correct! E for error, 6 for the shortstop.', '正确！E 是失误，6 是游击手。', '正解！Eはエラー、6は遊撃手。'), ('La letra dice el qué; el número, el quién.', 'The letter says what; the number says who.', '字母说是什么，数字说是谁。', '文字は「何」、数字は「だれ」。'), opts={'a': ('Error del campocorto', 'Error by the shortstop', '游击手失误', '遊撃手のエラー'), 'b': ('Jonrón del campocorto', 'Home run by the shortstop', '游击手的本垒打', '遊撃手のホームラン'), 'c': ('Seis errores', 'Six errors', '六个失误', 'エラー6つ')}), '5': act(('Arrastra la bola por la cadena 6-4-3: campocorto, segunda base, primera base', 'Drag the ball along the 6-4-3 chain: shortstop, second base, first base', '沿着 6-4-3 的路线拖动球：游击手、二垒、一垒', 'ボールを6-4-3の順にドラッグしよう：遊撃手、二塁、一塁'), ('¡Cadena perfecta! Doble play.', 'Perfect chain! Double play.', '完美的连线！双杀。', 'かんぺきな順番！ダブルプレー。'), ('Del 6 al 4 y del 4 al 3.', 'From 6 to 4 and from 4 to 3.', '从 6 到 4，再从 4 到 3。', '6から4、4から3へ。'), answer=('Campocorto, segunda base, primera base', 'Shortstop, second base, first base', '游击手、二垒、一垒', '遊撃手、二塁、一塁')), '6': act(('La hoja dice K al revés para un bateador. Eso significa que se ponchó:', 'The scoresheet shows a backwards K for a batter. That means he struck out:', '记录表上某个击球员是反写的 K。意思是他三振时：', 'スコアブックで、あるバッターが逆さのK。その三振は：'), ('¡Eso es! La K al revés es ponche mirando, sin swing.', "That's it! A backwards K means he struck out looking.", '对了！反写的 K 是看着三振。', 'そのとおり！逆さのKは見のがし三振。'), ('K normal: con swing. K al revés: mirando.', 'Regular K: swinging. Backwards K: looking.', '正 K：挥棒三振。反 K：看着三振。', 'ふつうのK：空ぶり。逆さのK：見のがし。'), opts={'a': ('Haciendo swing', 'Swinging', '挥了棒', 'ふって'), 'b': ('Mirando sin swing', 'Looking, without swinging', '看着，没有挥棒', 'ふらずに見のがして'), 'c': ('Corriendo', 'Running', '在跑', '走りながら')})})
map_titles['8.4'] = ('Anotar con números', 'Scoring with numbers', '用数字记录', '数字で記録する')
lesson('8.5', ('El marcador completo', 'The full scoreboard', '完整的记分牌', 'スコアボードのぜんぶ'), ('Leer el marcador completo: carreras (R), hits (H) y errores (E) por equipo, y las carreras de cada entrada, sin calcular nada más.', 'Read the full scoreboard: runs (R), hits (H) and errors (E) for each team, and the runs in each inning, without calculating anything else.', '读懂完整的记分牌：每队的得分（R）、安打（H）和失误（E），以及每一局的得分，不用再算别的。', 'スコアボードをぜんぶ読もう：チームごとの得点（R）、安打（H）、失策（E）と、イニングごとの得点。ほかの計算はいらないよ。'), [('El marcador es el periódico del juego.', "The scoreboard is the game's newspaper.", '记分牌就是比赛的报纸。', 'スコアボードは試合の新聞。'), ('Arriba van las entradas, y cada equipo anota sus carreras entrada por entrada.', 'The innings go across the top, and each team puts its runs inning by inning.', '上面是局数，每队一局一局地记下得分。', '上にイニングがならんで、チームごとにイニングの得点を書いていく。'), ('Al final hay tres números grandes: R, carreras, en inglés runs; H, hits; y E, errores, errors.', 'At the end there are three big numbers: R, runs; H, hits; and E, errors.', '最后有三个大数字：R 是得分，英语叫 runs；H 是安打，hits；E 是失误，errors。', '最後に大きな数字が3つ：Rは得点、英語で runs。Hは安打、hits。Eは失策、errors。'), ('Un equipo puede tener más hits y perder: ganan las carreras, no los hits.', 'A team can have more hits and lose: runs win, not hits.', '一个队可能安打更多却输了：赢球靠得分，不是靠安打。', '安打が多くても負けることがある：勝ちを決めるのは得点で、安打じゃない。'), ('Y un error en el marcador no es vergüenza de nadie: es información, cuenta qué pasó.', "And an error on the scoreboard is nobody's shame: it's information, it tells what happened.", '记分牌上的失误不是谁的耻辱：它是信息，告诉你发生了什么。', 'スコアボードのエラーは、だれかのはずかしいことじゃない。何が起きたかを伝える情報なんだ。'), ('Lee siempre en este orden: carreras, hits, errores.', 'Always read in this order: runs, hits, errors.', '一定按这个顺序读：得分、安打、失误。', 'いつもこの順番で読もう：得点、安打、失策。')], {'1': act(('En el marcador, la R significa:', 'On the scoreboard, R means:', '记分牌上的 R 表示：', 'スコアボードのRは：'), ('¡Eso es! R de runs.', "That's it! R for runs.", '对了！R 就是 runs。', 'そのとおり！Rは runs。'), ('Las R son las que ganan el juego.', 'The R is what wins the game.', 'R 就是决定胜负的数字。', 'Rが試合の勝ちを決めるんだ。'), opts={'a': ('Carreras (runs)', 'Runs', '得分 (runs)', '得点 (runs)'), 'b': ('Robos', 'Steals', '盗垒', '盗塁'), 'c': ('Relevos', 'Relievers', '救援投手', 'リリーフ')}), '2': act(('La H del marcador cuenta:', 'The H on the scoreboard counts:', '记分牌上的 H 记的是：', 'スコアボードのHが数えるのは：'), ('¡Correcto! H de hits.', 'Correct! H for hits.', '正确！H 就是 hits。', '正解！Hは hits。'), ('Hits: batazos buenos de cada equipo.', "Hits: each team's good batted balls.", '安打：每队打出的好球。', '安打：チームごとのいい打球。'), opts={'a': ('Los hits de cada equipo', "Each team's hits", '每队的安打', 'チームごとの安打'), 'b': ('Las horas del juego', 'The hours of the game', '比赛的小时数', '試合の時間'), 'c': ('Los jonrones solamente', 'Only home runs', '只有本垒打', 'ホームランだけ')}), '3': act(('Gana el equipo con más hits aunque tenga menos carreras', 'The team with more hits wins even if it has fewer runs', '安打多的队赢，即使得分比较少', '得点が少なくても、安打が多いチームが勝つ'), ('¡Bien! Ganan las carreras.', 'Good! Runs win.', '很好！得分才算赢。', 'いいね！得点で勝つ。'), ('Falso: mandan las carreras, no los hits.', 'False: runs rule, not hits.', '错：得分说了算，不是安打。', 'まちがい：決めるのは得点で、安打じゃない。')), '4': act(('La E del marcador cuenta:', 'The E on the scoreboard counts:', '记分牌上的 E 记的是：', 'スコアボードのEが数えるのは：'), ('¡Eso es! E de errores.', "That's it! E for errors.", '对了！E 就是失误（errors）。', 'そのとおり！Eはエラー（errors）。'), ('Errores: fallas en jugadas normales.', 'Errors: failures on normal plays.', '失误：普通的球没处理好。', '失策：ふつうのプレーのミス。'), opts={'a': ('Los errores de cada equipo', "Each team's errors", '每队的失误', 'チームごとの失策'), 'b': ('Las entradas', 'The innings', '局数', 'イニング'), 'c': ('Los expulsados', 'Players thrown out', '被驱逐的人', '退場した人')}), '5': act(('Un marcador dice 5 R, 8 H, 1 E contra 3 R, 9 H, 0 E. ¿Quién ganó?', 'A scoreboard says 5 R, 8 H, 1 E against 3 R, 9 H, 0 E. Who won?', '记分牌显示 5 R、8 H、1 E 对 3 R、9 H、0 E。谁赢了？', 'スコアボードは5 R、8 H、1 E 対 3 R、9 H、0 E。勝ったのは？'), ('¡Correcto! Carreras mandan.', 'Correct! Runs rule.', '正确！得分说了算。', '正解！得点で決まる。'), ('Más hits no siempre es ganar.', "More hits isn't always winning.", '安打多不一定赢。', '安打が多くても、勝つとはかぎらない。'), opts={'a': ('El de 5 carreras, aunque tuvo menos hits', 'The one with 5 runs, even with fewer hits', '5 分的队，虽然安打比较少', '5点のチーム、安打は少ないけど'), 'b': ('El de 9 hits', 'The one with 9 hits', '9 个安打的队', '9安打のチーム'), 'c': ('Nadie, es empate', "Nobody, it's a tie", '没人赢，是平局', 'どちらでもない、引き分け')}), '6': act(('En un marcador dibujado, toca la columna de las carreras (R) del equipo de arriba', 'On a drawn scoreboard, tap the runs column (R) of the top team', '在画出的记分牌上，点一下上面那一队的得分栏（R）', '絵のスコアボードで、上のチームの得点（R）の列をタッチしよう'), ('¡Bien! Primero se leen las carreras.', 'Good! Runs are read first.', '很好！先读得分。', 'いいね！まず得点を読む。'), ('R: el número que decide el juego.', 'R: the number that decides the game.', 'R：决定比赛的数字。', 'R：試合を決める数字。'), answer=('La R (runs) de la primera fila', 'The R (runs) of the first row', '第一行的 R（得分）', '1行目のR（得点）'))})
