exams_v3['8'] = {'1': {'q': ('Batazo limpio que pasa sin que nadie falle:', 'A clean batted ball that gets through without anyone failing:', '干净的击球，没有人失误就穿过了：', 'だれもミスせずに抜けた、きれいな打球は：'), 'opts': {'a': ('Hit', 'Hit', '安打', 'ヒット'), 'b': ('Error', 'Error', '失误', 'エラー'), 'c': ('Balk', 'Balk', '投手犯规', 'ボーク')}}, '2': {'q': ('Un defensor deja caer una bola fácil:', 'A fielder drops an easy ball:', '防守球员漏接了一个容易的球：', '守備の選手がかんたんなボールを落とした：'), 'opts': {'a': ('Error', 'Error', '失误', 'エラー'), 'b': ('Hit', 'Hit', '安打', 'ヒット'), 'c': ('Safe', 'Safe', '安全上垒', 'セーフ')}}, '3': {'q': ('Toca al defensor que falló la jugada fácil', 'Tap the fielder who missed the easy play', '点一下漏掉容易的球的防守球员', 'かんたんなプレーをミスした守備の選手をタッチしよう'), 'answer': ('El defensor que falló la jugada fácil', 'The fielder who missed the easy play', '漏掉容易的球的防守球员', 'かんたんなプレーをミスした守備の選手')}, '4': {'q': ('La diferencia clave entre hit y error es:', 'The key difference between a hit and an error is:', '安打和失误的关键区别是：', 'ヒットとエラーの大事なちがいは：'), 'opts': {'a': ('Si la defensa falló una jugada normal', 'Whether the defense failed a normal play', '防守有没有把普通的球处理失败', '守備がふつうのプレーをミスしたかどうか'), 'b': ('El tamaño del campo', 'The size of the field', '球场的大小', 'グラウンドの大きさ'), 'c': ('La hora', 'The time', '时间', '時間')}}, '5': {'q': ('Con bases llenas recibes base por bolas y anota el de tercera. ¿Qué te apuntan?', 'Bases loaded, you get walked and the runner on third scores. What do you get credit for?', '满垒时你被保送，三垒跑垒员回来得分。你会被记上什么？', '満塁でフォアボール、三塁ランナーがホームイン。君に記録されるのは？'), 'opts': {'a': ('Una carrera impulsada (RBI)', 'A run batted in (RBI)', '一个打点（RBI）', '打点（RBI）'), 'b': ('Un hit', 'A hit', '一支安打', 'ヒット'), 'c': ('Un error', 'An error', '一次失误', 'エラー')}}, '6': {'q': ('Verdadero o falso: si tu elevado de sacrificio hace anotar a un compañero, esa carrera es impulsada por ti', 'True or false: if your sacrifice fly lets a teammate score, you get the RBI', '对还是错：如果你的高飞牺牲打让队友得分，这一分算你的打点', '○か×か：君の犠牲フライで仲間がホームインしたら、その打点は君につく')}, '7': {'q': ('El conteo va dos bolas y cero strikes. ¿Quién va ganando?', "The count is two balls and no strikes. Who's ahead?", '球数是两坏球零好球。谁占上风？', 'カウントはツーボール、ノーストライク。有利なのはどっち？'), 'opts': {'a': ('El bateador', 'The batter', '击球员', 'バッター'), 'b': ('El pitcher', 'The pitcher', '投手', 'ピッチャー'), 'c': ('Nadie', 'Nobody', '谁都不占', 'どっちでもない')}}, '8': {'q': ('¿Qué es el pitch count?', 'What is the pitch count?', '什么是用球数（pitch count）？', '投球数（pitch count）って何？'), 'opts': {'a': ('Cuántos lanzamientos lleva el pitcher', 'How many pitches the pitcher has thrown', '投手已经投了多少球', 'ピッチャーが何球投げたか'), 'b': ('El conteo de bolas y strikes', 'The count of balls and strikes', '坏球和好球的球数', 'ボールとストライクのカウント'), 'c': ('Las carreras del juego', 'The runs in the game', '比赛的得分', '試合の得点')}}, '9': {'q': ('En la anotación, una K al revés significa:', 'In scorekeeping, a backwards K means:', '在记分时，反写的 K 表示：', 'スコアブックで、逆さのKの意味は：'), 'opts': {'a': ('Ponche mirando, sin swing', 'Strikeout looking, no swing', '看着三振，没有挥棒', '見のがし三振、ふらなかった'), 'b': ('Ponche con swing', 'Strikeout swinging', '挥棒三振', '空ぶり三振'), 'c': ('Un error', 'An error', '一次失误', 'エラー')}}, '10': {'q': ('¿Qué significa un doble play anotado 6-4-3?', 'What does a double play scored 6-4-3 mean?', '记作 6-4-3 的双杀是什么意思？', '6-4-3と書くダブルプレーの意味は？'), 'opts': {'a': ('Del campocorto al segunda base y a primera', 'From the shortstop to the second baseman to first', '从游击手传给二垒手，再传一垒', '遊撃手から二塁手、そして一塁へ'), 'b': ('Tres carreras', 'Three runs', '三分', '3点'), 'c': ('Seis outs', 'Six outs', '六个出局', '6アウト')}}, '11': {'q': ('En el marcador, ¿qué significa la H?', 'On the scoreboard, what does the H stand for?', '记分牌上的 H 是什么意思？', 'スコアボードのHの意味は？'), 'opts': {'a': ('Hits', 'Hits', '安打（hits）', 'ヒット（hits）'), 'b': ('Home', 'Home', '本垒（home）', 'ホーム（home）'), 'c': ('Hora', 'Hour', '小时', '時間')}}, '12': {'q': ('Verdadero o falso: el equipo con más hits siempre gana', 'True or false: the team with more hits always wins', '对还是错：安打多的队一定赢', '○か×か：ヒットが多いチームがかならず勝つ')}}
