levels['9'] = dict(title=('Robo de base y el pitcher', 'Stealing bases and the pitcher', '盗垒与投手', '盗塁とピッチャー'), badge=('Ladrón de Bases', 'Base Stealer', '盗垒大师', '盗塁王'))
lesson('9.1', ('El robo de base', 'The stolen base', '盗垒', '盗塁'), ('Entender el robo (stolen base): avanzar a la siguiente base durante el lanzamiento, sin batazo, y que permitir el robo — y desde cuándo — depende de la liga y la edad.', 'Understand the stolen base: moving up to the next base during the pitch, with no batted ball, and that whether stealing is allowed — and from what age — depends on the league and the age group.', '明白盗垒（stolen base）：在投手投球时、没有击球的情况下跑向下一个垒；还要知道能不能盗垒、从几岁开始可以，由联赛和年龄决定。', '盗塁（stolen base）を知ろう：打球なしで、投球のあいだに次の塁へ進むこと。盗塁してよいか、何歳からかは、リーグと年齢で決まる。'), [('Robar una base es avanzar a la siguiente mientras el pitcher lanza, sin que haya batazo.', 'Stealing a base is moving up to the next one while the pitcher pitches, without a batted ball.', '盗垒就是在投手投球的时候跑向下一个垒，不需要击球。', '盗塁は、ピッチャーが投げているあいだに、打球なしで次の塁へ進むこと。'), ('En inglés: stolen base.', "That's called a stolen base.", '英语叫 stolen base。', '英語で stolen base。'), ('Arrancas cuando el pitcher empieza su movimiento hacia home, y es una carrera entre tú, el tiro del catcher y la base que te espera.', "You take off when the pitcher starts his motion toward home, and it's a race between you, the catcher's throw and the base waiting for you.", '投手开始向本垒投球时你就起跑，这是你、捕手的传球和等着你的垒之间的一场赛跑。', 'ピッチャーがホームへ投げる動きをはじめたらスタート。君と、キャッチャーの送球と、待っている塁との競走だ。'), ('Pero escucha lo más importante: no en todas las ligas infantiles se puede robar, y cada liga decide desde qué edad.', "But listen to the most important part: you can't steal in every kids' league, and each league decides from what age.", '但最重要的是：不是每个少儿联赛都可以盗垒，从几岁开始可以，由每个联赛自己决定。', 'でも、いちばん大事なことを聞いて：子どものリーグがみんな盗塁できるわけじゃない。何歳からかは、それぞれのリーグが決める。'), ('Pregúntale a tu coach si en tu liga hay robos: él tiene la respuesta de tu liga.', 'Ask your coach if your league has steals: he has the answer for your league.', '问问你的教练你们联赛能不能盗垒：他知道你们联赛的答案。', '君のリーグで盗塁できるか、コーチに聞いてみよう。コーチが君のリーグの答えを知っているよ。')], {'1': act(('¿Qué es robar una base?', 'What is stealing a base?', '什么是盗垒？', '盗塁って何？'), ('¡Eso es! Stolen base.', "That's it! Stolen base.", '对了！盗垒。', 'そのとおり！盗塁。'), ('Robo: avanzas con el lanzamiento, no con un hit.', 'Stealing: you move up with the pitch, not with a hit.', '盗垒：靠投球的时机前进，不是靠安打。', '盗塁：ヒットじゃなく、投球のあいだに進むんだ。'), opts={'a': ('Avanzar durante el lanzamiento, sin batazo', 'Moving up during the pitch, with no batted ball', '投球时跑向下一个垒，没有击球', '打球なしで、投球のあいだに進むこと'), 'b': ('Llevarse la base a la casa', 'Taking the base home with you', '把垒包带回家', '塁をおうちに持って帰ること'), 'c': ('Un batazo fuerte', 'A hard-hit ball', '一个很猛的击球', '強い打球')}), '2': act(('En todas las ligas infantiles se puede robar desde cualquier edad', "In every kids' league you can steal from any age", '在所有少儿联赛里，任何年龄都可以盗垒', '子どものリーグなら、どこでも何歳からでも盗塁できる'), ('¡Bien! Cada liga decide.', 'Good! Each league decides.', '很好！由每个联赛决定。', 'いいね！リーグごとに決める。'), ('Falso: pregúntale a tu coach por tu liga.', 'False: ask your coach about your league.', '错：问问你的教练你们联赛的规定。', 'まちがい：君のリーグのことはコーチに聞こう。')), '3': act(('¿Cuándo arranca el corredor que roba?', 'When does the stealing runner take off?', '盗垒的跑垒员什么时候起跑？', '盗塁するランナーはいつスタートする？'), ('¡Correcto! Ese es tu momento.', "Correct! That's your moment.", '正确！那就是你的时机。', '正解！それが君のタイミング。'), ('El robo arranca con el lanzamiento.', 'The steal starts with the pitch.', '盗垒随着投球开始。', '盗塁は投球といっしょにはじまる。'), opts={'a': ('Cuando el pitcher empieza su movimiento o suelta la bola hacia home', 'When the pitcher starts his motion or releases the ball toward home', '投手开始投球动作或把球投向本垒时', 'ピッチャーが投げる動きをはじめるか、ホームへボールをはなしたとき'), 'b': ('Cuando el bateador conecta', 'When the batter makes contact', '击球员击中球时', 'バッターが打ったとき'), 'c': ('Cuando termina la entrada', 'When the inning ends', '这一局结束时', 'イニングが終わったとき')}), '4': act(('Llegaste a segunda antes de que el defensor te tocara con la bola. ¿Qué canta el umpire?', "You reached second before the fielder's tag. What does the umpire call?", '你在防守球员触杀之前到了二垒。裁判怎么判？', '守備のタッチより先に二塁に着いた。審判のコールは？'), ('¡Safe! Robo logrado.', 'Safe! Steal made.', '安全上垒！盗垒成功。', 'セーフ！盗塁成功。'), ('Llegaste primero: base robada.', 'You got there first: stolen base.', '你先到了：盗垒成功。', '先に着いた：盗塁成功。'), opts={'a': ('¡Safe! Base robada', 'Safe! Stolen base', '安全上垒！盗垒成功', 'セーフ！盗塁成功'), 'b': ('¡Out!', 'Out!', '出局！', 'アウト！'), 'c': ('¡Balk!', 'Balk!', '投手犯规！', 'ボーク！')}), '5': act(('Estás robando desde primera. Toca la base que quieres robar', "You're stealing from first. Tap the base you want to steal", '你从一垒盗垒。点一下你想盗的垒', '一塁から盗塁する。ぬすみたい塁をタッチしよう'), ('¡Bien! Segunda es la que más se roba.', 'Good! Second is the most stolen.', '很好！二垒是最常被盗的垒。', 'いいね！いちばんぬすまれるのは二塁。'), ('El robo clásico es a segunda.', 'The classic steal is to second.', '最经典的盗垒是盗二垒。', '基本の盗塁は二塁へ。'), answer=('Segunda base', 'Second base', '二垒', '二塁')), '6': act(('Si tu liga no permite robos todavía, ¿qué haces?', "If your league doesn't allow steals yet, what do you do?", '如果你们联赛还不允许盗垒，你怎么做？', '君のリーグでまだ盗塁できないなら、どうする？'), ('¡Eso es! Cada liga tiene su momento.', "That's it! Each league has its time.", '对了！每个联赛都有自己的时候。', 'そのとおり！リーグごとにその時がある。'), ('Las reglas de tu liga se respetan siempre.', "Your league's rules are always respected.", '你们联赛的规定一定要遵守。', 'リーグのルールはいつも守るんだ。'), opts={'a': ('Respeto la regla de mi liga y pregunto al coach', "I respect my league's rule and ask the coach", '我遵守联赛的规定，并问教练', 'リーグのルールを守って、コーチに聞く'), 'b': ('Robo igual', 'I steal anyway', '我照样盗垒', 'それでも盗塁する'), 'c': ('Me enojo', 'I get angry', '我生气', 'おこる')})})
map_titles['9.1'] = ('El robo de base', 'The stolen base', '盗垒', '盗塁')
lesson('9.2', ('Despegarse de la base', 'Taking a lead', '离垒', 'リードをとる'), ('Entender despegarse (lead): alejarse unos pasos de la base para acortar el camino, volver rápido si el pitcher mira, y que muchas ligas infantiles no permiten despegarse hasta que la bola cruza home.', "Understand taking a lead: moving a few steps away from the base to shorten the path, getting back fast if the pitcher looks, and that many kids' leagues don't allow leads until the ball crosses home.", '明白离垒（lead）：离开垒包几步，缩短要跑的距离；投手看过来时要很快回去；还要知道很多少儿联赛在球经过本垒之前不允许离垒。', 'リード（lead）を知ろう：塁から数歩はなれて、走る道を短くすること。ピッチャーが見たらすぐもどる。多くの子どものリーグでは、ボールがホームを通るまでリードできない。'), [('Antes de robar, el corredor se despega: da unos pasitos lejos de su base para quedar más cerca de la siguiente.', 'Before stealing, the runner takes a lead: a few little steps away from his base to be closer to the next one.', '盗垒之前，跑垒员会离垒：从自己的垒往外走几小步，离下一个垒更近一点。', '盗塁の前に、ランナーはリードをとる：自分の塁から少しはなれて、次の塁に近づくんだ。'), ('En inglés se dice lead.', "That's called taking a lead.", '英语叫 lead。', '英語で lead という。'), ('Pero el despego tiene peligro: quedaste fuera de tu lugar seguro.', "But the lead is risky: you're off your safe spot.", '但离垒有危险：你离开了你的安全区。', 'でもリードにはきけんがある：安全地帯の外にいるんだ。'), ('Si el pitcher se da vuelta y tira a tu base, debes volver volando.', 'If the pitcher turns and throws to your base, you have to fly back.', '如果投手转身传向你的垒，你要飞快地跑回去。', 'ピッチャーがふり向いて君の塁に投げたら、とんでもどらなきゃ。'), ('Y ojo: en muchas ligas de niños pequeños no se puede despegar hasta que el lanzamiento pasa por home.', "And careful: in many leagues for young kids you can't take a lead until the pitch goes past home.", '还要注意：很多小朋友的联赛里，投球经过本垒之前不能离垒。', 'それから気をつけて：小さい子のリーグの多くでは、投球がホームを通るまでリードできない。'), ('¿En tu liga se puede despegar? Pregunta a tu coach antes de hacerlo.', 'Can you take a lead in your league? Ask your coach before you do it.', '你们联赛可以离垒吗？离垒之前先问问你的教练。', '君のリーグではリードしていい？やる前にコーチに聞こう。')], {'1': act(('¿Qué es despegarse de la base (lead)?', 'What is taking a lead off the base?', '什么是离垒（lead）？', 'リード（lead）って何？'), ('¡Eso es! Lead.', "That's it! Lead.", '对了！离垒。', 'そのとおり！リード。'), ('Despegarte acorta tu camino.', 'Taking a lead shortens your path.', '离垒能缩短你要跑的路。', 'リードで走る道が短くなる。'), opts={'a': ('Alejarse unos pasos de la base para preparar el avance', 'Moving a few steps away from the base to get ready to advance', '离开垒包几步，准备前进', '進むじゅんびのために、塁から数歩はなれること'), 'b': ('Irse al dugout', 'Going to the dugout', '回到休息区', 'ダッグアウトへ行くこと'), 'c': ('Quitar la base del suelo', 'Pulling the base off the ground', '把垒包从地上拿起来', '塁を地面からはずすこと')}), '2': act(('Despegarse demasiado es gratis: nunca pasa nada', 'Taking too big a lead is free: nothing ever happens', '离垒太远也没关系：什么事都不会发生', 'リードを大きくとりすぎても平気：何も起きない'), ('¡Bien! Lejos de tu base hay peligro.', "Good! Far from your base there's danger.", '很好！离垒越远越危险。', 'いいね！塁から遠いと、きけんがある。'), ('Falso: despegado, un buen tiro te puede sacar.', 'False: off the base, a good throw can get you out.', '错：离开垒时，一个好的传球就能让你出局。', 'まちがい：リード中は、いい送球でアウトになることがある。')), '3': act(('Estás despegado y el pitcher se voltea hacia tu base. ¿Qué haces?', "You've taken a lead and the pitcher turns toward your base. What do you do?", '你离垒了，投手转向你的垒。你怎么做？', 'リードしていたら、ピッチャーが君の塁のほうを向いた。どうする？'), ('¡Correcto! De vuelta a tu lugar seguro.', 'Correct! Back to your safe spot.', '正确！回到你的安全区。', '正解！安全地帯にもどる。'), ('Pitcher mirando: regresa enseguida.', 'Pitcher looking: go back right away.', '投手在看：马上回去。', 'ピッチャーが見ている：すぐもどろう。'), opts={'a': ('Vuelvo corriendo a mi base', 'I run back to my base', '我跑回我的垒', '自分の塁に走ってもどる'), 'b': ('Sigo avanzando tranquilo', 'I keep moving up calmly', '我继续慢慢往前走', 'のんびり進みつづける'), 'c': ('Me agacho y espero', 'I crouch down and wait', '我蹲下来等', 'しゃがんで待つ')}), '4': act(('Toca dónde queda un corredor despegado de primera: entre qué dos bases', 'Tap where a runner leading off first is: between which two bases', '点一下从一垒离垒的跑垒员在哪里：在哪两个垒之间', '一塁からリードしているランナーはどこ？どの2つの塁のあいだかタッチしよう'), ('¡Bien! Ahí flota el corredor despegado.', "Good! That's where the leading runner floats.", '很好！离垒的跑垒员就在那里。', 'いいね！リードしたランナーはそこにいる。'), ('Despegado estás entre dos bases, sin lugar seguro.', "With a lead, you're between two bases, off your safe spot.", '离垒时你在两个垒之间，没有安全区。', 'リード中は、2つの塁のあいだ。安全地帯がない。'), answer=('Entre primera y segunda', 'Between first and second', '一垒和二垒之间', '一塁と二塁のあいだ')), '5': act(('En muchas ligas infantiles, el corredor solo puede despegarse:', "In many kids' leagues, the runner can only take a lead:", '在很多少儿联赛里，跑垒员只能在什么时候离垒：', '多くの子どものリーグでは、ランナーがリードできるのは：'), ('¡Eso es! Por eso se pregunta al coach.', "That's it! That's why you ask the coach.", '对了！所以要问教练。', 'そのとおり！だからコーチに聞くんだ。'), ('Cada liga pone su momento de despego.', 'Each league sets its moment for leads.', '每个联赛都有自己规定的离垒时机。', 'リードのタイミングは、リーグごとに決まる。'), opts={'a': ('Cuando el lanzamiento pasa por home', 'When the pitch goes past home', '投球经过本垒时', '投球がホームを通ったとき'), 'b': ('Desde que llega a la base', 'From the moment he reaches the base', '一到垒上就可以', '塁に着いたときから'), 'c': ('Nunca importa la liga', 'The league never matters', '联赛规定不重要', 'リーグは関係ない')}), '6': act(('Te despegaste mucho y el tiro del pitcher llegó a primera antes que tú al volver. ¿Qué canta?', "You took a big lead and the pitcher's throw got to first before you got back. What is the call?", '你离垒太远，投手的传球比你先回到一垒。怎么判？', '大きくリードしていたら、もどるより先にピッチャーの送球が一塁に着いた。コールは？'), ('¡Out! El despego se paga si te descuidas.', 'Out! The lead costs you if you get careless.', '出局！离垒时一不小心就要付出代价。', 'アウト！油断するとリードのつけがまわる。'), ('Volver tarde del despego es out.', 'Getting back late from a lead is an out.', '离垒后回得太慢就是出局。', 'リードからもどるのがおそいとアウト。'), opts={'a': ('¡Out!', 'Out!', '出局！', 'アウト！'), 'b': ('¡Safe!', 'Safe!', '安全上垒！', 'セーフ！'), 'c': ('¡Strike!', 'Strike!', '好球！', 'ストライク！')})})
map_titles['9.2'] = ('Despegarse de la base', 'Taking a lead', '离垒', 'リードをとる')
lesson('9.3', ('El pickoff', 'The pickoff', '牵制传球', '牽制球'), ('Entender el pickoff: el pitcher (o el catcher) tira de sorpresa a una base para intentar hacer out al corredor despegado, y por qué el corredor debe volver tocando la base.', 'Understand the pickoff: the pitcher (or the catcher) throws by surprise to a base to try to get the runner who took a lead out, and why the runner has to get back touching the base.', '明白牵制传球（pickoff）：投手（或捕手）突然传向一个垒，想让离垒的跑垒员出局；以及为什么跑垒员必须摸到垒包回去。', '牽制球（pickoff）を知ろう：ピッチャー（またはキャッチャー）が、リードしたランナーをアウトにしようと、ふいに塁へ投げること。ランナーが塁にふれてもどらなきゃいけない理由も。'), [('El pitcher también juega.', 'The pitcher plays too.', '投手也会出招。', 'ピッチャーもプレーしている。'), ('Si te despegas mucho, puede girar de sorpresa y tirar a tu base: eso es un pickoff, un tiro para sorprenderte fuera de tu base.', "If you take a big lead, he can turn by surprise and throw to your base: that's a pickoff, a throw to catch you off your base.", '如果你离垒太远，他可能突然转身传向你的垒：这就是牵制传球（pickoff），想趁你离开垒包时抓住你。', 'リードが大きいと、ふいにふり向いて君の塁に投げてくる：それが牽制球（pickoff）。塁をはなれた君をつかまえる送球だ。'), ('Si su tiro llega y el defensor te toca antes de que vuelvas, eres out.', 'If his throw gets there and the fielder tags you before you get back, you are out.', '如果他的传球到了，防守球员在你回去之前触到你，你就出局。', '送球が着いて、もどる前に守備にタッチされたら、アウト。'), ('Por eso el corredor despegado vive listo: un ojo en el pitcher y el cuerpo preparado para lanzarse de vuelta.', "That's why the runner with a lead is always ready: one eye on the pitcher and his body set to dive back.", '所以离垒的跑垒员要时刻准备：一只眼睛盯着投手，身体随时准备扑回去。', 'だからリードしたランナーは、いつもじゅんびしている：ピッチャーから目をはなさず、体はとびこんでもどれるように。'), ('Y si la bola se va lejos por un mal tiro, ¡ahí sí, a correr!', 'And if the ball goes far on a bad throw, then yes, run!', '如果传球传偏、球跑远了，这时就快跑！', 'そして悪い送球でボールが遠くへ行ったら、そのときは走れ！')], {'1': act(('¿Qué es un pickoff?', 'What is a pickoff?', '什么是牵制传球（pickoff）？', '牽制球（pickoff）って何？'), ('¡Eso es! Pickoff.', "That's it! Pickoff.", '对了！牵制传球。', 'そのとおり！牽制球。'), ('Con ese tiro el pitcher vigila al corredor.', 'With that throw, the pitcher keeps the runner close.', '投手用这个传球盯住跑垒员。', 'ピッチャーはその送球でランナーを見はっているんだ。'), opts={'a': ('Un tiro de sorpresa del pitcher a una base para sacar al corredor despegado', 'A surprise throw by the pitcher to a base to get the runner with a lead out', '投手突然传向一个垒，想让离垒的跑垒员出局', 'リードしたランナーをアウトにするための、ピッチャーのふいの送球'), 'b': ('Un tipo de bate', 'A kind of bat', '一种球棒', 'バットの種類'), 'c': ('Una señal del coach', "A coach's sign", '教练的暗号', 'コーチのサイン')}), '2': act(('En un pickoff, si vuelves a tu base antes de que te toquen, eres safe', 'On a pickoff, if you get back to your base before the tag, you are safe', '牵制传球时，如果你在被触杀之前回到垒上，你就安全上垒', '牽制球で、タッチより先に塁にもどれたらセーフ'), ('¡Bien! Tu lugar seguro te salva.', 'Good! Your base keeps you safe.', '很好！你的安全区救了你。', 'いいね！安全地帯が君を守る。'), ('Verdadero: llegar primero es safe.', 'True: getting there first is safe.', '这是对的：先到就是安全上垒。', '正しいよ：先に着けばセーフ。')), '3': act(('El tiro del pickoff se escapa lejos del primera base. Como corredor, ¿qué haces?', 'The pickoff throw gets away far from the first baseman. As the runner, what do you do?', '牵制传球传偏，球跑离一垒手很远。作为跑垒员，你怎么做？', '牽制球が一塁手から遠くへそれた。ランナーの君はどうする？'), ('¡Correcto! Bola lejos: a aprovechar.', 'Correct! Ball far away: take advantage.', '正确！球跑远了：抓住机会。', '正解！ボールが遠い：チャンスだ。'), ('Un mal tiro de pickoff regala una base.', 'A bad pickoff throw gives away a base.', '牵制传球传坏了，就是白送一个垒。', '悪い牽制球は、塁をひとつくれる。'), opts={'a': ('¡Corro a la siguiente base!', 'I run to the next base!', '我跑向下一个垒！', '次の塁へ走る！'), 'b': ('Me quedo parado', 'I stay still', '我站着不动', 'じっとしている'), 'c': ('Vuelvo al dugout', 'I go back to the dugout', '我回休息区', 'ダッグアウトにもどる')}), '4': act(('El pitcher hace pickoff a primera. Toca la base donde el defensor espera el tiro para tocarte', 'The pitcher throws a pickoff to first. Tap the base where the fielder waits for the throw to tag you', '投手向一垒牵制传球。点一下防守球员等着接球来触杀你的垒', 'ピッチャーが一塁に牽制球。守備がボールを待って君にタッチする塁をタッチしよう'), ('¡Bien! Ahí se decide el pickoff.', "Good! That's where the pickoff is decided.", '很好！牵制传球就在那里决定胜负。', 'いいね！そこで牽制球の勝負が決まる。'), ('Primera recibe el tiro de sorpresa.', 'First receives the surprise throw.', '一垒接这个突然的传球。', '一塁がふいの送球を受ける。'), answer=('Primera base', 'First base', '一垒', '一塁')), '5': act(('El tiro de pickoff llegó y te tocaron un paso antes de volver a la base. ¿Qué canta?', 'The pickoff throw got there and you were tagged one step before getting back to the base. What is the call?', '牵制传球到了，你差一步回到垒上时被触到了。怎么判？', '牽制球が着いて、塁にもどる1歩手前でタッチされた。コールは？'), ('¡Out! El pickoff funcionó.', 'Out! The pickoff worked.', '出局！牵制传球成功了。', 'アウト！牽制球が決まった。'), ('Tocado fuera de tu base: out.', 'Tagged off your base: out.', '在垒外被触到：出局。', '塁の外でタッチ：アウト。'), opts={'a': ('¡Out!', 'Out!', '出局！', 'アウト！'), 'b': ('¡Safe!', 'Safe!', '安全上垒！', 'セーフ！'), 'c': ('¡Bola!', 'Ball!', '坏球！', 'ボール！')}), '6': act(('El mejor antídoto contra el pickoff es:', 'The best antidote against the pickoff is:', '对付牵制传球最好的办法是：', '牽制球にいちばんきく対策は：'), ('¡Eso es! Corto y atento.', "That's it! Short and alert.", '对了！短一点，专心一点。', 'そのとおり！短く、注意して。'), ('Despego con cabeza, no con codicia.', 'Take a lead with your head, not with greed.', '离垒要动脑子，不能贪心。', 'リードは頭でとる。欲ばらないで。'), opts={'a': ('Un despego corto y volver rápido', 'A short lead and getting back fast', '离垒短一点，回得快一点', '短いリードと、すばやいもどり'), 'b': ('Despegarse lo máximo posible', 'Taking the biggest lead possible', '尽可能离垒远一点', 'できるだけ大きくリードする'), 'c': ('No mirar al pitcher', 'Not looking at the pitcher', '不看投手', 'ピッチャーを見ない')})})
map_titles['9.3'] = ('El pickoff', 'The pickoff', '牵制传球', '牽制球')
lesson('9.4', ('El balk: el engaño que no vale', "The balk: the trick that doesn't count", '投手犯规：不算数的骗人动作', 'ボーク：やってはいけないフェイント'), ('Entender el balk en palabras simples: un movimiento ilegal del pitcher con corredores en base — empezar a lanzar y pararse, o fingir un tiro sin soltar la bola — castigado con una base para cada corredor; y que en muchas ligas infantiles el balk no se canta o se enseña avisando primero.', "Understand the balk in simple words: an illegal move by the pitcher with runners on base — starting to pitch and stopping, or faking a throw without letting go of the ball — punished with one base for each runner; and that in many kids' leagues the balk isn't called or is taught with a warning first.", '用简单的话明白投手犯规（balk）：有跑垒员在垒上时投手的违规动作——开始投球又停下来，或者假装传球却不出手——处罚是每名跑垒员进一个垒；还要知道很多少儿联赛不判投手犯规，或者先提醒再教。', 'ボーク（balk）をかんたんな言葉で知ろう：ランナーがいるときのピッチャーの反則の動き——投げはじめて止まる、ボールをはなさずに投げるふりをする——で、ランナー全員が1つずつ進む。多くの子どものリーグでは、ボークをとらなかったり、まず注意して教えたりする。'), [('El pitcher puede engañar con la mirada, pero no con el cuerpo.', 'The pitcher can trick you with his eyes, but not with his body.', '投手可以用眼神骗人，但不能用身体骗人。', 'ピッチャーは目でだましてもいいけど、体でだましちゃいけない。'), ('Si con corredores en base empieza su movimiento de lanzar y se detiene, o hace como que tira a una base y no suelta la bola, cometió un balk.', "If, with runners on base, he starts his pitching motion and stops, or acts like he's throwing to a base and doesn't let go of the ball, he committed a balk.", '有跑垒员在垒上时，如果他开始投球动作又停下来，或者假装传向一个垒却没有把球传出去，就是投手犯规，英语叫 balk。', 'ランナーがいるときに、投げる動きをはじめて止まったり、塁に投げるふりをしてボールをはなさなかったら、ボーク。英語でも balk。'), ('El castigo es justo: cada corredor avanza una base gratis.', 'The penalty is fair: each runner moves up one base for free.', '处罚很公平：每名跑垒员免费进一个垒。', 'ばつはフェア：ランナー全員が1つずつ、ただで進む。'), ('Es como mover una pieza fuera de turno: no vale.', "It's like moving a game piece out of turn: it doesn't count.", '就像下棋时没轮到你就走棋：不算数。', 'ゲームで自分の番じゃないのにコマを動かすようなもの：だめなんだ。'), ('Y escucha: en muchas ligas de niños el balk no se canta, o el umpire avisa primero para enseñar.', "And listen: in many kids' leagues the balk isn't called, or the umpire warns first to teach.", '还有：很多少儿联赛不判投手犯规，或者裁判会先提醒，教大家怎么做。', 'それから：子どものリーグの多くでは、ボークをとらなかったり、審判がまず注意して教えたりする。'), ('¿En tu liga se cantan balks? Tu coach lo sabe.', 'Are balks called in your league? Your coach knows.', '你们联赛判投手犯规吗？你的教练知道。', '君のリーグではボークをとる？コーチが知っているよ。')], {'1': act(('¿Qué es un balk?', 'What is a balk?', '什么是投手犯规（balk）？', 'ボーク（balk）って何？'), ('¡Eso es! Balk.', "That's it! Balk.", '对了！投手犯规。', 'そのとおり！ボーク。'), ('Movimiento ilegal del pitcher: eso es balk.', "An illegal move by the pitcher: that's a balk.", '投手的违规动作：就是投手犯规。', 'ピッチャーの反則の動き：それがボーク。'), opts={'a': ('Un movimiento ilegal del pitcher con corredores en base', 'An illegal move by the pitcher with runners on base', '有跑垒员在垒上时投手的违规动作', 'ランナーがいるときのピッチャーの反則の動き'), 'b': ('Un batazo muy largo', 'A very long batted ball', '一个很远的击球', 'とても遠くへ飛ぶ打球'), 'c': ('Un robo de home', 'A steal of home', '盗本垒', 'ホームスチール')}), '2': act(('¿Cuál es el castigo del balk?', 'What is the penalty for a balk?', '投手犯规的处罚是什么？', 'ボークのばつは？'), ('¡Correcto! Una base gratis por corredor.', 'Correct! A free base per runner.', '正确！每名跑垒员免费进一个垒。', '正解！ランナー1人に1つ、ただで進む。'), ('Balk: todos avanzan una.', 'Balk: everybody moves up one.', '投手犯规：大家都进一个垒。', 'ボーク：みんな1つ進む。'), opts={'a': ('Cada corredor avanza una base', 'Each runner moves up one base', '每名跑垒员进一个垒', 'ランナー全員が1つ進む'), 'b': ('El pitcher sale del juego', 'The pitcher leaves the game', '投手被换下场', 'ピッチャーが試合から出る'), 'c': ('El bateador es out', 'The batter is out', '击球员出局', 'バッターがアウト')}), '3': act(('El balk solo se puede cantar si hay corredores en base', 'A balk can only be called if there are runners on base', '只有垒上有跑垒员时，才能判投手犯规', 'ボークは、ランナーがいるときだけとられる'), ('¡Bien! Sin corredores no hay balk.', 'Good! No runners, no balk.', '很好！没有跑垒员就没有投手犯规。', 'いいね！ランナーなしならボークなし。'), ('Verdadero: sin corredores, ese movimiento no se castiga como balk.', "True: with no runners, that move isn't called a balk.", '这是对的：没有跑垒员时，这个动作不算投手犯规。', '正しいよ：ランナーがいなければ、その動きはボークにならない。')), '4': act(('¿Cuál imagen muestra un balk?', 'Which picture shows a balk?', '哪张图是投手犯规？', 'ボークはどの絵？'), ('¡Eso es! Empezar y pararse: balk.', "That's it! Starting and stopping: balk.", '对了！开始又停下来：投手犯规。', 'そのとおり！はじめて止まる：ボーク。'), ('Detenerse a mitad del movimiento es el balk clásico.', 'Stopping halfway through the motion is the classic balk.', '动作做到一半停下来，就是最典型的投手犯规。', '動きのとちゅうで止まるのが、ボークの代表。'), opts={'a': ('El pitcher empieza a lanzar y se detiene a mitad de camino', 'The pitcher starts to pitch and stops halfway', '投手开始投球，做到一半停下来', 'ピッチャーが投げはじめて、とちゅうで止まる'), 'b': ('El pitcher lanza normal a home', 'The pitcher pitches normally to home', '投手正常地投向本垒', 'ピッチャーがふつうにホームへ投げる'), 'c': ('El pitcher tira un pickoff legal y completo', 'The pitcher makes a legal, complete pickoff', '投手做了一个合规、完整的牵制传球', 'ピッチャーが正しく、さいごまで牽制球を投げる')}), '5': act(('El pitcher fingió tirar a primera y se quedó con la bola, con corredor en primera. ¿Qué canta el umpire?', 'The pitcher faked a throw to first and kept the ball, with a runner on first. What does the umpire call?', '一垒有跑垒员，投手假装传向一垒，球却留在手里。裁判怎么判？', '一塁にランナー。ピッチャーが一塁に投げるふりをして、ボールを持ったまま。審判のコールは？'), ('¡Balk! Y el corredor avanza.', 'Balk! And the runner moves up.', '投手犯规！跑垒员前进。', 'ボーク！ランナーが進む。'), ('Fingir sin soltar: balk y una base.', 'Faking without letting go: balk and one base.', '假装传球却不出手：投手犯规，进一个垒。', 'はなさずにふり：ボークで1つ進む。'), opts={'a': ('¡Balk! Corredor a segunda', 'Balk! Runner to second', '投手犯规！跑垒员进二垒', 'ボーク！ランナーは二塁へ'), 'b': ('¡Safe!', 'Safe!', '安全上垒！', 'セーフ！'), 'c': ('¡Strike!', 'Strike!', '好球！', 'ストライク！')}), '6': act(('En tu liga infantil quizá el balk:', "In your kids' league, maybe the balk:", '在你的少儿联赛里，投手犯规可能：', '君の子どものリーグでは、ボークはたぶん：'), ('¡Correcto! Cada liga lo trata a su manera.', 'Correct! Each league handles it its own way.', '正确！每个联赛都有自己的处理方式。', '正解！リーグごとにやり方がちがう。'), ('En niños, muchas ligas enseñan antes de castigar.', 'With kids, many leagues teach before punishing.', '对小朋友，很多联赛先教再罚。', '子どものリーグの多くは、ばつの前に教える。'), opts={'a': ('No se canta todavía, o avisan primero: pregúntale a tu coach', "Isn't called yet, or they warn first: ask your coach", '还不判，或者先提醒：问问你的教练', 'まだとらないか、まず注意する：コーチに聞こう'), 'b': ('Se castiga con expulsión siempre', 'Is always punished by ejection', '一定会被驱逐出场', 'いつも退場になる'), 'c': ('No existe en ningún lado', "Doesn't exist anywhere", '哪里都没有', 'どこにもない')})})
map_titles['9.4'] = ('El balk: el engaño que no vale', "The balk: the trick that doesn't count", '投手犯规：不算数的骗人动作', 'ボーク：やってはいけないフェイント')
lesson('9.5', ('Wild pitch y passed ball', 'Wild pitch and passed ball', '暴投与捕逸', 'ワイルドピッチとパスボール'), ('Distinguir: wild pitch es un lanzamiento tan malo que el catcher no puede atraparlo ni bloquearlo (culpa del pitcher); passed ball es una bola atrapable que se le escapa al catcher (culpa del catcher). En ambos, los corredores pueden avanzar bajo su riesgo.', "Tell apart: a wild pitch is a pitch so bad the catcher can't catch or block it (the pitcher's fault); a passed ball is a catchable ball that gets away from the catcher (the catcher's fault). In both, runners can advance at their own risk.", '分清：暴投（wild pitch）是投得太差、捕手接不到也挡不住的球（投手的责任）；捕逸（passed ball）是能接住却让它从捕手那里溜走的球（捕手的责任）。两种情况下，跑垒员都可以冒险前进。', '見分けよう：ワイルドピッチは、キャッチャーがとることも止めることもできないほど悪い投球（ピッチャーの責任）。パスボールは、とれるボールをキャッチャーがのがすこと（キャッチャーの責任）。どちらも、ランナーは自分の判断で進んでいい。'), [('A veces la bola se escapa detrás del catcher y los corredores corren.', 'Sometimes the ball gets away behind the catcher and the runners run.', '有时候球从捕手身后溜走，跑垒员就跑起来了。', 'ときどき、ボールがキャッチャーのうしろへ転がって、ランナーが走る。'), ('¿De quién fue la culpa?', 'Whose fault was it?', '是谁的责任？', 'だれの責任？'), ('Si el lanzamiento fue tan malo — muy alto, muy bajo o muy lejos — que el catcher no tenía forma de atraparlo, es wild pitch: lanzamiento descontrolado, culpa del pitcher.', "If the pitch was so bad — very high, very low or very far — that the catcher had no way to catch it, it's a wild pitch: the pitcher's fault.", '如果球投得太差——太高、太低或太偏——捕手根本没办法接住，就是暴投（wild pitch）：投手的责任。', '投球が悪すぎて——高すぎ、低すぎ、遠すぎ——キャッチャーがとれなかったら、ワイルドピッチ（wild pitch）、暴投：ピッチャーの責任。'), ('Si la bola era normal y atrapable y se le escapó al catcher, es passed ball: bola pasada, culpa del catcher.', "If the ball was normal and catchable and the catcher let it get away, it's a passed ball: the catcher's fault.", '如果球很正常、能接住，却从捕手那里溜走了，就是捕逸（passed ball）：捕手的责任。', 'ふつうでとれるボールをキャッチャーがのがしたら、パスボール（passed ball）、捕逸：キャッチャーの責任。'), ('Culpas distintas, mismo apuro: los corredores pueden intentar avanzar, y el catcher debe recuperar la bola volando.', 'Different faults, same hurry: the runners can try to move up, and the catcher has to get the ball back fast.', '责任不同，一样着急：跑垒员可以试着前进，捕手要飞快地把球捡回来。', '責任はちがっても、あわてるのは同じ：ランナーは進もうとしていいし、キャッチャーは急いでボールをとりにいく。')], {'1': act(('El lanzamiento pasa por encima de la cabeza del catcher, imposible de atrapar. Es:', "The pitch goes over the catcher's head, impossible to catch. It is:", '投球从捕手头顶飞过，根本接不到。这是：', '投球がキャッチャーの頭の上をこえて、とれない。これは：'), ('¡Eso es! Culpa del pitcher.', "That's it! The pitcher's fault.", '对了！投手的责任。', 'そのとおり！ピッチャーの責任。'), ('Bola imposible: wild pitch.', 'Impossible ball: wild pitch.', '接不到的球：暴投。', 'とれないボール：ワイルドピッチ。'), opts={'a': ('Wild pitch (lanzamiento descontrolado)', 'Wild pitch', '暴投（wild pitch）', 'ワイルドピッチ（暴投）'), 'b': ('Passed ball', 'Passed ball', '捕逸', 'パスボール'), 'c': ('Balk', 'Balk', '投手犯规', 'ボーク')}), '2': act(('La bola llega normal al guante y se le escapa al catcher. Es:', 'The ball arrives normally at the glove and gets away from the catcher. It is:', '球正常地到了手套，却从捕手那里溜走了。这是：', 'ボールはふつうにミットに来たのに、キャッチャーがのがした。これは：'), ('¡Correcto! Era atrapable: passed ball.', 'Correct! It was catchable: passed ball.', '正确！能接住的球：捕逸。', '正解！とれた：パスボール。'), ('Atrapable y escapada: bola pasada.', 'Catchable and got away: passed ball.', '能接住却溜走了：捕逸。', 'とれるのにのがした：パスボール。'), opts={'a': ('Passed ball (bola pasada)', 'Passed ball', '捕逸（passed ball）', 'パスボール（捕逸）'), 'b': ('Wild pitch', 'Wild pitch', '暴投', 'ワイルドピッチ'), 'c': ('Un strike siempre', 'Always a strike', '一定是好球', 'いつもストライク')}), '3': act(('En un wild pitch o una passed ball, los corredores pueden avanzar si se atreven', 'On a wild pitch or a passed ball, the runners can advance if they dare', '暴投或捕逸时，跑垒员敢跑就可以前进', 'ワイルドピッチやパスボールのとき、ランナーは思いきって進んでいい'), ('¡Bien! La bola anda suelta.', 'Good! The ball is loose.', '很好！球没人控制。', 'いいね！ボールが転がっている。'), ('Verdadero: bola suelta, a correr con cuidado.', 'True: loose ball, run carefully.', '这是对的：球没人控制，小心地跑。', '正しいよ：ボールが転がっている、気をつけて走ろう。')), '4': act(('La diferencia entre wild pitch y passed ball es:', 'The difference between a wild pitch and a passed ball is:', '暴投和捕逸的区别是：', 'ワイルドピッチとパスボールのちがいは：'), ('¡Eso es! Así lo decide el anotador.', "That's it! That's how the scorer decides.", '对了！记录员就是这样决定的。', 'そのとおり！記録員はそうやって決める。'), ('Misma escapada, culpas distintas.', 'Same escape, different faults.', '一样溜走，责任不同。', '同じのがしでも、責任がちがう。'), opts={'a': ('De quién es la culpa: del pitcher o del catcher', "Whose fault it is: the pitcher's or the catcher's", '是谁的责任：投手还是捕手', 'だれの責任か：ピッチャーかキャッチャーか'), 'b': ('El color de la bola', 'The color of the ball', '球的颜色', 'ボールの色'), 'c': ('La entrada', 'The inning', '局数', 'イニング')}), '5': act(('La bola se escapó al fondo y el corredor de tercera anotó. Esa jugada NO se anota como:', 'The ball got away to the back and the runner from third scored. That play is NOT scored as:', '球溜到后面，三垒跑垒员跑回得分。这个打法“不”记作：', 'ボールがうしろへ転がって、三塁ランナーが得点した。このプレーの記録に「ならない」のは：'), ('¡Correcto! Avanzar por bola escapada no es robo.', "Correct! Moving up on a ball that got away isn't a steal.", '正确！趁球溜走前进不是盗垒。', '正解！のがしたボールで進んでも盗塁じゃない。'), ('El robo es durante el lanzamiento, no por la escapada.', 'A steal happens during the pitch, not because of the escape.', '盗垒是在投球时跑，不是因为球溜走了。', '盗塁は投球のあいだに走ること。のがしたからじゃない。'), opts={'a': ('Base robada', 'Stolen base', '盗垒', '盗塁'), 'b': ('Carrera', 'Run', '得分', '得点'), 'c': ('Avance', 'Advance', '进垒', '進塁')}), '6': act(('La bola escapada rodó hasta el fondo, detrás de home. Toca hacia dónde debe correr el catcher a buscarla', 'The ball that got away rolled all the way to the back, behind home. Tap where the catcher has to run to get it', '溜走的球一直滚到后面，在本垒后方。点一下捕手要跑去捡球的地方', 'のがしたボールが、ホームのうしろのおくまで転がった。キャッチャーがとりに走る場所をタッチしよう'), ('¡Bien! A recuperarla volando.', 'Good! Get it back fast.', '很好！快把球捡回来。', 'いいね！急いでとりにいこう。'), ('Detrás de home está la bola suelta.', 'The loose ball is behind home.', '没人控制的球在本垒后方。', '転がったボールはホームのうしろ。'), answer=('Detrás de home', 'Behind home', '本垒后方', 'ホームのうしろ'))})
