exams_v3['9'] = {'1': {'q': ('Robar una base es avanzar:', 'Stealing a base is moving up:', '盗垒是在什么时候前进：', '盗塁は、どうやって進むこと？'), 'opts': {'a': ('Durante el lanzamiento, sin batazo', 'During the pitch, with no batted ball', '投球时，没有击球', '打球なしで、投球のあいだに'), 'b': ('Con un jonrón', 'With a home run', '靠本垒打', 'ホームランで'), 'c': ('Caminando tranquilo', 'Walking calmly', '慢慢走过去', 'のんびり歩いて')}}, '2': {'q': ('¿Cómo se dice robo de base en inglés?', "What's it called when you take the next base during the pitch?", '“盗垒”的英语怎么说？', '盗塁は英語で何という？'), 'opts': {'a': ('Stolen base', 'Stolen base', 'Stolen base', 'Stolen base'), 'b': ('Safe base', 'Safe base', 'Safe base', 'Safe base'), 'c': ('Fast base', 'Fast base', 'Fast base', 'Fast base')}}, '3': {'q': ('¿Quién decide si en tu liga se puede robar?', 'Who decides if you can steal in your league?', '谁决定你们联赛能不能盗垒？', '君のリーグで盗塁できるかを決めるのはだれ？'), 'opts': {'a': ('Mi liga y mi coach', 'My league and my coach', '我的联赛和我的教练', 'リーグとコーチ'), 'b': ('El público', 'The crowd', '观众', 'お客さん'), 'c': ('Yo mismo', 'Myself', '我自己', '自分')}}, '4': {'q': ('Toca la base que más se roba desde primera', 'Tap the base that is stolen most from first', '点一下从一垒出发最常被盗的垒', '一塁からいちばんよくぬすまれる塁をタッチしよう'), 'answer': ('Segunda base', 'Second base', '二垒', '二塁')}, '5': {'q': ('¿Qué es despegarse de la base (lead)?', 'What is taking a lead?', '什么是离垒（lead）？', 'リードって何？'), 'opts': {'a': ('Alejarse unos pasos de la base para acortar el camino', 'Stepping a few steps off the base to shorten the way', '离开垒包几步，让跑垒的路变短', '塁から何歩かはなれて、次の塁までを近くする'), 'b': ('Correr a home', 'Running home', '跑回本垒', 'ホームへ走る'), 'c': ('Sentarse en la base', 'Sitting on the base', '坐在垒包上', '塁にすわる')}}, '6': {'q': ('Estás despegado y el pitcher mira hacia tu base. ¿Qué haces?', 'You have a lead and the pitcher looks at your base. What do you do?', '你离垒了，投手看向你的垒。你怎么做？', 'リードしていたら、ピッチャーが君の塁を見た。どうする？'), 'opts': {'a': ('Vuelvo rápido a mi base', 'I get back to my base fast', '我快速跑回自己的垒', 'すぐ自分の塁にもどる'), 'b': ('Me quedo quieto', 'I stand still', '我站着不动', 'じっとしている'), 'c': ('Corro a la siguiente', 'I run to the next one', '我跑向下一个垒', '次の塁へ走る')}}, '7': {'q': ('¿Qué es un pickoff?', 'What is a pickoff?', '什么是牵制（pickoff）？', '牽制球（pickoff）って何？'), 'opts': {'a': ('Un tiro de sorpresa a una base para sacar out al corredor despegado', 'A surprise throw to a base to get the runner with a lead out', '突然传向垒包，想让离垒的跑垒员出局', 'リードしているランナーをアウトにするため、ふいに塁へ投げる送球'), 'b': ('Un lanzamiento muy rápido', 'A very fast pitch', '很快的投球', 'とても速い投球'), 'c': ('Un batazo corto', 'A short hit', '短打', '短い打球')}}, '8': {'q': ('Verdadero o falso: en un pickoff, si vuelves a tu base antes de que te toquen, eres safe', "True or false: on a pickoff, if you get back to your base before you're tagged, you're safe", '对还是错：牵制时，你在被触杀之前回到垒上，就安全上垒', '○か×か：牽制球で、タッチされる前に塁にもどれたらセーフ')}, '9': {'q': ('Con corredores en base, el pitcher empieza a lanzar y se detiene. ¿Qué es?', 'With runners on base, the pitcher starts his motion and stops. What is it?', '有跑垒员时，投手开始投球动作又停下来。这是什么？', 'ランナーがいるとき、ピッチャーが投げはじめて止まった。これは？'), 'opts': {'a': ('Un balk', 'A balk', '投手犯规（balk）', 'ボーク'), 'b': ('Un strike', 'A strike', '好球', 'ストライク'), 'c': ('Un pickoff', 'A pickoff', '牵制', '牽制球')}}, '10': {'q': ('¿Qué pasa con un balk?', 'What happens on a balk?', '投手犯规会怎样？', 'ボークになるとどうなる？'), 'opts': {'a': ('Cada corredor avanza una base', 'Every runner moves up one base', '每个跑垒员都进一个垒', 'ランナーがみんな1つ進む'), 'b': ('El bateador es out', 'The batter is out', '击球员出局', 'バッターがアウト'), 'c': ('El pitcher batea', 'The pitcher bats', '投手去击球', 'ピッチャーが打つ')}}, '11': {'q': ('Un lanzamiento tan malo que el catcher no puede atraparlo ni bloquearlo es:', "A pitch so wild the catcher can't catch it or block it is:", '投得太偏，捕手接不到也挡不住的球是：', 'キャッチャーがとることも止めることもできない、とても悪い投球は：'), 'opts': {'a': ('Un wild pitch', 'A wild pitch', '暴投（wild pitch）', 'ワイルドピッチ'), 'b': ('Un passed ball', 'A passed ball', '捕逸（passed ball）', 'パスボール'), 'c': ('Un balk', 'A balk', '投手犯规', 'ボーク')}}, '12': {'q': ('Una bola que se podía atrapar se le escapa al catcher. ¿Qué es?', 'A catchable pitch gets past the catcher. What is it?', '一个本来能接住的球从捕手那里漏掉了。这是什么？', 'とれるはずの球を、キャッチャーがそらした。これは？'), 'opts': {'a': ('Un passed ball', 'A passed ball', '捕逸（passed ball）', 'パスボール'), 'b': ('Un wild pitch', 'A wild pitch', '暴投', 'ワイルドピッチ'), 'c': ('Un hit', 'A hit', '安打', 'ヒット')}}}
