levels['10'] = dict(title=('Reglas especiales', 'Special rules', '特殊规则', '特別なルール'), badge=('Juez del Diamante', 'Diamond Judge', '钻石裁判', 'ダイヤモンドの審判'))
lesson('10.1', ('Tercer strike caído', 'Dropped third strike', '不死三振', '振り逃げ'), ('Entender el tercer strike caído: si el catcher no atrapa limpio el tercer strike, el bateador puede correr a primera cuando la regla aplica — primera libre, o primera ocupada con dos outs — y que en muchas ligas infantiles esta regla no existe todavía.', "Understand the dropped third strike: if the catcher doesn't catch the third strike cleanly, the batter can run to first when the rule applies — first base open, or first occupied with two outs — and that in many kids' leagues this rule doesn't exist yet.", '明白不死三振（dropped third strike）：如果捕手没有干净地接住第三个好球，在规则适用时——一垒没人，或者一垒有人但已经两出局——击球员可以跑向一垒；还要知道很多少儿联赛还没有这条规则。', '振り逃げ（dropped third strike）を知ろう：キャッチャーが3つ目のストライクをきちんととれなかったら、ルールが使えるとき——一塁があいている、または一塁にランナーがいても2アウト——バッターは一塁へ走れる。多くの子どものリーグには、このルールがまだない。'), [('El bateador se ponchó… ¿o no?', 'The batter struck out… or did he?', '击球员三振了……真的吗？', 'バッターは三振……ほんとうに？'), ('Si el tercer strike no queda atrapado limpio por el catcher — se le cae o pica antes — y la regla aplica, el bateador puede ¡correr a primera!', "If the catcher doesn't catch the third strike cleanly — he drops it or it bounces first — and the rule applies, the batter can run to first!", '如果捕手没有干净地接住第三个好球——球掉了，或者先弹地——而且规则适用，击球员就可以跑向一垒！', '3つ目のストライクをキャッチャーがきちんととれなかったら——落とした、または先にバウンドした——ルールが使えるとき、バッターは一塁へ走れる！'), ('Se llama tercer strike caído, en inglés dropped third strike.', "It's called the dropped third strike.", '这叫不死三振，英语叫 dropped third strike。', 'これを振り逃げという。英語で dropped third strike。'), ('Aplica cuando primera está libre, o cuando hay dos outs aunque primera esté ocupada.', 'It applies when first base is open, or when there are two outs even if first is occupied.', '一垒没人时适用；或者两出局时，即使一垒有人也适用。', '一塁があいているとき、または2アウトなら一塁にランナーがいても使える。'), ('El catcher debe tocarlo con la bola o tirar a primera.', 'The catcher has to tag him with the ball or throw to first.', '捕手要拿球触到他，或者传向一垒。', 'キャッチャーはボールでタッチするか、一塁に投げなきゃいけない。'), ('Y ojo con tu liga: en muchas ligas de niños pequeños esta regla no se usa: el ponche es ponche y listo.', "And watch out for your league: in many leagues for young kids this rule isn't used: a strikeout is a strikeout, period.", '还要注意你们联赛：很多小朋友的联赛不用这条规则：三振就是三振，没别的。', 'それから君のリーグに気をつけて：小さい子のリーグの多くでは、このルールは使わない。三振は三振、それでおしまい。'), ('Pregunta a tu coach si en tu liga el bateador puede correr.', 'Ask your coach if the batter can run in your league.', '问问你的教练，你们联赛击球员能不能跑。', '君のリーグでバッターが走れるか、コーチに聞いてみよう。')], {'1': act(('¿Qué es el tercer strike caído?', 'What is the dropped third strike?', '什么是不死三振？', '振り逃げって何？'), ('¡Eso es! Dropped third strike.', "That's it! Dropped third strike.", '对了！不死三振。', 'そのとおり！振り逃げ。'), ('Tercer strike sin atrapada limpia: a correr, si la regla aplica.', 'Third strike without a clean catch: run, if the rule applies.', '第三个好球没接好：规则适用就跑。', '3つ目のストライクをきちんととれなかった：ルールが使えるなら走ろう。'), opts={'a': ('El catcher no atrapa limpio el tercer strike y el bateador puede correr a primera', "The catcher doesn't catch the third strike cleanly and the batter can run to first", '捕手没有干净地接住第三个好球，击球员可以跑向一垒', 'キャッチャーが3つ目のストライクをきちんととれず、バッターが一塁へ走れること'), 'b': ('Un strike que cae al suelo antes del bateador siempre', 'A strike that always falls to the ground before the batter', '一个总是在击球员前面落地的好球', 'いつもバッターの前で地面に落ちるストライク'), 'c': ('Un tipo de guante', 'A kind of glove', '一种手套', 'グラブの種類')}), '2': act(('Con primera libre y un out, el tercer strike se le escapa al catcher. El bateador debe:', 'With first base open and one out, the third strike gets away from the catcher. The batter must:', '一垒没人、一出局，第三个好球从捕手那里溜走。击球员要：', '一塁があいていて1アウト。3つ目のストライクをキャッチャーがのがした。バッターは：'), ('¡Correcto! Primera libre: a correr.', 'Correct! First is open: run.', '正确！一垒没人：快跑。', '正解！一塁があいている：走ろう。'), ('La regla te da esa oportunidad.', 'The rule gives you that chance.', '规则给了你这个机会。', 'ルールがそのチャンスをくれる。'), opts={'a': ('Correr a primera', 'Run to first', '跑向一垒', '一塁へ走る'), 'b': ('Volver al dugout', 'Go back to the dugout', '回休息区', 'ダッグアウトにもどる'), 'c': ('Quedarse parado', 'Stand still', '站着不动', 'じっとしている')}), '3': act(('Con primera ocupada y menos de dos outs, el bateador también puede correr con el tercer strike caído', 'With first occupied and fewer than two outs, the batter can also run on a dropped third strike', '一垒有人且不到两出局时，不死三振击球员也可以跑', '一塁にランナーがいて2アウト前でも、振り逃げで走れる'), ('¡Bien! Con primera ocupada solo aplica con dos outs.', 'Good! With first occupied it only applies with two outs.', '很好！一垒有人时，只有两出局才适用。', 'いいね！一塁にランナーがいたら、2アウトのときだけ。'), ('Falso: primera ocupada cierra la puerta, salvo con dos outs.', 'False: first occupied closes the door, except with two outs.', '错：一垒有人就不行，除非两出局。', 'まちがい：一塁がうまっているとだめ。2アウトならべつ。')), '4': act(('Con dos outs y primera ocupada, tercer strike caído. El bateador:', 'Two outs and first occupied, dropped third strike. The batter:', '两出局、一垒有人，不死三振。击球员：', '2アウトで一塁にランナー、振り逃げ。バッターは：'), ('¡Eso es! Con dos outs la puerta se abre.', "That's it! With two outs the door opens.", '对了！两出局时门就开了。', 'そのとおり！2アウトならドアがひらく。'), ('Dos outs: aunque primera esté ocupada, puede correr.', 'Two outs: even if first is occupied, he can run.', '两出局：即使一垒有人，也可以跑。', '2アウト：一塁がうまっていても走れる。'), opts={'a': ('Sí puede correr a primera', 'Yes, can run to first', '可以跑向一垒', '一塁へ走れる'), 'b': ('Nunca puede', 'Never can', '永远不行', '走れない'), 'c': ('Debe lanzar', 'Has to pitch', '要去投球', '投げなきゃいけない')}), '5': act(('El catcher atrapó limpio el tercer strike. ¿Qué canta el umpire?', 'The catcher caught the third strike cleanly. What does the umpire call?', '捕手干净地接住了第三个好球。裁判怎么判？', 'キャッチャーが3つ目のストライクをきちんととった。審判のコールは？'), ('¡Out! Atrapada limpia, no hay carrera a primera.', 'Out! Clean catch, no running to first.', '出局！干净接住，不能跑一垒。', 'アウト！きちんととったから、一塁へは走れない。'), ('Si el catcher la atrapa limpio, el ponche es final.', 'If the catcher catches it cleanly, the strikeout is final.', '捕手干净接住，三振就成立了。', 'キャッチャーがきちんととれば、三振で決まり。'), opts={'a': ('¡Out! Ponche completo', 'Out! Complete strikeout', '出局！三振成立', 'アウト！三振成立'), 'b': ('¡Safe!', 'Safe!', '安全上垒！', 'セーフ！'), 'c': ('¡Balk!', 'Balk!', '投手犯规！', 'ボーク！')}), '6': act(('En tu liga infantil, lo primero que debes saber de esta regla es:', "In your kids' league, the first thing you need to know about this rule is:", '在你的少儿联赛里，关于这条规则你首先要知道：', '君の子どものリーグで、このルールについてまず知っておくことは：'), ('¡Correcto! Muchas ligas de niños pequeños no la usan.', "Correct! Many leagues for young kids don't use it.", '正确！很多小朋友的联赛不用它。', '正解！小さい子のリーグの多くは使わない。'), ('Regla de liga: coach primero.', 'League rule: coach first.', '联赛的规定：先问教练。', 'リーグのルール：まずコーチに。'), opts={'a': ('Si mi liga la usa a mi edad: pregúntale a tu coach', 'If my league uses it at my age: ask your coach', '我的联赛在我这个年龄用不用：问问你的教练', '自分の年齢でリーグが使っているか：コーチに聞こう'), 'b': ('Que vale siempre en todo el mundo', 'That it always counts everywhere in the world', '它在全世界永远都适用', '世界中どこでもいつも使う'), 'c': ('Que la inventó el catcher', 'That the catcher invented it', '它是捕手发明的', 'キャッチャーが考えた')})})
map_titles['10.1'] = ('Tercer strike caído', 'Dropped third strike', '不死三振', '振り逃げ')
lesson('10.2', ('Infield fly: el out que protege', 'Infield fly: the out that protects', '内野飞球：保护人的出局', 'インフィールドフライ：守るためのアウト'), ('Entender el infield fly con el porqué: con corredores en primera y segunda (o bases llenas) y menos de dos outs, un elevado fácil al cuadro es out automático del bateador, para que la defensa no lo deje caer a propósito y haga un doble play tramposo.', "Understand the infield fly and why: with runners on first and second (or the bases loaded) and fewer than two outs, an easy fly ball to the infield is an automatic out for the batter, so the defense doesn't drop it on purpose to make a sneaky double play.", '明白内野飞球规则（infield fly）和它的理由：一垒和二垒有人（或满垒）且不到两出局时，打向内野的容易高飞球，击球员自动出局，这样防守方就不能故意让球掉下来，耍诈打出双杀。', 'インフィールドフライ（infield fly）と、その理由を知ろう：一塁と二塁にランナー（または満塁）で2アウト前のとき、内野へのかんたんなフライはバッターが自動でアウト。守備がわざと落として、ずるいダブルプレーをしないためだ。'), [('Escucha el porqué, y nunca se te olvida.', "Listen to the why, and you'll never forget it.", '听懂为什么，你就永远不会忘。', '理由を聞けば、ぜったいわすれないよ。'), ('Corredores en primera y segunda, un elevado fácil al cuadro.', 'Runners on first and second, an easy fly ball to the infield.', '一垒和二垒有跑垒员，一个打向内野的容易高飞球。', '一塁と二塁にランナー、内野へかんたんなフライ。'), ('Si la defensa lo deja caer a propósito, los corredores quedan atrapados: no saben si correr o quedarse, y la defensa haría un doble play de regalo.', "If the defense drops it on purpose, the runners are trapped: they don't know whether to run or stay, and the defense would get an easy double play.", '如果防守方故意让球掉下来，跑垒员就被困住了：不知道该跑还是该留，防守方就白捡一个双杀。', '守備がわざと落としたら、ランナーはこまってしまう：走るか、のこるか、わからない。守備はダブルプレーをただでもらえちゃう。'), ('Para proteger a los corredores existe el infield fly: el umpire canta «infield fly, bateador out» en cuanto ve que es un elevado fácil del cuadro, con menos de dos outs.', 'To protect the runners there is the infield fly: the umpire calls "infield fly, batter out" as soon as he sees it\'s an easy infield fly ball, with fewer than two outs.', '为了保护跑垒员，才有了内野飞球规则：只要裁判看出这是内野的容易高飞球、而且不到两出局，就会喊“内野飞球，击球员出局”。', 'ランナーを守るために、インフィールドフライがある：2アウト前で、内野のかんたんなフライだとわかったら、審判は「インフィールドフライ、バッターアウト」とコールする。'), ('El bateador es out aunque la bola caiga, y los corredores pueden avanzar bajo su riesgo, como con cualquier elevado.', 'The batter is out even if the ball falls, and the runners can move up at their own risk, as with any fly ball.', '即使球掉下来，击球员也出局；跑垒员可以冒险前进，就像任何高飞球一样。', 'ボールが落ちてもバッターはアウト。ランナーは、ふつうのフライと同じように、自分の判断で進んでいい。'), ('La regla castiga la trampa, no al bateador.', 'The rule punishes the trick, not the batter.', '这条规则惩罚的是耍诈，不是击球员。', 'このルールがばつするのは、ずるで、バッターじゃない。')], {'1': act(('¿Para qué existe el infield fly?', 'Why does the infield fly exist?', '为什么会有内野飞球规则？', 'インフィールドフライは何のためにある？'), ('¡Eso es! Protege a los corredores.', "That's it! It protects the runners.", '对了！它保护跑垒员。', 'そのとおり！ランナーを守る。'), ('La regla es un escudo contra la trampa.', 'The rule is a shield against the trick.', '这条规则是对付耍诈的盾牌。', 'このルールは、ずるをふせぐたて。'), opts={'a': ('Para que la defensa no deje caer un elevado fácil a propósito y haga un doble play tramposo', "So the defense doesn't drop an easy fly ball on purpose to make a sneaky double play", '为了不让防守方故意让容易的高飞球掉下来，耍诈打出双杀', '守備がかんたんなフライをわざと落として、ずるいダブルプレーをしないため'), 'b': ('Para que el juego sea más rápido', 'To make the game faster', '为了让比赛更快', '試合を速くするため'), 'c': ('Para castigar al bateador', 'To punish the batter', '为了惩罚击球员', 'バッターをばつするため')}), '2': act(('El infield fly se canta con corredores en:', 'The infield fly is called with runners on:', '内野飞球在什么情况下判：', 'インフィールドフライがコールされるランナーは：'), ('¡Correcto! Esas bases y esos outs.', 'Correct! Those bases and those outs.', '正确！这些垒，这些出局数。', '正解！その塁と、そのアウト数。'), ('Primera y segunda, menos de dos outs: ahí vive la regla.', "First and second, fewer than two outs: that's where the rule lives.", '一垒二垒有人，不到两出局：这就是规则适用的时候。', '一塁と二塁、2アウト前：そこでルールが使われる。'), opts={'a': ('Primera y segunda (o bases llenas) y menos de dos outs', 'First and second (or bases loaded) and fewer than two outs', '一垒和二垒有人（或满垒），且不到两出局', '一塁と二塁（または満塁）で、2アウト前'), 'b': ('Solo tercera', 'Only third', '只有三垒有人', '三塁だけ'), 'c': ('Bases vacías', 'Bases empty', '垒上没人', 'ランナーなし')}), '3': act(('Con dos outs también se canta infield fly', 'The infield fly is also called with two outs', '两出局时也判内野飞球', '2アウトでもインフィールドフライがコールされる'), ('¡Bien! Con dos outs no hace falta.', "Good! With two outs it isn't needed.", '很好！两出局时不需要。', 'いいね！2アウトならいらない。'), ('Falso: con dos outs la trampa no funciona, no se canta.', "False: with two outs the trick doesn't work, it isn't called.", '错：两出局时耍诈没用，所以不判。', 'まちがい：2アウトではずるがきかないから、コールしない。')), '4': act(('Elevado fácil al campocorto con corredores en primera y segunda y un out. El umpire canta:', 'Easy fly ball to the shortstop with runners on first and second and one out. The umpire calls:', '一垒二垒有人、一出局，一个打给游击手的容易高飞球。裁判喊：', '一塁と二塁にランナー、1アウト。遊撃手へかんたんなフライ。審判のコールは：'), ('¡Eso es! Out antes de que caiga.', "That's it! Out before it falls.", '对了！球还没落地就出局。', 'そのとおり！落ちる前にアウト。'), ('El canto llega con la bola en el aire.', 'The call comes with the ball in the air.', '球还在空中时裁判就喊了。', 'ボールが空中にあるうちにコールする。'), opts={'a': ('«¡Infield fly! Bateador out»', '"Infield fly! Batter out"', '“内野飞球！击球员出局”', '「インフィールドフライ！バッターアウト」'), 'b': ('«¡Safe!»', '"Safe!"', '“安全上垒！”', '「セーフ！」'), 'c': ('«¡Balk!»', '"Balk!"', '“投手犯规！”', '「ボーク！」')}), '5': act(('Si la bola del infield fly cae al suelo sin que nadie la atrape, el bateador:', 'If the infield fly ball falls to the ground without anyone catching it, the batter:', '如果内野飞球掉到地上没人接住，击球员：', 'インフィールドフライのボールがだれにもとられずに落ちたら、バッターは：'), ('¡Correcto! El out ya fue cantado.', 'Correct! The out was already called.', '正确！出局已经判了。', '正解！アウトはもうコールされた。'), ('Caiga o no caiga: bateador out.', 'Whether it falls or not: batter out.', '不管球掉不掉：击球员出局。', '落ちても落ちなくても：バッターアウト。'), opts={'a': ('Igual es out', 'Is out anyway', '照样出局', 'それでもアウト'), 'b': ('Se convierte en hit', 'It becomes a hit', '变成安打', 'ヒットになる'), 'c': ('Debe correr a primera', 'Has to run to first', '要跑向一垒', '一塁へ走らなきゃいけない')}), '6': act(('¿Cuál elevado puede ser infield fly?', 'Which fly ball can be an infield fly?', '哪个高飞球可以是内野飞球？', 'インフィールドフライになるのはどのフライ？'), ('¡Eso es! Fácil y en el cuadro.', "That's it! Easy and in the infield.", '对了！容易而且在内野。', 'そのとおり！かんたんで内野。'), ('Debe ser un elevado que un jugador del cuadro atrapa sin apuro.', 'It has to be a fly ball an infielder catches without hurrying.', '必须是内野手不用着急就能接住的高飞球。', '内野の選手があわてずにとれるフライじゃなきゃいけない。'), opts={'a': ('Un elevado fácil y alto sobre el cuadro', 'An easy, high fly ball over the infield', '一个内野上空又高又容易的高飞球', '内野の上の、高くてかんたんなフライ'), 'b': ('Una línea dura al jardín', 'A hard line drive to the outfield', '一个打向外野的强劲平直球', '外野への強いライナー'), 'c': ('Un elevado profundo a la pared', 'A deep fly ball to the wall', '一个飞向围墙的深远高飞球', 'フェンスへの深いフライ')})})
map_titles['10.2'] = ('Infield fly: el out que protege', 'Infield fly: the out that protects', '内野飞球：保护人的出局', 'インフィールドフライ：守るためのアウト')
lesson('10.3', ('Bola viva y bola muerta', 'Live ball and dead ball', '活球与死球（比赛停止）', 'ボールインプレーとボールデッド'), ('Distinguir bola viva (se puede correr y hacer outs) de bola muerta (todo se detiene: foul es el ejemplo diario, también el tiempo pedido y concedido, y un lanzamiento que golpea al bateador).', 'Tell apart a live ball (you can run and make outs) from a dead ball (everything stops: a foul is the everyday example, also time requested and granted, and a pitch that hits the batter).', '分清活球（可以跑垒、可以制造出局）和死球（比赛停止）（一切都停下来：界外球是最常见的例子，还有要求并获准的暂停，以及打到击球员的投球）。', 'ボールインプレー（走れるし、アウトにもできる）と、ボールデッド（すべて止まる：ファウルがいつもの例。タイムをもらったときや、投球がバッターに当たったときも）を見分けよう。'), [('La bola tiene dos estados, como un semáforo.', 'The ball has two states, like a traffic light.', '球有两种状态，就像红绿灯。', 'ボールには、信号みたいに2つのじょうたいがある。'), ('Bola viva, en inglés live ball: el semáforo está en verde, se puede correr, tirar y hacer outs.', 'Live ball: the light is green, you can run, throw and make outs.', '活球，英语叫 live ball：绿灯亮了，可以跑、可以传、可以制造出局。', 'ボールインプレー、英語で live ball：信号は青。走って、投げて、アウトにできる。'), ('Bola muerta, dead ball: luz roja, todo se detiene y nadie puede avanzar ni ser out.', 'Dead ball: red light, everything stops and nobody can move up or be put out.', '死球（比赛停止），dead ball：红灯亮了，一切都停下来，谁都不能进垒，也不会出局。', 'ボールデッド、dead ball：赤信号。すべて止まって、だれも進めないし、アウトにもならない。'), ('El foul es bola muerta.', 'A foul is a dead ball.', '界外球就是死球（比赛停止）。', 'ファウルはボールデッド。'), ('Cuando el umpire concede tiempo, también.', 'When the umpire grants time, too.', '裁判同意暂停时，也是。', '審判がタイムをみとめたときも。'), ('Y cuando un lanzamiento golpea al bateador, la bola muere en ese instante.', 'And when a pitch hits the batter, the ball goes dead that very instant.', '投球打到击球员的那一刻，球也就“死”了，比赛停止。', 'それから、投球がバッターに当たったしゅんかん、ボールデッドになる。'), ('Apréndete el semáforo: verde, juego; roja, quieto.', 'Learn the traffic light: green, play; red, freeze.', '记住红绿灯：绿灯，比赛；红灯，别动。', '信号をおぼえよう：青はプレー、赤はストップ。')], {'1': act(('Con bola viva, los jugadores pueden:', 'With a live ball, players can:', '活球时，球员可以：', 'ボールインプレーのとき、選手ができるのは：'), ('¡Eso es! Luz verde.', "That's it! Green light.", '对了！绿灯。', 'そのとおり！青信号。'), ('Bola viva: el juego sigue.', 'Live ball: the game goes on.', '活球：比赛继续。', 'ボールインプレー：試合はつづく。'), opts={'a': ('Correr, tirar y hacer outs', 'Run, throw and make outs', '跑、传球、制造出局', '走る、投げる、アウトにする'), 'b': ('Nada, todo está detenido', 'Nothing, everything is stopped', '什么都不能做，一切都停了', '何もできない、すべて止まっている'), 'c': ('Solo mirar', 'Only watch', '只能看', '見るだけ')}), '2': act(('Un batazo de foul convierte la bola en:', 'A foul ball turns the ball into:', '界外球让球变成：', 'ファウルになると、ボールは：'), ('¡Correcto! El foul detiene todo.', 'Correct! The foul stops everything.', '正确！界外球让一切停下来。', '正解！ファウルですべて止まる。'), ('Foul: luz roja.', 'Foul: red light.', '界外球：红灯。', 'ファウル：赤信号。'), opts={'a': ('Bola muerta', 'Dead ball', '死球（比赛停止）', 'ボールデッド'), 'b': ('Bola viva', 'Live ball', '活球', 'ボールインプレー'), 'c': ('Una base robada', 'A stolen base', '盗垒', '盗塁')}), '3': act(('Con bola muerta, un corredor puede avanzar a la siguiente base', 'With a dead ball, a runner can move up to the next base', '死球（比赛停止）时，跑垒员可以跑向下一个垒', 'ボールデッドのとき、ランナーは次の塁へ進める'), ('¡Bien! Nadie se mueve con luz roja.', 'Good! Nobody moves on a red light.', '很好！红灯时谁都不动。', 'いいね！赤信号ではだれも動かない。'), ('Falso: bola muerta, todos quietos.', 'False: dead ball, everyone freezes.', '错：死球（比赛停止），大家都不动。', 'まちがい：ボールデッドでは、みんなストップ。')), '4': act(('Pides tiempo y el umpire te lo concede levantando las manos. La bola queda:', 'You ask for time and the umpire grants it by raising his hands. The ball is:', '你要求暂停，裁判举起双手同意了。这时球是：', 'タイムをたのんで、審判が手を上げてみとめた。ボールは：'), ('¡Correcto! Tiempo concedido: bola muerta.', 'Correct! Time granted: dead ball.', '正确！暂停获准：死球（比赛停止）。', '正解！タイムがみとめられた：ボールデッド。'), ('Con el tiempo del umpire, todo se detiene.', "With the umpire's time, everything stops.", '裁判同意暂停，一切都停下来。', '審判のタイムで、すべて止まる。'), opts={'a': ('Muerta', 'Dead', '死球（比赛停止）', 'デッド'), 'b': ('Viva', 'Live', '活球', 'インプレー'), 'c': ('En foul solamente', 'Only foul', '只是界外球', 'ファウルだけ')}), '5': act(('El lanzamiento golpea al bateador. En ese instante la bola:', 'The pitch hits the batter. At that instant the ball:', '投球打到了击球员。那一刻，球：', '投球がバッターに当たった。そのしゅんかん、ボールは：'), ('¡Eso es! Golpeado: bola muerta.', "That's it! Hit by the pitch: dead ball.", '对了！触身球：死球（比赛停止）。', 'そのとおり！死球（デッドボール）：ボールデッド。'), ('El golpe apaga la jugada al instante.', 'When the pitch hits the batter, the play stops right away.', '一打到身上，这一球马上就停了。', '当たったしゅんかん、プレーは止まる。'), opts={'a': ('Muere: nadie puede avanzar por esa jugada', 'Goes dead: nobody can move up on that play', '“死”了，比赛停止：这一球谁都不能进垒', 'デッドになる：そのプレーではだれも進めない'), 'b': ('Sigue viva y todos corren', 'Stays live and everyone runs', '还是活球，大家都跑', 'インプレーのままで、みんな走る'), 'c': ('Se convierte en jonrón', 'Becomes a home run', '变成本垒打', 'ホームランになる')}), '6': act(('El corredor quedó a mitad de camino cuando se cantó foul. Toca dónde debe regresar con bola muerta', 'The runner was halfway when foul was called. Tap where he has to go back with the dead ball', '喊界外球的时候，跑垒员跑到一半。点一下死球（比赛停止）时他要回去的地方', 'ファウルがコールされたとき、ランナーはとちゅうにいた。ボールデッドでもどる場所をタッチしよう'), ('¡Bien! Con bola muerta se regresa.', 'Good! On a dead ball you go back.', '很好！死球（比赛停止）时要回去。', 'いいね！ボールデッドではもどる。'), ('Luz roja: cada quien a su base.', 'Red light: everyone to their base.', '红灯：大家都回自己的垒。', '赤信号：みんな自分の塁へ。'), answer=('Su base de origen', 'His starting base', '他原来的垒', 'もとの塁'))})
map_titles['10.3'] = ('Bola viva y bola muerta', 'Live ball and dead ball', '活球与死球（比赛停止）', 'ボールインプレーとボールデッド')
lesson('10.4', ('Interferencia y obstrucción', 'Interference and obstruction', '妨碍防守与妨碍跑垒', '守備妨害と走塁妨害'), ('Distinguir en lenguaje simple: interferencia es cuando el equipo que ataca estorba a un defensor que está jugando la bola; obstrucción es cuando un defensor sin la bola bloquea el camino de un corredor.', "Tell apart in simple words: interference is when the batting team gets in the way of a fielder who is playing the ball; obstruction is when a fielder without the ball blocks a runner's path.", '用简单的话分清：妨碍防守（interference）是进攻方挡住了正在处理球的防守球员；妨碍跑垒（obstruction）是没有拿球的防守球员挡住了跑垒员的路。', 'かんたんな言葉で見分けよう：守備妨害（interference）は、攻めているチームが、ボールをとろうとしている守備のじゃまをすること。走塁妨害（obstruction）は、ボールを持っていない守備が、ランナーの道をふさぐこと。'), [('Dos palabras largas para una idea corta: no estorbes y no bloquees.', "Two long words for a short idea: don't get in the way and don't block.", '两个长长的词，意思却很简单：不要妨碍，不要挡路。', '長い言葉が2つ、でも考えはかんたん：じゃましない、ふさがない。'), ('Si tu equipo está bateando y alguien estorba a un defensor que va a jugar la bola, eso es interferencia, en inglés interference: el que estorbó paga, casi siempre con un out.', "If your team is batting and someone gets in the way of a fielder about to play the ball, that's interference: whoever got in the way pays, almost always with an out.", '如果你们队在进攻，有人挡住了正要处理球的防守球员，这就是妨碍防守，英语叫 interference：妨碍的人要付出代价，几乎都是出局。', '君のチームが打っているときに、だれかがボールをとろうとしている守備のじゃまをしたら、守備妨害、英語で interference：じゃました人が、たいていアウトでつぐなう。'), ('Si un defensor sin la bola se para en el camino y bloquea a un corredor, eso es obstrucción, obstruction: paga la defensa, y el corredor avanza protegido.', "If a fielder without the ball stands in the way and blocks a runner, that's obstruction: the defense pays, and the runner moves up protected.", '如果一个没拿球的防守球员站在路上挡住跑垒员，这就是妨碍跑垒，obstruction：防守方要付出代价，跑垒员受到保护前进。', 'ボールを持っていない守備が道に立って、ランナーをふさいだら、走塁妨害、obstruction：守備がつぐなって、ランナーは守られて進む。'), ('¿Estorbó el que ataca? Interferencia.', 'Did the batting team get in the way? Interference.', '是进攻的人妨碍了吗？妨碍防守。', '攻めている人がじゃました？守備妨害。'), ('¿Bloqueó el que defiende sin bola? Obstrucción.', 'Did a fielder without the ball block? Obstruction.', '是没拿球的防守的人挡路了吗？妨碍跑垒。', 'ボールなしの守備がふさいだ？走塁妨害。')], {'1': act(('Un corredor choca con el campocorto justo cuando este va a atrapar un rolling. Es:', 'A runner crashes into the shortstop just as he is about to catch a ground ball. It is:', '游击手正要接滚地球时，跑垒员撞上了他。这是：', '遊撃手がゴロをとろうとしたとき、ランナーがぶつかった。これは：'), ('¡Correcto! Estorbó a quien jugaba la bola.', 'Correct! He got in the way of the one playing the ball.', '正确！他妨碍了正在处理球的人。', '正解！ボールをとる人のじゃまをした。'), ('El ataque estorbó: interferencia.', 'The offense got in the way: interference.', '进攻方妨碍了：妨碍防守。', '攻めている側がじゃました：守備妨害。'), opts={'a': ('Interferencia del corredor', "The runner's interference", '跑垒员妨碍防守', 'ランナーの守備妨害'), 'b': ('Obstrucción', 'Obstruction', '妨碍跑垒', '走塁妨害'), 'c': ('Nada, así es el juego', "Nothing, that's the game", '没什么，比赛就是这样', '何もない、それが野球')}), '2': act(('El primera base, sin bola, se para en la línea y bloquea al corredor que da la vuelta. Es:', 'The first baseman, without the ball, stands on the line and blocks the runner rounding the base. It is:', '一垒手没拿球，站在跑垒线上，挡住了正在绕垒的跑垒员。这是：', '一塁手がボールを持たずにラインに立って、まわってくるランナーをふさいだ。これは：'), ('¡Eso es! Defensor sin bola bloqueando.', "That's it! A fielder without the ball blocking.", '对了！没拿球的防守球员挡路。', 'そのとおり！ボールなしの守備がふさいだ。'), ('Bloqueo sin bola: obstrucción.', 'Blocking without the ball: obstruction.', '没拿球挡路：妨碍跑垒。', 'ボールなしでふさぐ：走塁妨害。'), opts={'a': ('Obstrucción', 'Obstruction', '妨碍跑垒', '走塁妨害'), 'b': ('Interferencia', 'Interference', '妨碍防守', '守備妨害'), 'c': ('Un pickoff', 'A pickoff', '牵制传球', '牽制球')}), '3': act(('Si el defensor tiene la bola, sí puede estar en el camino para tocar al corredor', 'If the fielder has the ball, he can be in the path to tag the runner', '如果防守球员拿着球，他可以站在路上去触杀跑垒员', '守備がボールを持っていたら、道にいてランナーにタッチしていい'), ('¡Bien! Con bola, el defensor juega.', 'Good! With the ball, the fielder is playing.', '很好！拿着球，防守球员就是在处理球。', 'いいね！ボールを持っていれば、守備はプレーしている。'), ('Verdadero: con la bola puede buscar el toque.', 'True: with the ball he can go for the tag.', '这是对的：拿着球他可以去触杀。', '正しいよ：ボールを持っていればタッチしにいける。')), '4': act(('Hubo interferencia del bateador con el catcher al intentar tirar. El umpire declara:', 'The batter interfered with the catcher as he tried to throw. The umpire declares:', '捕手要传球时，击球员妨碍了他。裁判宣布：', 'キャッチャーが投げようとしたとき、バッターがじゃました。審判のせんげんは：'), ('¡Correcto! El que estorba paga.', 'Correct! Whoever gets in the way pays.', '正确！妨碍的人要付出代价。', '正解！じゃました人がつぐなう。'), ('Interferencia del ataque: out.', 'Interference by the offense: out.', '进攻方妨碍防守：出局。', '攻撃側の守備妨害：アウト。'), opts={'a': ('Out por interferencia', 'Out for interference', '妨碍防守，出局', '守備妨害でアウト'), 'b': ('Carrera para el ataque', 'A run for the offense', '进攻方得一分', '攻撃側に1点'), 'c': ('Balk', 'Balk', '投手犯规', 'ボーク')}), '5': act(('La forma rápida de distinguirlas es preguntar:', 'The quick way to tell them apart is to ask:', '分清它们最快的办法是问：', 'すばやく見分けるには、こう考えよう：'), ('¡Eso es! Esa pregunta decide.', "That's it! That question decides.", '对了！这个问题决定一切。', 'そのとおり！その質問で決まる。'), ('Ataque estorba: interferencia. Defensa bloquea: obstrucción.', 'Offense gets in the way: interference. Defense blocks: obstruction.', '进攻方妨碍：妨碍防守。防守方挡路：妨碍跑垒。', '攻めている側のじゃま：守備妨害。守備がふさぐ：走塁妨害。'), opts={'a': ('¿Quién estorbó: el que ataca o el que defiende sin bola?', 'Who got in the way: the offense or a fielder without the ball?', '是谁妨碍了：进攻的人，还是没拿球的防守的人？', 'じゃましたのはだれ：攻めている人？ボールなしの守備？'), 'b': ('¿Qué entrada es?', 'What inning is it?', '现在是第几局？', '何回？'), 'c': ('¿Quién gritó?', 'Who yelled?', '谁喊了？', 'だれがさけんだ？')}), '6': act(('Toca al jugador que comete obstrucción: el defensor parado sin bola en el camino entre primera y segunda', 'Tap the player committing obstruction: the fielder standing without the ball in the path between first and second', '点一下犯了妨碍跑垒的球员：站在一垒和二垒之间路上、没拿球的防守球员', '走塁妨害をした選手をタッチしよう：一塁と二塁のあいだの道に、ボールなしで立っている守備'), ('¡Bien! Ese bloquea sin jugar la bola.', 'Good! He blocks without playing the ball.', '很好！他没处理球却挡了路。', 'いいね！ボールをとらずにふさいでいる。'), ('Sin bola y en el camino: obstrucción.', 'Without the ball and in the path: obstruction.', '没拿球又在路上：妨碍跑垒。', 'ボールなしで道にいる：走塁妨害。'), answer=('El defensor sin bola en el camino', 'The fielder without the ball in the path', '路上没拿球的防守球员', '道にいるボールなしの守備'))})
map_titles['10.4'] = ('Interferencia y obstrucción', 'Interference and obstruction', '妨碍防守与妨碍跑垒', '守備妨害と走塁妨害')
lesson('10.5', ('No pisar una base: la apelación', 'Missing a base: the appeal', '漏踩垒包：申诉', 'ベースのふみわすれ：アピール'), ('Entender que si un corredor no pisa una base (o sale antes en el pisa y corre), la defensa puede apelar: con la bola viva, tocar la base o al corredor y mostrarle la falta al umpire; si la apelación prospera, hay out.', "Understand that if a runner misses a base (or leaves early on a tag up), the defense can appeal: with the ball live, touch the base or the runner and show the mistake to the umpire; if the appeal succeeds, it's an out.", '明白如果跑垒员漏踩了一个垒（或者触垒后起跑时离开得太早），防守方可以申诉：在活球时，触碰那个垒或跑垒员，向裁判指出这个错误；申诉成功，就是出局。', 'ランナーがベースをふみわすれたら（またはタッチアップで早く出たら）、守備はアピールできることを知ろう：ボールインプレーのうちに、そのベースかランナーにさわって、審判にミスを見せる。アピールがみとめられたらアウト。'), [('Recuerda el Nivel 1: hay que pisar todas las bases.', 'Remember Level 1: you have to touch every base.', '还记得第 1 级吗：每个垒都要踩到。', 'レベル1をおぼえてる？ベースはぜんぶふまなきゃいけない。'), ('Si un corredor se salta una — o salió antes de la atrapada en un pisa y corre — el umpire no lo canta solo.', "If a runner skips one — or left before the catch on a tag up — the umpire doesn't call it on his own.", '如果跑垒员漏踩了一个垒——或者触垒后起跑时在接球前就跑了——裁判不会自己判。', 'ランナーがひとつとばしたら——またはタッチアップでキャッチの前に出たら——審判は自分からはコールしない。'), ('La defensa debe apelar, en inglés appeal: con la bola viva, un defensor toca la base que faltó, o al corredor, y le muestra claramente al umpire lo que pasó.', 'The defense has to appeal: with the ball live, a fielder touches the missed base, or the runner, and clearly shows the umpire what happened.', '防守方要申诉，英语叫 appeal：在活球时，一名防守球员触碰漏掉的垒或那名跑垒员，清楚地告诉裁判发生了什么。', '守備がアピールしなきゃいけない、英語で appeal：ボールインプレーのうちに、守備がふまれなかったベースか、ランナーにさわって、何が起きたかを審判にはっきり見せる。'), ('Si el umpire lo vio y está de acuerdo: out por apelación.', 'If the umpire saw it and agrees: out on appeal.', '如果裁判看到了，也同意：申诉出局。', '審判が見ていて、そのとおりだと思ったら：アピールアウト。'), ('Sin apelación, no hay castigo.', 'No appeal, no penalty.', '没有申诉，就没有处罚。', 'アピールがなければ、ばつもない。'), ('La defensa también tiene que estar despierta.', 'The defense has to be wide awake too.', '防守方也要时刻保持清醒。', '守備も、ちゃんと目をさましていなきゃね。')], {'1': act(('¿Qué es una apelación (appeal)?', 'What is an appeal?', '什么是申诉（appeal）？', 'アピール（appeal）って何？'), ('¡Eso es! Appeal.', "That's it! Appeal.", '对了！申诉。', 'そのとおり！アピール。'), ('Apelar es mostrar la falta con la bola en juego.', 'Appealing is showing the mistake with the ball in play.', '申诉就是在球还在比赛中时指出错误。', 'アピールは、ボールがプレー中のうちにミスを見せること。'), opts={'a': ('La defensa le muestra al umpire una base no pisada, tocando la base o al corredor con la bola viva', 'The defense shows the umpire a missed base, touching the base or the runner with the ball live', '防守方在活球时触碰垒或跑垒员，向裁判指出漏踩的垒', '守備がボールインプレーのうちにベースかランナーにさわって、ふみわすれを審判に見せること'), 'b': ('Un grito del público', 'A shout from the crowd', '观众的喊声', 'お客さんのさけび声'), 'c': ('Una señal del coach', "A coach's sign", '教练的暗号', 'コーチのサイン')}), '2': act(('Si un corredor no pisa una base y nadie apela, el juego sigue sin castigo', 'If a runner misses a base and nobody appeals, the game goes on without a penalty', '如果跑垒员漏踩垒而没人申诉，比赛继续，没有处罚', 'ランナーがベースをふみわすれても、だれもアピールしなければ、ばつなしで試合はつづく'), ('¡Bien! Sin apelación no hay out.', 'Good! No appeal, no out.', '很好！没有申诉就没有出局。', 'いいね！アピールなしならアウトなし。'), ('Verdadero: la defensa debe pedirlo.', 'True: the defense has to ask for it.', '这是对的：防守方必须提出。', '正しいよ：守備がもとめなきゃいけない。')), '3': act(('El corredor se saltó segunda sin pisarla. La defensa apela tocando:', 'The runner skipped second without touching it. The defense appeals by touching:', '跑垒员没踩二垒就跑过去了。防守方申诉要触碰：', 'ランナーが二塁をふまずに通りすぎた。守備がアピールでさわるのは：'), ('¡Correcto! La base que faltó.', 'Correct! The base that was missed.', '正确！漏掉的那个垒。', '正解！ふまれなかったベース。'), ('Se apela en la base del olvido.', 'You appeal at the forgotten base.', '在被忘掉的那个垒申诉。', 'わすれられたベースでアピールする。'), opts={'a': ('Segunda base con la bola', 'Second base with the ball', '拿着球触碰二垒', 'ボールを持って二塁'), 'b': ('Home', 'Home', '本垒', 'ホーム'), 'c': ('El montículo', 'The mound', '投手丘', 'マウンド')}), '4': act(('La defensa apeló bien y el umpire vio que el corredor nunca pisó segunda. Canta:', 'The defense appealed correctly and the umpire saw the runner never touched second. He calls:', '防守方申诉正确，裁判也看到跑垒员根本没踩二垒。他判：', '守備がきちんとアピールして、審判もランナーが二塁をふんでいないのを見ていた。コールは：'), ('¡Out! Apelación ganada.', 'Out! Appeal won.', '出局！申诉成功。', 'アウト！アピール成功。'), ('Base no pisada más apelación: out.', 'Missed base plus appeal: out.', '漏踩垒加上申诉：出局。', 'ふみわすれとアピール：アウト。'), opts={'a': ('¡Out!', 'Out!', '出局！', 'アウト！'), 'b': ('¡Safe!', 'Safe!', '安全上垒！', 'セーフ！'), 'c': ('¡Foul!', 'Foul!', '界外球！', 'ファウル！')}), '5': act(('Un corredor anotó pero salió antes de la atrapada en el pisa y corre. La defensa puede:', 'A runner scored but left before the catch on a tag up. The defense can:', '一名跑垒员得分了，但触垒后起跑时在接球前就跑了。防守方可以：', 'ランナーが得点したけど、タッチアップでキャッチの前に出ていた。守備ができるのは：'), ('¡Eso es! La salida temprana también se apela.', "That's it! Leaving early can be appealed too.", '对了！提前离垒也可以申诉。', 'そのとおり！早く出たのもアピールできる。'), ('Pisa y corre mal hecho: apelación.', 'A tag up done wrong: appeal.', '触垒后起跑做错了：申诉。', 'タッチアップのミス：アピール。'), opts={'a': ('Apelar tocando su base de salida con la bola', 'Appeal by touching his starting base with the ball', '拿着球触碰他出发的垒来申诉', 'ボールを持って、スタートしたベースにさわってアピール'), 'b': ('Nada, ya anotó', 'Nothing, he already scored', '什么都不能做，他已经得分了', '何もできない、もう得点した'), 'c': ('Batear por él', 'Bat for him', '替他击球', 'かわりに打つ')}), '6': act(('El corredor se saltó tercera camino a home. Toca la base donde la defensa debe apelar', 'The runner skipped third on the way home. Tap the base where the defense has to appeal', '跑垒员跑回本垒时漏踩了三垒。点一下防守方要申诉的垒', 'ランナーがホームへ向かうとき三塁をとばした。守備がアピールするベースをタッチしよう'), ('¡Bien! Ahí se muestra la falta.', "Good! That's where the mistake is shown.", '很好！就在那里指出错误。', 'いいね！そこでミスを見せる。'), ('La apelación vive en la base olvidada.', 'The appeal lives at the forgotten base.', '申诉就在被忘掉的那个垒。', 'アピールは、わすれられたベースで。'), answer=('Tercera base', 'Third base', '三垒', '三塁'))})
map_titles['10.5'] = ('No pisar una base: la apelación', 'Missing a base: the appeal', '漏踩垒包：申诉', 'ベースのふみわすれ：アピール')
exams_v3['10'] = {'1': {'q': ('El tercer strike caído ocurre cuando:', 'The dropped third strike happens when:', '什么时候会出现不死三振：', '振り逃げが起きるのは：'), 'opts': {'a': ('El catcher no atrapa limpio el tercer strike', "The catcher doesn't catch the third strike cleanly", '捕手没有干净地接住第三个好球', 'キャッチャーが3つ目のストライクをきちんととれないとき'), 'b': ('El bateador deja caer el bate', 'The batter drops the bat', '击球员把球棒掉了', 'バッターがバットを落としたとき'), 'c': ('El pitcher deja caer la bola', 'The pitcher drops the ball', '投手把球掉了', 'ピッチャーがボールを落としたとき')}}, '2': {'q': ('Con primera libre, el bateador con tercer strike caído puede:', 'With first base open, the batter with a dropped third strike can:', '一垒没人时，不死三振的击球员可以：', '一塁があいているとき、振り逃げのバッターは：'), 'opts': {'a': ('Correr a primera', 'Run to first', '跑向一垒', '一塁へ走れる'), 'b': ('Anotar directo', 'Score directly', '直接得分', 'そのまま得点'), 'c': ('Lanzar', 'Pitch', '投球', '投げる')}}, '3': {'q': ('Con primera ocupada y dos outs, ¿aplica?', 'With first occupied and two outs, does it apply?', '一垒有人、两出局，适用吗？', '一塁にランナーがいて2アウト。使える？'), 'opts': {'a': ('Sí', 'Yes', '适用', 'はい'), 'b': ('No', 'No', '不适用', 'いいえ'), 'c': ('Nunca', 'Never', '永远不', 'ぜったいだめ')}}, '4': {'q': ('Toca la base a la que corre el bateador con el tercer strike caído', 'Tap the base the batter runs to on a dropped third strike', '点一下不死三振时击球员要跑去的垒', '振り逃げでバッターが走る塁をタッチしよう'), 'answer': ('Primera base', 'First base', '一垒', '一塁')}, '5': {'q': ('Corredores en primera y segunda, un out, y un elevado fácil al cuadro. ¿Qué canta el umpire?', 'Runners on first and second, one out, and an easy pop-up in the infield. What does the umpire call?', '一垒和二垒有人，一出局，内野出现容易接的高飞球。裁判怎么判？', '一塁と二塁にランナー、1アウトで、内野にかんたんなフライ。審判のコールは？'), 'opts': {'a': ('Infield fly: el bateador es out', 'Infield fly: the batter is out', '内野高飞球：击球员出局', 'インフィールドフライ：バッターはアウト'), 'b': ('Foul', 'Foul', '界外球', 'ファウル'), 'c': ('Bola', 'Ball', '坏球', 'ボール')}}, '6': {'q': ('¿Para qué existe el infield fly?', 'Why does the infield fly rule exist?', '为什么有内野高飞球规则？', 'インフィールドフライのルールは何のためにある？'), 'opts': {'a': ('Para que la defensa no deje caer la bola a propósito y haga un doble play', "So the defense can't drop the ball on purpose to get a double play", '防止防守方故意让球落地来完成双杀', '守備がわざとボールを落としてダブルプレーをとらないように'), 'b': ('Para que el juego dure más', 'To make the game longer', '让比赛更久', '試合を長くするため'), 'c': ('Para ayudar al pitcher a descansar', 'To let the pitcher rest', '让投手休息', 'ピッチャーを休ませるため')}}, '7': {'q': ('Durante una bola muerta, los corredores:', 'While the ball is dead, the runners:', '死球（比赛停止）期间，跑垒员：', 'ボールデッドのあいだ、ランナーは：'), 'opts': {'a': ('No pueden avanzar', "Can't move up", '不能进垒', '進めない'), 'b': ('Corren libres', 'Run freely', '可以随便跑', '自由に走れる'), 'c': ('Anotan', 'Score', '得分', '得点する')}}, '8': {'q': ('Verdadero o falso: un foul es un ejemplo de bola muerta', 'True or false: a foul ball is an example of a dead ball', '对还是错：界外球就是死球（比赛停止）的一个例子', '○か×か：ファウルはボールデッドの例')}, '9': {'q': ('Un defensor sin la bola se para en el camino del corredor y lo bloquea. ¿Qué es?', "A fielder without the ball stands in the runner's way and blocks him. What is it?", '没有拿球的防守球员站在跑垒员的路上挡住他。这是什么？', 'ボールを持っていない守備の選手が、ランナーの走る道をふさいだ。これは？'), 'opts': {'a': ('Obstrucción', 'Obstruction', '妨碍跑垒', 'オブストラクション（走塁妨害）'), 'b': ('Interferencia', 'Interference', '干扰', 'インターフェア（守備妨害）'), 'c': ('Un error', 'An error', '失误', 'エラー')}}, '10': {'q': ('Un corredor estorba a propósito al defensor que va a atrapar la bola. ¿Qué es?', 'A runner gets in the way of the fielder who is about to catch the ball, on purpose. What is it?', '跑垒员故意挡住正要接球的防守球员。这是什么？', 'ランナーが、ボールをとろうとしている守備の選手をわざとじゃました。これは？'), 'opts': {'a': ('Interferencia', 'Interference', '干扰', 'インターフェア（守備妨害）'), 'b': ('Obstrucción', 'Obstruction', '妨碍跑垒', 'オブストラクション（走塁妨害）'), 'c': ('Un robo', 'A steal', '盗垒', '盗塁')}}, '11': {'q': ('El corredor no pisó segunda. ¿Qué puede hacer la defensa?', "The runner didn't touch second. What can the defense do?", '跑垒员没有踩二垒。防守方可以怎么做？', 'ランナーが二塁をふまなかった。守備はどうできる？'), 'opts': {'a': ('Apelar: tocar la base o al corredor con la bola y avisar al umpire', 'Appeal: touch the base or the runner with the ball and tell the umpire', '申诉：用球碰垒包或跑垒员，再告诉裁判', 'アピール：ボールで塁かランナーにさわって、審判に知らせる'), 'b': ('Nada', 'Nothing', '什么都不能做', '何もできない'), 'c': ('Pedir otro bateador', 'Ask for another batter', '要求换一个击球员', 'べつのバッターをたのむ')}}, '12': {'q': ('Verdadero o falso: si la apelación prospera, el corredor es out', 'True or false: if the appeal is upheld, the runner is out', '对还是错：如果申诉成立，跑垒员就出局', '○か×か：アピールがみとめられたら、ランナーはアウト')}}
