lesson('11.1', ('La goma del pitcher', "The pitcher's rubber", '投手板', '投手板（ラバー）'), ('Entender que el pitcher lanza apoyado en la goma (rubber) del montículo, que desde ahí empieza cada lanzamiento, y que la distancia del montículo a home cambia con la edad y la liga.', "Understand that the pitcher pitches with his foot on the mound's rubber, that every pitch starts there, and that the distance from the mound to home changes with age and league.", '明白投手要踩着投手丘上的投手板（rubber）投球，每一球都从那里开始；还要知道投手丘到本垒的距离会随年龄和联赛而不同。', 'ピッチャーはマウンドの投手板（rubber）に足をつけて投げること、1球1球そこからはじまること、マウンドからホームまでのきょりは年齢とリーグでかわることを知ろう。'), [('En la cima del montículo hay una tablita blanca: la goma, en inglés rubber.', "At the top of the mound there's a little white board: the rubber.", '投手丘的顶上有一块白色的小板子：投手板，英语叫 rubber。', 'マウンドのてっぺんに、白い板がある：投手板、英語で rubber。'), ('El pitcher lanza con un pie apoyado en ella: desde ahí empieza todo.', 'The pitcher pitches with one foot on it: everything starts there.', '投手一只脚踩在上面投球：一切都从这里开始。', 'ピッチャーは片足をそこにつけて投げる：ぜんぶそこからはじまる。'), ('Con ese pie en la goma, el pitcher mira al catcher, recibe la señal y lanza.', 'With that foot on the rubber, the pitcher looks at the catcher, gets the sign and pitches.', '脚踩着投手板，投手看着捕手，接收暗号，然后投球。', '投手板に足をつけたまま、キャッチャーを見て、サインを受けて、投げる。'), ('Ojo con esta verdad grande: la distancia de la goma a home no es la misma para todos.', "Pay attention to this big truth: the distance from the rubber to home isn't the same for everyone.", '注意这个重要的事实：投手板到本垒的距离，不是每个人都一样。', 'この大事なことに注意して：投手板からホームまでのきょりは、みんな同じじゃない。'), ('En ligas de niños es más corta y crece con la edad.', "In kids' leagues it's shorter and it grows with age.", '在少儿联赛里距离比较短，会随着年龄变长。', '子どものリーグでは短くて、年齢といっしょに長くなる。'), ('¿Cuál es la de tu liga? La mide tu campo, y tu coach la conoce.', 'What is it in your league? Your field measures it, and your coach knows it.', '你们联赛是多少？你们的球场量好了，你的教练知道。', '君のリーグではどれくらい？君のグラウンドがはかっていて、コーチが知っているよ。')], {'1': act(('¿Qué es la goma del pitcher?', "What is the pitcher's rubber?", '什么是投手板？', '投手板って何？'), ('¡Eso es! Rubber.', "That's it! Rubber.", '对了！投手板。', 'そのとおり！ラバー。'), ('Desde la goma empieza cada lanzamiento.', 'Every pitch starts from the rubber.', '每一球都从投手板开始。', '1球1球、投手板からはじまる。'), opts={'a': ('La tablita blanca del montículo donde el pitcher apoya el pie', 'The little white board on the mound where the pitcher puts his foot', '投手丘上投手踩脚的白色小板子', 'ピッチャーが足をつける、マウンドの白い板'), 'b': ('Un guante especial', 'A special glove', '一种特别的手套', 'とくべつなグラブ'), 'c': ('Una base más', 'One more base', '多出来的一个垒', 'もうひとつの塁')}), '2': act(('La distancia de la goma a home es la misma en todas las edades', 'The distance from the rubber to home is the same at every age', '投手板到本垒的距离，每个年龄都一样', '投手板からホームまでのきょりは、どの年齢でも同じ'), ('¡Bien! Cambia con la edad y la liga.', 'Good! It changes with age and league.', '很好！它随年龄和联赛而变。', 'いいね！年齢とリーグでかわる。'), ('Falso: en niños es más corta.', "False: for kids it's shorter.", '错：小朋友的距离比较短。', 'まちがい：子どもは短いよ。')), '3': act(('Al lanzar, el pitcher debe empezar:', 'When pitching, the pitcher has to start:', '投球时，投手必须从哪里开始：', '投げるとき、ピッチャーがはじめるのは：'), ('¡Correcto! Pie en la goma.', 'Correct! Foot on the rubber.', '正确！脚踩投手板。', '正解！足は投手板。'), ('La goma es su punto de partida.', 'The rubber is his starting point.', '投手板就是他的起点。', '投手板がスタートの場所。'), opts={'a': ('Con un pie apoyado en la goma', 'With one foot on the rubber', '一只脚踩在投手板上', '片足を投手板につけて'), 'b': ('Desde segunda base', 'From second base', '从二垒', '二塁から'), 'c': ('Desde donde quiera', 'From wherever he wants', '想从哪里就从哪里', 'すきなところから')}), '4': act(('Toca la goma: la tablita en la cima del montículo', 'Tap the rubber: the little board at the top of the mound', '点一下投手板：投手丘顶上的小板子', '投手板をタッチしよう：マウンドのてっぺんの板'), ('¡Bien! Ahí está la goma.', "Good! That's where the rubber is.", '很好！投手板就在那里。', 'いいね！そこに投手板がある。'), ('En el centro del diamante, arriba del montículo.', 'In the center of the diamond, on top of the mound.', '在钻石的中间，投手丘的顶上。', 'ダイヤモンドのまんなか、マウンドの上。'), answer=('El montículo, en su cima', 'The mound, at its top', '投手丘的顶上', 'マウンドのてっぺん')), '5': act(('El pitcher recibe la señal mirando al catcher, parado en la goma. Eso es el comienzo de:', 'The pitcher gets the sign looking at the catcher, standing on the rubber. That is the start of:', '投手站在投手板上，看着捕手接收暗号。这是什么的开始：', 'ピッチャーが投手板に立って、キャッチャーを見てサインを受ける。これは何のはじまり？'), ('¡Correcto! Todo lanzamiento nace ahí.', 'Correct! Every pitch is born there.', '正确！每一球都从那里诞生。', '正解！どの投球もそこからうまれる。'), ('Señal, goma y lanzamiento: la rutina completa.', 'Sign, rubber and pitch: the full routine.', '暗号、投手板、投球：完整的流程。', 'サイン、投手板、投球：いつもの流れ。'), opts={'a': ('Cada lanzamiento', 'Every pitch', '每一球', '1球1球の投球'), 'b': ('Un robo', 'A steal', '盗垒', '盗塁'), 'c': ('Un balk seguro', 'A sure balk', '一定是投手犯规', 'かならずボーク')}), '6': act(('Si quieres saber la distancia exacta de tu montículo, debes:', 'If you want to know the exact distance of your mound, you should:', '如果你想知道你们投手丘的确切距离，你应该：', '君のマウンドのきょりをちゃんと知りたいなら：'), ('¡Eso es! Depende de tu liga y tu edad.', "That's it! It depends on your league and your age.", '对了！它取决于你的联赛和年龄。', 'そのとおり！リーグと年齢しだい。'), ('Nada de copiar números de los grandes.', "Don't copy the grown-ups' numbers.", '不要照抄大人的数字。', '大人の数字をまねしないで。'), opts={'a': ('Preguntar a tu coach o ver la regla de tu liga', "Ask your coach or look at your league's rule", '问你的教练，或者看你们联赛的规定', 'コーチに聞くか、リーグのルールを見る'), 'b': ('Inventarla', 'Make it up', '自己编一个', '自分で決める'), 'c': ('Usar siempre la de los profesionales', "Always use the professionals' one", '一直用职业球员的距离', 'いつもプロのきょりを使う')})})
