exams_v3['11'] = {'1': {'q': ('La goma está en:', 'The rubber is at:', '投手板在：', '投手板があるのは：'), 'opts': {'a': ('La cima del montículo', 'The top of the mound', '投手丘的顶上', 'マウンドのてっぺん'), 'b': ('Segunda base', 'Second base', '二垒', '二塁'), 'c': ('El dugout', 'The dugout', '休息区', 'ダッグアウト')}}, '2': {'q': ('¿Cómo se dice goma del pitcher en inglés?', "What's the white board on the mound called?", '“投手板”的英语怎么说？', '投手板は英語で何という？'), 'opts': {'a': ('Rubber', 'Rubber', 'Rubber', 'Rubber'), 'b': ('Gum base', 'Gum base', 'Gum base', 'Gum base'), 'c': ('White base', 'White base', 'White base', 'White base')}}, '3': {'q': ('La distancia montículo-home en ligas infantiles es:', "The mound-to-home distance in kids' leagues is:", '少儿联赛里投手丘到本垒的距离：', '子どものリーグのマウンドからホームまでのきょりは：'), 'opts': {'a': ('Más corta y cambia con la edad', 'Shorter and it changes with age', '比较短，随年龄改变', '短くて、年齢でかわる'), 'b': ('Igual que la profesional', "The same as the professionals'", '和职业比赛一样', 'プロと同じ'), 'c': ('Siempre la misma', 'Always the same', '永远一样', 'いつも同じ')}}, '4': {'q': ('Toca dónde está la goma en el diamante', 'Tap where the rubber is on the diamond', '点一下钻石上投手板的位置', 'ダイヤモンドで投手板のある場所をタッチしよう'), 'answer': ('El montículo', 'The mound', '投手丘', 'マウンド')}, '5': {'q': ('¿Cuándo se usa sobre todo el windup (el movimiento completo)?', 'When is the windup (the full motion) used most?', '什么时候主要用全套动作（windup）？', 'ワインドアップ（大きな投げ方）をおもに使うのはいつ？'), 'opts': {'a': ('Sin corredores en base', 'With nobody on base', '垒上没人的时候', 'ランナーがいないとき'), 'b': ('Con bases llenas', 'With the bases loaded', '满垒的时候', '満塁のとき'), 'c': ('Solo al batear', 'Only when batting', '只有击球的时候', '打つときだけ')}}, '6': {'q': ('Con corredores en base, el pitcher usa el set o stretch para:', 'With runners on base, the pitcher uses the set (stretch) to:', '有跑垒员时，投手用固定式（set / stretch）是为了：', 'ランナーがいるとき、ピッチャーがセットポジションを使うのは：'), 'opts': {'a': ('Cuidar a los corredores con un movimiento corto', 'Keep an eye on the runners with a short motion', '用短的动作盯住跑垒员', '短い動きでランナーを見はるため'), 'b': ('Lanzar más lento', 'Throw slower', '投得慢一点', 'ゆっくり投げるため'), 'c': ('Descansar', 'Rest', '休息', '休むため')}}, '7': {'q': ('¿Cuáles son los primeros lanzamientos de un pitcher joven?', "What are a young pitcher's first pitches?", '年轻投手最先学的投球是什么？', '若いピッチャーが最初に覚える球は？'), 'opts': {'a': ('La recta y el cambio', 'The fastball and the changeup', '直球和变速球', 'ストレートとチェンジアップ'), 'b': ('Las curvas', 'Curveballs', '曲球', 'カーブ'), 'c': ('Solo bolas', 'Only balls', '只投坏球', 'ボールだけ')}}, '8': {'q': ('Verdadero o falso: las curvas son buenas para brazos jóvenes desde el primer día', 'True or false: curveballs are good for young arms from day one', '对还是错：曲球从第一天起就适合年轻的手臂', '○か×か：カーブは若いうでに最初の日からいい')}, '9': {'q': ('Te duele el codo mientras lanzas. ¿Qué haces?', 'Your elbow hurts while you pitch. What do you do?', '投球时你的手肘疼。你怎么做？', '投げているとき、ひじがいたい。どうする？'), 'opts': {'a': ('Paro y le aviso a un adulto', 'Stop and tell an adult', '停下来，告诉大人', 'やめて、大人に知らせる'), 'b': ('Sigo lanzando', 'Keep pitching', '继续投', '投げつづける'), 'c': ('Lanzo más fuerte', 'Throw harder', '投得更用力', 'もっと強く投げる')}}, '10': {'q': ('¿Quién decide cuántos lanzamientos y cuánto descanso te tocan?', 'Who decides how many pitches you can throw and how much rest you need?', '谁决定你能投多少球、需要休息多久？', '何球投げていいか、どれだけ休むかを決めるのはだれ？'), 'opts': {'a': ('Mi liga, según mi edad: le pregunto a mi coach', 'My league, by my age: I ask my coach', '我的联赛，按我的年龄：我问教练', 'リーグが年れいで決める：コーチに聞く'), 'b': ('El público', 'The crowd', '观众', '観客'), 'c': ('Yo solo', 'Just me', '我自己', '自分ひとり')}}, '11': {'q': ('El pitcher que entra a lanzar después del abridor es el:', 'The pitcher who comes in after the starter is the:', '在先发投手之后上场投球的是：', '先発のあとに投げるピッチャーは：'), 'opts': {'a': ('Relevista', 'Reliever', '中继投手', 'リリーフ'), 'b': ('Bateador', 'Batter', '击球员', 'バッター'), 'c': ('Umpire', 'Umpire', '裁判', '審判')}}, '12': {'q': ('¿Dónde calientan los relevistas?', 'Where do the relievers warm up?', '中继投手在哪里热身？', 'リリーフはどこで準備する？'), 'opts': {'a': ('En el bullpen', 'In the bullpen', '在牛棚', 'ブルペン'), 'b': ('En home', 'At home plate', '在本垒', 'ホームプレート'), 'c': ('En segunda', 'At second base', '在二垒', '二塁')}}}
