lesson('12.1', ('A dónde tirar la bola', 'Where to throw the ball', '球要传到哪里', 'ボールをどこに投げる？'), ('Pensar antes de cada lanzamiento a dónde irá la bola según los corredores y los outs, buscando primero frenar al corredor más adelantado y aceptando el out seguro cuando el tiro difícil no se puede.', "Think before every pitch about where the ball will go depending on the runners and the outs, looking first to stop the lead runner and taking the sure out when the hard throw can't be made.", '每一球投出之前，根据跑垒员和出局数先想好球要传到哪里：先想办法拦住前位跑者；难传的球传不了，就拿下稳妥的出局。', '1球ごとに、投げる前に、ランナーとアウト数を見て、ボールをどこへ投げるか考えよう。まずリードランナーを止めることを考え、むずかしい送球ができないときは確実なアウトをとる。'), [('Tienes la bola en el guante y todos corren.', "You've got the ball in your glove and everyone is running.", '球在你的手套里，大家都在跑。', 'ボールはグラブの中、みんな走っている。'), ('¿A dónde la tiras?', 'Where do you throw it?', '你要传到哪里？', 'どこに投げる？'), ('El All Star responde antes de que le bateen: antes de cada lanzamiento se pregunta, si me la batean, ¿qué hago?', "The All Star answers before the ball is hit: before every pitch he asks himself, if it's hit to me, what do I do?", '全明星在球被打出之前就有答案：每一球投出之前，他都会问自己：如果球打到我这里，我该怎么做？', 'オールスターは、打たれる前に答えを持っている：1球ごとに投げる前に考える。「ぼくのところに来たら、どうする？」'), ('Casi siempre conviene frenar al corredor más adelantado, el que está más cerca de anotar.', "It's almost always best to stop the lead runner, the one closest to scoring.", '几乎总是要先拦住前位跑者，也就是离得分最近的那个。', 'たいていは、リードランナーを止めるのがいい。いちばん得点に近いランナーだ。'), ('Pero un out seguro vale más que un tiro imposible: si el tiro largo no se puede, asegura el out en primera.', "But a sure out is worth more than an impossible throw: if the long throw can't be made, make sure of the out at first.", '但稳妥的出局比不可能的传球更有价值：如果远传做不到，就在一垒拿下出局。', 'でも、確実なアウトは、むりな送球よりねうちがある：遠くへの送球がむりなら、一塁で確実にアウトをとろう。'), ('Pensar antes: eso separa a un jugador cualquiera de un All Star.', "Thinking ahead: that's what separates a player from an All Star.", '提前思考：这就是普通球员和全明星的区别。', '先に考える：それが、ふつうの選手とオールスターのちがい。')], {'1': act(('¿Cuándo debes pensar a dónde vas a tirar la bola?', 'When should you think about where you will throw the ball?', '你应该什么时候想好球要传到哪里？', 'ボールをどこに投げるか、いつ考える？'), ('¡Eso es! La jugada se piensa antes.', "That's it! The play is thought out beforehand.", '对了！打法要提前想好。', 'そのとおり！プレーは先に考える。'), ('El All Star llega con el plan hecho.', 'The All Star arrives with the plan ready.', '全明星上场时就已经有计划了。', 'オールスターは計画を持ってのぞむ。'), opts={'a': ('Antes de cada lanzamiento', 'Before every pitch', '每一球投出之前', '1球ごとに、投げる前'), 'b': ('Cuando ya la tengas en el guante', 'When you already have it in your glove', '球已经在手套里的时候', 'もうグラブにボールが入ってから'), 'c': ('Nunca, se improvisa', 'Never, you make it up', '从来不想，临场发挥', '考えない、その場で決める')}), '2': act(('Sin corredores, atrapas un rolling. ¿A dónde tiras?', 'No runners, you field a ground ball. Where do you throw?', '垒上没人，你接到一个滚地球。传到哪里？', 'ランナーなしで、ゴロをとった。どこに投げる？'), ('¡Correcto! El out está en primera.', 'Correct! The out is at first.', '正确！出局就在一垒。', '正解！アウトは一塁で。'), ('Sin corredores, primera manda.', 'No runners: first rules.', '垒上没人：一垒说了算。', 'ランナーなし：一塁がいちばん。'), opts={'a': ('A primera', 'To first', '传一垒', '一塁'), 'b': ('A home', 'To home', '传本垒', 'ホーム'), 'c': ('A tercera', 'To third', '传三垒', '三塁')}), '3': act(('Un out seguro es mejor que intentar un tiro imposible y no hacer ninguno', 'A sure out is better than trying an impossible throw and getting none', '稳妥的出局，比尝试不可能的传球、结果一个出局都没有要好', 'むりな送球をしてアウトがとれないより、確実なアウトのほうがいい'), ('¡Sí! Asegura el out.', 'Yes! Make sure of the out.', '对！先确保出局。', 'そう！確実にアウトをとろう。'), ('Verdadero: un out real vale más que un sueño.', 'True: a real out is worth more than a dream.', '这是对的：真实的出局比梦想更有价值。', '正しいよ：本物のアウトは、ゆめよりねうちがある。')), '4': act(('Corredor en primera, rolling fácil al campocorto con tiempo. Toca la base donde frenas al corredor más adelantado', 'Runner on first, easy ground ball to the shortstop with time. Tap the base where you stop the lead runner', '一垒有人，一个打给游击手的容易滚地球，时间充足。点一下拦住前位跑者的垒', '一塁にランナー、遊撃手へかんたんなゴロで時間もある。リードランナーを止める塁をタッチしよう'), ('¡Bien! Ahí frenas al líder.', "Good! That's where you stop the leader.", '很好！就在那里拦住领头的人。', 'いいね！そこで先頭を止める。'), ('El más adelantado se frena en segunda.', 'The lead runner is stopped at second.', '前位跑者在二垒被拦住。', 'リードランナーは二塁で止める。'), answer=('Segunda base', 'Second base', '二垒', '二塁')), '5': act(('¿A qué corredor conviene frenar primero?', 'Which runner is it best to stop first?', '最好先拦住哪名跑垒员？', 'どのランナーを先に止めるのがいい？'), ('¡Correcto! Es el más cercano a anotar.', "Correct! He's the closest to scoring.", '正确！他离得分最近。', '正解！いちばん得点に近い。'), ('El líder de la fila es el peligro mayor.', 'The leader of the line is the biggest danger.', '排在最前面的人最危险。', '先頭のランナーがいちばんきけん。'), opts={'a': ('Al más adelantado', 'The lead runner', '前位跑者', 'リードランナー'), 'b': ('Al más lento', 'The slowest one', '最慢的那个', 'いちばんおそいランナー'), 'c': ('Al que está en el dugout', 'The one in the dugout', '休息区里的那个', 'ダッグアウトにいる人')}), '6': act(('Con dos outs y corredor en primera, rolling al segunda base. La jugada más fácil es:', 'Two outs and a runner on first, ground ball to the second baseman. The easiest play is:', '两出局、一垒有人，打给二垒手的滚地球。最简单的打法是：', '2アウト一塁、二塁手へゴロ。いちばんかんたんなプレーは：'), ('¡Eso es! Un out y se acabó.', "That's it! One out and it's over.", '对了！一个出局就结束了。', 'そのとおり！アウト1つで終わり。'), ('Con dos outs, el out más cerca gana.', 'With two outs, the closest out wins.', '两出局时，最近的出局就赢了。', '2アウトなら、いちばん近いアウトでいい。'), opts={'a': ('Tirar a primera o pisar segunda: un out acaba la entrada', 'Throw to first or step on second: one out ends the inning', '传一垒或踩二垒：一个出局就结束这一局', '一塁へ投げるか二塁をふむ：アウト1つでイニング終わり'), 'b': ('Tirar a home', 'Throw home', '传本垒', 'ホームへ投げる'), 'c': ('Guardar la bola', 'Keep the ball', '把球留在手里', 'ボールを持ったまま')})})
