lesson('12.2', ('El cortador', 'The cutoff man', '接力传球手', 'カットオフ（中継）'), ('Entender el cortador (cutoff): en tiros largos desde los jardines, un defensor del cuadro se coloca en el camino, recibe el tiro y lo pasa rápido a la base que haga falta.', 'Understand the cutoff: on long throws from the outfield, an infielder gets in the path, receives the throw and relays it quickly to whatever base is needed.', '明白接力传球手（cutoff）：外野远传时，一名内野手站到传球路线上，接住球后快速转传到需要的垒。', 'カットオフ（中継）を知ろう：外野からの遠い送球のとき、内野の選手が送球の道に入って、ボールを受けて、ひつような塁へすばやくつなぐ。'), [('Los jardines quedan lejos, y un tiro directo a home puede llegar débil o desviado.', 'The outfield is far away, and a direct throw home can arrive weak or off target.', '外野离得很远，直接传回本垒的球可能会没力气，或者传偏。', '外野は遠い。ホームへの直接の送球は、よわくなったり、それたりする。'), ('Por eso existe el cortador, en inglés cutoff: un defensor del cuadro se pone en el camino, levanta los brazos para que el jardinero lo vea, recibe el tiro y gira volando para tirar a donde haga falta.', "That's why there's the cutoff man: an infielder gets in the path, raises his arms so the outfielder sees him, receives the throw and spins fast to throw wherever it's needed.", '所以才有接力传球手，英语叫 cutoff：一名内野手站到路线上，举起双臂让外野手看见，接住球后飞快转身传到需要的地方。', 'だからカットオフ（中継）、英語で cutoff がある：内野の選手が道に入って、外野手から見えるようにうでを上げ、ボールを受けて、すばやくふり向いてひつようなところへ投げる。'), ('Dos tiros cortos y fuertes ganan contra uno largo y débil.', 'Two short, strong throws beat one long, weak one.', '两次又短又有力的传球，胜过一次又远又没力的传球。', '短くて強い送球2つは、長くてよわい送球1つにかつ。'), ('El cortador es el mensajero rápido de la defensa.', "The cutoff man is the defense's fast messenger.", '接力传球手就是防守方的快速信使。', 'カットオフは、守備のすばやいメッセンジャー。')], {'1': act(('¿Qué hace el cortador (cutoff)?', 'What does the cutoff man do?', '接力传球手（cutoff）做什么？', 'カットオフ（cutoff）は何をする？'), ('¡Correcto! Recibe y pasa.', 'Correct! Catch it and pass it on.', '正确！接住再传出去。', '正解！受けて、つなぐ。'), ('Cutoff: el puente de los tiros largos.', 'Cutoff: the bridge for long throws.', '接力传球手：远传的桥梁。', 'カットオフ：遠い送球のかけ橋。'), opts={'a': ('Recibe el tiro del jardinero y lo pasa a la base que haga falta', "Catches the outfielder's throw and passes it on to whatever base is needed", '接住外野手的传球，转传到需要的垒', '外野手の送球を受けて、ひつような塁へつなぐ'), 'b': ('Batea', 'Bats', '击球', '打つ'), 'c': ('Canta los strikes', 'Calls the strikes', '判好球', 'ストライクをコールする')}), '2': act(('¿Por qué se usa un cortador?', 'Why is a cutoff man used?', '为什么要用接力传球手？', 'なぜカットオフを使う？'), ('¡Eso es! Precisión y velocidad.', "That's it! Accuracy and speed.", '对了！又准又快。', 'そのとおり！せいかくで速い。'), ('Tiros cortos: menos error.', 'Short throws: fewer mistakes.', '短传：失误更少。', '短い送球：ミスが少ない。'), opts={'a': ('Porque dos tiros cortos llegan mejor que uno largo y débil', 'Because two short throws arrive better than one long, weak one', '因为两次短传比一次又远又没力的传球更好', '短い送球2つのほうが、長くてよわい送球1つよりよくとどくから'), 'b': ('Para descansar', 'To rest', '为了休息', '休むため'), 'c': ('Para confundir al umpire', 'To confuse the umpire', '为了让裁判搞不清楚', '審判をまよわせるため')}), '3': act(('Arrastra la bola en su camino: jardinero central, cortador, home', 'Drag the ball along its path: center fielder, cutoff man, home', '沿着路线拖动球：中外野手、接力传球手、本垒', 'ボールを道にそってドラッグしよう：中堅手、カットオフ、ホーム'), ('¡Relevo perfecto! Ese es el camino.', "Perfect relay! That's the path.", '完美的接力！就是这条路线。', 'かんぺきな中継！それが道だ。'), ('Del jardín al cortador, del cortador a home.', 'From the outfield to the cutoff, from the cutoff to home.', '从外野到接力传球手，再从接力传球手到本垒。', '外野からカットオフ、カットオフからホームへ。'), answer=('Jardín central, cortador, home', 'Center field, cutoff man, home', '中外野、接力传球手、本垒', 'センター、カットオフ、ホーム')), '4': act(('El cortador levanta los brazos para que el jardinero sepa a quién tirar', 'The cutoff man raises his arms so the outfielder knows who to throw to', '接力传球手举起双臂，让外野手知道该传给谁', 'カットオフは、外野手がだれに投げるかわかるように、うでを上げる'), ('¡Sí! Debe ser fácil de ver.', 'Yes! He has to be easy to see.', '对！他必须容易被看见。', 'そう！見つけやすくなきゃいけない。'), ('Verdadero: brazos arriba, blanco claro.', 'True: arms up, a clear target.', '这是对的：双臂举起，目标清楚。', '正しいよ：うでを上げて、はっきりした目じるし。')), '5': act(('¿Cómo se dice cortador en inglés?', "What's the name of the infielder who relays the outfielder's throw?", '“接力传球手”的英语怎么说？', 'カットオフは英語で何という？'), ('¡Bien! Cutoff.', 'Good! The cutoff man.', '很好！Cutoff。', 'いいね！Cutoff。'), ('Cortador: cutoff.', "That's the cutoff man.", '接力传球手：cutoff。', 'カットオフ：cutoff。'), opts={'a': ('Cutoff', 'Cutoff', 'Cutoff', 'Cutoff'), 'b': ('Bullpen', 'Bullpen', 'Bullpen', 'Bullpen'), 'c': ('Lead', 'Lead', 'Lead', 'Lead')}), '6': act(('El cortador suele ser:', 'The cutoff man is usually:', '接力传球手通常是：', 'カットオフはふつう：'), ('¡Correcto! Campocorto o segunda base, según el tiro.', 'Correct! Shortstop or second baseman, depending on the throw.', '正确！看传球方向，可能是游击手或二垒手。', '正解！送球によって、遊撃手か二塁手。'), ('El cuadro ayuda a los jardines con el tiro.', 'The infield helps the outfield with the throw.', '内野帮外野把球传到位。', '内野が外野の送球を手伝う。'), opts={'a': ('Un defensor del cuadro', 'An infielder', '一名内野手', '内野の選手'), 'b': ('El umpire', 'The umpire', '裁判', '審判'), 'c': ('El bateador', 'The batter', '击球员', 'バッター')})})
map_titles['12.2'] = ('El cortador', 'The cutoff man', '接力传球手', 'カットオフ（中継）')
lesson('12.3', ('Cubrir y respaldar', 'Covering and backing up', '补位占垒与补位防守', 'ベースカバーとバックアップ'), ('Aprender que en cada jugada todos se mueven: si un defensor sale por la bola, otro cubre su base, y detrás de cada base que recibe un tiro debe haber un respaldo (back up) por si la bola se escapa.', 'Learn that on every play everyone moves: if a fielder goes after the ball, another covers his base, and behind every base receiving a throw there should be a back up in case the ball gets away.', '知道每一球大家都要动起来：如果一名防守球员去追球，另一名就去补他的垒；每个接传球的垒后面，都要有人补位防守（back up），以防球漏掉。', '1つ1つのプレーで、みんなが動くことを知ろう：だれかがボールをとりに出たら、べつの人がその塁をカバーする。送球を受ける塁のうしろには、ボールがそれたときのためにバックアップ（back up）がいる。'), [('En defensa nadie se queda quieto mirando.', 'On defense nobody stands still watching.', '防守时，没有人站着不动光看。', '守備では、だれも立って見ているだけじゃない。'), ('Si el primera base sale lejos a buscar un rolling, el pitcher corre a cubrir primera.', 'If the first baseman goes far to get a ground ball, the pitcher runs to cover first.', '如果一垒手跑远去接滚地球，投手就跑去补一垒。', '一塁手が遠くまでゴロをとりに出たら、ピッチャーが一塁のカバーに走る。'), ('Y cuando se tira a una base, otro defensor corre a ponerse detrás de esa base para respaldar, en inglés back up: si la bola se escapa, él la frena y salva una base.', 'And when there is a throw to a base, another fielder runs to get behind that base to back up: if the ball gets away, he stops it and saves a base.', '当球传向一个垒时，另一名防守球员会跑到那个垒后面补位防守，英语叫 back up：如果球漏了，他把球拦住，救回一个垒。', 'そして、塁に送球するときは、べつの守備がその塁のうしろに走ってバックアップ、英語で back up：ボールがそれたら止めて、塁をひとつ守る。'), ('Cubrir es ocupar la base que quedó vacía; respaldar es ser la red detrás del tiro.', 'Covering is filling the base that was left empty; backing up is being the net behind the throw.', '补位占垒，就是占住空出来的垒；补位防守，就是当传球后面的那张网。', 'ベースカバーは、あいた塁に入ること。バックアップは、送球のうしろのネットになること。'), ('En cada jugada, cada jugador tiene un trabajo.', 'On every play, every player has a job.', '每一球，每个球员都有自己的工作。', 'どのプレーでも、どの選手にもしごとがある。')], {'1': act(('El primera base salió lejos por un rolling. ¿Quién cubre primera?', 'The first baseman went far for a ground ball. Who covers first?', '一垒手跑远去接滚地球。谁补一垒？', '一塁手がゴロをとりに遠くへ出た。一塁をカバーするのはだれ？'), ('¡Eso es! El pitcher cubre.', "That's it! The pitcher covers.", '对了！投手补位。', 'そのとおり！ピッチャーがカバー。'), ('Primera vacía: el pitcher la ocupa.', 'First is empty: the pitcher fills it.', '一垒空了：投手去占住。', '一塁があいた：ピッチャーが入る。'), opts={'a': ('El pitcher', 'The pitcher', '投手', 'ピッチャー'), 'b': ('El catcher', 'The catcher', '捕手', 'キャッチャー'), 'c': ('El jardinero izquierdo', 'The left fielder', '左外野手', '左翼手')}), '2': act(('¿Qué es respaldar (back up)?', 'What is backing up?', '什么是补位防守（back up）？', 'バックアップ（back up）って何？'), ('¡Correcto! La red detrás del tiro.', 'Correct! The net behind the throw.', '正确！传球后面的那张网。', '正解！送球のうしろのネット。'), ('Respaldar salva bases.', 'Backing up saves bases.', '补位防守能救回垒。', 'バックアップは塁を守る。'), opts={'a': ('Ponerse detrás de la base que recibe un tiro, por si la bola se escapa', 'Getting behind the base receiving a throw, in case the ball gets away', '站到接传球的垒后面，以防球漏掉', '送球を受ける塁のうしろに入ること。ボールがそれたときのため'), 'b': ('Sentarse en el dugout', 'Sitting in the dugout', '坐在休息区', 'ダッグアウトにすわること'), 'c': ('Batear dos veces', 'Batting twice', '击两次球', '2回打つこと')}), '3': act(('En defensa solo se mueve el jugador que atrapa la bola', 'On defense only the player catching the ball moves', '防守时只有接球的球员才动', '守備では、ボールをとる選手だけが動く'), ('¡Bien! Todos se mueven.', 'Good! Everybody moves.', '很好！大家都要动。', 'いいね！みんな動く。'), ('Falso: cada jugada mueve a los nueve.', 'False: every play moves all nine.', '错：每一球九个人都要动。', 'まちがい：どのプレーでも9人が動く。')), '4': act(('El catcher tira a segunda en un intento de robo. Toca al jardinero que respalda detrás de segunda', 'The catcher throws to second on a steal attempt. Tap the outfielder backing up behind second', '盗垒时捕手传向二垒。点一下在二垒后面补位防守的外野手', '盗塁でキャッチャーが二塁へ投げる。二塁のうしろでバックアップする外野手をタッチしよう'), ('¡Eso es! El central respalda segunda.', "That's it! The center fielder backs up second.", '对了！中外野手补位二垒。', 'そのとおり！中堅手が二塁をバックアップ。'), ('Detrás de segunda vive el central.', 'Behind second lives the center fielder.', '二垒后面是中外野手的位置。', '二塁のうしろには中堅手。'), answer=('El jardinero central', 'The center fielder', '中外野手', '中堅手')), '5': act(('¿Para qué sirve respaldar?', 'What is backing up for?', '补位防守有什么用？', 'バックアップは何のため？'), ('¡Correcto! Un error no se convierte en desastre.', "Correct! A mistake doesn't turn into a disaster.", '正确！一个失误不会变成大灾难。', '正解！ミスが大ごとにならない。'), ('La red convierte un escape en un susto.', 'The net turns an escape into just a scare.', '有这张网，漏球只是虚惊一场。', 'ネットがあれば、それても、ひやっとするだけ。'), opts={'a': ('Para que una bola escapada no regale bases extra', "So a ball that gets away doesn't give away extra bases", '让漏掉的球不白送额外的垒', 'それたボールで、よけいな塁をあげないため'), 'b': ('Para ver mejor', 'To see better', '为了看得更清楚', 'よく見るため'), 'c': ('Para descansar de pie', 'To rest standing up', '为了站着休息', '立って休むため')}), '6': act(('¿Cómo se dice respaldar en inglés?', "What's it called when you get behind a base in case the throw gets away?", '“补位防守”的英语怎么说？', 'バックアップは英語で何という？'), ('¡Bien! Back up.', 'Good! Backing up.', '很好！Back up。', 'いいね！Back up。'), ('Respaldar: back up.', "That's called backing up.", '补位防守：back up。', 'バックアップ：back up。'), opts={'a': ('Back up', 'Back up', 'Back up', 'Back up'), 'b': ('Tag up', 'Tag up', 'Tag up', 'Tag up'), 'c': ('Lead off', 'Lead off', 'Lead off', 'Lead off')})})
map_titles['12.3'] = ('Cubrir y respaldar', 'Covering and backing up', '补位占垒与补位防守', 'ベースカバーとバックアップ')
lesson('12.4', ('Las señales del coach y el repaso final', "The coach's signs and the final review", '教练的暗号和最后复习', 'コーチのサインとさいごのふくしゅう'), ('Conocer a los coaches de primera y tercera, que ven toda la jugada y mandan seguir o frenar, y las señales secretas del equipo; y repasar en situaciones cortas las reglas especiales de los niveles 9 y 10, solo como repaso.', "Meet the first and third base coaches, who see the whole play and tell you to keep going or stop, and the team's secret signs; and review in short situations the special rules from Levels 9 and 10, only as a review.", '认识一垒和三垒的跑垒指导员，他们能看到整个打法，告诉你继续跑还是停下；认识球队的秘密暗号；再用简短的情境复习第 9 级和第 10 级的特殊规则，只是复习。', '一塁と三塁のベースコーチを知ろう。プレーぜんたいを見て、走るか止まるかを教えてくれる。チームのひみつのサインも。そして、レベル9と10の特別なルールを、短い場面でふくしゅうしよう（ふくしゅうだけ）。'), [('Junto a primera y a tercera están los coaches de base, dentro de sus cuadros.', 'Next to first and third are the base coaches, inside their boxes.', '一垒和三垒旁边是跑垒指导员，他们站在自己的区域里。', '一塁と三塁の近くには、ベースコーチが、自分のボックスの中にいる。'), ('Ellos ven todo el campo y te dicen si sigues o te frenas: obedecer a tu coach de tercera es parte de correr bien.', 'They see the whole field and tell you whether to keep going or stop: listening to your third base coach is part of running well.', '他们能看到整个球场，告诉你继续跑还是停下：听三垒指导员的话，也是跑好垒的一部分。', 'グラウンドぜんぶを見て、走るか止まるかを教えてくれる：三塁コーチの言うことを聞くのも、じょうずに走ることのうち。'), ('El equipo además tiene señales con las manos para pedir un toque o un robo: son secretas y no se cuentan al rival.', "The team also has hand signs to call for a bunt or a steal: they're secret and you don't tell the other team.", '球队还有用手比的暗号，用来要求触击或盗垒：这些是秘密，不能告诉对手。', 'チームには、バントや盗塁をたのむ手のサインもある：ひみつだから、相手には教えない。'), ('Y antes de cerrar, repaso relámpago de lo aprendido en Estrella — repaso, no lección nueva: si el pitcher finge y no suelta, es balk; si el tercer strike no se atrapa limpio, el bateador puede correr cuando la regla aplica; y el elevado fácil con primera y segunda ocupadas es infield fly.', "And before we finish, a lightning review of what you learned in Star — a review, not a new lesson: if the pitcher fakes and doesn't let go, it's a balk; if the third strike isn't caught cleanly, the batter can run when the rule applies; and the easy fly ball with first and second occupied is an infield fly.", '结束之前，快速复习一下在“全明星”阶段学到的——是复习，不是新课：投手假装传球却不出手，是投手犯规；第三个好球没被干净接住，规则适用时击球员可以跑；一垒和二垒有人时的容易高飞球，是内野飞球。', 'さいごに、スターのステージでならったことを、いなずまふくしゅう——ふくしゅうで、新しいレッスンじゃない：ピッチャーがふりをしてボールをはなさなければボーク。3つ目のストライクをきちんととれなければ、ルールが使えるとき、バッターは走れる（振り逃げ）。一塁と二塁にランナーがいるときのかんたんなフライは、インフィールドフライ。'), ('Si ya lo sabías, estás listo para pensar como All Star.', "If you already knew it, you're ready to think like an All Star.", '如果你都已经知道了，你就准备好像全明星一样思考了。', 'もう知っていたなら、オールスターのように考えるじゅんびはできている。')], {'1': act(('¿Dónde están los coaches de base?', 'Where are the base coaches?', '跑垒指导员在哪里？', 'ベースコーチはどこにいる？'), ('¡Correcto! Uno en cada esquina.', 'Correct! One in each corner.', '正确！每个角落一个。', '正解！それぞれのかどに1人。'), ('Primera y tercera tienen su coach.', 'First and third each have their coach.', '一垒和三垒各有一名指导员。', '一塁と三塁に、それぞれコーチがいる。'), opts={'a': ('Junto a primera y junto a tercera', 'Next to first and next to third', '一垒旁边和三垒旁边', '一塁の近くと三塁の近く'), 'b': ('En el montículo', 'On the mound', '在投手丘上', 'マウンド'), 'c': ('En los jardines', 'In the outfield', '在外野', '外野')}), '2': act(('Vienes corriendo a tercera y tu coach levanta las manos para que pares. ¿Qué haces?', 'You come running to third and your coach raises his hands for you to stop. What do you do?', '你跑向三垒，指导员举起双手让你停下。你怎么做？', '三塁へ走ってきたら、コーチが止まれと手を上げた。どうする？'), ('¡Eso es! El coach ve todo.', "That's it! The coach sees everything.", '对了！指导员什么都看得到。', 'そのとおり！コーチはぜんぶ見ている。'), ('Manos arriba: alto en tercera.', 'Hands up: stop at third.', '双手举起：停在三垒。', '手が上がった：三塁でストップ。'), opts={'a': ('Me detengo en tercera', 'I stop at third', '我停在三垒', '三塁で止まる'), 'b': ('Sigo a home', 'I keep going home', '我继续跑回本垒', 'ホームへ走りつづける'), 'c': ('Regreso a primera', 'I go back to first', '我回一垒', '一塁にもどる')}), '3': act(('Las señales del equipo se le pueden contar al rival si pregunta amable', "The team's signs can be told to the other team if they ask nicely", '如果对手好好地问，可以把球队的暗号告诉他们', 'チームのサインは、相手がていねいに聞いたら教えてもいい'), ('¡Bien! Son secretas.', "Good! They're secret.", '很好！它们是秘密。', 'いいね！ひみつだよ。'), ('Falso: las señales son del equipo.', 'False: the signs belong to the team.', '错：暗号是球队自己的。', 'まちがい：サインはチームのもの。')), '4': act(('Repaso: el pitcher fingió tirar a primera y no soltó la bola, con corredor en base. Eso fue:', "Review: the pitcher faked a throw to first and didn't let go of the ball, with a runner on base. That was:", '复习：垒上有人，投手假装传向一垒却没出手。这是：', 'ふくしゅう：ランナーがいて、ピッチャーが一塁に投げるふりをして、ボールをはなさなかった。それは：'), ('¡Bien, repaso logrado! Era balk.', 'Good, review done! It was a balk.', '很好，复习成功！是投手犯规。', 'いいね、ふくしゅうできた！ボークだった。'), ('Repaso del Nivel 9: fingir sin soltar es balk.', 'Level 9 review: faking without letting go is a balk.', '复习第 9 级：假装却不出手就是投手犯规。', 'レベル9のふくしゅう：はなさずにふりをするのはボーク。'), opts={'a': ('Un balk', 'A balk', '投手犯规', 'ボーク'), 'b': ('Un pickoff legal', 'A legal pickoff', '合规的牵制传球', '正しい牽制球'), 'c': ('Un robo', 'A steal', '盗垒', '盗塁')}), '5': act(('Repaso: elevado fácil al cuadro, corredores en primera y segunda, un out. ¿Qué canta el umpire?', 'Review: easy fly ball to the infield, runners on first and second, one out. What does the umpire call?', '复习：内野的容易高飞球，一垒二垒有人，一出局。裁判怎么喊？', 'ふくしゅう：内野へかんたんなフライ、一塁と二塁にランナー、1アウト。審判のコールは？'), ('¡Eso es, repaso del Nivel 10!', "That's it, Level 10 review!", '对了，第 10 级复习成功！', 'そのとおり、レベル10のふくしゅう！'), ('Infield fly: bateador out cantado en el aire.', 'Infield fly: batter out, called in the air.', '内野飞球：球在空中就喊击球员出局。', 'インフィールドフライ：空中でバッターアウトのコール。'), opts={'a': ('«¡Infield fly! Bateador out»', '"Infield fly! Batter out"', '“内野飞球！击球员出局”', '「インフィールドフライ！バッターアウト」'), 'b': ('«¡Safe!»', '"Safe!"', '“安全上垒！”', '「セーフ！」'), 'c': ('«¡Bola!»', '"Ball!"', '“坏球！”', '「ボール！」')}), '6': act(('No entendiste una señal del coach. Lo mejor es:', "You didn't understand a sign from the coach. The best thing is:", '你没看懂教练的暗号。最好的做法是：', 'コーチのサインがわからなかった。いちばんいいのは：'), ('¡Bien! Preguntar es de All Star.', 'Good! Asking is what an All Star does.', '很好！问清楚才是全明星。', 'いいね！聞くのがオールスター。'), ('Mejor preguntar que adivinar.', 'Better to ask than to guess.', '问比猜好。', 'あてずっぽうより、聞くほうがいい。'), opts={'a': ('Pedir tiempo y preguntar', 'Ask for time and ask', '要求暂停，问清楚', 'タイムをとって聞く'), 'b': ('Hacer lo que yo quiera', 'Do whatever I want', '想怎么做就怎么做', 'すきなようにする'), 'c': ('Irme al dugout', 'Go to the dugout', '回休息区', 'ダッグアウトへ行く')})})
map_titles['12.4'] = ('Las señales del coach y el repaso final', "The coach's signs and the final review", '教练的暗号和最后复习', 'コーチのサインとさいごのふくしゅう')
lesson('12.5', ('Deportividad: así se porta un All Star', 'Sportsmanship: how an All Star behaves', '体育精神：全明星这样做', 'スポーツマンシップ：オールスターのふるまい'), ('Cerrar el contenido con la conducta del All Star: respetar las decisiones del umpire, animar al compañero que falla, saludar al rival al final gane o pierda, y dejar que el coach hable con el umpire cuando haya una discusión.', "Close the content with the All Star's behavior: respecting the umpire's decisions, cheering on a teammate who makes a mistake, shaking hands with the other team at the end win or lose, and letting the coach talk to the umpire when there is a disagreement.", '用全明星的行为结束全部内容：尊重裁判的判决，鼓励出错的队友，比赛结束时不论输赢都和对手握手，有争议时让教练去和裁判沟通。', 'オールスターのふるまいで、さいごをしめくくろう：審判の判定を大事にする、ミスした仲間をはげます、勝っても負けても試合のおわりに相手とあくしゅする、もめたときはコーチに審判と話してもらう。'), [('Un All Star no es solo el que batea jonrones.', "An All Star isn't just the one who hits home runs.", '全明星不只是打本垒打的人。', 'オールスターは、ホームランを打つ人だけじゃない。'), ('Es el que respeta la decisión del umpire aunque no le guste, el que anima a su compañero cuando falla en vez de burlarse, y el que al terminar el juego da la mano al rival, gane o pierda.', "It's the one who respects the umpire's decision even if he doesn't like it, who cheers on his teammate when he makes a mistake instead of making fun of him, and who shakes hands with the other team at the end of the game, win or lose.", '他尊重裁判的判决，即使自己不喜欢；队友出错时他会鼓励，而不是嘲笑；比赛结束时，不论输赢，他都和对手握手。', '気に入らなくても審判の判定を大事にする人。仲間がミスしたら、わらわずにはげます人。試合のおわりに、勝っても負けても相手とあくしゅする人。'), ('Eso es deportividad, en inglés sportsmanship.', "That's sportsmanship.", '这就是体育精神，英语叫 sportsmanship。', 'それがスポーツマンシップ、英語で sportsmanship。'), ('Si tu equipo no está de acuerdo con una jugada, el que habla con el umpire es tu coach, con respeto.', "If your team doesn't agree with a play, the one who talks to the umpire is your coach, with respect.", '如果你们队不同意某个判决，去和裁判沟通的是你的教练，而且要有礼貌。', 'チームがプレーになっとくできないときは、審判と話すのはコーチ。ていねいにね。'), ('Jugar bien se entrena; portarse bien también.', 'Playing well is trained; behaving well is too.', '打得好要训练；表现得好也要训练。', 'うまくプレーするのも練習、よくふるまうのも練習。'), ('Eso es pensar — y actuar — como un All Star.', "That's thinking — and acting — like an All Star.", '这就是像全明星一样思考——也像全明星一样行动。', 'それが、オールスターのように考えること——そして、ふるまうこと。')], {'1': act(('El umpire canta un strike que te pareció bola. ¿Qué hace un All Star?', 'The umpire calls a strike that looked like a ball to you. What does an All Star do?', '裁判判了一个好球，你觉得是坏球。全明星会怎么做？', '審判がストライクとコール。君にはボールに見えた。オールスターはどうする？'), ('¡Eso es un All Star! El umpire decide.', "That's an All Star! The umpire decides.", '这就是全明星！裁判说了算。', 'それがオールスター！審判が決める。'), ('Respeta y sigue: así se juega.', "Respect and keep going: that's how you play.", '尊重判决，继续比赛：这才是打球的方式。', '大事にして、つづける：それが野球。'), opts={'a': ('Respeta la decisión y sigue bateando', 'Respects the decision and keeps batting', '尊重判决，继续击球', '判定を大事にして、打ちつづける'), 'b': ('Le grita al umpire', 'Yells at the umpire', '对裁判大喊', '審判にどなる'), 'c': ('Tira el bate', 'Throws the bat', '扔球棒', 'バットを投げる')}), '2': act(('Tu compañero cometió un error que costó una carrera. ¿Qué le dices?', 'Your teammate made an error that cost a run. What do you say to him?', '你的队友失误，让对方得了一分。你对他说：', '仲間のエラーで1点とられた。なんと言う？'), ('¡Correcto! Animar es de equipo.', 'Correct! Cheering is what a team does.', '正确！鼓励是团队的表现。', '正解！はげますのがチーム。'), ('Todos fallan: el All Star levanta.', 'Everyone makes mistakes: the All Star lifts them up.', '每个人都会犯错：全明星会让大家振作起来。', 'だれでもミスする：オールスターは元気づける。'), opts={'a': ('«¡Tranquilo, la próxima es tuya!»', '"Don\'t worry, the next one is yours!"', '“没关系，下一个就是你的！”', '「だいじょうぶ、つぎは君の番だ！」'), 'b': ('«¡Lo hiciste todo mal!»', '"You did everything wrong!"', '“你全都做错了！”', '「ぜんぶだめだったね！」'), 'c': ('Nada, y me enojo con él', 'Nothing, and I get angry at him', '什么都不说，还生他的气', '何も言わずに、おこる')}), '3': act(('Al terminar el juego se da la mano al rival solo si ganaste', 'At the end of the game you shake hands with the other team only if you won', '比赛结束时，只有赢了才和对手握手', '試合のおわりに、勝ったときだけ相手とあくしゅする'), ('¡Bien! Se da la mano siempre.', 'Good! You always shake hands.', '很好！一定要握手。', 'いいね！いつもあくしゅする。'), ('Falso: gane o pierda, la mano va.', 'False: win or lose, you shake hands.', '错：不论输赢，都要握手。', 'まちがい：勝っても負けても、あくしゅ。')), '4': act(('Si tu equipo no está de acuerdo con una decisión, ¿quién habla con el umpire?', "If your team doesn't agree with a decision, who talks to the umpire?", '如果你们队不同意一个判决，谁去和裁判说？', 'チームが判定になっとくできないとき、審判と話すのはだれ？'), ('¡Eso es! El coach y con respeto.', "That's it! The coach, and with respect.", '对了！教练去，而且要有礼貌。', 'そのとおり！コーチが、ていねいに。'), ('Hablar es trabajo del coach.', "Talking is the coach's job.", '沟通是教练的工作。', '話すのはコーチのしごと。'), opts={'a': ('El coach, con respeto', 'The coach, with respect', '教练，有礼貌地', 'コーチ、ていねいに'), 'b': ('Todos los jugadores gritando', 'All the players yelling', '所有球员一起大喊', '選手みんなでどなる'), 'c': ('El público', 'The crowd', '观众', 'お客さん')}), '5': act(('¿Cuál imagen muestra deportividad?', 'Which picture shows sportsmanship?', '哪张图表现了体育精神？', 'スポーツマンシップはどの絵？'), ('¡Correcto! Respeto al final del juego.', 'Correct! Respect at the end of the game.', '正确！比赛结束时互相尊重。', '正解！試合のおわりに、そんけい。'), ('La fila de manos: el cierre de todo juego.', 'The handshake line: the close of every game.', '握手的队伍：每场比赛的结尾。', 'あくしゅのれつ：どの試合もそれでおわる。'), opts={'a': ('Dos equipos dándose la mano al terminar', 'Two teams shaking hands at the end', '比赛结束时两队握手', '試合のおわりにあくしゅする2つのチーム'), 'b': ('Un jugador tirando el casco de rabia', 'A player throwing his helmet in anger', '一名球员生气地扔头盔', 'おこってヘルメットを投げる選手'), 'c': ('Un jugador burlándose del rival', 'A player making fun of the other team', '一名球员嘲笑对手', '相手をからかう選手')}), '6': act(('¿Cómo se dice deportividad en inglés?', 'What do we call respecting the umpire, your teammates and the other team?', '“体育精神”的英语怎么说？', 'スポーツマンシップは英語で何という？'), ('¡Bien! Sportsmanship.', 'Good! Sportsmanship.', '很好！Sportsmanship。', 'いいね！Sportsmanship。'), ('Esa palabra también es de All Star.', 'That word belongs to an All Star too.', '这个词也属于全明星。', 'その言葉もオールスターのもの。'), opts={'a': ('Sportsmanship', 'Sportsmanship', 'Sportsmanship', 'Sportsmanship'), 'b': ('Strikeout', 'Strikeout', 'Strikeout', 'Strikeout'), 'c': ('Shortstop', 'Shortstop', 'Shortstop', 'Shortstop')})})
