exams_v3['12'] = {'1': {'q': ('¿Cuándo se piensa a dónde tirar la bola?', 'When do you think about where to throw the ball?', '什么时候想好球要传到哪里？', 'ボールをどこに投げるか、いつ考える？'), 'opts': {'a': ('Antes de cada lanzamiento', 'Before every pitch', '每一球投出之前', '1球ごとに、投げる前'), 'b': ('Después del juego', 'After the game', '比赛结束以后', '試合のあと'), 'c': ('Nunca', 'Never', '从来不想', '考えない')}}, '2': {'q': ('Sin corredores, rolling al tercera base: tira a:', 'No runners, ground ball to the third baseman: he throws to:', '垒上没人，打给三垒手的滚地球：他传向：', 'ランナーなし、三塁手へゴロ：投げるのは：'), 'opts': {'a': ('Primera', 'First', '一垒', '一塁'), 'b': ('Home', 'Home', '本垒', 'ホーム'), 'c': ('Segunda', 'Second', '二垒', '二塁')}}, '3': {'q': ('El corredor que conviene frenar primero es:', "The runner it's best to stop first is:", '最好先拦住的跑垒员是：', '先に止めるのがいいランナーは：'), 'opts': {'a': ('El más adelantado', 'The lead runner', '前位跑者', 'リードランナー'), 'b': ('El más lento', 'The slowest one', '最慢的那个', 'いちばんおそいランナー'), 'c': ('Ninguno', 'None', '谁都不用', 'だれでもない')}}, '4': {'q': ('Toca la base del out con un rolling sin corredores', 'Tap the base for the out on a ground ball with no runners', '垒上没人时的滚地球，点一下出局的垒', 'ランナーなしのゴロで、アウトにする塁をタッチしよう'), 'answer': ('Primera base', 'First base', '一垒', '一塁')}, '5': {'q': ('En un tiro largo desde los jardines, ¿qué hace el cortador?', 'On a long throw from the outfield, what does the cutoff man do?', '外野长传时，中继球员（cutoff）做什么？', '外野からの長い送球で、カットマンは何をする？'), 'opts': {'a': ('Recibe el tiro y lo pasa a la base que haga falta', 'Catches the throw and passes it on to whatever base is needed', '接住传球，再传到需要的垒', '送球を受けて、ひつような塁へつなぐ'), 'b': ('Batea', 'Bats', '击球', '打つ'), 'c': ('Se va al dugout', 'Goes to the dugout', '回休息区', 'ベンチにもどる')}}, '6': {'q': ('Verdadero o falso: el cortador es un defensor del cuadro que se pone en el camino del tiro', "True or false: the cutoff man is an infielder who gets in the throw's path", '对还是错：中继球员是站在传球路线上的内野手', '○か×か：カットマンは、送球の通り道に入る内野手')}, '7': {'q': ('El primera base sale lejos a buscar un rolling. ¿Quién cubre primera?', 'The first baseman goes far to get a grounder. Who covers first?', '一垒手跑远去接地滚球。谁去补一垒？', '一塁手がゴロをとりに遠くへ出た。一塁をカバーするのは？'), 'opts': {'a': ('El pitcher', 'The pitcher', '投手', 'ピッチャー'), 'b': ('El jardinero central', 'The center fielder', '中外野手', 'センター'), 'c': ('Nadie', 'Nobody', '没人', 'だれも')}}, '8': {'q': ('¿Para qué sirve respaldar (back up) detrás de una base?', 'What is backing up behind a base for?', '在垒包后面补位防守（back up）是为了什么？', '塁のうしろでバックアップするのは何のため？'), 'opts': {'a': ('Para frenar la bola si se escapa', 'To stop the ball if it gets away', '球漏掉时把它挡住', 'ボールがそれたときに止めるため'), 'b': ('Para descansar', 'To rest', '为了休息', '休むため'), 'c': ('Para batear', 'To bat', '为了击球', '打つため')}}, '9': {'q': ('¿Quién te dice si sigues corriendo o te frenas en tercera?', 'Who tells you whether to keep running or stop at third?', '谁告诉你要继续跑还是在三垒停下？', '三塁で、走りつづけるか止まるかを教えてくれるのは？'), 'opts': {'a': ('El coach de tercera', 'The third-base coach', '三垒指导员', '三塁コーチ'), 'b': ('El rival', 'The other team', '对手', '相手チーム'), 'c': ('El público', 'The crowd', '观众', '観客')}}, '10': {'q': ('Verdadero o falso: las señales del equipo se le cuentan al rival', "True or false: you tell the other team your team's signs", '对还是错：要把自己队的暗号告诉对手', '○か×か：チームのサインを相手に教える')}, '11': {'q': ('Al terminar el juego, ganes o pierdas, un All Star:', 'When the game ends, win or lose, an All Star:', '比赛结束时，不管输赢，全明星会：', '試合が終わったら、勝っても負けても、オールスターは：'), 'opts': {'a': ('Saluda al rival', 'Shakes hands with the other team', '和对手握手致意', '相手にあいさつする'), 'b': ('Se va sin saludar', 'Leaves without saying goodbye', '不打招呼就走', 'あいさつしないで帰る'), 'c': ('Se burla del rival', 'Makes fun of the other team', '嘲笑对手', '相手をからかう')}}, '12': {'q': ('Si no estás de acuerdo con el umpire, ¿qué haces?', "If you don't agree with the umpire, what do you do?", '如果你不同意裁判的判定，你怎么做？', '審判の判定に納得できないとき、どうする？'), 'opts': {'a': ('Dejo que mi coach hable con él', 'I let my coach talk to him', '让我的教练去和他说', 'コーチに話してもらう'), 'b': ('Le grito', 'I yell at him', '对他大喊', 'さけぶ'), 'c': ('Tiro el casco', 'I throw my helmet', '扔头盔', 'ヘルメットを投げる')}}}
