lesson('13.1', ('El equipo del catcher', "The catcher's gear", '捕手的护具', 'キャッチャーの防具'), ('Conocer las piezas del equipo del catcher (casco, careta, peto, espinilleras y mascota) y que se usan completas siempre que se recibe a un pitcher, también al calentar.', "Know the pieces of the catcher's gear (helmet, mask, chest protector, shin guards and mitt) and that they are worn complete every time you catch a pitcher, warming up too.", '认识捕手护具的每一件（头盔、面罩、护胸、护腿和捕手手套），并且知道每次接投手的球都要穿戴齐全，热身时也一样。', 'キャッチャーの防具（ヘルメット、マスク、プロテクター、レガース、キャッチャーミット）を知ろう。ピッチャーの球を受けるときは、ウォーミングアップでも、いつもぜんぶつけるんだ。'), [('El catcher se viste como un caballero con armadura, y no es por gusto: recibe la bola más rápida del juego.', 'The catcher dresses like a knight in armor, and not just for fun: he catches the fastest ball in the game.', '捕手穿得像披着盔甲的骑士，这可不是为了好玩：他要接比赛里最快的球。', 'キャッチャーはよろいを着た騎士みたいなかっこう。それにはわけがある：試合でいちばん速い球を受けるからだ。'), ('Lleva casco y careta para la cabeza y la cara, peto para el pecho y espinilleras para las piernas.', 'He wears a helmet and mask for his head and face, a chest protector for his chest and shin guards for his legs.', '他戴头盔和面罩保护头和脸，穿护胸保护胸口，戴护腿保护双腿。', 'ヘルメットとマスクで頭と顔を、プロテクターで胸を、レガースで足を守る。'), ("En la mano usa la mascota, en inglés catcher's mitt: un guante grande y acolchado.", "On his hand he wears the catcher's mitt: a big, padded glove.", "手上戴的是捕手手套，英语叫 catcher's mitt：一只又大又厚的手套。", "手にはキャッチャーミット、英語で catcher's mitt：大きくて、ぶあついグラブだ。"), ('La regla de oro: nunca recibes a un pitcher sin tu equipo completo, ni siquiera para calentar.', 'The golden rule: you never catch a pitcher without your full gear, not even to warm up.', '黄金规则：没有穿戴齐全的护具，绝对不接投手的球，连热身也不行。', '金のルール：防具をぜんぶつけていないときは、ピッチャーの球を受けない。ウォーミングアップでもだめ。'), ('Tu armadura es la que te deja jugar sin miedo.', 'Your armor is what lets you play without fear.', '你的盔甲让你可以毫不害怕地比赛。', 'よろいがあるから、こわがらずにプレーできるんだ。')], {'1': act(('¿Para qué usa el catcher tanto equipo?', 'Why does the catcher wear so much gear?', '捕手为什么要穿戴这么多护具？', 'キャッチャーはどうしてこんなに防具をつけるの？'), ('¡Eso es! Su armadura lo cuida.', "That's it! His armor takes care of him.", '对了！盔甲保护他。', 'そのとおり！よろいが守ってくれる。'), ('El catcher recibe cada lanzamiento: necesita protección.', 'The catcher catches every pitch: he needs protection.', '捕手要接每一个投球：他需要保护。', 'キャッチャーは全部の投球を受ける：守りがひつようなんだ。'), opts={'a': ('Para protegerse de la bola más rápida del juego', 'To protect himself from the fastest ball in the game', '为了保护自己不被比赛里最快的球打伤', '試合でいちばん速い球から身を守るため'), 'b': ('Para verse más grande', 'To look bigger', '为了看起来更大', '大きく見せるため'), 'c': ('Para correr más rápido', 'To run faster', '为了跑得更快', '速く走るため')}), '2': act(('¿Cuál imagen muestra al catcher listo para recibir?', 'Which picture shows the catcher ready to catch?', '哪张图是准备好接球的捕手？', '球を受けるじゅんびができたキャッチャーはどの絵？'), ('¡Correcto! Equipo completo.', 'Correct! Full gear.', '正确！护具齐全。', '正解！防具はぜんぶ。'), ('Sin careta no se recibe nunca.', 'You never catch without a mask.', '没戴面罩绝对不接球。', 'マスクなしでは、ぜったい受けない。'), opts={'a': ('Catcher con casco, careta, peto y espinilleras', 'Catcher with helmet, mask, chest protector and shin guards', '戴着头盔、面罩、护胸和护腿的捕手', 'ヘルメット、マスク、プロテクター、レガースをつけたキャッチャー'), 'b': ('Catcher con gorra y sin careta', 'Catcher with a cap and no mask', '戴着帽子、没戴面罩的捕手', 'ぼうしをかぶって、マスクなしのキャッチャー'), 'c': ('Catcher sin guante', 'Catcher without a mitt', '没戴手套的捕手', 'ミットなしのキャッチャー')}), '3': act(('Para calentar con el pitcher, el catcher puede recibir sin careta', 'To warm up with the pitcher, the catcher can catch without a mask', '和投手热身时，捕手可以不戴面罩接球', 'ピッチャーとのウォーミングアップなら、キャッチャーはマスクなしで受けてもいい'), ('¡Bien! Ni para calentar.', 'Good! Not even to warm up.', '很好！热身也不行。', 'いいね！ウォーミングアップでもだめ。'), ('Falso: el equipo va completo siempre, también al calentar.', 'False: the gear is always complete, warming up too.', '错：护具永远要齐全，热身时也一样。', 'まちがい：防具はいつもぜんぶ。ウォーミングアップでも。')), '4': act(('¿Cómo se llama el guante especial del catcher?', "What is the catcher's special glove called?", '捕手专用的手套叫什么？', 'キャッチャーのとくべつなグラブは何という？'), ('¡Eso es! Mascota.', "That's it! Catcher's mitt.", '对了！捕手手套。', 'そのとおり！キャッチャーミット。'), ('Es la mascota: grande y acolchada.', "It's the catcher's mitt: big and padded.", '是捕手手套：又大又厚。', 'キャッチャーミット：大きくて、ぶあつい。'), opts={'a': ("La mascota (catcher's mitt)", "The catcher's mitt", "捕手手套（catcher's mitt）", "キャッチャーミット（catcher's mitt）"), 'b': ('El bate', 'The bat', '球棒', 'バット'), 'c': ('La almohadilla', 'The pad', '垫子', 'クッション')}), '5': act(('Arrastra cada pieza a su lugar: careta, peto, espinilleras', 'Drag each piece to its place: mask, chest protector, shin guards', '把每件护具拖到它的位置：面罩、护胸、护腿', '防具をそれぞれの場所にドラッグしよう：マスク、プロテクター、レガース'), ('¡Perfecto! Cada pieza en su sitio.', 'Perfect! Each piece in its spot.', '完美！每件都放对了。', 'パーフェクト！それぞれの場所にぴったり。'), ('Careta en la cara, peto en el pecho, espinilleras en las piernas.', 'Mask on the face, chest protector on the chest, shin guards on the legs.', '面罩戴在脸上，护胸穿在胸前，护腿戴在腿上。', 'マスクは顔、プロテクターは胸、レガースは足。'), opts={'mask': ('Careta', 'Mask', '面罩', 'マスク'), 'chest': ('Peto', 'Chest protector', '护胸', 'プロテクター'), 'shins': ('Espinilleras', 'Shin guards', '护腿', 'レガース'), 'face': ('Cara', 'Face', '脸', '顔'), 'chestSlot': ('Pecho', 'Chest', '胸', '胸'), 'legs': ('Piernas', 'Legs', '腿', '足')}, answer=('Cara / Pecho / Piernas', 'Face / Chest / Legs', '脸 / 胸 / 腿', '顔 / 胸 / 足')), '6': act(('Antes de recibir, ¿qué revisa el catcher?', 'Before catching, what does the catcher check?', '接球之前，捕手要检查什么？', '受ける前に、キャッチャーは何をたしかめる？'), ('¡Eso es! Primero la revisión.', "That's it! The check comes first.", '对了！先检查。', 'そのとおり！まずはチェック。'), ('Revisa tu armadura antes de cada juego.', 'Check your armor before every game.', '每场比赛前都要检查你的盔甲。', '試合の前に、いつもよろいをたしかめよう。'), opts={'a': ('Que su equipo esté completo y bien puesto', 'That his gear is complete and put on right', '护具是否齐全、穿戴好了', '防具がぜんぶそろって、ちゃんとついているか'), 'b': ('Que la banca lo mire', 'That the dugout is watching him', '休息区的人有没有在看他', 'ベンチのみんなが見ているか'), 'c': ('Nada, sale corriendo', 'Nothing, he runs out', '什么都不检查，直接跑出去', '何もしない、すぐ走って出る')})})
map_titles['13.1'] = ('El equipo del catcher', "The catcher's gear", '捕手的护具', 'キャッチャーの防具')
lesson('13.2', ('Las señas al pitcher', 'Signs to the pitcher', '给投手的暗号', 'ピッチャーへのサイン'), ('Entender que el catcher le pide el lanzamiento al pitcher con señas de los dedos, escondidas entre las piernas, y que en ligas infantiles muchas veces el coach decide qué se pide.', "Understand that the catcher asks the pitcher for the pitch with finger signs hidden between his legs, and that in kids' leagues the coach often decides what to call.", '明白捕手用藏在两腿之间的手指暗号向投手要球，而且在少儿联赛里，常常是教练决定要投什么球。', 'キャッチャーは、足のあいだにかくした指のサインで、ピッチャーに投げる球をたのむ。子どものリーグでは、何をたのむかをコーチが決めることも多い。'), [('El catcher y el pitcher hablan sin decir una palabra.', 'The catcher and the pitcher talk without saying a word.', '捕手和投手一句话都不说也能交流。', 'キャッチャーとピッチャーは、ひとことも言わずに話す。'), ('Agachado, el catcher esconde la mano entre las piernas y muestra dedos: un dedo puede ser la recta, dos dedos el cambio.', 'Crouched down, the catcher hides his hand between his legs and shows fingers: one finger can be the fastball, two fingers the changeup.', '捕手蹲着，把手藏在两腿之间比手指：一根手指可以代表直球，两根手指代表变速球。', 'しゃがんだキャッチャーは、足のあいだに手をかくして指を見せる：指1本はストレート、2本はチェンジアップ、というふうに。'), ('Se llaman señas, en inglés signs.', "They're called signs.", '这叫暗号，英语叫 signs。', 'これをサイン、英語で signs という。'), ('Las esconde para que el rival no las vea.', "He hides them so the other team can't see them.", '他把暗号藏起来，不让对手看到。', '相手に見られないように、かくすんだ。'), ('El pitcher mira, y si está de acuerdo, lanza.', 'The pitcher looks, and if he agrees, he pitches.', '投手看着，如果同意，就投球。', 'ピッチャーは見て、オーケーなら投げる。'), ('En ligas de niños, muchas veces el coach le pasa la seña al catcher y el catcher la pasa al pitcher.', "In kids' leagues, the coach often passes the sign to the catcher and the catcher passes it to the pitcher.", '在少儿联赛里，常常是教练把暗号传给捕手，捕手再传给投手。', '子どものリーグでは、コーチがキャッチャーにサインを出して、キャッチャーがピッチャーに伝えることが多い。'), ('Si no entendiste una seña, se pide tiempo y se habla: nunca se lanza adivinando.', "If you didn't understand a sign, ask for time and talk: you never pitch by guessing.", '如果没看懂暗号，就要求暂停，当面说清楚：绝对不能靠猜来投球。', 'サインがわからなかったら、タイムをとって話す：あてずっぽうでは、ぜったい投げない。')], {'1': act(('¿Para qué sirven las señas (signs)?', 'What are signs for?', '暗号（signs）是用来做什么的？', 'サイン（signs）は何のため？'), ('¡Eso es! Hablan sin palabras.', "That's it! They talk without words.", '对了！不用说话也能交流。', 'そのとおり！言葉なしで話す。'), ('Las señas piden el lanzamiento en secreto.', 'Signs ask for the pitch in secret.', '暗号偷偷地要球。', 'サインはこっそり球をたのむ。'), opts={'a': ('Para pedirle el lanzamiento al pitcher sin hablar', 'To ask the pitcher for the pitch without talking', '不说话就向投手要球', '話さずにピッチャーに投げる球をたのむため'), 'b': ('Para saludar al público', 'To wave at the crowd', '向观众打招呼', 'お客さんにあいさつするため'), 'c': ('Para pedir agua', 'To ask for water', '要水喝', '水をたのむため')}), '2': act(('¿Dónde esconde el catcher la mano de las señas?', 'Where does the catcher hide the hand giving signs?', '捕手把比暗号的手藏在哪里？', 'キャッチャーはサインを出す手をどこにかくす？'), ('¡Correcto! Bien escondida.', 'Correct! Well hidden.', '正确！藏得很好。', '正解！しっかりかくれている。'), ('Si el rival la ve, descubre el plan.', 'If the other team sees it, they find out the plan.', '如果被对手看到，计划就被发现了。', '相手に見られたら、作戦がばれちゃう。'), opts={'a': ('Entre las piernas, donde el rival no la ve', "Between his legs, where the other team can't see it", '两腿之间，对手看不到的地方', '足のあいだ、相手から見えないところ'), 'b': ('Detrás de la espalda del umpire', "Behind the umpire's back", '裁判的背后', '審判のせなかのうしろ'), 'c': ('En el bolsillo', 'In his pocket', '口袋里', 'ポケットの中')}), '3': act(('Si el pitcher no entiende la seña, debe lanzar adivinando', "If the pitcher doesn't understand the sign, he should pitch by guessing", '如果投手没看懂暗号，就应该靠猜来投球', 'ピッチャーはサインがわからなかったら、あてずっぽうで投げればいい'), ('¡Bien! Nunca adivinando.', 'Good! Never by guessing.', '很好！绝对不能猜。', 'いいね！あてずっぽうはだめ。'), ('Falso: se pide tiempo y se habla.', 'False: ask for time and talk.', '错：要求暂停，当面说清楚。', 'まちがい：タイムをとって話そう。')), '4': act(('En ligas de niños, ¿quién decide muchas veces qué lanzamiento pedir?', "In kids' leagues, who often decides which pitch to call?", '在少儿联赛里，常常是谁决定要投什么球？', '子どものリーグでは、どの球をたのむかをよく決めるのはだれ？'), ('¡Eso es! El coach ayuda.', "That's it! The coach helps.", '对了！教练来帮忙。', 'そのとおり！コーチが手伝う。'), ('Coach → catcher → pitcher: así viaja la seña.', "Coach → catcher → pitcher: that's how the sign travels.", '教练 → 捕手 → 投手：暗号就是这样传的。', 'コーチ → キャッチャー → ピッチャー：サインはこう伝わる。'), opts={'a': ('El coach, que pasa la seña al catcher', 'The coach, who passes the sign to the catcher', '教练，他把暗号传给捕手', 'コーチ。キャッチャーにサインを出す'), 'b': ('El público', 'The crowd', '观众', 'お客さん'), 'c': ('El bateador', 'The batter', '击球员', 'バッター')}), '5': act(('Toca al jugador que primero recibe la seña del coach', "Tap the player who first gets the coach's sign", '点一下最先收到教练暗号的球员', 'コーチのサインを最初に受けとる選手をタッチしよう'), ('¡Bien! El catcher.', 'Good! The catcher.', '很好！是捕手。', 'いいね！キャッチャー。'), ('El coach se la pasa al catcher.', 'The coach passes it to the catcher.', '教练把暗号传给捕手。', 'コーチはキャッチャーにサインを出す。'), answer=('El catcher', 'The catcher', '捕手', 'キャッチャー')), '6': act(('Las señas se muestran abiertas para que todos las vean', 'Signs are shown openly so everyone can see them', '暗号要公开比出来，让大家都看到', 'サインはみんなに見えるように、はっきり見せる'), ('¡Correcto! Son secretas.', "Correct! They're secret.", '正确！暗号是秘密。', '正解！サインはひみつ。'), ('Falso: se esconden del equipo rival.', 'False: they are hidden from the other team.', '错：要藏起来不让对手看到。', 'まちがい：相手チームからかくすんだ。'))})
map_titles['13.2'] = ('Las señas al pitcher', 'Signs to the pitcher', '给投手的暗号', 'ピッチャーへのサイン')
lesson('13.3', ('Bloquear la bola en tierra', 'Blocking the ball in the dirt', '挡住落地球', 'ワンバウンドをブロック'), ('Aprender la técnica de bloquear: caer de rodillas frente a la bola que pica, con el cuerpo detrás, para que rebote cerca y ningún corredor avance gratis.', 'Learn the blocking technique: drop to your knees in front of the ball that bounces, with your body behind it, so it bounces close and no runner moves up for free.', '学会挡球的技术：在弹地的球前面跪下，用身体挡在球后面，让球弹在身边，不让跑垒员白白进垒。', 'ブロックのやり方を知ろう：はずんだ球の前にひざをついて、体を球のうしろに入れる。球は近くに落ちて、ランナーはただで進めない。'), [('A veces el lanzamiento pica en la tierra y viene botando hacia ti.', 'Sometimes the pitch hits the dirt and comes bouncing at you.', '有时投球打在地上，弹跳着向你过来。', 'ときどき、投球が地面でバウンドして、はねながら来る。'), ('No intentes atraparla con una mano: ¡bloquéala!', "Don't try to catch it with one hand: block it!", '别想用一只手去接：要挡住它！', '片手でとろうとしないで：ブロックしよう！'), ('Bloquear, en inglés block, es caer de rodillas justo frente a la bola, con el pecho inclinado y la mascota cubriendo el hueco entre las piernas.', 'Blocking is dropping to your knees right in front of the ball, with your chest leaning forward and the mitt covering the gap between your legs.', '挡球，英语叫 block，就是正对着球跪下来，胸口往前倾，用手套盖住两腿之间的空隙。', 'ブロック、英語で block は、球の真正面でひざをつくこと。胸は前にかたむけて、ミットで足のあいだのすきまをふさぐ。'), ('La bola pega en tu peto y cae muerta delante de ti, cerquita.', 'The ball hits your chest protector and drops dead in front of you, close by.', '球打在你的护胸上，掉在你面前，离你很近。', '球はプロテクターに当たって、目の前のすぐ近くにぽとりと落ちる。'), ('Así ningún corredor avanza.', 'That way no runner moves up.', '这样就没有跑垒员能前进。', 'これでランナーは進めない。'), ('Bloquear duele un poquito a veces, y para eso llevas tu armadura completa.', "Blocking hurts a little sometimes, and that's why you wear your full armor.", '挡球有时候会有点疼，所以你要穿齐全套盔甲。', 'ブロックはときどき少しいたい。だから、よろいをぜんぶつけているんだ。')], {'1': act(('¿Qué hace el catcher cuando el lanzamiento pica en la tierra?', 'What does the catcher do when the pitch hits the dirt?', '投球打在地上时，捕手怎么做？', '投球が地面でバウンドしたら、キャッチャーはどうする？'), ('¡Eso es! A bloquear.', "That's it! Block it.", '对了！挡住它。', 'そのとおり！ブロックだ。'), ('Tu cuerpo es el muro: la bola cae delante de ti.', 'Your body is the wall: the ball drops in front of you.', '你的身体就是墙：球掉在你面前。', '体がかべになる：球は目の前に落ちる。'), opts={'a': ('Lo bloquea cayendo de rodillas frente a la bola', 'He blocks it, dropping to his knees in front of the ball', '跪在球前面把球挡住', '球の前にひざをついてブロックする'), 'b': ('Se aparta y la deja pasar', 'He steps aside and lets it go by', '躲开，让球过去', 'よけて、球を通す'), 'c': ('La patea', 'He kicks it', '用脚踢球', 'ける')}), '2': act(('¿Dónde debe caer la bola bloqueada?', 'Where should the blocked ball land?', '被挡住的球应该落在哪里？', 'ブロックした球はどこに落ちればいい？'), ('¡Correcto! Cerquita y a la vista.', 'Correct! Close and in sight.', '正确！近，而且看得到。', '正解！近くで、見えるところ。'), ('Si cae delante, la recoges rápido y nadie avanza.', 'If it lands in front, you pick it up fast and nobody moves up.', '球落在前面，你就能马上捡起来，谁也不能前进。', '前に落ちれば、すぐ拾えて、だれも進めない。'), opts={'a': ('Delante del catcher, cerquita', 'In front of the catcher, close by', '捕手前面，离得很近', 'キャッチャーの前、すぐ近く'), 'b': ('Detrás del catcher', 'Behind the catcher', '捕手后面', 'キャッチャーのうしろ'), 'c': ('En la banca', 'In the dugout', '休息区里', 'ベンチの中')}), '3': act(('Para bloquear alcanza con estirar una mano hacia la bola que pica', "To block, it's enough to reach one hand toward the bouncing ball", '挡球时，只要朝弹地的球伸出一只手就够了', 'ブロックは、はずむ球に片手をのばすだけでいい'), ('¡Bien! Se bloquea con el cuerpo.', 'Good! You block with your body.', '很好！要用身体挡。', 'いいね！体でブロックする。'), ('Falso: rodillas al suelo y cuerpo detrás de la bola.', 'False: knees down and body behind the ball.', '错：跪下来，身体挡在球后面。', 'まちがい：ひざをついて、体を球のうしろに。')), '4': act(('¿Cuál imagen muestra un buen bloqueo?', 'Which picture shows a good block?', '哪张图是好的挡球？', 'いいブロックはどの絵？'), ('¡Eso es! Esa es la forma.', "That's it! That's the way.", '对了！就是这样。', 'そのとおり！それがやり方。'), ('Rodillas, pecho y mascota cubriendo el hueco.', 'Knees, chest and mitt covering the gap.', '跪下、挺胸、用手套盖住空隙。', 'ひざ、胸、すきまをふさぐミット。'), opts={'a': ('Catcher de rodillas, pecho inclinado y mascota entre las piernas', 'Catcher on his knees, chest leaning and mitt between his legs', '捕手跪着，胸口前倾，手套放在两腿之间', 'ひざをついて、胸をかたむけ、ミットを足のあいだに入れたキャッチャー'), 'b': ('Catcher parado de lado', 'Catcher standing sideways', '侧身站着的捕手', '横向きに立っているキャッチャー'), 'c': ('Catcher saltando', 'Catcher jumping', '跳起来的捕手', 'ジャンプしているキャッチャー')}), '5': act(('¿Para qué sirve bloquear bien?', 'What is a good block for?', '好好挡球有什么用？', 'ちゃんとブロックすると何がいい？'), ('¡Correcto! Proteges las bases.', 'Correct! You protect the bases.', '正确！你守住了垒。', '正解！塁を守った。'), ('Bola controlada, corredores quietos.', 'Ball under control, runners stay put.', '球被控制住，跑垒员就不动。', '球をおさえれば、ランナーは動けない。'), opts={'a': ('Para que ningún corredor avance con la bola suelta', 'So no runner moves up on a loose ball', '让跑垒员不能趁球没人控制时前进', 'ころがった球でランナーを進ませないため'), 'b': ('Para descansar las piernas', 'To rest your legs', '让腿休息', '足を休めるため'), 'c': ('Para asustar al bateador', 'To scare the batter', '吓唬击球员', 'バッターをこわがらせるため')}), '6': act(('Bloquear se hace sin equipo porque la bola viene despacio', 'Blocking is done without gear because the ball comes slowly', '挡球不用穿护具，因为球来得很慢', 'ブロックは球がゆっくりだから、防具なしでやる'), ('¡Bien! Armadura siempre.', 'Good! Armor always.', '很好！永远要穿盔甲。', 'いいね！よろいはいつも。'), ('Falso: se bloquea con el equipo completo puesto.', 'False: you block with your full gear on.', '错：挡球时要穿齐全套护具。', 'まちがい：防具をぜんぶつけてブロックする。'))})
map_titles['13.3'] = ('Bloquear la bola en tierra', 'Blocking the ball in the dirt', '挡住落地球', 'ワンバウンドをブロック')
lesson('13.4', ('La interferencia del catcher', "Catcher's interference", '捕手干扰', 'キャッチャーのインターフェア'), ('Entender la interferencia del catcher: si su guante toca el bate en el swing, o estorba al bateador, el bateador gana primera base.', "Understand catcher's interference: if his glove touches the bat on the swing, or gets in the batter's way, the batter gets first base.", '明白捕手干扰：如果捕手的手套在挥棒时碰到球棒，或者妨碍了击球员，击球员就上一垒。', 'キャッチャーのインターフェアを知ろう：スイングのときにミットがバットにさわったり、バッターのじゃまをしたら、バッターは一塁へ行ける。'), [('El catcher vive pegadito al bateador, y a veces pasa esto: el bateador hace su swing y su bate roza la mascota del catcher.', "The catcher lives right next to the batter, and sometimes this happens: the batter swings and his bat brushes the catcher's mitt.", '捕手离击球员很近，有时会发生这种事：击球员挥棒，球棒擦到了捕手的手套。', 'キャッチャーはバッターのすぐそば。だから、こんなことが起きる：バッターがスイングして、バットがキャッチャーミットにふれる。'), ("Eso es interferencia del catcher, en inglés catcher's interference.", "That's catcher's interference.", "这就是捕手干扰，英语叫 catcher's interference。", "これがキャッチャーのインターフェア、英語で catcher's interference。"), ('Nadie lo hizo a propósito, pero la regla protege al que batea: si el guante estorbó el swing, el bateador va a primera base.', 'Nobody did it on purpose, but the rule protects the batter: if the glove got in the way of the swing, the batter goes to first base.', '没有人是故意的，但规则保护击球员：如果手套妨碍了挥棒，击球员就上一垒。', 'だれもわざとじゃない。でもルールはバッターを守る：ミットがスイングのじゃまをしたら、バッターは一塁へ。'), ('Por eso el catcher se coloca cerca, pero no tanto: deja el espacio justo para recibir sin tocar el bate.', "That's why the catcher sets up close, but not too close: he leaves just enough room to catch without touching the bat.", '所以捕手要靠近，但不能太近：留出刚好的空间，接球时碰不到球棒。', 'だからキャッチャーは近くにかまえるけど、近すぎない：バットにさわらずに受けられる、ちょうどいいすきまをあける。')], {'1': act(('¿Qué es la interferencia del catcher?', "What is catcher's interference?", '什么是捕手干扰？', 'キャッチャーのインターフェアって何？'), ('¡Eso es! Guante contra bate.', "That's it! Glove against bat.", '对了！手套碰球棒。', 'そのとおり！ミットとバット。'), ('Si el guante estorba el swing, hay interferencia.', 'If the glove gets in the way of the swing, there is interference.', '如果手套妨碍了挥棒，就是干扰。', 'ミットがスイングのじゃまをしたら、インターフェア。'), opts={'a': ('Su guante toca el bate o estorba el swing del bateador', "His glove touches the bat or gets in the way of the batter's swing", '他的手套碰到球棒，或者妨碍了击球员挥棒', 'ミットがバットにさわる、またはバッターのスイングのじゃまをする'), 'b': ('El catcher habla con el pitcher', 'The catcher talks with the pitcher', '捕手和投手说话', 'キャッチャーがピッチャーと話す'), 'c': ('El catcher bloquea una bola', 'The catcher blocks a ball', '捕手挡住一个球', 'キャッチャーが球をブロックする')}), '2': act(('Si hay interferencia del catcher, ¿qué gana el bateador?', "If there is catcher's interference, what does the batter get?", '如果出现捕手干扰，击球员得到什么？', 'キャッチャーのインターフェアがあったら、バッターは何をもらえる？'), ('¡Correcto! Va a primera.', 'Correct! He goes to first.', '正确！他上一垒。', '正解！一塁へ。'), ('La regla protege su swing: primera base.', 'The rule protects his swing: first base.', '规则保护他的挥棒：上一垒。', 'ルールがスイングを守る：一塁。'), opts={'a': ('Primera base', 'First base', '上一垒', '一塁'), 'b': ('Un strike menos', 'One strike less', '少一个好球', 'ストライクが1つへる'), 'c': ('Otro lanzamiento igual', 'The same pitch again', '再投一次同样的球', '同じ投球をもう一度')}), '3': act(('La interferencia del catcher siempre es a propósito', "Catcher's interference is always on purpose", '捕手干扰总是故意的', 'キャッチャーのインターフェアは、いつもわざと'), ('¡Bien! Casi nunca lo es.', 'Good! It almost never is.', '很好！几乎从来不是故意的。', 'いいね！ほとんどわざとじゃない。'), ('Falso: suele ser un roce sin querer.', "False: it's usually an accidental brush.", '错：通常是不小心擦到的。', 'まちがい：たいていは、うっかりふれただけ。')), '4': act(('¿Cómo evita el catcher la interferencia?', 'How does the catcher avoid interference?', '捕手怎样避免干扰？', 'キャッチャーはどうやってインターフェアをふせぐ？'), ('¡Eso es! Cerca, no encima.', "That's it! Close, not on top.", '对了！靠近，但不贴上去。', 'そのとおり！近いけど、くっつかない。'), ('El espacio justo: recibes sin tocar el bate.', 'Just enough room: you catch without touching the bat.', '刚好的空间：接球时碰不到球棒。', 'ちょうどいいすきま：バットにさわらずに受ける。'), opts={'a': ('Colocándose cerca, pero dejando espacio al bate', 'Setting up close, but leaving room for the bat', '靠近，但给球棒留出空间', '近くにかまえるけど、バットのすきまをあける'), 'b': ('Recibiendo desde la banca', 'Catching from the dugout', '在休息区里接球', 'ベンチから受ける'), 'c': ('Sin mascota', 'Without a mitt', '不戴手套', 'ミットなしで')}), '5': act(('El bate roza la mascota en el swing. ¿Qué pasa?', 'The bat brushes the mitt on the swing. What happens?', '挥棒时球棒擦到手套。会怎样？', 'スイングでバットがミットにふれた。どうなる？'), ('¡Bien cantado!', 'Well called!', '判得好！', 'いいコール！'), ('Roce al swing: el bateador gana primera.', 'A brush on the swing: the batter gets first.', '挥棒时擦到：击球员上一垒。', 'スイングでふれた：バッターは一塁。'), opts={'a': ('Interferencia del catcher: bateador a primera', "Catcher's interference: batter to first", '捕手干扰：击球员上一垒', 'キャッチャーのインターフェア：バッターは一塁へ'), 'b': ('Strike cantado', 'Strike called', '判好球', 'ストライクのコール'), 'c': ('Bola muerta sin castigo', 'Dead ball with no penalty', '死球（比赛停止），不处罚', 'ボールデッドで、ばつなし')}), '6': act(('Si el guante toca el bate, el bateador es out', 'If the glove touches the bat, the batter is out', '如果手套碰到球棒，击球员出局', 'ミットがバットにさわったら、バッターはアウト'), ('¡Correcto! No es out.', "Correct! He's not out.", '正确！他不出局。', '正解！アウトじゃない。'), ('Falso: es al revés, el bateador va a primera.', "False: it's the other way around, the batter goes to first.", '错：正好相反，击球员上一垒。', 'まちがい：その反対で、バッターは一塁へ行く。'))})
map_titles['13.4'] = ('La interferencia del catcher', "Catcher's interference", '捕手干扰', 'キャッチャーのインターフェア')
lesson('13.5', ('La jugada en home', 'The play at the plate', '本垒攻防', 'ホームのプレー'), ('Defender home en una jugada cerrada: recibir el tiro sobre el plato, tocar al corredor sin bloquearle el paso sin bola, y cuidar el cuerpo de los dos.', "Defend home on a close play: catch the throw at the plate, tag the runner without blocking his path when you don't have the ball, and take care of both players' bodies.", '在接杀的紧要关头守住本垒：在本垒上接传球，触杀跑垒员；没有球的时候不能挡住他的路；还要照顾好两个人的身体。', 'きわどいプレーでホームを守ろう：ホームで送球を受けて、ランナーにタッチする。ボールを持っていないときは、ランナーの道をふさがない。二人とも体を大切に。'), [('¡Viene el corredor a home y el tiro viene del jardín!', 'The runner is coming home and the throw is coming from the outfield!', '跑垒员冲向本垒，传球也从外野飞来了！', 'ランナーがホームに向かってくる。外野からの送球も来る！'), ('La jugada en home, en inglés play at the plate, es la más emocionante.', 'The play at the plate is the most exciting one.', '本垒攻防，英语叫 play at the plate，是最刺激的一幕。', 'ホームのプレー、英語で play at the plate は、いちばんドキドキするプレー。'), ('El catcher se coloca junto al plato, recibe la bola y toca al corredor con ella.', 'The catcher sets up next to the plate, catches the ball and tags the runner with it.', '捕手站在本垒旁边，接住球，再用球触碰跑垒员。', 'キャッチャーはホームのそばでかまえて、球を受けて、その球でランナーにタッチする。'), ('Pero ojo: sin la bola, no puedes tapar el plato ni bloquear el paso del corredor; primero la bola, después el toque.', "But careful: without the ball, you can't cover the plate or block the runner's path; ball first, then the tag.", '但要注意：没有球的时候，你不能挡住本垒，也不能挡住跑垒员的路；先接球，再触杀。', 'でも気をつけて：ボールを持っていないときは、ホームをかくしたり、ランナーの道をふさいだりしてはいけない。まずボール、それからタッチ。'), ('Y el corredor tampoco puede chocar contigo a propósito: los dos se cuidan.', "And the runner can't crash into you on purpose either: both take care of each other.", '跑垒员也不能故意撞你：两个人都要互相照顾。', 'それに、ランナーもわざとぶつかってはいけない：二人とも相手を大切にする。'), ('Bola, toque y ¡a esperar la decisión del umpire!', "Ball, tag, and wait for the umpire's call!", '接球、触杀，然后等裁判判决！', 'ボール、タッチ、そして審判のコールを待とう！')], {'1': act(('En la jugada en home, ¿qué necesita primero el catcher?', 'On the play at the plate, what does the catcher need first?', '在本垒攻防时，捕手首先需要什么？', 'ホームのプレーで、キャッチャーにまずひつようなのは？'), ('¡Eso es! Primero la bola.', "That's it! The ball first.", '对了！先接球。', 'そのとおり！まずボール。'), ('Sin bola no hay toque que valga.', 'Without the ball there is no tag that counts.', '没有球，触杀就不算。', 'ボールがなければ、タッチにならない。'), opts={'a': ('Recibir la bola, y después tocar al corredor', 'To catch the ball, and then tag the runner', '先接住球，再触碰跑垒员', '球を受けて、それからランナーにタッチ'), 'b': ('Tapar el plato sin bola', 'To cover the plate without the ball', '没拿球就挡住本垒', 'ボールなしでホームをかくす'), 'c': ('Gritar muy fuerte', 'To yell very loud', '大声喊叫', 'すごく大きな声を出す')}), '2': act(('El catcher puede bloquear el plato sin tener la bola', 'The catcher can block the plate without having the ball', '捕手可以在没拿到球时挡住本垒', 'キャッチャーはボールを持っていなくてもホームをふさいでいい'), ('¡Bien! Eso estorba al corredor.', "Good! That gets in the runner's way.", '很好！那会妨碍跑垒员。', 'いいね！それはランナーのじゃまになる。'), ('Falso: sin bola, no se tapa el paso.', "False: without the ball, you don't block the path.", '错：没有球，就不能挡路。', 'まちがい：ボールなしでは、道をふさがない。')), '3': act(('¿Cómo se hace el out en home?', 'How is the out made at home?', '本垒出局是怎样完成的？', 'ホームでのアウトはどうやってとる？'), ('¡Correcto! Toque con la bola.', 'Correct! A tag with the ball.', '正确！用球触杀。', '正解！ボールでタッチ。'), ('Toque limpio, antes del plato: out.', 'A clean tag, before the plate: out.', '干净的触杀，在踩本垒之前：出局。', 'ホームの前に、ちゃんとタッチ：アウト。'), opts={'a': ('Tocando al corredor con la bola antes de que toque el plato', 'Tagging the runner with the ball before he touches the plate', '在跑垒员踩到本垒之前用球触碰他', 'ランナーがホームにさわる前に、ボールでタッチする'), 'b': ('Empujando al corredor', 'Pushing the runner', '推跑垒员', 'ランナーをおす'), 'c': ('Quitándole el casco', 'Taking his helmet off', '把他的头盔摘下来', 'ヘルメットをとる')}), '4': act(('El corredor puede chocar a propósito contra el catcher', 'The runner can crash into the catcher on purpose', '跑垒员可以故意撞捕手', 'ランナーはわざとキャッチャーにぶつかってもいい'), ('¡Bien! Nadie choca a propósito.', 'Good! Nobody crashes on purpose.', '很好！谁都不能故意撞人。', 'いいね！だれもわざとぶつからない。'), ('Falso: los dos jugadores se cuidan.', 'False: both players take care of each other.', '错：两个球员要互相照顾。', 'まちがい：二人とも相手を大切にする。')), '5': act(('Toca el plato que el corredor debe pisar para anotar', 'Tap the plate the runner must touch to score', '点一下跑垒员得分必须踩的垒', 'ランナーが得点するためにふむところをタッチしよう'), ('¡Eso es! Home.', "That's it! Home.", '对了！本垒。', 'そのとおり！ホーム。'), ('Ahí se anota la carrera.', "That's where the run scores.", '在那里得分。', 'そこで得点が入る。'), answer=('Home (el plato)', 'Home (the plate)', '本垒', 'ホーム（ホームプレート）')), '6': act(('El catcher toca al corredor con la bola antes del plato. ¿Qué canta el umpire?', 'The catcher tags the runner with the ball before the plate. What does the umpire call?', '捕手在跑垒员踩本垒之前用球触碰了他。裁判怎么判？', 'キャッチャーがホームの前でボールをランナーにタッチした。審判のコールは？'), ('¡Bien! Out en home.', 'Good! Out at home.', '很好！本垒出局。', 'いいね！ホームでアウト。'), ('Toque antes del plato: out.', 'Tag before the plate: out.', '在踩本垒前触杀：出局。', 'ホームの前でタッチ：アウト。'), opts={'a': ('¡Out!', 'Out!', '出局！', 'アウト！'), 'b': ('¡Safe!', 'Safe!', '安全上垒！', 'セーフ！'), 'c': ('¡Foul!', 'Foul!', '界外球！', 'ファウル！')})})
