exams_v3['13'] = {'1': {'q': ('El catcher va a calentar con el pitcher sin careta porque «es solo calentar». ¿Está bien?', 'The catcher goes to warm up with the pitcher without a mask because "it\'s just warming up." Is that OK?', '捕手不戴面罩去和投手热身，因为“只是热身而已”。这样可以吗？', 'キャッチャーが「ただのウォーミングアップだから」とマスクなしでピッチャーと練習する。それでいい？'), 'opts': {'a': ('Sí, calentar no cuenta', "Yes, warming up doesn't count", '可以，热身不算', 'いい、ウォーミングアップは関係ない'), 'b': ('No: el equipo va completo siempre', 'No: the gear is always complete', '不行：护具永远要齐全', 'だめ：防具はいつもぜんぶ'), 'c': ('Solo si lanza suave', 'Only if he pitches softly', '只有投得很轻时才可以', 'ゆっくり投げるときだけいい')}}, '2': {'q': ('¿Qué pieza protege el pecho del catcher?', "Which piece protects the catcher's chest?", '哪件护具保护捕手的胸口？', 'キャッチャーの胸を守る防具はどれ？'), 'opts': {'a': ('El peto', 'The chest protector', '护胸', 'プロテクター'), 'b': ('Las espinilleras', 'The shin guards', '护腿', 'レガース'), 'c': ('La mascota', 'The mitt', '捕手手套', 'ミット')}}, '3': {'q': ('El catcher muestra dos dedos escondidos entre las piernas. ¿Qué está haciendo?', 'The catcher shows two fingers hidden between his legs. What is he doing?', '捕手在两腿之间藏着比出两根手指。他在做什么？', 'キャッチャーが足のあいだで指を2本かくして見せている。何をしている？'), 'opts': {'a': ('Pidiendo un lanzamiento con una seña', 'Asking for a pitch with a sign', '用暗号要一个球', 'サインで投げる球をたのんでいる'), 'b': ('Saludando al pitcher', 'Waving at the pitcher', '向投手打招呼', 'ピッチャーにあいさつしている'), 'c': ('Contando outs para él solo', 'Counting outs just for himself', '自己数出局数', '自分だけでアウトを数えている')}}, '4': {'q': ('¿Por qué las señas van escondidas?', 'Why are signs hidden?', '为什么暗号要藏起来？', 'どうしてサインはかくすの？'), 'opts': {'a': ('Para que el equipo rival no las vea', "So the other team can't see them", '为了不让对手看到', '相手チームに見られないため'), 'b': ('Para que el umpire no se enoje', "So the umpire doesn't get angry", '为了不让裁判生气', '審判がおこらないため'), 'c': ('Porque es la moda', "Because it's in style", '因为很流行', 'はやっているから')}}, '5': {'q': ('El lanzamiento pica en la tierra frente al catcher. ¿Qué técnica usa?', 'The pitch bounces in the dirt in front of the catcher. What technique does he use?', '投球在捕手面前弹地。他用什么技术？', '投球がキャッチャーの前でバウンドした。どのやり方を使う？'), 'opts': {'a': ('Bloquear: rodillas al suelo y cuerpo frente a la bola', 'Block: knees down and body in front of the ball', '挡球：跪下，身体挡在球前', 'ブロック：ひざをついて、体を球の前に'), 'b': ('Estirar una mano y rezar', 'Reach out one hand and hope', '伸出一只手碰运气', '片手をのばして、いのる'), 'c': ('Apartarse rápido', 'Step aside fast', '赶快躲开', 'すばやくよける')}}, '6': {'q': ('Una bola bien bloqueada debe quedar…', 'A well-blocked ball should end up…', '挡得好的球应该停在……', 'うまくブロックした球は……'), 'opts': {'a': ('Delante del catcher, cerquita', 'In front of the catcher, close by', '捕手前面，离得很近', 'キャッチャーの前、すぐ近く'), 'b': ('Detrás de la banca', 'Behind the dugout', '休息区后面', 'ベンチのうしろ'), 'c': ('En los jardines', 'In the outfield', '外野', '外野')}}, '7': {'q': ('El bate del bateador roza la mascota durante el swing. ¿Qué regla se aplica?', "The batter's bat brushes the mitt during the swing. Which rule applies?", '挥棒时击球员的球棒擦到手套。适用哪条规则？', 'スイングのとき、バッターのバットがミットにふれた。どのルール？'), 'opts': {'a': ('Interferencia del catcher: el bateador va a primera', "Catcher's interference: the batter goes to first", '捕手干扰：击球员上一垒', 'キャッチャーのインターフェア：バッターは一塁へ'), 'b': ('Strike para el bateador', 'Strike for the batter', '给击球员一个好球', 'バッターにストライク'), 'c': ('Nada, sigue todo igual', 'Nothing, everything stays the same', '没事，一切照旧', '何もなし、そのまま')}}, '8': {'q': ('¿Cómo se coloca el catcher para evitar su interferencia?', 'How does the catcher set up to avoid his interference?', '捕手怎样站位来避免干扰？', 'インターフェアをふせぐために、キャッチャーはどうかまえる？'), 'opts': {'a': ('Cerca, pero dejando espacio al bate', 'Close, but leaving room for the bat', '靠近，但给球棒留出空间', '近くで、でもバットのすきまをあける'), 'b': ('Pegado al bateador', 'Right up against the batter', '紧贴着击球员', 'バッターにくっつく'), 'c': ('Muy lejos de home', 'Very far from home', '离本垒很远', 'ホームからすごく遠く')}}, '9': {'q': ('En la jugada en home, el catcher todavía no tiene la bola. ¿Qué no puede hacer?', "On the play at the plate, the catcher doesn't have the ball yet. What can't he do?", '本垒攻防时，捕手还没拿到球。他不能做什么？', 'ホームのプレーで、キャッチャーはまだボールを持っていない。してはいけないのは？'), 'opts': {'a': ('Bloquear el plato y tapar el paso del corredor', "Block the plate and the runner's path", '挡住本垒和跑垒员的路', 'ホームとランナーの道をふさぐ'), 'b': ('Esperar junto al plato', 'Wait next to the plate', '在本垒旁边等', 'ホームのそばで待つ'), 'c': ('Pedir el tiro en voz alta', 'Call for the throw out loud', '大声要传球', '大きな声で送球をよぶ')}}, '10': {'q': ('El catcher recibe el tiro y toca al corredor antes del plato. ¿Resultado?', 'The catcher catches the throw and tags the runner before the plate. Result?', '捕手接到传球，在跑垒员踩本垒之前触杀了他。结果是？', 'キャッチャーが送球を受けて、ホームの前でランナーにタッチした。結果は？'), 'opts': {'a': ('Out', 'Out', '出局', 'アウト'), 'b': ('Safe', 'Safe', '安全上垒', 'セーフ'), 'c': ('Foul', 'Foul', '界外球', 'ファウル')}}, '11': {'q': ('El corredor viene a home buscando chocar al catcher a propósito. ¿Eso se vale?', 'The runner comes home trying to crash into the catcher on purpose. Is that allowed?', '跑垒员冲回本垒，想故意撞捕手。这样可以吗？', 'ランナーがわざとキャッチャーにぶつかろうとホームに来る。それはいい？'), 'opts': {'a': ('No: los dos jugadores se cuidan', 'No: both players take care of each other', '不行：两个球员要互相照顾', 'だめ：二人とも相手を大切にする'), 'b': ('Sí, es parte del juego', "Yes, it's part of the game", '可以，这是比赛的一部分', 'いい、それも野球'), 'c': ('Solo si va perdiendo', 'Only if his team is losing', '只有输球时才可以', '負けているときだけいい')}}, '12': {'q': ('¿Cómo se llama el guante grande y acolchado del catcher?', "What is the catcher's big, padded glove called?", '捕手又大又厚的手套叫什么？', 'キャッチャーの大きくてぶあついグラブは何という？'), 'opts': {'a': ("Mascota (catcher's mitt)", "Catcher's mitt", "捕手手套（catcher's mitt）", "キャッチャーミット（catcher's mitt）"), 'b': ('Peto', 'Chest protector', '护胸', 'プロテクター'), 'c': ('Carril', 'Lane', '通道', 'レーン')}}}
