levels['15'] = dict(title=('Los jardines', 'The outfield', '外野', '外野'), badge=('Halcón de los Jardines', 'Outfield Hawk', '外野雄鹰', '外野のタカ'))
lesson('15.1', ('El primer paso: hacia atrás', 'The first step: backwards', '第一步：向后', '第一歩は後ろ'), ('Entender que ante un batazo alto o profundo, el primer paso del jardinero va hacia atrás, para no quedar corto; la bola que cae delante se alcanza corriendo, la que pasa por encima, no.', "Understand that on a high or deep hit, the outfielder's first step goes back, so he doesn't come up short; the ball that drops in front can be reached running, the one that goes over his head can't.", '明白遇到又高又远的击球时，外野手的第一步要向后，才不会判断不足；落在前面的球可以跑过去接到，从头顶飞过去的就接不到了。', '高くて深い打球では、外野手の第一歩は後ろ。そうすれば足りなくならない。前に落ちる球は走ればとれるけど、頭の上をこえた球はとれない。'), [('En los jardines hay una regla de oro: tu primer paso va hacia atrás, en inglés first step back.', "In the outfield there's a golden rule: your first step goes back.", '外野有一条黄金规则：第一步后退，英语叫 first step back。', '外野には金のルールがある：第一歩は後ろ、英語で first step back。'), ('Cuando la bola sale alta y lejos, si das un paso hacia adelante y la bola te pasa por encima, ya no la alcanzas nunca.', 'When the ball goes up high and far, if you take a step forward and the ball goes over your head, you never catch up to it.', '当球又高又远地飞出去时，如果你往前迈一步，球却从你头顶飞过，你就再也追不上了。', 'ボールが高く遠くへ飛んだとき、前に一歩出て頭の上をこされたら、もうぜったい追いつけない。'), ('Pero si tu primer paso va atrás, la bola que cae delante la persigues corriendo y llegas.', 'But if your first step goes back and the ball drops in front of you, you can run in and get to it.', '但如果你第一步后退，落在前面的球你可以跑上去，赶得到。', 'でも第一歩が後ろなら、前に落ちる球は走って追いかけて、まにあう。'), ('Atrás primero, y después ajustas.', 'Back first, and then you adjust.', '先后退，再调整。', 'まず後ろ、それから合わせる。'), ('Es mejor correr hacia adelante que mirar cómo la bola cae detrás de ti.', "It's better to run forward than to watch the ball drop behind you.", '往前跑，总比眼睁睁看着球落在身后好。', 'ボールが後ろに落ちるのを見ているより、前に走るほうがいい。')], {'1': act(('¿Hacia dónde va el primer paso del jardinero ante un batazo alto?', "Where does the outfielder's first step go on a high hit?", '遇到高飞的击球，外野手的第一步往哪里？', '高い打球で、外野手の第一歩はどっち？'), ('¡Eso es! Atrás primero.', "That's it! Back first.", '对了！先后退。', 'そのとおり！まず後ろ。'), ('La que cae delante se alcanza; la que pasa, no.', "The one that drops in front can be reached; the one that goes over can't.", '落在前面的接得到；飞过去的接不到。', '前に落ちるのはとれる。こえた球はとれない。'), opts={'a': ('Hacia atrás', 'Backwards', '向后', '後ろ'), 'b': ('Hacia adelante siempre', 'Always forward', '总是向前', 'いつも前'), 'c': ('Hacia la banca', 'Toward the dugout', '朝休息区', 'ベンチのほう')}), '2': act(('Si el jardinero da su primer paso hacia adelante y la bola le pasa por encima, todavía puede alcanzarla corriendo hacia atrás', 'If the outfielder takes his first step forward and the ball goes over his head, he can still reach it running backwards', '如果外野手第一步往前跨，球又从他头顶飞过，他往后跑还能追到', '外野手が最初の一歩を前にふみ出して、ボールが頭の上をこえても、後ろに走ればまだとれる'), ('¡Bien! Casi nunca se alcanza.', 'Good! He almost never catches up to it.', '很好！几乎追不到。', 'いいね！ほとんどとれない。'), ('Falso: por eso el primer paso va atrás.', "False: that's why the first step goes back.", '错：所以第一步要后退。', 'まちがい：だから第一歩は後ろなんだ。')), '3': act(('¿Qué bola sí puedes alcanzar?', 'Which ball can you reach?', '哪种球你能接到？', 'どの球ならとれる？'), ('¡Correcto! La de delante.', 'Correct! The one in front.', '正确！前面的那个。', '正解！前の球。'), ('Corres hacia adelante y la buscas.', 'You run forward and go get it.', '你往前跑去接它。', '前に走って、とりにいく。'), opts={'a': ('La que cae delante de ti', 'The one that drops in front of you', '落在你前面的球', '前に落ちる球'), 'b': ('La que ya salió del campo', 'The one that already left the field', '已经飞出场外的球', 'もう場外に出た球'), 'c': ('La que pasó muy por encima', 'The one that went way over your head', '从你头顶高高飞过的球', '頭のずっと上をこえた球')}), '4': act(('¿Cuál imagen muestra el buen primer paso?', 'Which picture shows the good first step?', '哪张图是正确的第一步？', 'いい第一歩はどの絵？'), ('¡Eso es! Ese llega.', "That's it! That one gets there.", '对了！这个能赶到。', 'そのとおり！この選手はまにあう。'), ('Primero atrás, después a la bola.', 'First back, then to the ball.', '先后退，再去追球。', 'まず後ろ、それからボールへ。'), opts={'a': ('Jardinero girando hacia atrás al salir el batazo', 'Outfielder turning back as the ball is hit', '球一被击出，外野手就转身向后', '打球が出たしゅんかん、後ろを向く外野手'), 'b': ('Jardinero entrando hacia el cuadro', 'Outfielder coming in toward the infield', '朝内野跑过来的外野手', '内野のほうに入ってくる外野手'), 'c': ('Jardinero parado esperando', 'Outfielder standing still waiting', '站着不动等待的外野手', 'じっと立って待つ外野手')}), '5': act(('¿Cuándo decides tu primer paso?', 'When do you decide your first step?', '什么时候决定第一步？', '第一歩はいつ決める？'), ('¡Correcto! Al instante.', 'Correct! Instantly.', '正确！马上。', '正解！すぐに。'), ('Leer rápido es la mitad de la atrapada.', 'Reading fast is half the catch.', '判断得快，就成功了一半。', 'すばやく読むのが、キャッチの半分。'), opts={'a': ('Apenas sale el batazo, leyendo su altura', 'As soon as the ball is hit, reading how high it goes', '球一被击出，就看它有多高', '打球が出たらすぐ、高さを読んで'), 'b': ('Cuando la bola ya cayó', 'When the ball has already landed', '球已经落地时', 'ボールがもう落ちたとき'), 'c': ('Cuando el coach grita tarde', 'When the coach yells late', '教练很晚才喊的时候', 'コーチがおそくさけんだとき')}), '6': act(('El primer paso hacia atrás también sirve para bolas que caen cortitas', 'The first step back also works for balls that drop short', '第一步后退，对落得比较近的球也适用', '第一歩を後ろにするのは、短く落ちる球にも使える'), ('¡Bien! Ajustas hacia adelante.', 'Good! You adjust forward.', '很好！再往前调整。', 'いいね！前に合わせる。'), ('Verdadero: atrás primero y ajustas corriendo hacia adelante.', 'True: back first and you adjust running forward.', '对：先后退，再往前跑调整。', '正しい：まず後ろ、それから前に走って合わせる。'))})
map_titles['15.1'] = ('El primer paso: hacia atrás', 'The first step: backwards', '第一步：向后', '第一歩は後ろ')
lesson('15.2', ('¿De quién es el elevado? La prioridad del centro', "Whose fly ball is it? The center's priority", '高飞球归谁？中外野的优先权', 'フライはだれのもの？センターの優先権'), ('Entender la prioridad en los jardines: el jardinero central (center fielder) manda en el medio; si él pide la bola, los jardineros de las esquinas ceden y respaldan.', 'Understand priority in the outfield: the center fielder is in charge of the middle; if he calls for the ball, the corner outfielders give way and back up.', '明白外野的优先权：中外野手（center fielder）负责中间区域；他喊着要球，左右两边的外野手就让开并补位。', '外野の優先権を知ろう：センター（center fielder）がまんなかのリーダー。センターがコールしたら、左右の外野手はゆずってバックアップする。'), [('En el Nivel 14 aprendiste a gritar «¡Mía!»; es repaso.', 'In Level 14 you learned to yell "Mine!"; this is review.', '在第 14 级你学会了喊“我接！”；这是复习。', 'レベル14で「オーライ！」のコールをならったね。これはふくしゅう。'), ('Ahora, ¿quién gana cuando dos jardineros pueden llegar?', 'Now, who wins when two outfielders can get there?', '那么，如果两个外野手都能赶到，谁说了算？', 'では、二人の外野手がとどきそうなとき、勝つのはだれ？'), ('Manda el jardinero central, en inglés center fielder: él ve todo el campo de frente y cubre el medio.', 'The center fielder is in charge: he sees the whole field in front of him and covers the middle.', '中外野手说了算，英语叫 center fielder：他能正面看到整个球场，负责中间。', 'センター、英語で center fielder がリーダー：グラウンドぜんぶを正面から見て、まんなかを守る。'), ('Si el central pide la bola, los jardineros izquierdo y derecho ceden, se apartan y respaldan.', 'If the center fielder calls for the ball, the left and right fielders give way, step aside and back up.', '如果中外野手喊着要球，左外野手和右外野手就让开，退到一边补位。', 'センターがコールしたら、レフトとライトはゆずって、どいて、バックアップする。'), ('Se llama prioridad, en inglés priority.', "It's called priority.", '这叫优先权，英语叫 priority。', 'これを優先権、英語で priority という。'), ('Una sola voz manda en el medio, y es la del centro.', "Only one voice is in charge in the middle, and it's the center fielder's.", '中间只有一个声音说了算，那就是中外野手的声音。', 'まんなかでは、声は1つだけ。それはセンターの声。')], {'1': act(('¿Quién manda en los elevados del medio de los jardines?', 'Who is in charge of the fly balls in the middle of the outfield?', '外野中间的高飞球由谁负责？', '外野のまんなかのフライは、だれがリーダー？'), ('¡Eso es! Manda el centro.', "That's it! The center is in charge.", '对了！中外野说了算。', 'そのとおり！センターがリーダー。'), ('Él ve todo de frente: su palabra manda.', 'He sees everything in front of him: his word rules.', '他能正面看到一切：他说了算。', '正面からぜんぶ見える：センターの声が決める。'), opts={'a': ('El jardinero central', 'The center fielder', '中外野手', 'センター'), 'b': ('El jardinero derecho siempre', 'Always the right fielder', '总是右外野手', 'いつもライト'), 'c': ('El más alto del equipo', 'The tallest player on the team', '队里最高的球员', 'チームでいちばん背の高い選手')}), '2': act(('El central grita «¡Mía!». ¿Qué hace el jardinero izquierdo?', 'The center fielder yells "Mine!". What does the left fielder do?', '中外野手喊“我接！”。左外野手怎么做？', 'センターが「オーライ！」とさけんだ。レフトはどうする？'), ('¡Correcto! Ceder y respaldar.', 'Correct! Give way and back up.', '正确！让开并补位。', '正解！ゆずってバックアップ。'), ('Sin choques y con respaldo, como siempre.', 'No crashes and with backup, as always.', '不撞人，还有人补位，跟平常一样。', 'ぶつからないで、バックアップも。いつもどおり。'), opts={'a': ('Cede, se aparta y respalda', 'He gives way, steps aside and backs up', '让开，退到一边补位', 'ゆずって、どいて、バックアップ'), 'b': ('Sigue corriendo igual', 'He keeps running the same way', '照样继续跑', 'そのまま走りつづける'), 'c': ('Se queda parado mirando', 'He stands still watching', '站着不动看', 'じっと立って見ている')}), '3': act(('La prioridad del central significa que él atrapa todas las bolas de los jardines', "The center fielder's priority means he catches every ball in the outfield", '中外野手的优先权，意思是外野所有的球都由他接', 'センターの優先権とは、外野のボールをぜんぶセンターがとること'), ('¡Bien! Solo manda en las dudosas.', 'Good! He only rules the doubtful ones.', '很好！他只负责拿不准的球。', 'いいね！まよう球だけを決める。'), ('Falso: cada quien atrapa las suyas; el central decide las del medio.', 'False: each one catches his own; the center decides the ones in the middle.', '错：每个人接自己的球；中间的由中外野手决定。', 'まちがい：自分の球はそれぞれがとる。まんなかの球はセンターが決める。')), '4': act(('¿Por qué manda el jardinero central?', 'Why is the center fielder in charge?', '为什么由中外野手说了算？', 'どうしてセンターがリーダーなの？'), ('¡Eso es! Su vista manda.', "That's it! His view is in charge.", '对了！他的视野说了算。', 'そのとおり！見えるからリーダー。'), ('De frente se lee mejor la bola.', 'From in front you read the ball better.', '从正面更容易判断球。', '正面からのほうが、ボールがよく読める。'), opts={'a': ('Porque ve todo el campo de frente y cubre el medio', 'Because he sees the whole field in front of him and covers the middle', '因为他能正面看到整个球场，负责中间', 'グラウンドぜんぶを正面から見て、まんなかを守るから'), 'b': ('Porque batea mejor', 'Because he hits better', '因为他打得更好', 'いちばん打つのがうまいから'), 'c': ('Porque es el capitán', "Because he's the captain", '因为他是队长', 'キャプテンだから')}), '5': act(('Toca la posición del jardinero que manda en el medio', 'Tap the position of the outfielder who is in charge of the middle', '点一下负责中间的外野手的位置', 'まんなかのリーダーの外野手のポジションをタッチしよう'), ('¡Bien! El 8.', 'Good! Number 8.', '很好！8 号。', 'いいね！8番。'), ('Centro del jardín: el general de afuera.', 'Center of the outfield: the general out there.', '外野正中间：外面的指挥官。', '外野のまんなか：外の司令官。'), answer=('Jardinero central (8)', 'Center fielder (8)', '中外野手（8）', 'センター（8）')), '6': act(('Si nadie pide una bola entre dos jardineros, es más seguro que caiga', "If nobody calls a ball between two outfielders, it's safer to let it drop", '如果两个外野手之间的球没人喊，让它掉下来更安全', '二人の外野手のあいだの球をだれもコールしなければ、落とすほうが安全'), ('¡Correcto! Alguien debe pedirla.', 'Correct! Someone has to call it.', '正确！一定要有人喊。', '正解！だれかがコールしなきゃ。'), ('Falso: sin voz hay choque o bola caída.', "False: with no voice there's a crash or a dropped ball.", '错：没人喊，不是撞在一起就是球掉了。', 'まちがい：声がないと、ぶつかるか、ボールが落ちる。'))})
map_titles['15.2'] = ('¿De quién es el elevado? La prioridad del centro', "Whose fly ball is it? The center's priority", '高飞球归谁？中外野的优先权', 'フライはだれのもの？センターの優先権')
lesson('15.3', ('Atrapada de verdad o bola de pique', 'A real catch or a trap', '真接杀还是弹跳接球', 'ほんとうのキャッチか、ワンバウンドか'), ('Distinguir la atrapada legal (la bola queda segura en el guante o la mano sin tocar el suelo) de la bola de pique (la bola toca el suelo antes o a la vez), que no es atrapada y no hace out.', "Tell apart the legal catch (the ball stays secure in the glove or hand without touching the ground) from the trap (the ball touches the ground before or at the same time), which isn't a catch and doesn't make an out.", '分清合法的接杀（球稳稳留在手套或手里，没有碰到地面）和弹跳接球（球先碰地，或同时碰地）：弹跳接球不算接住，不会让击球员出局。', 'ルールどおりのキャッチ（ボールが地面にふれずに、グラブや手にしっかり入る）と、ワンバウンド捕球（先に、または同時に地面にふれる）を見分けよう。ワンバウンド捕球はキャッチじゃないから、アウトにならない。'), [('El jardinero se lanza, la bola entra al guante… pero antes rozó el pasto.', 'The outfielder dives, the ball goes into the glove… but first it brushed the grass.', '外野手飞扑过去，球进了手套……可是之前擦到了草地。', '外野手がとびこんで、ボールがグラブに入る……でも、その前に芝にふれていた。'), ('¿Out o no?', 'Out or not?', '出局还是不出局？', 'アウト？それとも？'), ('Aquí está la diferencia: atrapada, en inglés catch, es cuando la bola queda segura en tu guante o en tu mano sin haber tocado el suelo.', "Here's the difference: a catch is when the ball stays secure in your glove or your hand without having touched the ground.", '区别在这里：接杀，英语叫 catch，就是球稳稳留在你的手套或手里，而且没有碰过地面。', 'ちがいはここ：キャッチ、英語で catch は、地面にふれずに、ボールがグラブや手にしっかり入ること。'), ('Si la bola toca el suelo antes o al mismo tiempo, aunque después quede en tu guante, es una bola de pique, en inglés trap, y no es atrapada: el bateador no es out por esa jugada.', "If the ball touches the ground before or at the same time, even if it ends up in your glove afterward, it's a trap, and it's not a catch: the batter isn't out on that play.", '如果球先碰到地面或同时碰地，就算之后留在你的手套里，也是弹跳接球，英语叫 trap，不算接杀：击球员不会因为这一球出局。', 'ボールが先に、または同時に地面にふれたら、あとでグラブに入っても、ワンバウンド捕球、英語で trap。キャッチじゃない：そのプレーでバッターはアウトにならない。'), ('El umpire mira una sola cosa: ¿tocó el suelo o no?', 'The umpire looks at just one thing: did it touch the ground or not?', '裁判只看一件事：球有没有碰到地面？', '審判が見るのは1つだけ：地面にふれた？ふれていない？')], {'1': act(('¿Qué es una atrapada (catch) de verdad?', 'What is a real catch?', '什么是真正的接杀（catch）？', 'ほんとうのキャッチ（catch）って何？'), ('¡Eso es! Sin tocar el suelo.', "That's it! Without touching the ground.", '对了！没碰到地面。', 'そのとおり！地面にふれずに。'), ('Segura y sin picar: atrapada.', 'Secure and without bouncing: a catch.', '稳稳的，没弹地：就是接杀。', 'しっかり、はずまずに：キャッチ。'), opts={'a': ('La bola queda segura en el guante o la mano sin tocar el suelo', 'The ball stays secure in the glove or hand without touching the ground', '球稳稳留在手套或手里，没碰到地面', 'ボールが地面にふれずに、グラブや手にしっかり入る'), 'b': ('La bola pica y luego entra al guante', 'The ball bounces and then goes into the glove', '球先弹地，再进手套', 'ボールがはずんでからグラブに入る'), 'c': ('La bola queda bajo el cuerpo', 'The ball ends up under your body', '球压在身体下面', 'ボールが体の下にある')}), '2': act(('La bola rozó el pasto y después quedó en el guante. ¿Qué es?', 'The ball brushed the grass and then stayed in the glove. What is it?', '球擦到草地，然后留在手套里。这是什么？', 'ボールが芝にふれて、それからグラブに入った。これは？'), ('¡Correcto! De pique.', 'Correct! A trap.', '正确！弹跳接球。', '正解！ワンバウンド捕球。'), ('Tocó el suelo: no cuenta como atrapada.', "It touched the ground: it doesn't count as a catch.", '碰到地面了：不算接杀。', '地面にふれた：キャッチにならない。'), opts={'a': ('Una bola de pique (trap): no es atrapada', "A trap: it's not a catch", '弹跳接球（trap）：不算接杀', 'ワンバウンド捕球（trap）：キャッチじゃない'), 'b': ('Una atrapada legal', 'A legal catch', '合法的接杀', 'ルールどおりのキャッチ'), 'c': ('Un jonrón', 'A home run', '本垒打', 'ホームラン')}), '3': act(('Con una bola de pique, el bateador es out igual porque la bola terminó en el guante', 'With a trap, the batter is out anyway because the ball ended up in the glove', '弹跳接球时，因为球最后在手套里，击球员照样出局', 'ワンバウンド捕球でも、ボールがグラブにあるからバッターはアウト'), ('¡Bien! No es out por atrapada.', "Good! A trap isn't an out.", '很好！不会因为接杀出局。', 'いいね！キャッチのアウトにはならない。'), ('Falso: la bola sigue en juego y hay que jugarla.', 'False: the ball is still in play and you have to play it.', '错：球还在比赛中，要继续处理。', 'まちがい：ボールはまだプレー中。プレーをつづけよう。')), '4': act(('Si la bola fue de pique, ¿qué debe hacer el jardinero?', 'If there is a trap, what should the outfielder do?', '如果是弹跳接球，外野手该怎么做？', 'ワンバウンド捕球のとき、外野手はどうする？'), ('¡Eso es! La jugada sigue.', "That's it! The play goes on.", '对了！比赛继续。', 'そのとおり！プレーはつづく。'), ('Nada de celebrar: bola viva, a tirar.', 'No celebrating: live ball, throw it.', '别庆祝：活球，快传。', 'よろこぶのはなし：インプレー、投げよう。'), opts={'a': ('Recoger la bola y tirar rápido a una base', 'Pick up the ball and throw fast to a base', '捡起球，快速传向一个垒', 'ボールを拾って、すばやく塁へ投げる'), 'b': ('Quedarse celebrando', 'Stay there celebrating', '在那里庆祝', 'その場でよろこぶ'), 'c': ('Mostrar el guante al público', 'Show the glove to the crowd', '把手套给观众看', 'お客さんにグラブを見せる')}), '5': act(('Bola que pica antes de entrar al guante del jardinero. ¿Qué decide el umpire?', "A ball that bounces before going into the outfielder's glove. What does the umpire decide?", '球在进入外野手手套之前弹地了。裁判怎么判？', '外野手のグラブに入る前にはずんだボール。審判の判定は？'), ('¡Bien decidido!', 'Well decided!', '判得好！', 'いい判定！'), ('Picó primero: sigue el juego.', 'It bounced first: the game goes on.', '先弹地了：比赛继续。', '先にはずんだ：試合はつづく。'), opts={'a': ('No es atrapada: bola en juego', "It's not a catch: ball in play", '不算接杀：球继续比赛', 'キャッチじゃない：ボールはプレー中'), 'b': ('Out del bateador', "The batter's out", '击球员出局', 'バッターアウト'), 'c': ('Foul', 'Foul', '界外球', 'ファウル')}), '6': act(('Para que sea atrapada, la bola puede rebotar una vez en el suelo si el guante la cubre', 'For it to be a catch, the ball can bounce once on the ground if the glove covers it', '只要手套盖住球，球在地上弹一下也算接杀', 'グラブでおおえば、ボールが地面で1回はずんでもキャッチになる'), ('¡Correcto! Ni un rebote.', 'Correct! Not even one bounce.', '正确！一次都不能弹。', '正解！1回もはずんじゃだめ。'), ('Falso: si toca el suelo una sola vez, ya es de pique.', "False: one touch of the ground and it's already a trap.", '错：只要碰一下地面，就是弹跳接球。', 'まちがい：地面に1回ふれたら、もうワンバウンド捕球。'))})
map_titles['15.3'] = ('Atrapada de verdad o bola de pique', 'A real catch or a trap', '真接杀还是弹跳接球', 'ほんとうのキャッチか、ワンバウンドか')
lesson('15.4', ('Dejar la bola adelante y la pista de advertencia', 'Keeping the ball in front and the warning track', '把球留在身前和警戒区', 'ボールを前に止める、ウォーニングトラック'), ('Jugar la bola de modo que siempre quede delante del jardinero, y conocer la pista de advertencia (warning track): la franja junto a la valla que avisa con los pies que la pared está cerca.', 'Play the ball so it always stays in front of the outfielder, and know the warning track: the strip next to the fence that lets your feet know the wall is close.', '处理球时让它永远留在外野手身前，并认识警戒区（warning track）：围墙旁边的那条地带，让你的脚感觉到墙就在附近。', 'ボールがいつも外野手の前にあるようにプレーしよう。それから、ウォーニングトラック（warning track）を知ろう：フェンスのそばの帯で、かべが近いことを足で知らせてくれる。'), [('Dos secretos de los jardines.', 'Two secrets of the outfield.', '外野的两个秘诀。', '外野のひみつを2つ。'), ('Primero: deja la bola adelante.', 'First: keep the ball in front.', '第一：把球留在身前。', '1つ目：ボールを前に止める。'), ('Si un batazo pica delante de ti, recógelo tranquilo; si te pasa por el lado o por encima, los corredores corren y corren.', 'If a hit bounces in front of you, pick it up calmly; if it gets past you on the side or over your head, the runners run and run.', '如果击球在你前面弹地，就冷静地捡起来；如果从你旁边或头顶过去，跑垒员就会一直跑。', '打球が前でバウンドしたら、落ちついて拾う。横や頭の上をぬけたら、ランナーはどんどん走る。'), ('Por eso, ante la duda, se juega un paso más atrás.', "That's why, when in doubt, you play a step farther back.", '所以，拿不准的时候，就多退一步。', 'だから、まよったら一歩後ろで守る。'), ('Segundo: junto a la valla hay una franja de tierra distinta, la pista de advertencia, en inglés warning track.', "Second: next to the fence there's a strip of different dirt, the warning track.", '第二：围墙旁边有一条不一样的土地带，叫警戒区，英语叫 warning track。', '2つ目：フェンスのそばに、ちがう土の帯がある。ウォーニングトラック、英語で warning track。'), ('Cuando tus pies la sienten, la valla está cerquita: atrapa con cuidado y no choques contra la pared.', "When your feet feel it, the fence is very close: catch carefully and don't crash into the wall.", '当你的脚感觉到它，围墙就很近了：小心接球，别撞到墙上。', '足で感じたら、フェンスはすぐそこ：気をつけてとって、かべにぶつからないように。')], {'1': act(('¿Por qué el jardinero juega un paso más atrás ante la duda?', 'Why does the outfielder play a step farther back when in doubt?', '为什么拿不准时外野手要多退一步？', 'まようとき、外野手はどうして一歩後ろで守るの？'), ('¡Eso es! Bola adelante, jugada viva.', "That's it! Ball in front, play alive.", '对了！把球留在身前，比赛还有机会。', 'そのとおり！ボールを前に止めれば、プレーはつづく。'), ('La bola que te pasa vale muchas bases.', 'The ball that gets past you is worth many bases.', '从你身边漏过去的球会让对方跑好几个垒。', 'ぬけた球は、何個も塁をあげてしまう。'), opts={'a': ('Para que la bola quede siempre delante de él', 'So the ball always stays in front of him', '让球永远留在他身前', 'ボールがいつも前にあるように'), 'b': ('Para estar cerca de la banca', 'To be close to the dugout', '为了离休息区近一点', 'ベンチに近くいるため'), 'c': ('Para descansar', 'To rest', '为了休息', '休むため')}), '2': act(('¿Qué es la pista de advertencia (warning track)?', 'What is the warning track?', '什么是警戒区（warning track）？', 'ウォーニングトラック（warning track）って何？'), ('¡Correcto! Tus pies la sienten.', 'Correct! Your feet feel it.', '正确！你的脚感觉得到。', '正解！足で感じる。'), ('Tierra distinta bajo los pies: la valla está cerca.', 'Different dirt underfoot: the fence is close.', '脚下的土不一样了：围墙很近。', '足もとの土がかわった：フェンスが近い。'), opts={'a': ('La franja junto a la valla que avisa que la pared está cerca', 'The strip next to the fence that warns you the wall is close', '围墙旁边提醒你墙很近的那条地带', 'かべが近いことを知らせる、フェンスのそばの帯'), 'b': ('La línea de foul', 'The foul line', '界外线', 'ファウルライン'), 'c': ('El círculo de espera', 'The on-deck circle', '待打区', 'ネクストバッターズサークル')}), '3': act(('La pista de advertencia está en el medio de los jardines', 'The warning track is in the middle of the outfield', '警戒区在外野的正中间', 'ウォーニングトラックは外野のまんなかにある'), ('¡Bien! Está junto a la valla.', "Good! It's next to the fence.", '很好！它在围墙旁边。', 'いいね！フェンスのそば。'), ('Falso: bordea todo el jardín, pegada a la pared.', 'False: it runs along the whole outfield, right by the wall.', '错：它沿着整个外野，紧挨着墙。', 'まちがい：外野ぜんぶにそって、かべのすぐそばにある。')), '4': act(('¿Cómo notas la pista de advertencia sin mirar abajo?', 'How do you notice the warning track without looking down?', '不往下看，怎么知道到了警戒区？', '下を見ないで、ウォーニングトラックにどう気づく？'), ('¡Eso es! Se siente con los pies.', "That's it! You feel it with your feet.", '对了！用脚感觉。', 'そのとおり！足で感じる。'), ('Así miras la bola y no el suelo.', 'That way you watch the ball and not the ground.', '这样你就能看着球，而不是看地面。', 'そうすれば、地面じゃなくボールを見ていられる。'), opts={'a': ('Los pies sienten un suelo distinto al pasto', 'Your feet feel ground different from the grass', '脚感觉到和草地不一样的地面', '足が芝とちがう地面を感じる'), 'b': ('Suena una alarma', 'An alarm goes off', '会响警报', 'ブザーが鳴る'), 'c': ('El coach grita siempre', 'The coach always yells', '教练总会喊', 'コーチがいつもさけぶ')}), '5': act(('Cuando sientes la pista de advertencia, debes correr más fuerte hacia la valla', 'When you feel the warning track, you should run harder toward the fence', '感觉到警戒区时，你应该更用力地冲向围墙', 'ウォーニングトラックを感じたら、フェンスに向かってもっと強く走る'), ('¡Correcto! Es aviso de cuidado.', "Correct! It's a warning to be careful.", '正确！这是提醒你要小心。', '正解！気をつけてのサインだ。'), ('Falso: te avisa para que no choques.', "False: it warns you so you don't crash.", '错：它提醒你别撞上去。', 'まちがい：ぶつからないように知らせてくれる。')), '6': act(('Toca la franja de tierra que te avisa que ya vas a chocar con la valla', "Tap the strip of dirt that warns you you're about to hit the fence", '点一下那条提醒你快要撞到围墙的土地带', 'もうすぐフェンスにぶつかるよと知らせる土のところをタッチしよう'), ('¡Bien! Ahí mismo.', 'Good! Right there.', '很好！就在那里。', 'いいね！そこだ。'), ('Pegada a la valla, todo alrededor del jardín.', 'Right by the fence, all around the outfield.', '紧挨着围墙，绕着整个外野。', 'フェンスのすぐそば、外野ぜんぶにそって。'), answer=('La pista de advertencia, junto a la valla', 'The warning track, next to the fence', '警戒区，在围墙旁边', 'ウォーニングトラック、フェンスのそば'))})
map_titles['15.4'] = ('Dejar la bola adelante y la pista de advertencia', 'Keeping the ball in front and the warning track', '把球留在身前和警戒区', 'ボールを前に止める、ウォーニングトラック')
lesson('15.5', ('Jugar con el sol de frente', 'Playing with the sun in your face', '迎着太阳接球', '太陽が正面のとき'), ('Atrapar elevados con sol de frente: usar el guante como visera sin tapar la bola, ponerse de lado cuando se puede y pedir ayuda con la voz si se pierde la bola.', 'Catch fly balls with the sun in your face: use the glove as a visor without covering the ball, turn a little sideways when you can, and ask for help out loud if you lose the ball.', '迎着太阳接高飞球：把手套当成遮阳板，但别挡住球；能侧身就侧一点；如果看不到球，就大声求助。', '太陽が正面のときのフライをとろう：グラブをひさしにして日差しを遮る、でもボールはかくさない。できたら少し横を向く。ボールを見うしなったら、大きな声で助けをもとめる。'), [('Hay elevados traicioneros: los que vienen con el sol de frente.', 'Some fly balls are tricky: the ones that come with the sun in your face.', '有些高飞球很狡猾：就是迎着太阳飞来的那些。', 'いじわるなフライがある：太陽が正面にあるときのフライだ。'), ('El truco de los jardineros: sube el guante y úsalo como visera, en inglés visor, para tapar el sol sin tapar la bola; la bola se mira por un ladito del guante.', "The outfielders' trick: raise your glove and use it as a visor, to block the sun without blocking the ball; you watch the ball just past the side of the glove.", '外野手的诀窍：举起手套当遮阳板，英语叫 visor，用手套遮阳，但不要挡住球；从手套旁边看球。', '外野手のコツ：グラブを上げてひさし、英語で visor にする。グラブで日差しを遮るけど、ボールはかくさない。ボールはグラブの横から見る。'), ('Si puedes, colócate un poco de lado para que el sol no te dé de lleno.', "If you can, stand a little sideways so the sun doesn't hit you straight on.", '如果可以，稍微侧过身子，别让阳光正面照着你。', 'できたら、少し横を向いて、日差しを正面から受けないようにする。'), ('Y si pierdes la bola en el brillo, dilo en voz alta: tu compañero puede respaldarte.', 'And if you lose the ball in the glare, say it out loud: your teammate can back you up.', '如果你在强光中看不到球，就大声说出来：你的队友可以帮你补位。', 'まぶしくてボールを見うしなったら、大きな声で言おう：仲間がバックアップしてくれる。'), ('Perderla en silencio es el único error de verdad.', 'Losing it in silence is the only real mistake.', '默不作声地丢了球，才是真正的错误。', 'だまって見うしなうことだけが、ほんとうのミスだ。')], {'1': act(('¿Qué usas como visera contra el sol?', 'What do you use as a visor against the sun?', '你用什么当遮阳板来挡太阳？', '太陽よけのひさしに何を使う？'), ('¡Eso es! Guante de visera.', "That's it! Glove as a visor.", '对了！手套当遮阳板。', 'そのとおり！グラブがひさし。'), ('Tapas el sol y la bola se ve por el lado.', 'You block the sun and see the ball from the side.', '挡住太阳，从旁边看球。', '日差しを遮って、横からボールを見る。'), opts={'a': ('El guante, tapando el sol sin tapar la bola', 'The glove, blocking the sun without blocking the ball', '手套：手套遮阳，但不挡住球', 'グラブ。日差しを遮るけど、ボールはかくさない'), 'b': ('La mano libre sobre los ojos solamente', 'Only your free hand over your eyes', '只用空着的手遮住眼睛', '空いている手を目の上にのせるだけ'), 'c': ('El casco del bateador', "The batter's helmet", '击球员的头盔', 'バッターのヘルメット')}), '2': act(('Si pierdes la bola en el sol, lo mejor es quedarte callado', 'If you lose the ball in the sun, the best thing is to stay quiet', '如果在阳光下看不到球，最好不要说话', '太陽でボールを見うしなったら、だまっているのがいちばん'), ('¡Bien! Hay que decirlo.', 'Good! You have to say it.', '很好！一定要说出来。', 'いいね！言わなきゃ。'), ('Falso: avisa en voz alta y tu compañero respalda.', 'False: call it out loud and your teammate backs you up.', '错：大声说出来，队友就会补位。', 'まちがい：大きな声で言えば、仲間がバックアップしてくれる。')), '3': act(('¿Qué más ayuda con el sol de frente?', 'What else helps with the sun in your face?', '迎着太阳时，还有什么办法？', '太陽が正面のとき、ほかに何が役に立つ？'), ('¡Correcto! De lado se ve mejor.', 'Correct! Sideways you see better.', '正确！侧身看得更清楚。', '正解！横からのほうがよく見える。'), ('Y la gorra ayuda un poquito también.', 'And your cap helps a little too.', '帽子也能帮一点忙。', 'ぼうしも少し役に立つ。'), opts={'a': ('Colocarse un poco de lado para que no dé de lleno', "Standing a little sideways so it doesn't hit you straight on", '稍微侧身，别让阳光正面照着', '少し横を向いて、正面から日差しを受けない'), 'b': ('Mirar fijo al sol', 'Staring right at the sun', '直直盯着太阳看', '太陽をじっと見る'), 'c': ('Cerrar los ojos y adivinar', 'Closing your eyes and guessing', '闭上眼睛猜', '目をとじて、あてずっぽう')}), '4': act(('¿Cuál imagen muestra la técnica correcta?', 'Which picture shows the right technique?', '哪张图是正确的技术？', '正しいやり方はどの絵？'), ('¡Eso es! Esa es la forma.', "That's it! That's the way.", '对了！就是这样。', 'そのとおり！それがやり方。'), ('Sol tapado, bola a la vista.', 'Sun blocked, ball in sight.', '遮住太阳，看得到球。', '日差しを遮って、ボールは見える。'), opts={'a': ('Jardinero con el guante alto como visera mirando la bola', 'Outfielder with the glove raised like a visor watching the ball', '外野手把手套举高当遮阳板，看着球', 'グラブを高く上げてひさしにして、ボールを見る外野手'), 'b': ('Jardinero tapándose la cara con las dos manos', 'Outfielder covering his face with both hands', '外野手用双手捂住脸', '両手で顔をかくす外野手'), 'c': ('Jardinero de espaldas al batazo', 'Outfielder with his back to the hit', '背对击球方向的外野手', '打球にせなかを向けた外野手')}), '5': act(('Con sol de frente, el jardinero debe atrapar igual sin cambiar nada', 'With the sun in his face, the outfielder should catch the same way without changing anything', '迎着太阳时，外野手应该照常接球，什么都不用改', '太陽が正面でも、外野手は何もかえずにいつもどおりとればいい'), ('¡Correcto! Hay técnica para eso.', "Correct! There's a technique for that.", '正确！这有专门的技术。', '正解！そのためのやり方がある。'), ('Falso: visera, lado y voz: tres ayudas.', 'False: visor, sideways and voice: three helps.', '错：遮阳板、侧身、出声：三个帮手。', 'まちがい：ひさし、横向き、声：3つの助け。')), '6': act(('Tu compañero perdió la bola en el sol y lo avisó. ¿Qué haces?', 'Your teammate lost the ball in the sun and said so. What do you do?', '你的队友在阳光下看不到球，并说出来了。你怎么做？', '仲間が太陽でボールを見うしなって、そう言った。どうする？'), ('¡Bien! Respaldar es de equipo.', 'Good! Backing up is teamwork.', '很好！补位就是团队合作。', 'いいね！バックアップはチームプレー。'), ('Avisar y respaldar: así se salvan jugadas.', "Warn and back up: that's how plays are saved.", '提醒加补位：这样才能救下这一球。', '知らせて、バックアップ：これでプレーが助かる。'), opts={'a': ('Corres a respaldar la jugada', 'You run to back up the play', '你跑过去补位', 'バックアップに走る'), 'b': ('Te ríes desde tu posición', 'You laugh from your position', '你在自己的位置上笑', '自分のポジションでわらう'), 'c': ('Miras al público', 'You look at the crowd', '你看观众', 'お客さんを見る')})})
map_titles['15.5'] = ('Jugar con el sol de frente', 'Playing with the sun in your face', '迎着太阳接球', '太陽が正面のとき')
exams_v3['15'] = {'1': {'q': ('Sale un batazo alto y profundo. ¿Tu primer paso?', 'A high, deep hit goes up. Your first step?', '一个又高又远的击球飞起来。你的第一步？', '高くて深い打球が上がった。第一歩は？'), 'opts': {'a': ('Hacia atrás', 'Backwards', '向后', '後ろ'), 'b': ('Hacia adelante', 'Forward', '向前', '前'), 'c': ('Hacia la banca', 'Toward the dugout', '朝休息区', 'ベンチのほう')}}, '2': {'q': ('La bola que un jardinero sí puede recuperar es la que…', 'The ball an outfielder can get back is the one that…', '外野手能接到的球，是那种……', '外野手がとれるのは、どんな球？'), 'opts': {'a': ('Cae delante de él', 'Drops in front of him', '落在他前面的', '前に落ちる球'), 'b': ('Le pasó muy por encima', 'Went way over his head', '从他头顶高高飞过的', '頭のずっと上をこえた球'), 'c': ('Ya salió del campo', 'Already left the field', '已经飞出场外的', 'もう場外に出た球')}}, '3': {'q': ('Elevado dudoso entre el centro y la izquierda: el central lo pide. ¿Quién lo atrapa?', 'A doubtful fly ball between center and left: the center fielder calls it. Who catches it?', '一个拿不准的高飞球在中外野和左外野之间：中外野手喊着要。谁来接？', 'センターとレフトのあいだのまようフライ：センターがコールした。だれがとる？'), 'opts': {'a': ('El jardinero central: su palabra manda en el medio', 'The center fielder: his word rules in the middle', '中外野手：中间他说了算', 'センター：まんなかではセンターの声が決める'), 'b': ('El izquierdo, porque llegó primero a gritar', 'The left fielder, because he yelled first', '左外野手，因为他先喊', 'レフト。先にさけんだから'), 'c': ('Los dos a la vez', 'Both at the same time', '两个人同时接', '二人同時に')}}, '4': {'q': ('El central pidió la bola. El jardinero derecho debe…', 'The center fielder called for the ball. The right fielder must…', '中外野手喊着要球。右外野手应该……', 'センターがコールした。ライトは……'), 'opts': {'a': ('Ceder, apartarse y respaldar', 'Give way, step aside and back up', '让开，退到一边补位', 'ゆずって、どいて、バックアップ'), 'b': ('Seguir corriendo igual', 'Keep running the same way', '照样继续跑', 'そのまま走りつづける'), 'c': ('Irse a su posición sin mirar', 'Go to his position without looking', '不看就回自己的位置', '見ないで自分のポジションにもどる')}}, '5': {'q': ('La bola rozó el pasto una fracción antes de entrar al guante. ¿Qué fue?', 'The ball brushed the grass a split second before going into the glove. What was it?', '球在进手套前一瞬间擦到了草地。这是什么？', 'グラブに入るほんの少し前に、ボールが芝にふれた。これは？'), 'opts': {'a': ('Una bola de pique (trap): no es atrapada', "A trap: it's not a catch", '弹跳接球（trap）：不算接杀', 'ワンバウンド捕球（trap）：キャッチじゃない'), 'b': ('Una atrapada legal', 'A legal catch', '合法的接杀', 'ルールどおりのキャッチ'), 'c': ('Un out seguro', 'A sure out', '肯定出局', 'たしかなアウト')}}, '6': {'q': ('Tras un pique así, la bola sigue viva. ¿Qué hace el jardinero?', 'After a trap, the ball is still live. What does the outfielder do?', '弹跳接球之后，球还是活球。外野手做什么？', 'ワンバウンド捕球のあと、ボールはまだインプレー。外野手はどうする？'), 'opts': {'a': ('La recoge y tira rápido a una base', 'He picks it up and throws fast to a base', '捡起球，快速传向一个垒', '拾って、すばやく塁へ投げる'), 'b': ('La muestra al umpire celebrando', 'He shows it to the umpire celebrating', '拿给裁判看，还在庆祝', 'よろこびながら審判に見せる'), 'c': ('Espera a que el umpire grite', 'He waits for the umpire to yell', '等裁判喊', '審判がさけぶのを待つ')}}, '7': {'q': ('¿Por qué ante la duda el jardinero juega un paso más atrás?', 'Why does the outfielder play a step farther back when in doubt?', '为什么拿不准时外野手要多退一步？', 'まようとき、外野手はどうして一歩後ろで守るの？'), 'opts': {'a': ('Para que la bola quede siempre delante de él', 'So the ball always stays in front of him', '让球永远留在他身前', 'ボールがいつも前にあるように'), 'b': ('Para estar más lejos del coach', 'To be farther from the coach', '为了离教练远一点', 'コーチから遠くいるため'), 'c': ('Para ver mejor al público', 'To see the crowd better', '为了看清楚观众', 'お客さんをよく見るため')}}, '8': {'q': ('Corriendo hacia la valla sientes bajo los pies un suelo distinto al pasto. ¿Qué es?', 'Running toward the fence, you feel ground under your feet that is different from the grass. What is it?', '你朝围墙跑，脚下感觉到和草地不一样的地面。那是什么？', 'フェンスに向かって走っていると、足もとに芝とちがう地面を感じた。これは？'), 'opts': {'a': ('La pista de advertencia: la valla está cerca', 'The warning track: the fence is close', '警戒区：围墙很近了', 'ウォーニングトラック：フェンスが近い'), 'b': ('La caja de bateo', "The batter's box", '击球员区', 'バッターボックス'), 'c': ('El montículo', 'The mound', '投手丘', 'マウンド')}}, '9': {'q': ('Sentir la pista de advertencia te avisa de…', 'Feeling the warning track warns you to…', '感觉到警戒区，是提醒你……', 'ウォーニングトラックを感じたら、それは……のサイン'), 'opts': {'a': ('Cuidarte para no chocar con la valla', 'Be careful not to crash into the fence', '小心别撞到围墙', 'フェンスにぶつからないよう気をつける'), 'b': ('Correr todavía más fuerte', 'Run even harder', '跑得更用力', 'もっと強く走る'), 'c': ('Pedir tiempo', 'Ask for time', '要求暂停', 'タイムをとる')}}, '10': {'q': ('Elevado con sol de frente. ¿Qué técnica usas?', 'A fly ball with the sun in your face. What technique do you use?', '迎着太阳的高飞球。你用什么技术？', '太陽が正面のフライ。どのやり方を使う？'), 'opts': {'a': ('El guante como visera, tapando el sol sin tapar la bola', 'The glove as a visor, blocking the sun without blocking the ball', '把手套当遮阳板，遮住太阳但不挡住球', 'グラブをひさしにして、日差しを遮るけどボールはかくさない'), 'b': ('Cierro los ojos y estiro el guante', 'I close my eyes and reach out the glove', '我闭上眼睛伸出手套', '目をとじてグラブをのばす'), 'c': ('Miro fijo al sol', 'I stare right at the sun', '我直直盯着太阳', '太陽をじっと見る')}}, '11': {'q': ('Perdiste la bola en el brillo del sol. ¿Qué haces?', 'You lost the ball in the glare of the sun. What do you do?', '你在强烈的阳光下看不到球了。你怎么做？', 'まぶしくてボールを見うしなった。どうする？'), 'opts': {'a': ('Lo digo en voz alta para que un compañero respalde', 'I say it out loud so a teammate backs me up', '我大声说出来，让队友补位', '大きな声で言って、仲間にバックアップしてもらう'), 'b': ('Me quedo callado y adivino', 'I stay quiet and guess', '我不说话，靠猜', 'だまって、あてずっぽう'), 'c': ('Me siento en el pasto', 'I sit down on the grass', '我坐到草地上', '芝にすわる')}}, '12': {'q': ('La prioridad en los jardines significa que…', 'Priority in the outfield means that…', '外野的优先权意思是……', '外野の優先権とは……'), 'opts': {'a': ('Hay una voz que manda en cada zona, y el centro manda en el medio', 'One voice is in charge in each zone, and the center rules the middle', '每个区域由一个声音说了算，中间由中外野手说了算', 'それぞれの場所に声が1つ、まんなかはセンターが決める'), 'b': ('Todos atrapan todo', 'Everyone catches everything', '每个人什么球都接', 'みんながぜんぶとる'), 'c': ('Nadie debe pedir ninguna bola', 'Nobody should call for any ball', '谁都不该喊着要球', 'だれもボールをコールしない')}}}
