lesson('16.1', ('La caja de bateo, la postura y el agarre', "The batter's box, the stance and the grip", '击球员区、站姿和握棒', 'バッターボックス、スタンス、グリップ'), ("Colocarse en la caja de bateo (batter's box) con los pies dentro, postura cómoda y equilibrada, y agarrar el bate firme sin apretarlo como si fuera a romperse.", "Set up in the batter's box with your feet inside, a comfortable and balanced stance, and grip the bat firmly without squeezing it as if it were going to break.", '双脚站在击球员区里，站姿舒服、平衡，稳稳地握棒，但不要捏得像要把它捏断一样。', 'バッターボックスに両足を入れて、楽でバランスのいいスタンスをとる。バットはしっかり、でも折れそうなほど強くにぎらない。'), [("Tu turno empieza en la caja de bateo, en inglés batter's box: ese rectángulo pintado junto a home.", "Your turn starts in the batter's box: that painted rectangle next to home.", "你的打击从击球员区开始，英语叫 batter's box：就是本垒旁边画出来的那个长方形。", "打席はバッターボックス、英語で batter's box から始まる：ホームのそばにかいてある長方形だ。"), ('Los dos pies van dentro de la caja, separados, rodillas suaves y peso en equilibrio.', 'Both feet go inside the box, apart, knees soft and weight balanced.', '双脚都站在区里，分开，膝盖放松，重心平衡。', '両足はボックスの中、広げて、ひざはやわらかく、体重はバランスよく。'), ('Las manos agarran el bate firmes, pero sin apretarlo como si fuera a romperse: manos duras, swing lento.', 'Your hands hold the bat firmly, but without squeezing it as if it were going to break: stiff hands, slow swing.', '双手稳稳地握棒，但别捏得像要把它捏断：手太僵，挥棒就慢。', '手はバットをしっかりにぎる。でも折れそうなほど強くはにぎらない：手がかたいと、スイングはおそい。'), ('El bate descansa sobre el hombro de atrás, listo.', 'The bat rests on your back shoulder, ready.', '球棒靠在后面的肩膀上，准备好。', 'バットはうしろのかたにのせて、じゅんびオーケー。'), ('Postura y agarre: en inglés, stance y grip.', 'Stance and grip.', '站姿和握棒，英语叫 stance 和 grip。', 'スタンスとグリップ。英語で stance と grip。'), ('Desde ahí, todo es mirar la bola.', "From there, it's all about watching the ball.", '接下来，就是看球了。', 'そこからは、ボールを見るだけ。')], {'1': act(('¿Dónde van los pies del bateador?', "Where do the batter's feet go?", '击球员的双脚放在哪里？', 'バッターの足はどこ？'), ('¡Eso es! Dentro de la caja.', "That's it! Inside the box.", '对了！在区里。', 'そのとおり！ボックスの中。'), ('La caja marca tu lugar para batear.', 'The box marks your place to bat.', '击球员区标出你击球的位置。', 'ボックスが打つ場所を決める。'), opts={'a': ("Dentro de la caja de bateo (batter's box)", "Inside the batter's box", "击球员区里（batter's box）", "バッターボックスの中（batter's box）"), 'b': ('Encima de home', 'On top of home', '本垒上面', 'ホームの上'), 'c': ('Fuera de las líneas, donde sea', 'Outside the lines, anywhere', '线外面，哪里都行', '線の外、どこでも')}), '2': act(('¿Cómo se agarra el bate?', 'How do you grip the bat?', '怎么握棒？', 'バットはどうにぎる？'), ('¡Correcto! Firme y suelto a la vez.', 'Correct! Firm and loose at the same time.', '正确！又稳又放松。', '正解！しっかり、でもやわらかく。'), ('Manos duras hacen un swing lento.', 'Stiff hands make a slow swing.', '手太僵，挥棒就慢。', '手がかたいと、スイングはおそい。'), opts={'a': ('Firme, sin apretarlo como si fuera a romperse', 'Firmly, without squeezing it as if it were going to break', '稳稳地握，但别捏得像要捏断', 'しっかり、でも折れそうなほど強くない'), 'b': ('Apretando con toda la fuerza', 'Squeezing with all your strength', '用尽全力捏紧', 'ありったけの力でにぎる'), 'c': ('Con una sola mano siempre', 'Always with one hand', '总是用一只手', 'いつも片手で')}), '3': act(('La postura es pies juntos y cuerpo rígido', 'The stance is feet together and a stiff body', '站姿是双脚并拢、身体僵硬', 'スタンスは足をそろえて、体はかたく'), ('¡Bien! Pies separados y suaves.', 'Good! Feet apart and soft.', '很好！双脚分开，放松。', 'いいね！足を広げて、やわらかく。'), ('Falso: equilibrio y rodillas suaves.', 'False: balance and soft knees.', '错：要平衡，膝盖放松。', 'まちがい：バランスと、やわらかいひざ。')), '4': act(('¿Cuál imagen muestra una buena postura?', 'Which picture shows a good stance?', '哪张图是好的站姿？', 'いいスタンスはどの絵？'), ('¡Eso es! Listo para mirar la bola.', "That's it! Ready to watch the ball.", '对了！准备好看球了。', 'そのとおり！ボールを見るじゅんびオーケー。'), ('Caja, pies y bate: todo en su sitio.', 'Box, feet and bat: everything in its place.', '击球员区、双脚、球棒：都在该在的地方。', 'ボックス、足、バット：ぜんぶ決まった場所に。'), opts={'a': ('Bateador en la caja, pies separados y bate sobre el hombro de atrás', 'Batter in the box, feet apart and bat on the back shoulder', '击球员在区里，双脚分开，球棒靠在后肩上', 'ボックスの中で、足を広げて、バットをうしろのかたにのせたバッター'), 'b': ('Bateador fuera de la caja', 'Batter outside the box', '站在区外的击球员', 'ボックスの外のバッター'), 'c': ('Bateador mirando a la banca', 'Batter looking at the dugout', '在看休息区的击球员', 'ベンチを見ているバッター')}), '5': act(('¿Para qué sirve una buena postura?', 'What is a good stance for?', '好的站姿有什么用？', 'いいスタンスは何のため？'), ('¡Correcto! Equilibrio es poder.', 'Correct! Balance is power.', '正确！平衡就是力量。', '正解！バランスは力。'), ('Sin equilibrio, el swing se cae.', 'Without balance, the swing falls apart.', '没有平衡，挥棒就会散掉。', 'バランスがないと、スイングがくずれる。'), opts={'a': ('Para estar en equilibrio y hacer un swing rápido', 'To be balanced and make a quick swing', '保持平衡，挥棒更快', 'バランスをとって、すばやくスイングするため'), 'b': ('Para verse bien en la foto', 'To look good in the photo', '拍照好看', '写真で見ばえがいいように'), 'c': ('Para cansar al pitcher', 'To tire out the pitcher', '让投手累', 'ピッチャーをつかれさせるため')}), '6': act(('El bateador puede pararse con un pie fuera de la caja si le queda cómodo', "The batter can stand with one foot outside the box if it's comfortable for him", '如果觉得舒服，击球员可以一只脚站在区外', 'バッターは、楽なら片足をボックスの外に出して立ってもいい'), ('¡Bien! Los dos dentro.', 'Good! Both inside.', '很好！两只脚都在里面。', 'いいね！両足とも中。'), ('Falso: los dos pies van dentro de la caja.', 'False: both feet go inside the box.', '错：双脚都要在击球员区里。', 'まちがい：両足ともボックスの中。'))})
map_titles['16.1'] = ('La caja de bateo, la postura y el agarre', "The batter's box, the stance and the grip", '击球员区、站姿和握棒', 'バッターボックス、スタンス、グリップ')
lesson('16.2', ('Ojos en la bola desde la mano del pitcher', "Eyes on the ball from the pitcher's hand", '从投手手里就开始看球', 'ピッチャーの手からボールを見る'), ('Mirar la bola desde que sale de la mano del pitcher y seguirla hasta el bate, sin mirar a otro lado; y conocer el swing a medias: empezar el swing y frenarlo, donde el umpire decide si hubo swing.', "Watch the ball from the moment it leaves the pitcher's hand and follow it all the way to the bat, without looking away; and know the checked swing: starting the swing and stopping it, where the umpire decides if there was a swing.", '从球离开投手的手那一刻起就看着它，一路跟到球棒，不要看别处；还要知道半挥棒：开始挥棒又停下来，由裁判决定算不算挥棒。', 'ボールがピッチャーの手をはなれたときから、バットまでずっと見つづける。よそ見はしない。それから、ハーフスイングを知ろう：スイングを始めて止めること。スイングしたかどうかは審判が決める。'), [('El secreto de los buenos bateadores cabe en una frase: ojos en la bola desde la mano del pitcher.', "The secret of good hitters fits in one phrase: eyes on the ball from the pitcher's hand.", '好击球员的秘诀一句话就能说完：从投手手里就开始看球。', 'いいバッターのひみつは一言で言える：ピッチャーの手からボールを見る。'), ('Mira su mano, encuentra la bola cuando sale y síguela todo el camino hasta tu bate.', 'Look at his hand, find the ball when it comes out and follow it all the way to your bat.', '看着他的手，球一出手就找到它，一路跟到你的球棒。', '手を見て、出てきたボールを見つけて、バットまでずっと追いかける。'), ('Y aquí va una jugada curiosa: a veces amagas el swing y te frenas a mitad de camino.', "And here's a curious play: sometimes you start to swing and stop halfway.", '还有一个有趣的情况：有时候你开始挥棒，挥到一半又停住了。', 'それから、おもしろいプレー：ときどき、スイングしかけて、とちゅうで止める。'), ('Eso es un swing a medias, en inglés checked swing: empezó el movimiento y se detuvo.', "That's a checked swing: the motion started and stopped.", '这叫半挥棒，英语叫 checked swing：动作开始了，又停下来。', 'これがハーフスイング、英語で checked swing：動きが始まって、止まった。'), ('Decide el umpire de home: si para él el bate cruzó buscando la bola, canta strike; si te frenaste a tiempo, es bola.', "The home plate umpire decides: if he thinks the bat went through looking for the ball, he calls a strike; if you stopped in time, it's a ball.", '由本垒裁判决定：如果他认为球棒挥过去找球了，就判好球；如果你及时停住了，就是坏球。', '球審が決める：バットがボールをねらって出たと思えば、ストライク。まにあって止めていれば、ボール。'), ('Mirar bien también es saber frenar.', 'Watching well also means knowing how to stop.', '会看球，也包括会收住。', 'よく見ることは、止めることでもある。')], {'1': act(('¿Desde cuándo miras la bola?', 'From when do you watch the ball?', '你从什么时候开始看球？', 'いつからボールを見る？'), ('¡Eso es! Desde la mano.', "That's it! From the hand.", '对了！从手里开始。', 'そのとおり！手から。'), ('Seguirla todo el camino es el secreto.', 'Following it all the way is the secret.', '一路跟着它就是秘诀。', 'ずっと追いかけるのがひみつ。'), opts={'a': ('Desde que sale de la mano del pitcher', "From when it leaves the pitcher's hand", '从球离开投手的手开始', 'ピッチャーの手をはなれたときから'), 'b': ('Solo cuando ya viene cerca', "Only when it's already close", '球已经很近时才看', 'もう近くに来たときだけ'), 'c': ('Después del swing', 'After the swing', '挥棒之后', 'スイングのあと')}), '2': act(('¿Qué es un swing a medias (checked swing)?', 'What is a checked swing?', '什么是半挥棒（checked swing）？', 'ハーフスイング（checked swing）って何？'), ('¡Correcto! Amagar y frenar.', 'Correct! Start and stop.', '正确！开始又停住。', '正解！しかけて止める。'), ('Empezó y se detuvo: swing a medias.', 'It started and stopped: a checked swing.', '开始了又停下：就是半挥棒。', '始まって止まった：ハーフスイング。'), opts={'a': ('Empezar el swing y frenarlo a mitad de camino', 'Starting the swing and stopping it halfway', '开始挥棒，挥到一半停住', 'スイングを始めて、とちゅうで止める'), 'b': ('Un swing con una mano', 'A one-handed swing', '单手挥棒', '片手のスイング'), 'c': ('Un toque de bola', 'A bunt', '触击', 'バント')}), '3': act(('¿Quién decide si el swing a medias fue swing?', 'Who decides if the checked swing was a swing?', '半挥棒算不算挥棒，由谁决定？', 'ハーフスイングがスイングだったかを決めるのはだれ？'), ('¡Eso es! Decide el umpire.', "That's it! The umpire decides.", '对了！裁判决定。', 'そのとおり！審判が決める。'), ('Si el bate cruzó buscando la bola, es strike.', "If the bat went through looking for the ball, it's a strike.", '如果球棒挥过去找球了，就是好球。', 'バットがボールをねらって出たら、ストライク。'), opts={'a': ('El umpire de home', 'The home plate umpire', '本垒裁判', '球審'), 'b': ('El bateador', 'The batter', '击球员', 'バッター'), 'c': ('La banca', 'The dugout', '休息区的人', 'ベンチ')}), '4': act(('En el swing a medias, el bateador nunca movió el bate', 'On a checked swing, the batter never moved the bat', '半挥棒时，击球员根本没动球棒', 'ハーフスイングでは、バッターはバットを動かしていない'), ('¡Bien! Sí lo movió, se frenó.', 'Good! He moved it, then stopped.', '很好！他动了，然后停住了。', 'いいね！動かして、止めたんだ。'), ('Falso: el movimiento empezó y se detuvo.', 'False: the motion started and stopped.', '错：动作开始了，又停住了。', 'まちがい：動きが始まって、止まった。')), '5': act(('Mirar la mano del pitcher ayuda a ver la bola más temprano', "Watching the pitcher's hand helps you see the ball earlier", '看着投手的手，能帮你更早看到球', 'ピッチャーの手を見ると、ボールが早く見える'), ('¡Correcto! La ves desde que nace.', "Correct! You see it from the moment it's born.", '正确！球一出现你就看到了。', '正解！生まれたときから見える。'), ('Verdadero: bola vista temprano, swing a tiempo.', 'True: ball seen early, swing on time.', '对：早点看到球，挥棒就来得及。', '正しい：早く見れば、スイングがまにあう。')), '6': act(('El bateador amagó y se frenó sin buscar la bola. ¿Qué puede cantar el umpire?', 'The batter started to swing and stopped without going after the ball. What can the umpire call?', '击球员开始挥棒，没有去追球就停住了。裁判可以怎么判？', 'バッターがスイングしかけて、ボールをねらわずに止めた。審判のコールは？'), ('¡Bien cantado!', 'Well called!', '判得好！', 'いいコール！'), ('Se frenó a tiempo: bola.', 'He stopped in time: ball.', '他及时停住了：坏球。', 'まにあって止めた：ボール。'), opts={'a': ('¡Bola! No hubo swing', 'Ball! There was no swing', '坏球！没有挥棒', 'ボール！スイングなし'), 'b': ('¡Strike! sin mirar', 'Strike! He swung', '好球！看都不看', 'ストライク！見ないで'), 'c': ('¡Foul!', 'Foul!', '界外球！', 'ファウル！')})})
map_titles['16.2'] = ('Ojos en la bola desde la mano del pitcher', "Eyes on the ball from the pitcher's hand", '从投手手里就开始看球', 'ピッチャーの手からボールを見る')
lesson('16.3', ('El foul tip: la rozada veloz', 'The foul tip: the speedy brush', '擦棒球：飞快的一擦', 'ファウルチップ：さっとかすめる球'), ('Entender el foul tip: la bola que roza el bate y el catcher atrapa directo es strike y la bola sigue viva; si no la atrapa, es foul normal.', "Understand the foul tip: the ball that brushes the bat and the catcher catches directly is a strike and the ball stays live; if he doesn't catch it, it's a regular foul.", '明白擦棒球：球擦过球棒，捕手直接接住，算好球，球继续是活球；如果捕手没接住，就是普通的界外球。', 'ファウルチップを知ろう：バットをかすめた球をキャッチャーが直接とったら、ストライクで、ボールはインプレーのまま。とれなかったら、ふつうのファウル。'), [('Escucha el sonido más fino del béisbol: ¡tic!', 'Listen to the faintest sound in baseball: tick!', '听听棒球里最细的声音：嗒！', '野球でいちばん小さな音を聞いて：チッ！'), ('La bola apenas roza el bate, sale disparada hacia atrás y el catcher la atrapa directo, sin que toque el suelo.', 'The ball barely brushes the bat, shoots back and the catcher catches it directly, without it touching the ground.', '球只是轻轻擦过球棒，往后飞出去，捕手没让它落地就直接接住了。', 'ボールがバットをほんの少しかすめて、うしろへ飛び、キャッチャーが地面にふれる前に直接とる。'), ('Eso es un foul tip.', "That's a foul tip.", '这就是擦棒球，英语叫 foul tip。', 'これがファウルチップ、英語で foul tip。'), ('No es un foul común: si el catcher lo atrapa, cuenta como strike y la bola sigue viva, como un lanzamiento más.', "It's not a regular foul: if the catcher catches it, it counts as a strike and the ball stays live, like any other pitch.", '它不是普通的界外球：如果捕手接住了，就算好球，球继续是活球，就像普通的一次投球。', 'ふつうのファウルじゃない：キャッチャーがとったら、ストライクで、ボールはインプレーのまま。ふつうの投球と同じ。'), ('Hasta puede ser el tercer strike y ponche.', 'It can even be the third strike and a strikeout.', '它甚至可以是第三个好球，三振出局。', '3つ目のストライクで、三振になることもある。'), ('Pero si el catcher no la atrapa y la bola cae, ahí sí es foul normal y la bola se detiene.', "But if the catcher doesn't catch it and the ball drops, then it's a regular foul and the ball stops.", '但如果捕手没接住，球掉下来，那就是普通的界外球，比赛停止。', 'でもキャッチャーがとれずにボールが落ちたら、それはふつうのファウルで、プレーは止まる。'), ('Roce, atrapada y strike: foul tip.', 'Brush, catch and strike: foul tip.', '擦棒、接住、好球：擦棒球。', 'かすめて、とって、ストライク：ファウルチップ。')], {'1': act(('¿Qué es un foul tip?', 'What is a foul tip?', '什么是擦棒球？', 'ファウルチップって何？'), ('¡Eso es! Foul tip.', "That's it! Foul tip.", '对了！擦棒球。', 'そのとおり！ファウルチップ。'), ('Roce y atrapada directa del catcher.', 'Brush and a direct catch by the catcher.', '擦棒，加上捕手直接接住。', 'かすめて、キャッチャーが直接とる。'), opts={'a': ('La bola roza el bate y el catcher la atrapa directo', 'The ball brushes the bat and the catcher catches it directly', '球擦过球棒，捕手直接接住', 'バットをかすめた球を、キャッチャーが直接とる'), 'b': ('Un foul muy alto a los jardines', 'A very high foul to the outfield', '飞向外野的很高的界外球', '外野への、とても高いファウル'), 'c': ('Un lanzamiento malo del pitcher', 'A bad pitch by the pitcher', '投手投的坏球', 'ピッチャーの悪い投球')}), '2': act(('El foul tip atrapado cuenta como strike', 'A caught foul tip counts as a strike', '被接住的擦棒球算好球', 'とったファウルチップはストライクになる'), ('¡Bien! Strike, no foul gratis.', 'Good! A strike, not a free foul.', '很好！是好球，不是白给的界外球。', 'いいね！ストライク。ただのファウルじゃない。'), ('Verdadero: atrapado, el roce cuenta como strike.', 'True: caught, the brush counts as a strike.', '对：被接住时，擦棒算好球。', '正しい：とったら、かすめた球はストライク。')), '3': act(('Si el catcher no atrapa el roce y la bola cae, ¿qué es?', "If the catcher doesn't catch the brush and the ball drops, what is it?", '如果捕手没接住擦棒的球，球掉了下来，这是什么？', 'キャッチャーがかすめた球をとれずに、ボールが落ちたら？'), ('¡Correcto! Sin atrapada, foul común.', 'Correct! No catch, regular foul.', '正确！没接住，就是普通界外球。', '正解！とれなければ、ふつうのファウル。'), ('La atrapada directa es lo que lo cambia todo.', 'The direct catch is what changes everything.', '直接接住才是关键。', '直接とるかどうかで、ぜんぶかわる。'), opts={'a': ('Foul normal y la bola se detiene', 'A regular foul and the ball stops', '普通的界外球，比赛停止', 'ふつうのファウルで、プレーは止まる'), 'b': ('Strike igual', 'A strike anyway', '照样算好球', 'それでもストライク'), 'c': ('Jonrón', 'A home run', '本垒打', 'ホームラン')}), '4': act(('Con el foul tip atrapado, ¿la bola sigue viva?', 'With a caught foul tip, does the ball stay live?', '擦棒球被接住后，球还是活球吗？', 'ファウルチップをとったら、ボールはインプレーのまま？'), ('¡Eso es! Bola viva.', "That's it! Live ball.", '对了！活球。', 'そのとおり！インプレー。'), ('Por eso los corredores deben cuidarse.', "That's why runners have to be careful.", '所以跑垒员要小心。', 'だからランナーは気をつけなきゃ。'), opts={'a': ('Sí, sigue viva como un lanzamiento más', 'Yes, it stays live like any other pitch', '是的，就像普通的一次投球，继续是活球', 'はい、ふつうの投球と同じでインプレー'), 'b': ('No, el juego se detiene siempre', 'No, the game always stops', '不是，比赛总是停止', 'いいえ、いつもプレーは止まる'), 'c': ('Solo si hay corredores', 'Only if there are runners', '只有垒上有人时才是', 'ランナーがいるときだけ')}), '5': act(('Roce del bate, atrapada directa del catcher con dos strikes. ¿Qué canta el umpire?', 'A brush off the bat, a direct catch by the catcher with two strikes. What does the umpire call?', '两好球时，球擦过球棒，捕手直接接住。裁判怎么判？', '2ストライクで、バットをかすめた球をキャッチャーが直接とった。審判のコールは？'), ('¡Bien! Ponche por foul tip.', 'Good! Strikeout on a foul tip.', '很好！擦棒球三振。', 'いいね！ファウルチップで三振。'), ('Atrapado con dos strikes: tercer strike.', 'Caught with two strikes: the third strike.', '两好球时被接住：就是第三个好球。', '2ストライクでとった：3つ目のストライク。'), opts={'a': ('¡Strike tres! ¡Out!', 'Strike three! Out!', '第三个好球！出局！', 'ストライク・スリー！アウト！'), 'b': ('¡Foul! Sigue bateando', 'Foul! Keep batting', '界外球！继续打', 'ファウル！打ちつづける'), 'c': ('¡Bola!', 'Ball!', '坏球！', 'ボール！')}), '6': act(('Todo roce al bate es foul tip aunque el catcher no atrape la bola', "Every brush off the bat is a foul tip even if the catcher doesn't catch the ball", '只要球擦到球棒，就算捕手没接住，也是擦棒球', 'バットをかすめた球は、キャッチャーがとれなくても、ぜんぶファウルチップ'), ('¡Correcto! Sin atrapada no hay foul tip.', 'Correct! No catch, no foul tip.', '正确！没接住就不是擦棒球。', '正解！とれなければファウルチップじゃない。'), ('Falso: sin atrapada directa, es foul normal.', "False: without a direct catch, it's a regular foul.", '错：没有直接接住，就是普通的界外球。', 'まちがい：直接とれなければ、ふつうのファウル。'))})
map_titles['16.3'] = ('El foul tip: la rozada veloz', 'The foul tip: the speedy brush', '擦棒球：飞快的一擦', 'ファウルチップ：さっとかすめる球')
lesson('16.4', ('El toque de sacrificio y el carril a primera', 'The sacrifice bunt and the lane to first', '牺牲触击和通往一垒的通道', '犠牲バントと一塁へのレーン'), ('Aplicar el toque como sacrificio (repaso del toque): avanzar al compañero aceptando el propio out; y correr a primera por el carril del corredor sin estorbar el tiro.', "Use the bunt as a sacrifice (review of the bunt): move a teammate up while accepting your own out; and run to first in the runner's lane without getting in the way of the throw.", '把触击当作牺牲来用（复习触击）：接受自己出局，让队友前进；还要在跑者通道里跑向一垒，不妨碍传球。', 'バントを犠牲として使おう（バントのふくしゅう）：自分のアウトとひきかえに、仲間を進める。それから、一塁へはレーンの中を走って、送球のじゃまをしない。'), [('Repaso aplicado: ya conoces el toque de bola.', 'Applied review: you already know the bunt.', '应用复习：你已经认识触击了。', 'ふくしゅうして使おう：バントはもう知っているね。'), ('Hoy lo usas con un propósito grande: el toque de sacrificio, en inglés sacrifice bunt.', 'Today you use it for a big purpose: the sacrifice bunt.', '今天你要用它完成一个大任务：牺牲触击，英语叫 sacrifice bunt。', '今日は大きな目的に使う：犠牲バント、英語で sacrifice bunt。'), ('Tu compañero está en base y tú tocas suave para que él avance, aunque a ti te hagan out en primera.', "Your teammate is on base and you bunt softly so he moves up, even if you're put out at first.", '你的队友在垒上，你轻轻触击让他前进，就算你自己在一垒出局。', '仲間が塁にいて、君はやさしくバントして仲間を進める。自分は一塁でアウトになっても。'), ('Te sacrificas por el equipo, y por eso se llama así.', "You sacrifice yourself for the team, and that's why it has that name.", '你为球队牺牲了自己，所以才叫这个名字。', 'チームのために自分をぎせいにする。だからこの名前なんだ。'), ("Y al correr a primera, hazlo por tu caminito: el carril del corredor, en inglés runner's lane, marcado junto a la línea.", "And when you run to first, stay in your path: the runner's lane, marked next to the line.", "跑向一垒时，要走你的小路：跑者通道，英语叫 runner's lane，就画在线旁边。", "そして一塁へ走るときは、自分の小道を走ろう：ランナーのレーン、英語で runner's lane。線のそばにかいてある。"), ('La última parte del camino se corre dentro del carril, en zona de foul: si corres por dentro del campo y estorbas el tiro a primera, el umpire puede cantarte out por interferencia.', 'The last part of the way is run inside the lane, in foul territory: if you run inside the field and get in the way of the throw to first, the umpire can call you out for interference.', '最后一段路要在通道里跑，在界外区：如果你跑在场内，挡住了传向一垒的球，裁判可以判你妨碍出局。', '最後のところはレーンの中、ファウルゾーンを走る：グラウンドの内がわを走って一塁への送球のじゃまをしたら、審判は守備妨害でアウトにできる。'), ('Toca, avanza a tu compañero y corre por tu carril.', 'Bunt, move your teammate up and run in your lane.', '触击，让队友前进，在你的通道里跑。', 'バントして、仲間を進めて、レーンを走ろう。')], {'1': act(('¿Qué busca el toque de sacrificio?', 'What is the sacrifice bunt for?', '牺牲触击是为了什么？', '犠牲バントは何のため？'), ('¡Eso es! Equipo primero.', "That's it! Team first.", '对了！球队第一。', 'そのとおり！チームが先。'), ('Te sacrificas: él avanza, tú sales.', "You sacrifice yourself: he moves up, you're out.", '你牺牲自己：他前进，你出局。', '自分をぎせいに：仲間は進み、君はアウト。'), opts={'a': ('Que el compañero avance de base, aunque hagan out al bateador', 'For the teammate to move up a base, even if the batter is put out', '让队友进一个垒，就算击球员出局', '仲間を1つ進めるため。バッターがアウトになっても'), 'b': ('Un jonrón suave', 'A soft home run', '一个轻轻的本垒打', 'やさしいホームラン'), 'c': ('Que el pitcher se canse', 'To tire out the pitcher', '让投手累', 'ピッチャーをつかれさせるため')}), '2': act(("¿Qué es el carril del corredor (runner's lane)?", "What is the runner's lane?", "什么是跑者通道（runner's lane）？", "ランナーのレーン（runner's lane）って何？"), ('¡Correcto! Tu camino a primera.', 'Correct! Your path to first.', '正确！你通往一垒的路。', '正解！一塁への君の道。'), ('La última parte se corre dentro de él.', 'The last part is run inside it.', '最后一段要在里面跑。', '最後のところはその中を走る。'), opts={'a': ('El caminito marcado junto a la línea camino a primera', 'The little path marked next to the line on the way to first', '通往一垒的线旁边画出来的小路', '一塁への線のそばにかいてある小道'), 'b': ('La pista de advertencia', 'The warning track', '警戒区', 'ウォーニングトラック'), 'c': ('El círculo de espera', 'The on-deck circle', '待打区', 'ネクストバッターズサークル')}), '3': act(('En el toque de sacrificio, el bateador busca llegar a salvo como sea', 'On a sacrifice bunt, the batter tries to be safe no matter what', '牺牲触击时，击球员不管怎样都要安全上垒', '犠牲バントでは、バッターはなんとしてもセーフをねらう'), ('¡Bien! Busca avanzar al compañero.', 'Good! He tries to move his teammate up.', '很好！他是要让队友前进。', 'いいね！仲間を進めるのがねらい。'), ('Falso: acepta su out por el equipo.', 'False: he accepts his out for the team.', '错：他为球队接受自己出局。', 'まちがい：チームのために自分のアウトを受け入れる。')), '4': act(('¿Qué puede pasar si corres por dentro del campo y estorbas el tiro a primera?', 'What can happen if you run inside the field and get in the way of the throw to first?', '如果你跑在场内，挡住了传向一垒的球，会怎样？', 'グラウンドの内がわを走って、一塁への送球のじゃまをしたら？'), ('¡Eso es! Por eso existe el carril.', "That's it! That's why the lane exists.", '对了！所以才有通道。', 'そのとおり！だからレーンがある。'), ('Dentro del carril, el tiro pasa libre.', 'Inside the lane, the throw goes by freely.', '在通道里跑，传球就能顺利通过。', 'レーンの中なら、送球はじゃまされない。'), opts={'a': ('El umpire puede cantarte out por interferencia', 'The umpire can call you out for interference', '裁判可以判你妨碍出局', '審判は守備妨害でアウトにできる'), 'b': ('Nada, es tu camino', "Nothing, it's your path", '没事，那是你的路', '何もない、自分の道だから'), 'c': ('Te dan segunda base', 'You get second base', '给你上二垒', '二塁がもらえる')}), '5': act(('Toca el carril por donde corre el bateador a primera', 'Tap the lane the batter runs in to first', '点一下击球员跑向一垒的通道', 'バッターが一塁へ走るレーンをタッチしよう'), ('¡Bien! Ese es tu camino.', "Good! That's your path.", '很好！那是你的路。', 'いいね！それが君の道。'), ('Pegado a la línea, del lado de foul.', 'Right by the line, on the foul side.', '紧挨着线，在界外那一边。', '線のすぐそば、ファウルがわ。'), answer=('El carril junto a la línea de primera, en zona de foul', 'The lane next to the first base line, in foul territory', '一垒线旁边的通道，在界外区', '一塁線のそばのレーン、ファウルゾーン')), '6': act(('El toque de sacrificio solo sirve si el bateador también llega a salvo', 'The sacrifice bunt only works if the batter is also safe', '牺牲触击只有在击球员也安全上垒时才有用', '犠牲バントは、バッターもセーフにならないと意味がない'), ('¡Correcto! Sirve si avanza el compañero.', 'Correct! It works if the teammate moves up.', '正确！只要队友前进就有用。', '正解！仲間が進めば成功。'), ('Falso: su trabajo es mover al corredor.', 'False: his job is to move the runner.', '错：他的任务是让跑垒员前进。', 'まちがい：しごとはランナーを進めること。'))})
map_titles['16.4'] = ('El toque de sacrificio y el carril a primera', 'The sacrifice bunt and the lane to first', '牺牲触击和通往一垒的通道', '犠牲バントと一塁へのレーン')
lesson('16.5', ('Soltar el bate y usar el casco', 'Dropping the bat and wearing the helmet', '放下球棒，戴好头盔', 'バットを置いて、ヘルメットをかぶる'), ('Soltar el bate sin lanzarlo — dejarlo caer junto a home — y correr con el casco puesto y bien ajustado, que no se quita hasta llegar a la banca.', 'Let go of the bat without throwing it — drop it next to home — and run with your helmet on and fitted well, which stays on until you reach the dugout.', '放开球棒但不要扔——让它掉在本垒旁边——戴着合适的头盔跑，回到休息区之前都不能摘下来。', 'バットは投げずに手をはなす——ホームのそばに落とす——ヘルメットをしっかりかぶって走る。ベンチに着くまでぬがない。'), [('Conectaste la bola.', 'You hit the ball.', '你打中球了。', 'ボールを打った。'), ('¿Y ahora?', 'And now?', '然后呢？', 'さあ、どうする？'), ('No lances el bate: déjalo caer suave junto a home, en inglés drop the bat.', "Don't throw the bat: drop it softly next to home plate.", '别扔球棒：让它轻轻掉在本垒旁边，英语叫 drop the bat。', 'バットは投げない：ホームのそばにそっと落とす、英語で drop the bat。'), ('Un bate volando puede golpear al catcher o al umpire.', 'A flying bat can hit the catcher or the umpire.', '飞出去的球棒可能打到捕手或裁判。', '飛んだバットは、キャッチャーや審判に当たるかもしれない。'), ('Y corre con tu casco puesto: el casco, en inglés helmet, te protege de un tiro desviado o de una caída, y no se quita hasta llegar a la banca.', "And run with your helmet on: the helmet protects you from a wild throw or a fall, and it doesn't come off until you reach the dugout.", '戴着头盔跑：头盔，英语叫 helmet，能保护你不被偏了的传球打到，摔倒也不怕，回到休息区之前都不能摘。', 'ヘルメットをかぶって走ろう：ヘルメット、英語で helmet は、それた送球やころんだときから守ってくれる。ベンチに着くまでぬがない。'), ('Bateadores inteligentes: bate al suelo, casco en la cabeza y a correr por el carril que ya conoces.', 'Smart hitters: bat on the ground, helmet on your head and run in the lane you already know.', '聪明的击球员：球棒放地上，头盔戴头上，在你已经认识的通道里跑。', 'かしこいバッター：バットは地面に、ヘルメットは頭に。知っているレーンを走ろう。')], {'1': act(('¿Qué haces con el bate después de conectar?', 'What do you do with the bat after making contact?', '击中球以后，你怎么处理球棒？', '打ったあと、バットはどうする？'), ('¡Eso es! Bate al suelo.', "That's it! Bat on the ground.", '对了！球棒放地上。', 'そのとおり！バットは地面に。'), ('Un bate volando puede golpear a alguien.', 'A flying bat can hit someone.', '飞出去的球棒可能打到人。', '飛んだバットは人に当たるかもしれない。'), opts={'a': ('Lo dejas caer suave junto a home', 'You drop it softly next to home', '让它轻轻掉在本垒旁边', 'ホームのそばにそっと落とす'), 'b': ('Lo lanzas lejos', 'You throw it far', '把它扔远', '遠くへ投げる'), 'c': ('Lo llevas corriendo a primera', 'You carry it running to first', '拿着它跑向一垒', '持ったまま一塁へ走る')}), '2': act(('El casco se puede quitar corriendo a primera si estorba', 'You can take your helmet off running to first if it gets in the way', '跑向一垒时，如果头盔碍事，可以摘下来', '一塁へ走るとき、じゃまならヘルメットをぬいでいい'), ('¡Bien! Casco hasta la banca.', 'Good! Helmet on until the dugout.', '很好！头盔一直戴到休息区。', 'いいね！ベンチまでヘルメット。'), ('Falso: protege de tiros y caídas en todo el camino.', 'False: it protects you from throws and falls the whole way.', '错：一路上它都在保护你不被传球打到、摔倒也不怕。', 'まちがい：ずっと送球やころぶことから守ってくれる。')), '3': act(('¿Para qué protege el casco al correr las bases?', 'What does the helmet protect you from when running the bases?', '跑垒时头盔保护你不受什么伤害？', '塁を走るとき、ヘルメットは何から守ってくれる？'), ('¡Correcto! Cabeza protegida siempre.', 'Correct! Head always protected.', '正确！头部永远受保护。', '正解！頭はいつも守る。'), ('Los tiros desviados existen: casco puesto.', 'Wild throws happen: helmet on.', '传球偏是会发生的：戴好头盔。', 'それた送球はある：ヘルメットをかぶろう。'), opts={'a': ('De un tiro desviado o de una caída', 'From a wild throw or a fall', '偏了的传球或摔倒', 'それた送球や、ころぶこと'), 'b': ('Solo del sol', 'Only from the sun', '只是挡太阳', '太陽だけ'), 'c': ('De nada, es decoración', "From nothing, it's decoration", '什么都不挡，只是装饰', '何も守らない、かざり')}), '4': act(('¿Quiénes están cerca de home y pueden recibir un bate lanzado?', 'Who is near home and could get hit by a thrown bat?', '谁在本垒附近，可能被扔出去的球棒打到？', 'ホームの近くにいて、投げたバットに当たるかもしれないのはだれ？'), ('¡Eso es! Ellos están pegados.', "That's it! They're right there.", '对了！他们就在旁边。', 'そのとおり！すぐそばにいる。'), ('Por ellos se deja caer, no se lanza.', "Because of them you drop it, you don't throw it.", '为了他们，要放下，不能扔。', 'だから投げずに、落とすんだ。'), opts={'a': ('El catcher y el umpire', 'The catcher and the umpire', '捕手和裁判', 'キャッチャーと審判'), 'b': ('Solo el público', 'Only the crowd', '只有观众', 'お客さんだけ'), 'c': ('Nadie', 'Nobody', '没有人', 'だれもいない')}), '5': act(('Un casco bien ajustado no se mueve aunque corras rápido', "A well-fitted helmet doesn't move even if you run fast", '戴合适的头盔，就算你跑得很快也不会晃', 'ぴったりのヘルメットは、速く走ってもずれない'), ('¡Bien! Ajustado es seguro.', 'Good! Fitted is safe.', '很好！合适就安全。', 'いいね！ぴったりなら安全。'), ('Verdadero: si baila en tu cabeza, pide ayuda para ajustarlo.', 'True: if it wobbles on your head, ask for help to fit it.', '对：如果它在头上晃，就请人帮你调整。', '正しい：頭でぐらぐらしたら、合わせてもらおう。')), '6': act(('¿Cuál imagen muestra al bateador correcto tras conectar?', 'Which picture shows the right batter after making contact?', '哪张图是击中球后做得对的击球员？', '打ったあと、正しいバッターはどの絵？'), ('¡Eso es! Así se hace.', "That's it! That's how it's done.", '对了！就该这样。', 'そのとおり！そうやるんだ。'), ('Bate abajo, casco arriba, a correr.', 'Bat down, helmet up, run.', '球棒放下，头盔戴上，快跑。', 'バットは下、ヘルメットは上、さあ走れ。'), opts={'a': ('Bate cayendo junto a home y corredor con casco puesto', 'Bat dropping next to home and runner with his helmet on', '球棒掉在本垒旁边，跑垒员戴着头盔', 'ホームのそばにバットが落ちて、ランナーはヘルメットをかぶっている'), 'b': ('Bate volando por el aire', 'Bat flying through the air', '球棒在空中飞', 'バットが空中を飛んでいる'), 'c': ('Corredor sin casco', 'Runner without a helmet', '没戴头盔的跑垒员', 'ヘルメットなしのランナー')})})
map_titles['16.5'] = ('Soltar el bate y usar el casco', 'Dropping the bat and wearing the helmet', '放下球棒，戴好头盔', 'バットを置いて、ヘルメットをかぶる')
exams_v3['16'] = {'1': {'q': ('¿Dónde deben ir los dos pies del bateador?', "Where must both of the batter's feet go?", '击球员的双脚必须放在哪里？', 'バッターの両足はどこ？'), 'opts': {'a': ("Dentro de la caja de bateo (batter's box)", "Inside the batter's box", "击球员区里（batter's box）", "バッターボックスの中（batter's box）"), 'b': ('Fuera de la caja, donde quiera', 'Outside the box, wherever he wants', '在击球员区外面，随便哪里', 'ボックスの外、どこでも'), 'c': ('Un pie sobre home', 'One foot on home', '一只脚踩在本垒上', '片足をホームに')}}, '2': {'q': ('Agarrar el bate apretándolo con toda la fuerza hace el swing…', 'Squeezing the bat with all your strength makes the swing…', '用尽全力捏紧球棒，挥棒会……', 'ありったけの力でバットをにぎると、スイングは……'), 'opts': {'a': ('Más lento', 'Slower', '更慢', 'おそくなる'), 'b': ('Más rápido siempre', 'Always faster', '总是更快', 'いつも速くなる'), 'c': ('No cambia nada', "It doesn't change anything", '没有任何变化', '何もかわらない')}}, '3': {'q': ('¿Desde qué momento sigues la bola con los ojos?', 'From what moment do you follow the ball with your eyes?', '你从什么时候开始用眼睛追球？', 'いつから目でボールを追う？'), 'opts': {'a': ('Desde que sale de la mano del pitcher', "From when it leaves the pitcher's hand", '从球离开投手的手开始', 'ピッチャーの手をはなれたときから'), 'b': ('Cuando ya pasó por tu lado', 'When it has already gone by you', '球已经过去以后', 'もう横を通りすぎたとき'), 'c': ('Solo en el swing', 'Only on the swing', '只在挥棒时', 'スイングのときだけ')}}, '4': {'q': ('El bateador empieza el swing y se frena a mitad de camino. ¿Qué es y quién decide?', 'The batter starts the swing and stops halfway. What is it and who decides?', '击球员开始挥棒，挥到一半停住了。这是什么？由谁决定？', 'バッターがスイングを始めて、とちゅうで止めた。これは何で、だれが決める？'), 'opts': {'a': ('Swing a medias (checked swing): decide el umpire de home', 'Checked swing: the home plate umpire decides', '半挥棒（checked swing）：本垒裁判决定', 'ハーフスイング（checked swing）：球審が決める'), 'b': ('Foul tip: decide el catcher', 'Foul tip: the catcher decides', '擦棒球：捕手决定', 'ファウルチップ：キャッチャーが決める'), 'c': ('Toque: decide el coach', 'Bunt: the coach decides', '触击：教练决定', 'バント：コーチが決める')}}, '5': {'q': ('¡Tic! La bola roza el bate y el catcher la atrapa directo. ¿Qué es?', 'Tick! The ball brushes the bat and the catcher catches it directly. What is it?', '嗒！球擦过球棒，捕手直接接住。这是什么？', 'チッ！ボールがバットをかすめて、キャッチャーが直接とった。これは？'), 'opts': {'a': ('Foul tip: cuenta como strike y la bola sigue viva', 'Foul tip: it counts as a strike and the ball stays live', '擦棒球：算好球，球继续是活球', 'ファウルチップ：ストライクで、ボールはインプレー'), 'b': ('Foul común y bola muerta', 'Regular foul and dead ball', '普通界外球，死球（比赛停止）', 'ふつうのファウルで、ボールデッド'), 'c': ('Bola, porque rozó el bate', 'Ball, because it brushed the bat', '坏球，因为擦到了球棒', 'ボール。バットにかすめたから')}}, '6': {'q': ('El roce no fue atrapado por el catcher y cayó al suelo. ¿Qué es?', "The brush wasn't caught by the catcher and dropped to the ground. What is it?", '擦棒的球捕手没接住，掉到了地上。这是什么？', 'かすめた球をキャッチャーがとれずに、地面に落ちた。これは？'), 'opts': {'a': ('Foul normal', 'Regular foul', '普通的界外球', 'ふつうのファウル'), 'b': ('Foul tip atrapado', 'Caught foul tip', '被接住的擦棒球', 'とったファウルチップ'), 'c': ('Strike tres seguro', 'Sure strike three', '肯定是第三个好球', 'たしかにストライク・スリー')}}, '7': {'q': ('¿Cuál es el trabajo del bateador en el toque de sacrificio?', "What is the batter's job on a sacrifice bunt?", '牺牲触击时，击球员的任务是什么？', '犠牲バントで、バッターのしごとは？'), 'opts': {'a': ('Tocar suave para que el compañero avance, aceptando su out', 'Bunt softly so the teammate moves up, accepting his out', '轻轻触击让队友前进，接受自己出局', 'やさしくバントして仲間を進め、自分のアウトを受け入れる'), 'b': ('Llegar a salvo como sea', 'Be safe no matter what', '不管怎样都要安全上垒', 'なんとしてもセーフになる'), 'c': ('Hacer swing completo despacio', 'Take a full swing slowly', '慢慢地全力挥棒', 'ゆっくりフルスイングする')}}, '8': {'q': ('Corriendo a primera, la última parte del camino se corre…', 'Running to first, the last part of the way is run…', '跑向一垒时，最后一段路要……', '一塁へ走るとき、最後のところは……'), 'opts': {'a': ('Dentro del carril del corredor, junto a la línea', "Inside the runner's lane, next to the line", '在跑者通道里，线的旁边', 'ランナーのレーンの中、線のそば'), 'b': ('Por el medio del cuadro', 'Through the middle of the infield', '从内野中间', '内野のまんなか'), 'c': ('Por donde sea más corto', 'Wherever is shortest', '哪里最近走哪里', 'いちばん近いところ')}}, '9': {'q': ('Si corres por dentro del campo y estorbas el tiro a primera, el umpire puede…', 'If you run inside the field and get in the way of the throw to first, the umpire can…', '如果你跑在场内，挡住了传向一垒的球，裁判可以……', 'グラウンドの内がわを走って一塁への送球のじゃまをしたら、審判は……'), 'opts': {'a': ('Cantarte out por interferencia', 'Call you out for interference', '判你妨碍出局', '守備妨害でアウトにする'), 'b': ('Darte segunda base', 'Give you second base', '给你上二垒', '二塁をあげる'), 'c': ('No ver nada', 'Not see anything', '什么都没看到', '何も見ない')}}, '10': {'q': ('Conectaste un hit. ¿Qué haces con el bate?', 'You got a hit. What do you do with the bat?', '你打出了安打。你怎么处理球棒？', 'ヒットを打った。バットはどうする？'), 'opts': {'a': ('Lo dejo caer suave junto a home', 'I drop it softly next to home', '我让它轻轻掉在本垒旁边', 'ホームのそばにそっと落とす'), 'b': ('Lo lanzo hacia la banca', 'I throw it toward the dugout', '我把它扔向休息区', 'ベンチに向かって投げる'), 'c': ('Lo cargo hasta primera', 'I carry it all the way to first', '我一路拿到一垒', '一塁まで持っていく')}}, '11': {'q': ('¿Hasta cuándo llevas el casco puesto corriendo las bases?', 'Until when do you keep your helmet on running the bases?', '跑垒时，头盔要戴到什么时候？', '塁を走るとき、ヘルメットはいつまでかぶる？'), 'opts': {'a': ('Hasta llegar a la banca', 'Until I reach the dugout', '一直到回到休息区', 'ベンチに着くまで'), 'b': ('Hasta primera base', 'Until first base', '到一垒为止', '一塁まで'), 'c': ('Me lo quito al conectar', 'I take it off when I make contact', '击中球就摘下来', '打ったらぬぐ')}}, '12': {'q': ('El casco al correr protege sobre todo de…', 'Running, the helmet mostly protects you from…', '跑垒时，头盔主要保护你不受……', '走るとき、ヘルメットがおもに守るのは……'), 'opts': {'a': ('Un tiro desviado o una caída', 'A wild throw or a fall', '偏了的传球或摔倒', 'それた送球や、ころぶこと'), 'b': ('El sol únicamente', 'Only the sun', '只有太阳', '太陽だけ'), 'c': ('Los gritos del público', 'The shouts from the crowd', '观众的叫喊', 'お客さんの声')}}}
