levels['17'] = dict(title=('Estrategia del equipo', 'Team strategy', '球队战术', 'チームの作戦'), badge=('Estratega', 'Strategist', '战术大师', '作戦家'))
lesson('17.1', ('La base por bolas intencional', 'The intentional walk', '故意四坏球', '敬遠'), ('Entender que la defensa a veces decide no competir contra un bateador peligroso y lo manda a primera a propósito, y que la forma de darla cambia según la liga: se pregunta al coach.', "Understand that the defense sometimes decides not to compete against a dangerous batter and sends him to first on purpose, and that the way it's given changes by league: ask the coach.", '明白防守方有时决定不和危险的击球员对决，故意让他上一垒；而且怎么执行，每个联赛都不一样：问问教练。', '守備はときどき、こわいバッターと勝負しないで、わざと一塁へ歩かせることがある。そのやり方はリーグでちがうから、コーチに聞こう。'), [('Viene el bateador más fuerte del otro equipo y primera está libre.', "The other team's strongest batter is up and first base is open.", '对方最强的击球员上场了，一垒没人。', '相手チームでいちばん強いバッターが来た。一塁はあいている。'), ('A veces la defensa toma una decisión fría: no competir con él y mandarlo a primera caminando a propósito.', 'Sometimes the defense makes a cool-headed decision: not compete with him and send him to first, walking, on purpose.', '有时防守方会冷静地做决定：不和他对决，故意让他走上一垒。', 'ときどき守備は、れいせいに決める：勝負しないで、わざと一塁へ歩かせる。'), ('Eso es la base por bolas intencional, en inglés intentional walk.', "That's the intentional walk.", '这就是故意四坏球，英语叫 intentional walk。', 'これが敬遠、英語で intentional walk。'), ('No es miedo: es estrategia, para buscar un out más fácil con el siguiente bateador.', "It's not fear: it's strategy, to look for an easier out against the next batter.", '这不是害怕：是战术，为了对下一个击球员拿一个更容易的出局。', 'こわいからじゃない：作戦だ。次のバッターで、とりやすいアウトをねらうため。'), ('Ojo: la forma de darla cambia según la liga — en algunas se lanzan las bolas, en otras basta avisar al umpire —.', "Careful: the way it's given changes by league — in some the balls are pitched, in others it's enough to tell the umpire.", '注意：每个联赛的做法不一样——有的要把坏球投出来，有的只要告诉裁判就行。', '気をつけて：やり方はリーグでかわる——ボールを投げるリーグもあれば、審判に知らせるだけのリーグもある。'), ('En tu liga puede ser distinto: pregúntale a tu coach cómo se hace.', "It may be different in your league: ask your coach how it's done.", '你们联赛可能不一样：问问你的教练是怎么做的。', '君のリーグではちがうかもしれない：どうやるか、コーチに聞いてみよう。')], {'1': act(('¿Qué es la base por bolas intencional?', 'What is the intentional walk?', '什么是故意四坏球？', '敬遠って何？'), ('¡Eso es! Decisión del equipo.', "That's it! A team decision.", '对了！是球队的决定。', 'そのとおり！チームの決定。'), ('Estrategia, no accidente.', 'Strategy, not an accident.', '是战术，不是意外。', '作戦で、うっかりじゃない。'), opts={'a': ('Mandar al bateador a primera a propósito, sin competir con él', 'Sending the batter to first on purpose, without competing with him', '故意让击球员上一垒，不和他对决', 'わざとバッターを一塁へ。勝負しない'), 'b': ('Un error del pitcher', "A pitcher's mistake", '投手的失误', 'ピッチャーのミス'), 'c': ('Cuatro bolas por accidente', 'Four balls by accident', '不小心投了四个坏球', 'うっかり4つのボール')}), '2': act(('¿Por qué se da una base intencional?', 'Why is an intentional walk given?', '为什么要故意四坏球？', 'どうして敬遠するの？'), ('¡Correcto! Se piensa en equipo.', 'Correct! You think as a team.', '正确！要为球队着想。', '正解！チームで考える。'), ('Se cambia un bateador peligroso por uno más manejable.', 'You trade a dangerous batter for an easier one.', '用一个危险的击球员，换一个好对付的。', 'こわいバッターを、勝負しやすいバッターにかえる。'), opts={'a': ('Para buscar un out más fácil con el siguiente bateador', 'To look for an easier out against the next batter', '为了对下一个击球员拿一个更容易的出局', '次のバッターで、とりやすいアウトをねらうため'), 'b': ('Para terminar antes el juego', 'To end the game sooner', '为了早点结束比赛', '試合を早く終わらせるため'), 'c': ('Para descansar al catcher', 'To rest the catcher', '为了让捕手休息', 'キャッチャーを休ませるため')}), '3': act(('La base intencional significa que el equipo tiene miedo y juega mal', 'The intentional walk means the team is afraid and plays badly', '故意四坏球说明球队害怕，打得不好', '敬遠は、チームがこわがっていて、プレーが下手ということ'), ('¡Bien! Es estrategia.', "Good! It's strategy.", '很好！这是战术。', 'いいね！作戦だ。'), ('Falso: los mejores equipos la usan pensando.', 'False: the best teams use it, thinking.', '错：最强的球队也会动脑筋用它。', 'まちがい：いちばん強いチームも、考えて使う。')), '4': act(('¿Cómo se da la base intencional en tu liga?', 'How is the intentional walk given in your league?', '在你们联赛，故意四坏球怎么执行？', '君のリーグでは、敬遠はどうやる？'), ('¡Eso es! Cada liga tiene su forma.', "That's it! Each league has its way.", '对了！每个联赛有自己的做法。', 'そのとおり！リーグごとにやり方がある。'), ('En tu liga puede ser distinto: pregúntale a tu coach.', 'It may be different in your league: ask your coach.', '你们联赛可能不一样：问问你的教练。', '君のリーグではちがうかもしれない：コーチに聞いてみよう。'), opts={'a': ('Como diga mi liga: pregúntale a tu coach', 'However my league says: ask your coach', '照我们联赛的规定：问问你的教练', 'リーグの決まりどおり：コーチに聞こう'), 'b': ('Siempre lanzando bolas altísimas', 'Always pitching really high balls', '总是投很高的坏球', 'いつもすごく高いボールを投げる'), 'c': ('Siempre sin lanzar nada', 'Always without pitching anything', '总是一球都不投', 'いつも何も投げない')}), '5': act(('Con primera ocupada, regalar la base intencional suele ser mala idea', 'With first base occupied, giving the intentional walk is usually a bad idea', '一垒有人时，故意四坏球通常不是好主意', '一塁がうまっているとき、敬遠はたいていよくない'), ('¡Correcto! Llenas las bases gratis.', 'Correct! You load the bases for free.', '正确！你白白让垒都满了。', '正解！ただで塁がうまる。'), ('Verdadero: se usa sobre todo con primera libre.', "True: it's mostly used with first base open.", '对：它主要在一垒没人时用。', '正しい：おもに一塁があいているときに使う。')), '6': act(('La defensa avisa que manda al bateador a primera a propósito. ¿Qué pasa?', 'The defense announces it is sending the batter to first on purpose. What happens?', '防守方宣布故意让击球员上一垒。会怎样？', '守備が、わざとバッターを一塁へ歩かせると知らせた。どうなる？'), ('¡Bien! A primera caminando.', 'Good! To first, walking.', '很好！走上一垒。', 'いいね！歩いて一塁へ。'), ('Decisión anunciada: a primera.', 'Decision announced: to first.', '宣布了：上一垒。', '決定を知らせた：一塁へ。'), opts={'a': ('Base por bolas intencional: el bateador va a primera', 'Intentional walk: the batter goes to first', '故意四坏球：击球员上一垒', '敬遠：バッターは一塁へ'), 'b': ('Ponche cantado', 'Strikeout called', '判三振', '三振のコール'), 'c': ('Bola muerta y nadie avanza', 'Dead ball and nobody moves up', '死球（比赛停止），谁都不前进', 'ボールデッドで、だれも進まない')})})
map_titles['17.1'] = ('La base por bolas intencional', 'The intentional walk', '故意四坏球', '敬遠')
lesson('17.2', ('El bateo y corrido', 'The hit and run', '打跑战术', 'ヒットエンドラン'), ('Entender el bateo y corrido (hit and run): el corredor sale con el lanzamiento y el bateador busca contacto para poner la bola en juego y protegerlo.', 'Understand the hit and run: the runner takes off with the pitch and the batter looks for contact to put the ball in play and protect him.', '明白打跑战术（hit and run）：跑垒员随着投球起跑，击球员想办法碰到球，把球打进场内来保护他。', 'ヒットエンドラン（hit and run）を知ろう：ランナーは投球と同時にスタートして、バッターはボールを前に飛ばしてランナーを守る。'), [('El coach cruza los brazos y manda una jugada valiente: el bateo y corrido, en inglés hit and run.', 'The coach crosses his arms and calls a brave play: the hit and run.', '教练交叉双臂，下了一个大胆的战术：打跑战术，英语叫 hit and run。', 'コーチがうでを組んで、ゆうかんな作戦を出す：ヒットエンドラン、英語で hit and run。'), ('Funciona así: el corredor de primera sale corriendo con el lanzamiento, como si robara, y el bateador hace swing buscando contacto, aunque el lanzamiento no sea perfecto, para poner la bola en juego y proteger al corredor.', "It works like this: the runner on first takes off with the pitch, as if he were stealing, and the batter swings looking for contact, even if the pitch isn't perfect, to put the ball in play and protect the runner.", '是这样进行的：一垒跑垒员随着投球起跑，就像盗垒一样；击球员挥棒，想办法碰到球，就算这一球不完美，也要把球打进场内，保护跑垒员。', 'やり方はこう：一塁ランナーは投球と同時に、盗塁みたいに走り出す。バッターは、投球がかんぺきじゃなくても、ボールに当てようとスイングして、ボールを前に飛ばしてランナーを守る。'), ('Si la bola pasa por el hueco que dejó el defensor que cubrió segunda, ¡es perfecta!', "If the ball goes through the hole left by the fielder who covered second, it's perfect!", '如果球从去补位二垒的防守球员留下的空当穿过去，那就太完美了！', 'ボールが、二塁カバーに行った守備のあけたすきまをぬけたら、かんぺき！'), ('Es trabajo de dos: uno corre, el otro protege.', "It's a job for two: one runs, the other protects.", '这是两个人的工作：一个跑，一个保护。', '二人のしごと：一人が走って、もう一人が守る。')], {'1': act(('¿Qué es el bateo y corrido (hit and run)?', 'What is the hit and run?', '什么是打跑战术（hit and run）？', 'ヒットエンドラン（hit and run）って何？'), ('¡Eso es! Jugada de dos.', "That's it! A play for two.", '对了！两个人的战术。', 'そのとおり！二人のプレー。'), ('Uno corre y el otro lo protege bateando.', 'One runs and the other protects him by hitting.', '一个跑，另一个用击球来保护他。', '一人が走って、もう一人が打って守る。'), opts={'a': ('El corredor sale con el lanzamiento y el bateador busca contacto', 'The runner takes off with the pitch and the batter looks for contact', '跑垒员随投球起跑，击球员想办法碰到球', 'ランナーは投球と同時にスタート、バッターはボールに当てる'), 'b': ('El bateador corre antes de batear', 'The batter runs before hitting', '击球员先跑再打', 'バッターが打つ前に走る'), 'c': ('Dos bateadores a la vez', 'Two batters at once', '两个击球员同时打', 'バッターが二人同時に')}), '2': act(('¿Por qué el bateador busca contacto aunque el lanzamiento sea malo?', 'Why does the batter look for contact even if the pitch is bad?', '为什么就算这一球不好，击球员也要想办法碰到？', 'どうして投球が悪くても、バッターは当てにいくの？'), ('¡Correcto! Su swing protege.', 'Correct! His swing protects.', '正确！他的挥棒是保护。', '正解！スイングが守る。'), ('Sin contacto, el corredor queda vendido en el robo.', 'Without contact, the runner is left hanging on the steal.', '碰不到球，跑垒员就只能硬着头皮盗垒。', '当たらないと、ランナーは盗塁で取りのこされる。'), opts={'a': ('Para proteger al corredor que ya salió', 'To protect the runner who already took off', '为了保护已经起跑的跑垒员', 'もうスタートしたランナーを守るため'), 'b': ('Para hacer jonrón', 'To hit a home run', '为了打本垒打', 'ホームランを打つため'), 'c': ('Para cansar al catcher', 'To tire out the catcher', '为了让捕手累', 'キャッチャーをつかれさせるため')}), '3': act(('En el bateo y corrido, el corredor espera en su base a ver el batazo', 'On the hit and run, the runner waits on his base to see the hit', '打跑战术时，跑垒员在垒上等着看击球', 'ヒットエンドランでは、ランナーは塁で打球を見て待つ'), ('¡Bien! Sale con el lanzamiento.', 'Good! He takes off with the pitch.', '很好！他随着投球起跑。', 'いいね！投球と同時にスタート。'), ('Falso: arranca con el lanzamiento, sin esperar.', 'False: he takes off with the pitch, without waiting.', '错：他随着投球起跑，不等。', 'まちがい：待たずに、投球と同時にスタートする。')), '4': act(('¿Qué hueco aprovecha la bola en el bateo y corrido?', 'What hole does the ball use on the hit and run?', '打跑战术时，球从哪个空当穿过去？', 'ヒットエンドランで、ボールはどのすきまをぬける？'), ('¡Eso es! Por ahí pasa la bola.', "That's it! That's where the ball goes through.", '对了！球就从那里穿过。', 'そのとおり！そこをボールがぬける。'), ('La defensa se mueve y el hueco aparece.', 'The defense moves and the hole appears.', '防守一移动，空当就出现了。', '守備が動くと、すきまができる。'), opts={'a': ('El que deja el defensor que salió a cubrir segunda', 'The one left by the fielder who went to cover second', '去补位二垒的防守球员留下的空当', '二塁カバーに行った守備のあけたすきま'), 'b': ('El hueco de la banca', 'The hole in the dugout', '休息区的洞', 'ベンチのあな'), 'c': ('Ninguno, se batea al aire siempre', 'None, you always hit it in the air', '没有，总是打高飞球', 'ない、いつもフライを打つ')}), '5': act(('El bateo y corrido es una jugada que manda el coach con una señal', 'The hit and run is a play the coach calls with a sign', '打跑战术是教练用暗号下的战术', 'ヒットエンドランは、コーチがサインで出す作戦'), ('¡Bien! La manda el coach.', 'Good! The coach calls it.', '很好！是教练下的。', 'いいね！コーチが出す。'), ('Verdadero: por eso hay que mirar las señales.', "True: that's why you have to watch the signs.", '对：所以要看暗号。', '正しい：だからサインを見なきゃ。')), '6': act(('Si el bateador no le pega a la bola en el bateo y corrido, ¿qué le espera al corredor?', "If the batter doesn't hit the ball on the hit and run, what's waiting for the runner?", '打跑战术时如果击球员没打到球，跑垒员会怎样？', 'ヒットエンドランでバッターが当てられなかったら、ランナーはどうなる？'), ('¡Correcto! Por eso el contacto manda.', "Correct! That's why contact rules.", '正确！所以碰到球最重要。', '正解！だから当てることが大事。'), ('Sin batazo, el corredor queda solo contra el tiro.', 'With no hit, the runner is alone against the throw.', '没打到球，跑垒员只能独自面对传球。', '打球がないと、ランナーはひとりで送球と勝負。'), opts={'a': ('Un posible out robando, porque salió sin protección', 'A possible out stealing, because he left without protection', '可能盗垒出局，因为他没有保护就出发了', '盗塁でアウトになるかも。守りなしで出たから'), 'b': ('Nada, vuelve gratis', 'Nothing, he goes back for free', '没事，他可以白白回去', '何もない、ただでもどれる'), 'c': ('Una base extra automática', 'An automatic extra base', '自动多进一个垒', '自動で1つ進める')})})
map_titles['17.2'] = ('El bateo y corrido', 'The hit and run', '打跑战术', 'ヒットエンドラン')
lesson('17.3', ('El squeeze: el toque que anota', 'The squeeze: the bunt that scores', '抢分触击：能得分的触击', 'スクイズ：点をとるバント'), ('Entender el squeeze: con corredor en tercera, el bateador toca la bola para que el corredor anote; en el squeeze suicida el corredor arranca con el lanzamiento.', 'Understand the squeeze: with a runner on third, the batter bunts so the runner scores; on the suicide squeeze the runner takes off with the pitch.', '明白抢分触击：三垒有人时，击球员触击让跑垒员得分；强迫抢分时，跑垒员随着投球起跑。', 'スクイズを知ろう：三塁にランナーがいるとき、バッターがバントしてランナーを帰す。スーサイドスクイズでは、ランナーは投球と同時にスタートする。'), [('La jugada más atrevida con corredor en tercera: el squeeze, en inglés squeeze play.', 'The boldest play with a runner on third: the squeeze play.', '三垒有人时最大胆的战术：抢分触击，英语叫 squeeze play。', '三塁にランナーがいるときの、いちばん大たんなプレー：スクイズ、英語で squeeze play。'), ('El bateador toca la bola suavecita y el corredor de tercera corre a home para anotar.', 'The batter bunts the ball very softly and the runner on third runs home to score.', '击球员轻轻触击，三垒跑垒员冲回本垒得分。', 'バッターがそっとバントして、三塁ランナーがホームへ走って得点する。'), ('Hay una versión todavía más valiente: el squeeze suicida, suicide squeeze, donde el corredor arranca con el lanzamiento, antes de saber si el toque salió bien.', "There's an even braver version: the suicide squeeze, where the runner takes off with the pitch, before knowing if the bunt worked.", '还有更大胆的版本：强迫抢分，suicide squeeze，跑垒员随着投球就起跑，还不知道触击成不成功。', 'もっとゆうかんなやり方もある：スーサイドスクイズ、suicide squeeze。バントがうまくいくかわかる前に、ランナーは投球と同時にスタートする。'), ('Si el bateador falla el toque, el corredor queda atrapado sin base.', 'If the batter misses the bunt, the runner is caught without a base.', '如果击球员触击失败，跑垒员就会被困住，没有垒可回。', 'バッターがバントに失敗したら、ランナーは塁がなくて、つかまってしまう。'), ('Por eso el squeeze se practica mucho y solo se manda cuando el coach confía en el toque.', "That's why the squeeze is practiced a lot and only called when the coach trusts the bunt.", '所以抢分触击要多练习，只有教练相信这次触击时才会下这个战术。', 'だからスクイズはたくさん練習して、コーチがバントを信じているときだけ出す。')], {'1': act(('¿Qué busca el squeeze?', 'What is the squeeze for?', '抢分触击是为了什么？', 'スクイズは何のため？'), ('¡Eso es! Toque y carrera.', "That's it! Bunt and run.", '对了！触击加得分。', 'そのとおり！バントで得点。'), ('La bola suave trae la carrera a home.', 'The soft ball brings the run home.', '轻轻的一球把分数带回本垒。', 'やさしい打球が得点を帰す。'), opts={'a': ('Que el corredor de tercera anote con un toque de bola', 'For the runner on third to score on a bunt', '让三垒跑垒员靠触击得分', '三塁ランナーをバントで帰すため'), 'b': ('Un jonrón desde tercera', 'A home run from third', '从三垒打出本垒打', '三塁からホームラン'), 'c': ('Cansar al pitcher', 'To tire out the pitcher', '为了让投手累', 'ピッチャーをつかれさせるため')}), '2': act(('¿Qué hace el bateador en el squeeze?', 'What does the batter do on the squeeze?', '抢分触击时击球员做什么？', 'スクイズでバッターは何をする？'), ('¡Correcto! Toque seguro.', 'Correct! A sure bunt.', '正确！稳稳的触击。', '正解！たしかなバント。'), ('Su único trabajo: que la bola toque el bate.', 'His only job: the ball has to touch the bat.', '他唯一的任务：让球碰到球棒。', 'しごとは1つ：ボールをバットに当てること。'), opts={'a': ('Toca la bola suave para alejarla de home', 'He bunts the ball softly to move it away from home', '轻轻触击，让球离开本垒', 'そっとバントして、ボールをホームからはなす'), 'b': ('Hace swing completo', 'He takes a full swing', '全力挥棒', 'フルスイングする'), 'c': ('Se aparta del lanzamiento', 'He steps away from the pitch', '躲开投球', '投球からはなれる')}), '3': act(('En el squeeze suicida, el corredor espera en tercera hasta ver el toque', 'On the suicide squeeze, the runner waits at third until he sees the bunt', '强迫抢分时，跑垒员在三垒等着看触击', 'スーサイドスクイズでは、ランナーはバントを見るまで三塁で待つ'), ('¡Bien! Arranca con el lanzamiento.', 'Good! He takes off with the pitch.', '很好！他随着投球起跑。', 'いいね！投球と同時にスタート。'), ('Falso: por eso es tan atrevido, sale antes.', "False: that's why it's so bold, he leaves early.", '错：所以才这么大胆，他提早出发。', 'まちがい：だから大たんなんだ。先に出る。')), '4': act(('Si en el squeeze suicida el bateador falla el toque, ¿qué pasa con el corredor?', 'If the batter misses the bunt on the suicide squeeze, what happens to the runner?', '强迫抢分时如果击球员触击失败，跑垒员会怎样？', 'スーサイドスクイズでバッターがバントに失敗したら、ランナーは？'), ('¡Eso es! Ese es el riesgo.', "That's it! That's the risk.", '对了！这就是风险。', 'そのとおり！それがリスク。'), ('Sin toque, el corredor queda vendido.', 'No bunt, and the runner is left hanging.', '没有触击，跑垒员就被困住了。', 'バントがないと、ランナーは取りのこされる。'), opts={'a': ('Queda atrapado camino a home, casi sin defensa', "He's caught on the way home, almost defenseless", '他在跑回本垒的路上被困住，几乎没办法', 'ホームへのとちゅうで、つかまってしまう'), 'b': ('Anota igual', 'He scores anyway', '他照样得分', 'それでも得点'), 'c': ('Vuelve a tercera sin problema', 'He goes back to third with no problem', '他轻松回到三垒', '問題なく三塁にもどる')}), '5': act(('El squeeze solo se manda cuando el coach confía en el toque del bateador', "The squeeze is only called when the coach trusts the batter's bunt", '只有教练相信击球员的触击时，才会下抢分触击', 'スクイズは、コーチがバッターのバントを信じているときだけ出す'), ('¡Correcto! Confianza y práctica.', 'Correct! Trust and practice.', '正确！信任加练习。', '正解！信らいと練習。'), ('Verdadero: es una jugada de práctica, no de suerte.', "True: it's a play of practice, not luck.", '对：这是靠练习的战术，不是靠运气。', '正しい：練習のプレーで、運じゃない。')), '6': act(('Toca la base desde donde arranca el corredor del squeeze', 'Tap the base the squeeze runner starts from', '点一下抢分触击时跑垒员出发的垒', 'スクイズのランナーがスタートする塁をタッチしよう'), ('¡Bien! Desde tercera.', 'Good! From third.', '很好！从三垒。', 'いいね！三塁から。'), ('Tercera a home: ese es el squeeze.', "Third to home: that's the squeeze.", '三垒到本垒：这就是抢分触击。', '三塁からホーム：それがスクイズ。'), answer=('Tercera base', 'Third base', '三垒', '三塁'))})
map_titles['17.3'] = ('El squeeze: el toque que anota', 'The squeeze: the bunt that scores', '抢分触击：能得分的触击', 'スクイズ：点をとるバント')
lesson('17.4', ('La defensa se acomoda', 'The defense adjusts', '防守站位调整', '守備が位置をかえる'), ('Entender que la defensa se acomoda según el bateador y la situación: cuadro adentro para buscar el out en home, cuadro atrás para el doble play, y jardineros según la fuerza del bateador.', "Understand defensive positioning: the defense adjusts to the batter and the situation: infield in to go for the out at home, infield back for the double play, and outfielders according to the batter's strength.", '明白防守会根据击球员和局面调整站位：内野前移，为了在本垒拿出局；内野后退，为了双杀；外野手则根据击球员的力量调整。', '守備はバッターと場面に合わせて位置をかえる：ホームでアウトをとるなら前進守備、ダブルプレーなら定位置、外野はバッターの力に合わせる。'), [('La defensa no se para siempre igual: se acomoda, en inglés defensive shift y positioning.', "The defense doesn't always stand the same way: it adjusts its positioning.", '防守不会永远站在同样的位置：会调整站位，英语叫 defensive shift 和 positioning。', '守備はいつも同じ場所に立つわけじゃない：守備シフト、英語で defensive shift や positioning で位置をかえる。'), ('Si hay corredor en tercera y el juego está cerrado, el cuadro juega adentro, infield in, pegado al pasto, para tirar rápido a home.', "If there's a runner on third and the game is close, the infield plays in, right at the edge of the grass, to throw home fast.", '如果三垒有人，比分又很接近，内野就前移，infield in，贴近草地，好快速传回本垒。', '三塁にランナーがいて、試合がせっていたら、内野は前進守備、infield in。芝のところまで前に出て、すばやくホームへ投げる。'), ('Si se busca el doble play, el cuadro juega atrás, tranquilo, en su lugar de siempre.', "If you're looking for the double play, the infield plays back, calmly, in its usual spot.", '如果想打双杀，内野就退回平常的位置，从容防守。', 'ダブルプレーをねらうなら、内野はいつもの場所で、落ちついて守る。'), ('Con un bateador muy fuerte, los jardines dan pasos atrás.', 'With a very strong batter, the outfielders take steps back.', '遇到力量很大的击球员，外野手就往后退几步。', 'とても強いバッターのときは、外野は何歩か下がる。'), ('Cada posición cuenta una historia: el coach lee el juego y mueve a su gente como piezas de ajedrez.', 'Each position tells a story: the coach reads the game and moves his players like chess pieces.', '每个站位都有它的道理：教练读懂比赛，像下棋一样调动球员。', 'どの位置にもわけがある：コーチは試合を読んで、チェスのコマみたいに選手を動かす。')], {'1': act(('¿Por qué la defensa cambia de posición según la jugada?', 'Why does the defense change position depending on the play?', '为什么防守要根据局面改变站位？', 'どうして守備はプレーに合わせて位置をかえるの？'), ('¡Eso es! Cada lugar tiene un plan.', "That's it! Each spot has a plan.", '对了！每个站位都有计划。', 'そのとおり！どの場所にも作戦がある。'), ('Posición es estrategia.', 'Position is strategy.', '站位就是战术。', '位置は作戦だ。'), opts={'a': ('Para prepararse para la jugada que más le conviene', 'To get ready for the play that suits it best', '为了准备最有利的打法', 'いちばん合うプレーにそなえるため'), 'b': ('Para confundir al público', 'To confuse the crowd', '为了把观众弄糊涂', 'お客さんをまよわせるため'), 'c': ('Porque se aburre en el mismo sitio', 'Because it gets bored in the same spot', '因为站在同一个地方很无聊', '同じ場所はあきるから')}), '2': act(('Con corredor en tercera y juego cerrado, ¿cómo juega el cuadro?', 'Runner on third and a close game, how does the infield play?', '三垒有人、比分接近，内野怎么站？', '三塁にランナー、せった試合。内野はどう守る？'), ('¡Correcto! Cuadro adentro (infield in).', 'Correct! Infield in.', '正确！内野前移（infield in）。', '正解！前進守備（infield in）。'), ('Cerca de home para defender la carrera.', 'Close to home to defend the run.', '靠近本垒，守住这一分。', 'ホームの近くで、得点をふせぐ。'), opts={'a': ('Adentro, cerca, para tirar rápido a home', 'In, close, to throw home fast', '前移、靠近，快速传回本垒', '前に出て、すばやくホームへ投げる'), 'b': ('Muy atrás, junto a los jardines', 'Way back, next to the outfield', '远远退到外野旁边', 'ずっと下がって、外野のそば'), 'c': ('En la banca', 'In the dugout', '在休息区里', 'ベンチの中')}), '3': act(('¿Cuándo juega el cuadro atrás, en su lugar normal?', 'When does the infield play back, in its normal spot?', '内野什么时候退回平常的位置？', '内野がいつもの場所で守るのはいつ？'), ('¡Bien! Atrás para el doble play.', 'Good! Back for the double play.', '很好！退后打双杀。', 'いいね！ダブルプレーは定位置。'), ('Lejos de home, el tiro a home llegaría tarde: mejor dos outs.', 'Far from home, the throw home would be late: better two outs.', '离本垒太远，传回本垒会来不及：不如拿两个出局。', 'ホームから遠いと、ホームへの送球はまにあわない：アウト2つのほうがいい。'), opts={'a': ('Cuando busca el doble play con calma', "When it's calmly looking for the double play", '想从容地打双杀时', 'ダブルプレーを落ちついてねらうとき'), 'b': ('Cuando hay corredor en tercera y juego cerrado', "When there's a runner on third and a close game", '三垒有人、比分接近时', '三塁にランナーがいて、せった試合のとき'), 'c': ('Nunca', 'Never', '从来不', 'ぜったいない')}), '4': act(('Ante un bateador muy fuerte, los jardines suelen dar pasos atrás', 'Against a very strong batter, the outfielders usually take steps back', '遇到力量很大的击球员，外野手通常往后退几步', 'とても強いバッターのときは、外野はたいてい何歩か下がる'), ('¡Correcto! Respetan su fuerza.', 'Correct! They respect his strength.', '正确！他们尊重他的力量。', '正解！力をみとめている。'), ('Verdadero: espacio atrás para las bolas profundas.', 'True: room behind for the deep balls.', '对：为远球留出后面的空间。', '正しい：深い打球のために、うしろに場所をあける。')), '5': act(('¿Quién decide cómo se acomoda la defensa?', 'Who decides how the defense adjusts?', '谁决定防守怎么调整站位？', '守備の位置はだれが決める？'), ('¡Eso es! Lee y mueve.', "That's it! He reads and moves.", '对了！他读懂比赛，调动球员。', 'そのとおり！読んで、動かす。'), ('Mueve a sus jugadores como piezas de ajedrez.', 'He moves his players like chess pieces.', '他像下棋一样移动自己的球员。', '選手をチェスのコマみたいに動かすんだ。'), opts={'a': ('El coach, leyendo el juego', 'The coach, reading the game', '教练，看懂比赛后决定', 'コーチ。試合を読んで'), 'b': ('El bateador rival', "The other team's batter", '对方的击球员', '相手のバッター'), 'c': ('El público', 'The crowd', '观众', 'お客さん')}), '6': act(('Acomodar la defensa es hacer trampa', 'Adjusting the defense is cheating', '调整防守站位是作弊', '守備の位置をかえるのはずる'), ('¡Bien! Es estrategia legal.', "Good! It's legal strategy.", '很好！这是合规的战术。', 'いいね！ルールどおりの作戦だ。'), ('Falso: cada equipo se coloca como mejor le convenga.', 'False: each team sets up however suits it best.', '错：每支球队都可以按最有利的方式站位。', 'まちがい：どのチームも、いちばん合うように位置をとる。'))})
map_titles['17.4'] = ('La defensa se acomoda', 'The defense adjusts', '防守站位调整', '守備が位置をかえる')
lesson('17.5', ('El marcador decide la jugada y el walk-off', 'The score decides the play and the walk-off', '比分决定打法，再见安打', 'スコアがプレーを決める、サヨナラヒット'), ('Leer marcador, entrada y outs antes de cada jugada para decidir riesgos; y conocer el walk-off: el batazo que gana el juego en la última oportunidad y termina el partido en ese instante.', 'Read the score, inning and outs before every play to decide risks; and know the walk-off: the hit that wins the game in the last chance and ends it that very instant.', '每次比赛前都要看比分、局数和出局数，决定要不要冒险；还要认识再见安打：在最后的机会打出赢球的一击，比赛当场结束。', '1つ1つのプレーの前に、スコア、イニング、アウトを見て、どこまでせめるか決めよう。それから、サヨナラヒットを知ろう：最後のチャンスで試合に勝つ一打。そのしゅんかんに試合は終わる。'), [('Antes de cada jugada, los jugadores de Salón de la Fama miran tres cosas: el marcador, la entrada y los outs.', 'Before every play, Hall of Fame players look at three things: the score, the inning and the outs.', '每次比赛前，名人堂级的球员都会看三样东西：比分、局数和出局数。', 'プレーの前に、殿堂入りの選手は3つを見る：スコア、イニング、アウト。'), ('Con el juego empatado al final, un corredor se cuida distinto que ganando por mucho.', 'With the game tied at the end, a runner plays it differently than when winning by a lot.', '比赛最后打平时，跑垒员的跑法和大比分领先时不一样。', '最後に同点のときと、大きく勝っているときでは、ランナーの気をつけ方がちがう。'), ('Y escucha cómo se llama el momento más feliz del béisbol: si el equipo de casa batea en su última oportunidad, empata o pierde por poco, y un batazo trae la carrera que gana, eso es un walk-off: el juego se acaba en ese instante y todos salen a celebrar, porque el rival ya no tiene otro turno.', "And listen to what the happiest moment in baseball is called: if the home team bats in its last chance, tied or losing by a little, and a hit brings in the winning run, that's a walk-off: the game ends that very instant and everyone runs out to celebrate, because the other team has no more turns.", '再听听棒球里最快乐的时刻叫什么：如果主队在最后一次机会进攻，比分打平或只落后一点，一记击球带回了赢球的一分，这就是再见安打，英语叫 walk-off：比赛当场结束，大家冲出来庆祝，因为对手再也没有进攻机会了。', 'それから、野球でいちばんうれしいしゅんかんの名前を聞いて：ホームチームが最後のチャンスで、同点か少し負けていて、一打で勝ちこしの点が入ったら、それがサヨナラヒット、英語で walk-off。そのしゅんかんに試合は終わって、みんなでおいわい。相手にはもう攻撃がないからだ。'), ('Ganando el equipo de casa al llegar a ese turno, ni siquiera hace falta jugarlo: el juego ya terminó.', "If the home team is already winning when that turn comes, it doesn't even need to be played: the game is already over.", '如果轮到那一局时主队已经领先，那一局根本不用打：比赛已经结束了。', 'その攻撃の前にホームチームが勝っていたら、やる必要もない：試合はもう終わっている。'), ('El marcador no es solo números: decide qué riesgo vale la pena.', "The score isn't just numbers: it decides which risk is worth taking.", '比分不只是数字：它决定哪种风险值得冒。', 'スコアはただの数字じゃない：どのリスクをとる価値があるかを決める。')], {'1': act(('¿Qué tres datos miras antes de cada jugada?', 'What three things do you look at before every play?', '每次比赛前你看哪三样东西？', 'プレーの前に見る3つは？'), ('¡Eso es! Tres datos, una decisión.', "That's it! Three facts, one decision.", '对了！三个信息，一个决定。', 'そのとおり！3つの情報で、1つの決定。'), ('Con ellos sabes qué riesgo vale.', 'With them you know which risk is worth it.', '有了它们，你就知道哪种风险值得冒。', 'それで、どのリスクがいいかわかる。'), opts={'a': ('Marcador, entrada y outs', 'Score, inning and outs', '比分、局数和出局数', 'スコア、イニング、アウト'), 'b': ('El público, el clima y la banca', 'The crowd, the weather and the dugout', '观众、天气和休息区', 'お客さん、天気、ベンチ'), 'c': ('Mi promedio, mi guante y mi gorra', 'My average, my glove and my cap', '我的打击率、我的手套和我的帽子', '自分の打率、グラブ、ぼうし')}), '2': act(('¿Qué es un walk-off?', 'What is a walk-off?', '什么是再见安打？', 'サヨナラヒットって何？'), ('¡Correcto! Walk-off: juego terminado.', 'Correct! Walk-off: game over.', '正确！再见安打：比赛结束。', '正解！サヨナラ：試合終了。'), ('Carrera que gana y a celebrar: no hay otro turno.', "Winning run and celebrate: there's no other turn.", '赢球的一分，然后庆祝：没有下一局了。', '勝ちこしの点で、おいわい：次の攻撃はない。'), opts={'a': ('El batazo del equipo de casa que gana el juego en su última oportunidad y lo termina al instante', "The home team's hit that wins the game in its last chance and ends it instantly", '主队在最后机会打出、赢下比赛并让比赛当场结束的一击', 'ホームチームが最後のチャンスで試合に勝ち、すぐに試合を終わらせる一打'), 'b': ('El último out de la defensa', "The defense's last out", '防守的最后一个出局', '守備の最後のアウト'), 'c': ('Un jonrón en la práctica', 'A home run in practice', '练习时的本垒打', '練習でのホームラン')}), '3': act(('El walk-off solo lo puede dar el equipo de casa en su última oportunidad al bate', 'Only the home team can get a walk-off, in its last chance at bat', '只有主队在最后一次进攻机会时，才能打出再见安打', 'サヨナラは、ホームチームが最後の攻撃でしかできない'), ('¡Bien! Así es la jugada.', "Good! That's how the play works.", '很好！就是这样。', 'いいね！そういうプレーだ。'), ('Verdadero: el de casa siempre tiene su turno para responder.', 'True: the home team always gets its turn to answer.', '对：主队总会有回应的一局。', '正しい：ホームチームには、いつも反撃の攻撃がある。')), '4': act(('Si el equipo de casa ya va ganando al llegar a su último turno, ¿qué pasa?', 'If the home team is already winning when its last turn comes, what happens?', '如果轮到最后一局时主队已经领先，会怎样？', 'ホームチームが最後の攻撃の前にもう勝っていたら？'), ('¡Eso es! Ya ganaron.', "That's it! They already won.", '对了！他们已经赢了。', 'そのとおり！もう勝っている。'), ('No hay nada que remontar: juego acabado.', "There's nothing to come back from: game over.", '没有要追的分：比赛结束。', '追いかける点がない：試合終了。'), opts={'a': ('El juego ya terminó, no hace falta batearlo', "The game is already over, it doesn't need to bat", '比赛已经结束，不用再打', '試合はもう終わり。打たなくていい'), 'b': ('Se batea igual por costumbre', 'It bats anyway out of habit', '照习惯还是要打', 'いつものくせで打つ'), 'c': ('Se regala un turno al rival', 'A turn is given to the other team', '送给对手一局', '相手に攻撃をあげる')}), '5': act(('Con el juego muy abierto a favor, conviene arriesgar igual que en un juego empatado', "With the game wide open in your favor, it's best to take risks the same as in a tied game", '大比分领先时，冒险的方式和平手时一样', '大きく勝っているときも、同点のときと同じようにせめるのがいい'), ('¡Correcto! El marcador manda el riesgo.', 'Correct! The score sets the risk.', '正确！比分决定风险。', '正解！スコアがリスクを決める。'), ('Falso: cada marcador pide su jugada.', 'False: each score calls for its own play.', '错：每种比分都有适合它的打法。', 'まちがい：スコアごとに合うプレーがある。')), '6': act(('Última oportunidad de casa, juego empatado y un hit trae la carrera que gana. ¿Qué pasó?', "Home team's last chance, tied game, and a hit brings in the winning run. What happened?", '主队最后的机会，比分打平，一记安打带回了赢球的一分。发生了什么？', 'ホームチームの最後のチャンス、同点で、ヒットで勝ちこしの点が入った。何が起きた？'), ('¡Bien! A celebrar.', 'Good! Celebrate.', '很好！庆祝吧。', 'いいね！おいわいだ。'), ('Carrera que gana en el último turno: se acabó.', "Winning run on the last turn: it's over.", '最后一局打回赢球的分：结束了。', '最後の攻撃で勝ちこし：おしまい。'), opts={'a': ('¡Walk-off! Juego terminado', 'Walk-off! Game over', '再见安打！比赛结束', 'サヨナラ！試合終了'), 'b': ('Sigue el juego un turno más', 'The game goes on one more turn', '比赛再继续一局', '試合はもう1回つづく'), 'c': ('Foul, no cuenta', "Foul, it doesn't count", '界外球，不算', 'ファウル、数えない')})})
map_titles['17.5'] = ('El marcador decide la jugada y el walk-off', 'The score decides the play and the walk-off', '比分决定打法，再见安打', 'スコアがプレーを決める、サヨナラヒット')
exams_v3['17'] = {'1': {'q': ('Primera libre y viene el bateador más peligroso. La defensa lo manda a primera a propósito. ¿Qué jugada es?', 'First base is open and the most dangerous batter is up. The defense sends him to first on purpose. What play is it?', '一垒没人，最危险的击球员上场了。防守方故意让他上一垒。这是什么战术？', '一塁があいていて、いちばんこわいバッターが来た。守備がわざと一塁へ歩かせた。何のプレー？'), 'opts': {'a': ('Base por bolas intencional (intentional walk)', 'Intentional walk', '故意四坏球（intentional walk）', '敬遠（intentional walk）'), 'b': ('Balk', 'Balk', '投手犯规', 'ボーク'), 'c': ('Squeeze', 'Squeeze', '抢分触击', 'スクイズ')}}, '2': {'q': ('¿Cómo se da la base intencional en tu liga?', 'How is the intentional walk given in your league?', '在你们联赛，故意四坏球怎么执行？', '君のリーグでは、敬遠はどうやる？'), 'opts': {'a': ('Como lo defina mi liga: pregúntale a tu coach', 'However my league defines it: ask your coach', '照我们联赛的规定：问问你的教练', 'リーグの決まりどおり：コーチに聞こう'), 'b': ('Con un número igual en todas las ligas', 'With the same number in every league', '每个联赛都用同一个数字', 'どのリーグも同じ数で'), 'c': ('Lanzando a la banca', 'Pitching to the dugout', '把球投向休息区', 'ベンチに向かって投げる')}}, '3': {'q': ('Corredor en primera: sale con el lanzamiento y el bateador busca contacto. ¿Qué jugada es?', 'Runner on first: he takes off with the pitch and the batter looks for contact. What play is it?', '一垒跑垒员随投球起跑，击球员想办法碰到球。这是什么战术？', '一塁ランナーが投球と同時にスタートして、バッターは当てにいく。何のプレー？'), 'opts': {'a': ('Bateo y corrido (hit and run)', 'Hit and run', '打跑战术（hit and run）', 'ヒットエンドラン（hit and run）'), 'b': ('Toque de sacrificio', 'Sacrifice bunt', '牺牲触击', '犠牲バント'), 'c': ('Walk-off', 'Walk-off', '再见安打', 'サヨナラ')}}, '4': {'q': ('En el bateo y corrido, el trabajo del bateador es…', "On the hit and run, the batter's job is…", '打跑战术时，击球员的任务是……', 'ヒットエンドランで、バッターのしごとは……'), 'opts': {'a': ('Proteger al corredor poniendo la bola en juego', 'Protect the runner by putting the ball in play', '把球打进场内来保护跑垒员', 'ボールを前に飛ばして、ランナーを守る'), 'b': ('Esperar un lanzamiento perfecto', 'Wait for a perfect pitch', '等一个完美的球', 'かんぺきな投球を待つ'), 'c': ('Hacer siempre jonrón', 'Always hit a home run', '总是打本垒打', 'いつもホームランを打つ')}}, '5': {'q': ('Corredor en tercera: el bateador toca y el corredor anota. ¿Qué jugada es?', 'Runner on third: the batter bunts and the runner scores. What play is it?', '三垒有人：击球员触击，跑垒员得分。这是什么战术？', '三塁にランナー：バッターがバントして、ランナーが得点。何のプレー？'), 'opts': {'a': ('Squeeze', 'Squeeze', '抢分触击', 'スクイズ'), 'b': ('Bateo y corrido', 'Hit and run', '打跑战术', 'ヒットエンドラン'), 'c': ('Doble play', 'Double play', '双杀', 'ダブルプレー')}}, '6': {'q': ('En el squeeze suicida, el corredor de tercera arranca…', 'On the suicide squeeze, the runner on third takes off…', '强迫抢分时，三垒跑垒员什么时候起跑……', 'スーサイドスクイズで、三塁ランナーがスタートするのは……'), 'opts': {'a': ('Con el lanzamiento, antes de ver el toque', 'With the pitch, before seeing the bunt', '随着投球，还没看到触击就出发', '投球と同時、バントを見る前'), 'b': ('Cuando la bola ya llegó a los jardines', 'When the ball has already reached the outfield', '球已经到外野时', 'ボールがもう外野に行ったとき'), 'c': ('Después de la atrapada', 'After the catch', '接杀之后', 'キャッチのあと')}}, '7': {'q': ('Corredor en tercera y juego cerrado: ¿cómo se acomoda el cuadro?', 'Runner on third and a close game: how does the infield adjust?', '三垒有人、比分接近：内野怎么调整站位？', '三塁にランナー、せった試合：内野はどうする？'), 'opts': {'a': ('Adentro (infield in), para tirar rápido a home', 'In (infield in), to throw home fast', '前移（infield in），快速传回本垒', '前進守備（infield in）、すばやくホームへ投げる'), 'b': ('Atrás del todo', 'All the way back', '退到最后面', 'いちばんうしろ'), 'c': ('No se acomoda nunca', 'It never adjusts', '从来不调整', 'ぜったい位置をかえない')}}, '8': {'q': ('¿Cuándo le conviene al cuadro jugar atrás, en su sitio normal?', 'When is it best for the infield to play back, in its normal spot?', '内野什么时候退回平常的位置最好？', '内野がいつもの場所で守るのがいいのはいつ？'), 'opts': {'a': ('Cuando busca el doble play con calma', "When it's calmly looking for the double play", '想从容地打双杀时', 'ダブルプレーを落ちついてねらうとき'), 'b': ('Cuando defiende home con juego cerrado', 'When it defends home in a close game', '比分接近、要守本垒时', 'せった試合でホームを守るとき'), 'c': ('Nunca juega atrás', 'It never plays back', '从来不退后', 'ぜったい定位置で守らない')}}, '9': {'q': ('Antes de decidir tu jugada, los tres datos que miras son…', 'Before deciding your play, the three things you look at are…', '决定打法之前，你要看的三样东西是……', 'プレーを決める前に見る3つは……'), 'opts': {'a': ('Marcador, entrada y outs', 'Score, inning and outs', '比分、局数和出局数', 'スコア、イニング、アウト'), 'b': ('Clima, público y banca', 'Weather, crowd and dugout', '天气、观众和休息区', '天気、お客さん、ベンチ'), 'c': ('Mi promedio y mi guante', 'My average and my glove', '我的打击率和我的手套', '自分の打率とグラブ')}}, '10': {'q': ('Equipo de casa, última oportunidad, hit que trae la carrera que gana. ¿Qué es?', 'Home team, last chance, a hit that brings in the winning run. What is it?', '主队，最后的机会，一记安打带回赢球的一分。这是什么？', 'ホームチーム、最後のチャンス、勝ちこしの点が入るヒット。これは？'), 'opts': {'a': ('Walk-off: el juego termina en ese instante', 'Walk-off: the game ends that instant', '再见安打：比赛当场结束', 'サヨナラ：そのしゅんかんに試合終了'), 'b': ('Entrada extra automática', 'Automatic extra inning', '自动进入延长局', '自動で延長戦'), 'c': ('Foul grande', 'Big foul', '一个大的界外球', '大きなファウル')}}, '11': {'q': ('El equipo de casa ya gana al llegar a su último turno. ¿Qué pasa?', 'The home team is already winning when its last turn comes. What happens?', '轮到最后一局时主队已经领先。会怎样？', 'ホームチームが最後の攻撃の前にもう勝っている。どうなる？'), 'opts': {'a': ('El juego ya terminó: no se batea ese turno', "The game is already over: that turn isn't batted", '比赛已经结束：那一局不用打', '試合はもう終わり：その攻撃はしない'), 'b': ('Se batea de cortesía', "It's batted as a courtesy", '出于礼貌还是要打', '礼儀として打つ'), 'c': ('El rival batea dos veces', 'The other team bats twice', '对手打两次', '相手が2回打つ')}}, '12': {'q': ('Ante un bateador de mucha fuerza, los jardines suelen…', 'Against a batter with a lot of power, the outfielders usually…', '遇到力量很大的击球员，外野手通常……', 'とても力のあるバッターのとき、外野はたいてい……'), 'opts': {'a': ('Dar pasos atrás', 'Take steps back', '往后退几步', '何歩か下がる'), 'b': ('Acercarse mucho al cuadro', 'Come in very close to the infield', '靠到内野很近的地方', '内野のすぐ近くまで来る'), 'c': ('Salir del campo', 'Leave the field', '离开球场', 'グラウンドから出る')}}}
