lesson('18.1', ('Deslizarse seguro', 'Sliding safely', '安全滑垒', '安全なスライディング'), ('Deslizarse (slide) pies primero, con las manos arriba y sin ir contra el defensor; y saber que deslizarse de cabeza puede estar prohibido en su liga: se pregunta al coach.', 'Slide feet first, with your hands up and never into the fielder; and know that sliding head first may be banned in your league: ask the coach.', '脚先滑垒（slide），双手举起，不冲撞防守球员；还要知道，你们联赛可能禁止头先滑垒：问问教练。', '足から、手を上げて、守備にぶつからずにスライディング（slide）しよう。頭からのスライディングは、君のリーグでは禁止かもしれない：コーチに聞こう。'), [('Llegas corriendo a la base y el tiro viene cerca: ¡a deslizarse!', "You're running into the base and the throw is close: time to slide!", '你跑向垒包，传球也快到了：滑垒！', '塁へ走っていて、送球がせまっている：スライディングだ！'), ('Deslizarse, en inglés slide, es tirarse por el suelo para llegar por debajo del guante del defensor.', "To slide is to drop down onto the ground to get in under the fielder's glove.", '滑垒，英语叫 slide，就是贴着地面滑过去，从防守球员的手套下面滑进垒。', 'スライディング、英語で slide は、地面にすべりこんで、タッチの下をくぐること。'), ('La forma segura en ligas de niños es pies primero, feet-first slide: las piernas van al frente, el cuerpo se recuesta un poco y las manos suben para no apoyarlas en el suelo.', "The safe way in kids' leagues is feet first: your legs go in front, your body leans back a little and your hands go up so you don't put them on the ground.", '儿童联赛里安全的方式是脚先滑垒，feet-first slide：双腿在前，身体稍微往后躺，双手举起，不要撑地。', '子どものリーグで安全なのは、足から、feet-first slide。足を前に、体を少しうしろにたおして、手は上げて地面につかない。'), ('Nunca te lanzas contra el defensor para tumbarlo: se llega a la base, no al jugador.', 'You never throw yourself into the fielder to knock him down: you go to the base, not to the player.', '绝不要冲向防守球员把他撞倒：你要去的是垒包，不是球员。', '守備をたおそうと、ぶつかっていくことはぜったいにしない：めざすのは塁で、選手じゃない。'), ('Y ojo: en muchas ligas infantiles deslizarse de cabeza está prohibido, porque la cabeza va desprotegida al frente.', "And careful: in many kids' leagues sliding head first is banned, because your head goes in front, unprotected.", '还要注意：很多儿童联赛禁止头先滑垒，因为头在最前面，没有保护。', 'それから気をつけて：子どものリーグの多くでは、頭からのスライディングは禁止。頭が守られないまま前に出るからだ。'), ('En tu liga puede ser distinto: pregúntale a tu coach antes de hacerlo.', 'It may be different in your league: ask your coach before you do it.', '你们联赛可能不一样：做之前先问问你的教练。', '君のリーグではちがうかもしれない：やる前にコーチに聞いてみよう。')], {'1': act(('¿Cuál es la forma segura de deslizarse en ligas de niños?', "What's the safe way to slide in kids' leagues?", '儿童联赛里安全的滑垒方式是什么？', '子どものリーグで安全なスライディングは？'), ('¡Eso es! Pies primero.', "That's it! Feet first.", '对了！脚先。', 'そのとおり！足から。'), ('Piernas al frente y manos arriba: seguro.', 'Legs in front and hands up: safe.', '双腿在前，双手举起：安全。', '足を前、手は上：安全。'), opts={'a': ('Pies primero, con las manos arriba', 'Feet first, with your hands up', '脚先滑垒，双手举起', '足から、手を上げて'), 'b': ('De cabeza, con las manos al frente', 'Head first, with your hands in front', '头先滑垒，双手在前', '頭から、手を前に'), 'c': ('Contra el defensor, empujándolo', 'Into the fielder, pushing him', '冲向防守球员，推他', '守備にぶつかって、おす')}), '2': act(('Al deslizarse, hay que apoyar las manos en el suelo para frenar', 'When you slide, you have to put your hands on the ground to brake', '滑垒时要用手撑地来刹车', 'スライディングでは、手を地面について止まる'), ('¡Bien! Manos arriba.', 'Good! Hands up.', '很好！双手举起。', 'いいね！手は上。'), ('Falso: apoyar las manos puede lastimar las muñecas.', 'False: putting your hands down can hurt your wrists.', '错：用手撑地会伤到手腕。', 'まちがい：手をつくと、手首をいためることがある。')), '3': act(('¿Contra qué se desliza un corredor?', 'What does a runner slide into?', '跑垒员朝什么滑过去？', 'ランナーは何に向かってすべる？'), ('¡Correcto! A la base.', 'Correct! To the base.', '正确！朝垒包。', '正解！塁へ。'), ('El defensor no es un obstáculo para chocar.', "The fielder isn't something to crash into.", '防守球员不是用来撞的。', '守備はぶつかる相手じゃない。'), opts={'a': ('Contra la base, nunca contra el defensor', 'Into the base, never into the fielder', '朝垒包，绝不朝防守球员', '塁に向かって。守備にはぜったい向かわない'), 'b': ('Contra el defensor para tumbarlo', 'Into the fielder to knock him down', '朝防守球员，把他撞倒', '守備をたおすために守備へ'), 'c': ('Contra la valla', 'Into the fence', '朝围栏', 'フェンスへ')}), '4': act(('¿Se puede deslizar de cabeza en tu liga?', 'Can you slide head first in your league?', '在你们联赛可以头先滑垒吗？', '君のリーグでは、頭からスライディングしていい？'), ('¡Eso es! Pregunta primero.', "That's it! Ask first.", '对了！先问。', 'そのとおり！まず聞こう。'), ('En tu liga puede ser distinto: pregúntale a tu coach.', 'It may be different in your league: ask your coach.', '你们联赛可能不一样：问问你的教练。', '君のリーグではちがうかもしれない：コーチに聞いてみよう。'), opts={'a': ('Depende de mi liga: pregúntale a tu coach', 'It depends on my league: ask your coach', '要看我们联赛：问问你的教练', 'リーグによる：コーチに聞こう'), 'b': ('Siempre, en todas', 'Always, in all of them', '永远可以，所有联赛都行', 'いつでも、どのリーグでも'), 'c': ('Nunca se pregunta nada', 'You never ask anything', '什么都不用问', '何も聞かなくていい')}), '5': act(('Deslizarse sirve para llegar por debajo del guante del defensor', "Sliding helps you get in under the fielder's glove", '滑垒能帮你从防守球员的手套下面滑进垒', 'スライディングは、守備のグラブの下をくぐって塁に着くためのもの'), ('¡Bien! Por eso se usa.', "Good! That's why it's used.", '很好！所以才用它。', 'いいね！だから使う。'), ('Verdadero: bajo y rápido a la base.', 'True: low and fast to the base.', '对：又低又快地到垒。', '正しい：低く、速く、塁へ。')), '6': act(('¿Cuál imagen muestra el deslizamiento seguro?', 'Which picture shows the safe slide?', '哪张图是安全的滑垒？', '安全なスライディングはどの絵？'), ('¡Eso es! Ese llega seguro.', "That's it! That one arrives safely.", '对了！这样到垒才安全。', 'そのとおり！それなら安全に着く。'), ('Pies primero, siempre en ligas de niños.', "Feet first, always in kids' leagues.", '儿童联赛里，永远脚先。', '子どものリーグでは、いつも足から。'), opts={'a': ('Corredor pies primero con las manos arriba', 'Runner feet first with hands up', '脚先滑垒、双手举起的跑垒员', '足から、手を上げたランナー'), 'b': ('Corredor de cabeza', 'Runner head first', '头先滑垒的跑垒员', '頭からのランナー'), 'c': ('Corredor chocando al defensor', 'Runner crashing into the fielder', '撞向防守球员的跑垒员', '守備にぶつかるランナー')})})
map_titles['18.1'] = ('Deslizarse seguro', 'Sliding safely', '安全滑垒', '安全なスライディング')
lesson('18.2', ('La regla de misericordia', 'The mercy rule', '提前结束规则', 'コールドゲーム'), ('Entender la regla de misericordia (mercy rule): si un equipo va ganando por una diferencia muy grande, el juego puede terminar antes para cuidar a los niños; la diferencia exacta la define cada liga.', 'Understand the mercy rule: if one team is winning by a very big difference, the game can end early to look after the kids; each league sets the exact difference.', '明白提前结束规则（mercy rule）：如果一支球队领先太多，比赛可以提前结束，好保护孩子们；具体差多少，由每个联赛规定。', 'コールドゲーム（mercy rule）を知ろう：点差がとても大きくなったら、子どもたちを守るために試合を早く終わらせることがある。点差がいくつかは、リーグごとに決める。'), [('Imagina un juego donde un equipo anota y anota y el otro no puede salir del hoyo.', "Imagine a game where one team scores and scores and the other can't climb out of the hole.", '想象一场比赛，一支球队一直得分，另一支球队怎么也追不上。', 'ある試合を思いうかべて：片方のチームが点をとりつづけて、もう片方はぜんぜん追いつけない。'), ('Seguir así ya no enseña nada y solo cansa y entristece.', "Going on like that doesn't teach anything anymore, it only tires and saddens.", '再这样打下去，什么也学不到，只会让人又累又难过。', 'そのまま続けても、もう何も学べない。つかれて、悲しくなるだけ。'), ('Para eso existe la regla de misericordia, en inglés mercy rule: si la diferencia de carreras pasa el límite que marca la liga, el juego termina antes, con respeto por los dos equipos.', "That's what the mercy rule is for: if the run difference goes past the limit the league sets, the game ends early, with respect for both teams.", '所以才有提前结束规则，英语叫 mercy rule：如果分差超过联赛规定的界限，比赛就提前结束，尊重两支球队。', 'そのためにあるのがコールドゲーム、英語で mercy rule。点差がリーグの決めた限度をこえたら、両チームを大切にして、試合を早く終わらせる。'), ('Cuál es esa diferencia y desde cuándo se cuenta lo define cada liga, y cambia según la edad.', 'What that difference is and from when it counts is set by each league, and it changes with age.', '分差是多少、从什么时候开始算，都由每个联赛规定，还会按年龄不同而改变。', 'その点差がいくつで、いつから数えるかは、リーグごとに決める。年れいでもかわる。'), ('Aquí no aprendes un número: aprendes la idea.', "Here you don't learn a number: you learn the idea.", '这里你学的不是一个数字：而是这个道理。', 'ここで覚えるのは数字じゃない：考え方だ。'), ('En tu liga puede ser distinto: pregúntale a tu coach cuál es el límite.', 'It may be different in your league: ask your coach what the limit is.', '你们联赛可能不一样：问问你的教练界限是多少。', '君のリーグではちがうかもしれない：限度がいくつか、コーチに聞いてみよう。')], {'1': act(('¿Para qué existe la regla de misericordia?', 'What is the mercy rule for?', '提前结束规则是为了什么？', 'コールドゲームは何のため？'), ('¡Eso es! Cuida a todos.', "That's it! It looks after everyone.", '对了！它保护所有人。', 'そのとおり！みんなを守る。'), ('Ganar con respeto también es béisbol.', 'Winning with respect is baseball too.', '有尊重地赢，也是棒球。', '相手を大切にして勝つのも野球だ。'), opts={'a': ('Para terminar antes un juego con una diferencia enorme, cuidando a los niños', 'To end a game with a huge difference early, looking after the kids', '为了让分差很大的比赛提前结束，保护孩子们', '点差がとても大きい試合を早く終わらせて、子どもたちを守るため'), 'b': ('Para castigar al equipo que pierde', 'To punish the losing team', '为了惩罚输的球队', '負けているチームをばっするため'), 'c': ('Para jugar menos siempre', 'To always play less', '为了永远少打一点', 'いつも少なく試合をするため')}), '2': act(('¿Quién define la diferencia de carreras de la regla de misericordia?', 'Who sets the run difference for the mercy rule?', '提前结束规则的分差由谁规定？', 'コールドゲームの点差はだれが決める？'), ('¡Correcto! Lo define la liga.', 'Correct! The league sets it.', '正确！由联赛规定。', '正解！リーグが決める。'), ('En tu liga puede ser distinto: pregúntale a tu coach.', 'It may be different in your league: ask your coach.', '你们联赛可能不一样：问问你的教练。', '君のリーグではちがうかもしれない：コーチに聞いてみよう。'), opts={'a': ('Cada liga, según la edad', 'Each league, depending on age', '每个联赛，按年龄规定', 'リーグごとに、年れいで'), 'b': ('El equipo que va ganando', 'The team that is winning', '领先的球队', '勝っているチーム'), 'c': ('El público', 'The crowd', '观众', 'お客さん')}), '3': act(('La regla de misericordia tiene el mismo número de carreras en todas las ligas', 'The mercy rule has the same number of runs in every league', '每个联赛的提前结束规则都是同样的分数', 'コールドゲームの点数は、どのリーグも同じ'), ('¡Bien! Cambia por liga y edad.', 'Good! It changes by league and age.', '很好！按联赛和年龄而变。', 'いいね！リーグと年れいでかわる。'), ('Falso: por eso no se aprende un número fijo.', "False: that's why you don't learn a fixed number.", '错：所以不要背一个固定的数字。', 'まちがい：だから決まった数字は覚えない。')), '4': act(('Cuando se aplica la regla de misericordia, el equipo que va ganando gana el juego', 'When the mercy rule is applied, the team that is winning wins the game', '用了提前结束规则时，领先的球队赢得比赛', 'コールドゲームになったら、勝っているチームの勝ち'), ('¡Correcto! El resultado se queda.', 'Correct! The result stands.', '正确！比分有效。', '正解！結果はそのまま。'), ('Verdadero: el juego termina con ese marcador.', 'True: the game ends with that score.', '对：比赛以这个比分结束。', '正しい：そのスコアで試合が終わる。')), '5': act(('¿Qué debe hacer el equipo que va ganando por mucho?', 'What should the team that is winning by a lot do?', '大比分领先的球队应该怎么做？', '大きく勝っているチームはどうする？'), ('¡Eso es! Respeto siempre.', "That's it! Respect, always.", '对了！永远尊重。', 'そのとおり！いつも相手を大切に。'), ('El rival de hoy es un compañero del béisbol.', "Today's opponent is a baseball teammate too.", '今天的对手，也是棒球的伙伴。', '今日の相手も、野球の仲間だ。'), opts={'a': ('Jugar con respeto, sin burlarse nunca del rival', 'Play with respect, never making fun of the other team', '有尊重地比赛，绝不嘲笑对手', '相手を大切にして、ぜったいにからかわない'), 'b': ('Burlarse un poquito', 'Make fun a little', '稍微嘲笑一下', '少しだけからかう'), 'c': ('Seguir anotando con celebraciones exageradas', 'Keep scoring with over-the-top celebrations', '一边得分一边夸张地庆祝', '大げさにおいわいしながら点をとりつづける')}), '6': act(('La diferencia pasó el límite de la liga. ¿Qué decide el umpire?', "The difference went past the league's limit. What does the umpire decide?", '分差超过了联赛的界限。裁判怎么判？', '点差がリーグの限度をこえた。審判はどう決める？'), ('¡Bien! Juego cerrado con respeto.', 'Good! Game closed with respect.', '很好！有尊重地结束比赛。', 'いいね！相手を大切にして試合終了。'), ('El límite de su liga manda.', "Their league's limit is what counts.", '那个联赛的界限说了算。', 'そのリーグの限度で決まる。'), opts={'a': ('Juego terminado por la regla de misericordia de esa liga', "Game over by that league's mercy rule", '按那个联赛的提前结束规则，比赛结束', 'そのリーグのコールドゲームで試合終了'), 'b': ('Que se juegue el doble de tiempo', 'Play twice as long', '比赛时间加倍', '2ばいの時間やる'), 'c': ('Que nadie gane', 'Nobody wins', '没有人赢', 'だれも勝たない')})})
map_titles['18.2'] = ('La regla de misericordia', 'The mercy rule', '提前结束规则', 'コールドゲーム')
lesson('18.3', ('Juego oficial, juego suspendido y entradas extra', 'Official game, suspended game and extra innings', '正式比赛、中断比赛和延长局', '正式試合、サスペンデッドゲーム、延長戦'), ('Entender que un juego se vuelve oficial cuando ya se jugó lo que la liga pide; que si el clima lo detiene puede quedar suspendido y seguir otro día; y que si el juego oficial termina empatado, en algunas ligas hay entradas extra hasta que alguien gane.', 'Understand that a game becomes official once what the league requires has been played; that if the weather stops it, it can be suspended and continue another day; and that if the official game ends tied, some leagues play extra innings until someone wins.', '明白比赛打完联赛要求的部分后就成为正式比赛；如果因天气停下来，可能成为中断比赛，改天继续；如果正式比赛打平，有些联赛会打延长局，直到有一方赢。', 'リーグが決めた分をやったら、試合は正式試合になる。天気で止まったら、サスペンデッドゲームになって別の日に続けることがある。正式試合が同点で終わったら、延長戦をするリーグもある。'), [('Tres palabras de partido grande.', 'Three big-game words.', '三个大比赛用语。', '大きな試合の言葉を3つ。'), ('Juego oficial, en inglés official game: cuando ya se jugó la parte que la liga pide, el resultado vale aunque después pase algo.', 'Official game: once the part the league requires has been played, the result counts even if something happens afterward.', '正式比赛，英语叫 official game：打完了联赛要求的部分，之后就算发生什么事，比分也有效。', '正式試合、英語で official game：リーグが決めた分をもうやったら、あとで何があっても、結果は有効。'), ('Si cae un rayo o llega la oscuridad y el juego debe parar — repaso de seguridad: con rayos se sale del campo —, el juego puede quedar suspendido, suspended game, y terminarse otro día desde donde quedó, si la liga así lo dice.', 'If lightning strikes or it gets dark and the game has to stop — safety review: with lightning you leave the field — the game can be suspended and finished another day from where it stopped, if the league says so.', '如果打雷或天黑了，比赛必须停下——复习安全：有闪电就离开球场——比赛可能成为中断比赛，suspended game，如果联赛这样规定，就改天从停下的地方接着打完。', 'かみなりが落ちたり、暗くなったりして試合を止めなきゃいけないとき——安全の復習：かみなりならグラウンドから出る——試合はサスペンデッドゲーム、suspended game になって、リーグがそう決めていれば、別の日に止まったところから続ける。'), ('Y si un juego oficial termina empatado, algunas ligas siguen con entradas extra, extra innings: turnos nuevos, uno para cada equipo, hasta que uno termine arriba.', 'And if an official game ends tied, some leagues keep going with extra innings: new turns, one for each team, until one ends up ahead.', '如果正式比赛打平，有些联赛会继续打延长局，extra innings：新的进攻机会，每队各一次，直到有一方领先。', '正式試合が同点で終わったら、延長戦、extra innings を続けるリーグもある：新しい攻撃を、それぞれのチームに1回ずつ。どちらかが上に立つまで。'), ('Cuánto se necesita para que un juego sea oficial y si hay entradas extra lo define cada liga: pregúntale a tu coach.', 'How much it takes for a game to be official and whether there are extra innings is set by each league: ask your coach.', '要打多少才算正式比赛、有没有延长局，都由每个联赛规定：问问你的教练。', 'どこまでやれば正式試合か、延長戦があるかは、リーグごとに決める：コーチに聞こう。')], {'1': act(('¿Qué es un juego oficial?', 'What is an official game?', '什么是正式比赛？', '正式試合って何？'), ('¡Eso es! Resultado que vale.', "That's it! A result that counts.", '对了！比分有效。', 'そのとおり！有効な結果。'), ('Lo define tu liga: pregúntale a tu coach.', 'Your league decides: ask your coach.', '由你的联赛决定：问问你的教练。', 'リーグが決めること。コーチに聞こう。'), opts={'a': ('El que ya jugó lo que la liga pide para que el resultado valga', 'One that has already played what the league requires for the result to count', '已经打完联赛要求的部分、比分有效的比赛', 'リーグが決めた分をもうやって、結果が有効になった試合'), 'b': ('Cualquier juego con público', 'Any game with a crowd', '任何有观众的比赛', 'お客さんがいる試合ならどれでも'), 'c': ('El primer juego del año', 'The first game of the year', '一年里的第一场比赛', '1年で最初の試合')}), '2': act(('¿Qué es un juego suspendido?', 'What is a suspended game?', '什么是中断比赛？', 'サスペンデッドゲームって何？'), ('¡Correcto! Se guarda y se sigue.', "Correct! It's saved and continued.", '正确！保存下来，再继续。', '正解！とっておいて、続ける。'), ('Clima feo hoy, final otro día.', 'Bad weather today, ending another day.', '今天天气不好，改天再打完。', '今日は天気が悪い、終わりは別の日。'), opts={'a': ('Un juego detenido que puede terminarse otro día desde donde quedó', 'A stopped game that can be finished another day from where it stopped', '停下来的比赛，可以改天从停下的地方接着打完', '止まった試合を、別の日に止まったところから終わらせる'), 'b': ('Un juego cancelado para siempre', 'A game canceled forever', '永远取消的比赛', 'ずっと中止の試合'), 'c': ('Un juego sin umpire', 'A game with no umpire', '没有裁判的比赛', '審判がいない試合')}), '3': act(('Con rayos cerca, el juego sigue hasta terminar la entrada', 'With lightning nearby, the game goes on until the inning ends', '附近有闪电时，比赛继续打到这一局结束', '近くでかみなりが光っても、イニングが終わるまで試合を続ける'), ('¡Bien! Rayos es salir ya (repaso).', 'Good! Lightning means leave now (review).', '很好！有闪电就马上离开（复习）。', 'いいね！かみなりはすぐに出る（復習）。'), ('Falso: rayos significa salir del campo sin esperar.', 'False: lightning means leaving the field without waiting.', '错：有闪电就要立刻离开球场，不要等。', 'まちがい：かみなりなら、待たずにグラウンドから出る。')), '4': act(('¿Qué son las entradas extra (extra innings)?', 'What are extra innings?', '什么是延长局（extra innings）？', '延長戦（extra innings）って何？'), ('¡Eso es! A desempatar.', "That's it! To break the tie.", '对了！为了打破平局。', 'そのとおり！決着をつける。'), ('Uno para cada equipo, hasta que alguien quede arriba.', 'One for each team, until someone ends up ahead.', '每队各一次，直到有一方领先。', 'それぞれ1回ずつ、どちらかが上に立つまで。'), opts={'a': ('Turnos nuevos para desempatar un juego oficial empatado', 'New turns to break the tie in a tied official game', '为了打破正式比赛平局的新的进攻机会', '同点の正式試合で、決着をつける新しい攻撃'), 'b': ('Entradas de práctica', 'Practice innings', '练习局', '練習のイニング'), 'c': ('La entrada de la banca', 'Innings played in the dugout', '休息区的入口', 'ベンチの入り口')}), '5': act(('¿En todas las ligas hay entradas extra?', 'Do all leagues have extra innings?', '所有联赛都有延长局吗？', 'どのリーグにも延長戦がある？'), ('¡Correcto! Pregunta en tu liga.', 'Correct! Ask in your league.', '正确！在你们联赛问一问。', '正解！君のリーグで聞こう。'), ('En tu liga puede ser distinto: pregúntale a tu coach.', 'It may be different in your league: ask your coach.', '你们联赛可能不一样：问问你的教练。', '君のリーグではちがうかもしれない：コーチに聞いてみよう。'), opts={'a': ('No: lo define cada liga, pregúntale a tu coach', 'No: each league sets it, ask your coach', '不是：由每个联赛规定，问问你的教练', 'ない：リーグごとに決める、コーチに聞こう'), 'b': ('Sí, en todas igual', 'Yes, the same in all of them', '是的，所有联赛都一样', 'ある、どこも同じ'), 'c': ('Solo en los juegos con lluvia', 'Only in rainy games', '只有下雨的比赛才有', '雨の試合だけ')}), '6': act(('Si un juego suspendido se sigue otro día, empieza desde cero', 'If a suspended game continues another day, it starts from zero', '中断比赛改天继续时，从零开始', 'サスペンデッドゲームを別の日に続けるときは、0から始める'), ('¡Bien! Sigue donde quedó.', 'Good! It continues where it stopped.', '很好！从停下的地方继续。', 'いいね！止まったところから続ける。'), ('Falso: se retoma desde el punto en que se detuvo, si la liga así lo dice.', 'False: it picks up from the point where it stopped, if the league says so.', '错：如果联赛这样规定，就从停下的地方接着打。', 'まちがい：リーグがそう決めていれば、止まったところから再開する。'))})
map_titles['18.3'] = ('Juego oficial, juego suspendido y entradas extra', 'Official game, suspended game and extra innings', '正式比赛、中断比赛和延长局', '正式試合、サスペンデッドゲーム、延長戦')
lesson('18.4', ('Los cambios, el reingreso y batear fuera de turno', 'Substitutions, re-entry and batting out of order', '换人、再次上场和打错棒次', '選手交代、再出場、打順まちがい'), ('Entender la sustitución (el que entra hereda el lugar al bate del que salió), que si el que salió puede volver (reingreso) lo define la liga, y que batear fuera de turno es un error que la defensa puede reclamar al umpire.', 'Understand substitution (the player who comes in takes the batting spot of the one who left), that whether the player who left can come back (re-entry) is set by the league, and that batting out of order is a mistake the defense can point out to the umpire.', '明白换人（substitution）：上场的球员接替下场球员的棒次；下场的球员能不能再次上场（re-entry），由联赛规定；打错棒次是防守方可以向裁判提出的错误。', '選手交代（substitution）を知ろう：入った選手は、出た選手の打順をひきつぐ。出た選手がもどれるか（再出場、re-entry）はリーグが決める。打順まちがいは、守備が審判にうったえられるミス。'), [('Un partido también se mueve desde la banca.', 'A game also moves from the dugout.', '比赛也会从休息区那边改变。', '試合はベンチからも動く。'), ('Cuando entra un jugador nuevo, es una sustitución, en inglés substitution: el que entra hereda el lugar en el orden al bate del que salió, y el coach avisa al umpire.', "When a new player comes in, it's a substitution: the one who comes in takes over the spot in the batting order of the one who left, and the coach tells the umpire.", '有新球员上场，就是换人，英语叫 substitution：上场的人接替下场球员在棒次里的位置，教练要告诉裁判。', '新しい選手が入るのは選手交代、英語で substitution。入った選手は、出た選手の打順をひきついで、コーチが審判に知らせる。'), ('¿Puede volver el que salió?', 'Can the one who left come back?', '下场的人还能回来吗？', '出た選手はもどれる？'), ('Eso se llama reingreso, re-entry, y lo define cada liga: en unas sí y en otras no; pregúntale a tu coach.', "That's called re-entry, and each league sets it: in some yes and in others no; ask your coach.", '这叫再次上场，re-entry，由每个联赛规定：有的可以，有的不行；问问你的教练。', 'それを再出場、re-entry という。リーグごとに決める：もどれるリーグもあれば、もどれないリーグもある。コーチに聞こう。'), ('Y cuidado con este error: si alguien batea en el turno de otro, es batear fuera de turno, en inglés batting out of order.', "And watch out for this mistake: if someone bats in another player's turn, that's batting out of order.", '还要小心这个错误：如果有人在别人的棒次上去打击，就是打错棒次，英语叫 batting out of order。', 'それから、このミスに気をつけて：ほかの人の打順で打つのは打順まちがい、英語で batting out of order。'), ('Si la defensa se da cuenta y avisa al umpire a tiempo, hay castigo; por eso el coach y el capitán cuidan la tarjeta de alineación como un tesoro.', "If the defense notices and tells the umpire in time, there's a penalty; that's why the coach and the captain guard the lineup card like a treasure.", '如果防守方发现了并及时告诉裁判，就会受罚；所以教练和队长像保护宝贝一样看好出场名单卡。', '守備が気づいて、まにあううちに審判に知らせたら、ばつがある。だからコーチとキャプテンは、メンバー表を宝物みたいに大事にする。')], {'1': act(('Cuando entra un sustituto, ¿qué lugar al bate ocupa?', 'When a substitute comes in, which batting spot does he take?', '替补上场时，他打第几棒？', '交代で入った選手は、どの打順に入る？'), ('¡Eso es! Hereda el turno.', "That's it! He takes over the turn.", '对了！他接替这个棒次。', 'そのとおり！打順をひきつぐ。'), ('Entra por alguien y hereda su lugar.', 'He comes in for someone and takes his spot.', '他替谁上场，就接替谁的位置。', 'だれかのかわりに入って、その打順をひきつぐ。'), opts={'a': ('El del jugador que salió', 'That of the player who left', '下场球员的棒次', '出た選手の打順'), 'b': ('El último de la fila siempre', 'Always last in line', '永远排最后', 'いつもいちばん最後'), 'c': ('El que él elija', 'Whichever he chooses', '他自己选', '自分で選んだ打順')}), '2': act(('¿Puede volver al juego el jugador que salió?', 'Can the player who left come back into the game?', '下场的球员还能再次上场吗？', '出た選手は試合にもどれる？'), ('¡Correcto! Lo define la liga.', 'Correct! The league sets it.', '正确！由联赛规定。', '正解！リーグが決める。'), ('En tu liga puede ser distinto: pregúntale a tu coach.', 'It may be different in your league: ask your coach.', '你们联赛可能不一样：问问你的教练。', '君のリーグではちがうかもしれない：コーチに聞いてみよう。'), opts={'a': ('Depende del reingreso de mi liga: pregúntale a tu coach', "It depends on my league's re-entry: ask your coach", '要看我们联赛的再次上场规定：问问你的教练', 'リーグの再出場の決まりによる：コーチに聞こう'), 'b': ('Siempre puede volver', 'He can always come back', '永远可以回来', 'いつでももどれる'), 'c': ('Nunca, en ninguna liga', 'Never, in any league', '绝对不行，任何联赛都不行', 'どのリーグでもぜったいだめ')}), '3': act(('¿Qué es batear fuera de turno (batting out of order)?', 'What is batting out of order?', '什么是打错棒次（batting out of order）？', '打順まちがい（batting out of order）って何？'), ('¡Eso es! Saltarse el orden.', "That's it! Skipping the order.", '对了！跳过了顺序。', 'そのとおり！順番をとばした。'), ('La tarjeta manda el orden de los turnos.', 'The card sets the order of the turns.', '出场名单卡决定打击顺序。', 'メンバー表が打順を決める。'), opts={'a': ('Batear en el turno de otro jugador', "Batting in another player's turn", '在别人的棒次上去打击', 'ほかの選手の打順で打つ'), 'b': ('Batear con el casco chueco', 'Batting with a crooked helmet', '戴歪头盔打击', 'ヘルメットがずれたまま打つ'), 'c': ('Batear de zurdo siendo derecho', 'Batting lefty when you are a righty', '本来右打却用左打', '右打ちなのに左で打つ')}), '4': act(('Si nadie se da cuenta del bateo fuera de turno a tiempo, el juego puede seguir', 'If nobody notices the batting out of order in time, the game can go on', '如果没人及时发现打错棒次，比赛可以继续', 'だれも打順まちがいにまにあううちに気づかなければ、試合は続けられる'), ('¡Bien! El reclamo tiene su momento.', 'Good! The appeal has its moment.', '很好！提出申诉有它的时机。', 'いいね！うったえるにはタイミングがある。'), ('Verdadero: por eso la defensa también mira la tarjeta.', "True: that's why the defense watches the card too.", '对：所以防守方也要看名单卡。', '正しい：だから守備もメンバー表を見る。')), '5': act(('¿Quién avisa al umpire de un cambio?', 'Who tells the umpire about a change?', '谁把换人告诉裁判？', '交代はだれが審判に知らせる？'), ('¡Correcto! Avisa el coach.', 'Correct! The coach tells him.', '正确！教练告诉他。', '正解！コーチが知らせる。'), ('Cambio sin aviso no vale.', "A change without telling doesn't count.", '不告诉裁判的换人不算数。', '知らせない交代は無効。'), opts={'a': ('El coach', 'The coach', '教练', 'コーチ'), 'b': ('El público', 'The crowd', '观众', 'お客さん'), 'c': ('El bateador rival', "The other team's batter", '对方的击球员', '相手のバッター')}), '6': act(('El capitán puede ayudar cuidando que el orden al bate se respete', 'The captain can help by making sure the batting order is respected', '队长可以帮忙确认打击顺序有没有被遵守', 'キャプテンは、打順が守られているか見て手伝える'), ('¡Bien! Capitán atento.', 'Good! An alert captain.', '很好！细心的队长。', 'いいね！気がきくキャプテン。'), ('Verdadero: cuidar la tarjeta es trabajo de equipo.', 'True: guarding the card is teamwork.', '对：看好名单卡是团队的工作。', '正しい：メンバー表を守るのはチームのしごと。'))})
map_titles['18.4'] = ('Los cambios, el reingreso y batear fuera de turno', 'Substitutions, re-entry and batting out of order', '换人、再次上场和打错棒次', '選手交代、再出場、打順まちがい')
lesson('18.5', ('El corredor especial', 'The courtesy runner', '礼貌跑者', 'コーテシーランナー'), ('Entender el corredor especial o de cortesía que algunas ligas permiten para el catcher (y a veces el pitcher), para que pueda prepararse sin detener el juego; existe solo si la liga lo permite.', 'Understand the special or courtesy runner that some leagues allow for the catcher (and sometimes the pitcher), so he can get ready without stopping the game; it only exists if the league allows it.', '明白有些联赛允许为捕手（有时也为投手）安排礼貌跑者，让他能准备好而不耽误比赛；只有联赛允许时才有。', 'キャッチャー（ときにはピッチャーも）のために、コーテシーランナーをみとめるリーグがある。試合を止めずに準備できるように。リーグがみとめているときだけある。'), [('El catcher trabaja mucho: en cada entrada debe ponerse toda su armadura.', 'The catcher works hard: every inning he has to put on all his armor.', '捕手的工作很辛苦：每一局都要穿上全身护具。', 'キャッチャーはたくさん働く：イニングごとに、よろいを全部つけなきゃいけない。'), ('Algunas ligas le echan una mano con el corredor especial, en inglés courtesy runner: si el catcher llega a base cuando ya hay dos outs, un compañero de la banca puede correr por él, para que el catcher vaya a vestirse y la entrada siguiente no se detenga.', "Some leagues give him a hand with the courtesy runner: if the catcher gets on base when there are already two outs, a teammate from the dugout can run for him, so the catcher can go get dressed and the next inning doesn't stop.", '有些联赛会用礼貌跑者帮他一把，英语叫 courtesy runner：如果捕手在两出局后上了垒，休息区的一个队友可以替他跑，让捕手去穿护具，下一局就不会耽误。', 'それを助けるリーグもある。コーテシーランナー、英語で courtesy runner。2アウトでキャッチャーが塁に出たら、ベンチの仲間がかわりに走れる。キャッチャーは用具をつけに行けて、次のイニングが止まらない。'), ('Algunas ligas también lo permiten para el pitcher.', 'Some leagues also allow it for the pitcher.', '有些联赛也允许投手这样做。', 'ピッチャーにもみとめるリーグがある。'), ('Pero ojo: esto no existe en todas las ligas ni con las mismas reglas.', "But careful: this doesn't exist in every league, or with the same rules.", '但要注意：不是每个联赛都有，规则也不一样。', 'でも気をつけて：どのリーグにもあるわけじゃないし、ルールも同じじゃない。'), ('Es un regalo de algunas ligas, no una regla de todos.', "It's an extra some leagues allow, not a rule for everyone.", '这是有些联赛的贴心安排，不是所有人的规则。', '一部のリーグのプレゼントで、みんなのルールじゃない。'), ('En tu liga puede ser distinto: pregúntale a tu coach si existe y cómo funciona.', 'It may be different in your league: ask your coach if it exists and how it works.', '你们联赛可能不一样：问问你的教练有没有、怎么用。', '君のリーグではちがうかもしれない：あるかどうか、どうやるか、コーチに聞いてみよう。')], {'1': act(('¿Qué es el corredor especial o de cortesía (courtesy runner)?', 'What is a courtesy runner?', '什么是礼貌跑者（courtesy runner）？', 'コーテシーランナー（courtesy runner）って何？'), ('¡Eso es! Ayuda para el catcher.', "That's it! Help for the catcher.", '对了！帮捕手的忙。', 'そのとおり！キャッチャーの助け。'), ('Corre por él mientras se viste su armadura.', 'He runs for him while he puts on his armor.', '他穿护具时，队友替他跑。', 'よろいをつけている間に、かわりに走る。'), opts={'a': ('Un compañero que corre por el catcher para que este pueda prepararse', 'A teammate who runs for the catcher so he can get ready', '替捕手跑垒的队友，让捕手能做准备', 'キャッチャーが準備できるように、かわりに走る仲間'), 'b': ('El corredor más rápido del mundo', 'The fastest runner in the world', '世界上跑得最快的人', '世界でいちばん速いランナー'), 'c': ('Un corredor del equipo rival', 'A runner from the other team', '对方球队的跑垒员', '相手チームのランナー')}), '2': act(('¿Por qué lo usan con el catcher?', 'Why is it used with the catcher?', '为什么捕手要用它？', 'どうしてキャッチャーに使うの？'), ('¡Correcto! El juego sigue.', 'Correct! The game goes on.', '正确！比赛继续。', '正解！試合は続く。'), ('Armadura puesta a tiempo, entrada sin espera.', 'Armor on in time, inning with no wait.', '护具及时穿好，下一局不用等。', 'よろいがまにあえば、イニングは待たない。'), opts={'a': ('Porque ponerse la armadura toma tiempo y el juego no se detiene', "Because putting on the armor takes time and the game doesn't stop", '因为穿护具要花时间，比赛不能停', 'よろいをつけるのに時間がかかって、試合は止まらないから'), 'b': ('Para que el catcher descanse todo el juego', 'So the catcher rests the whole game', '让捕手休息一整场', 'キャッチャーが試合中ずっと休むため'), 'c': ('Para anotar más fácil', 'To score more easily', '为了更容易得分', 'もっと点をとりやすくするため')}), '3': act(('El corredor especial existe en todas las ligas igual', 'The courtesy runner exists the same way in every league', '每个联赛的礼貌跑者规则都一样', 'コーテシーランナーは、どのリーグでも同じ'), ('¡Bien! Solo en algunas ligas.', 'Good! Only in some leagues.', '很好！只有部分联赛才有。', 'いいね！一部のリーグだけ。'), ('Falso: en tu liga puede ser distinto: pregúntale a tu coach.', 'False: it may be different in your league: ask your coach.', '错：你们联赛可能不一样：问问你的教练。', 'まちがい：君のリーグではちがうかもしれない：コーチに聞いてみよう。')), '4': act(('¿Cuándo suele salir el corredor por el catcher?', 'When does the runner for the catcher usually come in?', '替捕手的跑垒员通常什么时候上场？', 'キャッチャーのかわりのランナーは、ふつういつ出る？'), ('¡Eso es! Con dos outs.', "That's it! With two outs.", '对了！两出局时。', 'そのとおり！2アウトで。'), ('Así se viste mientras termina la entrada.', 'That way he gets dressed while the inning ends.', '这样他就能在这一局结束前穿好护具。', 'そうすれば、イニングが終わるまでに用具をつけられる。'), opts={'a': ('Cuando el catcher está en base con dos outs', 'When the catcher is on base with two outs', '捕手在垒上、两出局时', '2アウトでキャッチャーが塁にいるとき'), 'b': ('En cualquier momento del juego', 'At any moment of the game', '比赛的任何时候', '試合のいつでも'), 'c': ('Solo en la práctica', 'Only at practice', '只在练习时', '練習のときだけ')}), '5': act(('Algunas ligas también permiten corredor especial para el pitcher', 'Some leagues also allow a courtesy runner for the pitcher', '有些联赛也允许为投手安排礼貌跑者', 'ピッチャーにもコーテシーランナーをみとめるリーグがある'), ('¡Correcto! Algunas lo permiten.', 'Correct! Some allow it.', '正确！有的联赛允许。', '正解！みとめるリーグもある。'), ('Verdadero: según la liga, pitcher también.', 'True: depending on the league, the pitcher too.', '对：看联赛，投手也可以。', '正しい：リーグによっては、ピッチャーも。')), '6': act(('Si tu liga no tiene corredor especial, ¿qué hace el catcher en base?', "If your league doesn't have a courtesy runner, what does the catcher on base do?", '如果你们联赛没有礼貌跑者，在垒上的捕手怎么办？', '君のリーグにコーテシーランナーがなかったら、塁にいるキャッチャーは？'), ('¡Bien! Como todos.', 'Good! Like everyone.', '很好！和大家一样。', 'いいね！みんなと同じ。'), ('Sin esa regla, cada quien corre su base.', 'Without that rule, everyone runs his own base.', '没有这条规则，就各跑各的垒。', 'そのルールがなければ、自分の塁は自分で走る。'), opts={'a': ('Corre él mismo como cualquier jugador', 'He runs himself like any player', '像其他球员一样自己跑', 'ほかの選手と同じように自分で走る'), 'b': ('No puede batear nunca', 'He can never bat', '他永远不能打击', 'ぜったい打てない'), 'c': ('Se sienta en la base', 'He sits on the base', '他坐在垒包上', '塁にすわる')})})
