exams_v3['18'] = {'1': {'q': ('¿Cuál deslizamiento es el seguro en ligas de niños?', "Which slide is the safe one in kids' leagues?", '儿童联赛里哪种滑垒是安全的？', '子どものリーグで安全なスライディングは？'), 'opts': {'a': ('Pies primero, manos arriba', 'Feet first, hands up', '脚先，双手举起', '足から、手を上げて'), 'b': ('De cabeza', 'Head first', '头先', '頭から'), 'c': ('Buscando chocar al defensor', 'Looking to crash into the fielder', '想撞向防守球员', '守備にぶつかりにいく')}}, '2': {'q': ('¿Puedes deslizarte de cabeza en tu liga?', 'Can you slide head first in your league?', '在你们联赛可以头先滑垒吗？', '君のリーグでは、頭からスライディングしていい？'), 'opts': {'a': ('Lo pregunto a mi coach: cada liga decide', 'I ask my coach: each league decides', '我问我的教练：每个联赛自己决定', 'コーチに聞く：リーグごとに決める'), 'b': ('Siempre se puede', 'You always can', '永远可以', 'いつでもいい'), 'c': ('Nadie lo decide nunca', 'Nobody ever decides it', '从来没人决定', 'だれも決めない')}}, '3': {'q': ('La regla de misericordia sirve para…', 'The mercy rule is for…', '提前结束规则是为了……', 'コールドゲームは……のため'), 'opts': {'a': ('Terminar antes un juego con diferencia enorme, cuidando a los niños', 'Ending a game with a huge difference early, looking after the kids', '让分差很大的比赛提前结束，保护孩子们', '点差がとても大きい試合を早く終わらせて、子どもたちを守る'), 'b': ('Castigar al equipo perdedor', 'Punishing the losing team', '惩罚输的球队', '負けたチームをばっする'), 'c': ('Acortar todos los juegos', 'Shortening every game', '缩短所有比赛', 'すべての試合を短くする')}}, '4': {'q': ('La diferencia de carreras de la regla de misericordia la define…', 'The run difference for the mercy rule is set by…', '提前结束规则的分差由……规定', 'コールドゲームの点差を決めるのは……'), 'opts': {'a': ('Cada liga, según la edad', 'Each league, depending on age', '每个联赛，按年龄', 'リーグごと、年れいで'), 'b': ('Un número fijo igual para todas las ligas', "A fixed number that's the same for every league", '所有联赛都一样的固定数字', 'どのリーグも同じ、決まった数字'), 'c': ('El equipo visitante', 'The visiting team', '客队', 'ビジターチーム')}}, '5': {'q': ('Un juego detenido por rayos que se terminará otro día desde donde quedó es un…', 'A game stopped by lightning that will be finished another day from where it stopped is a…', '因闪电停下、改天从停下处打完的比赛是……', 'かみなりで止まって、別の日に止まったところから終わらせる試合は……'), 'opts': {'a': ('Juego suspendido', 'Suspended game', '中断比赛', 'サスペンデッドゲーム'), 'b': ('Juego perdido para los dos', 'A game lost for both', '两队都输的比赛', '両チームの負け'), 'c': ('Juego de práctica', 'Practice game', '练习赛', '練習試合')}}, '6': {'q': ('Un juego se vuelve oficial cuando…', 'A game becomes official when…', '比赛在……时成为正式比赛', '試合が正式試合になるのは……'), 'opts': {'a': ('Ya se jugó lo que la liga pide para que el resultado valga', 'What the league requires has been played for the result to count', '打完联赛要求的部分、比分有效时', 'リーグが決めた分をやって、結果が有効になったとき'), 'b': ('Llega el primer espectador', 'The first spectator arrives', '第一个观众到场时', '最初のお客さんが来たとき'), 'c': ('Se canta el primer strike', 'The first strike is called', '裁判喊第一个好球时', '最初のストライクがコールされたとき')}}, '7': {'q': ('El juego oficial terminó empatado y tu liga lo permite. ¿Qué sigue?', 'The official game ended tied and your league allows it. What comes next?', '正式比赛打平了，你们联赛也允许。接下来呢？', '正式試合が同点で終わって、君のリーグはみとめている。次は？'), 'opts': {'a': ('Entradas extra (extra innings) para desempatar', 'Extra innings to break the tie', '打延长局（extra innings）来分胜负', '延長戦（extra innings）で決着'), 'b': ('Los dos equipos ganan', 'Both teams win', '两队都赢', '両チームの勝ち'), 'c': ('Se repite el juego otro mes', 'The game is replayed another month', '下个月重新比赛', '別の月にやり直し')}}, '8': {'q': ('Entra un sustituto por un compañero. ¿Qué turno al bate ocupa?', 'A substitute comes in for a teammate. Which batting turn does he take?', '一名替补替队友上场。他打第几棒？', '交代で仲間のかわりに入った。どの打順？'), 'opts': {'a': ('El del jugador que salió', 'That of the player who left', '下场球员的棒次', '出た選手の打順'), 'b': ('El último siempre', 'Always last', '永远最后', 'いつも最後'), 'c': ('El que él prefiera', 'Whichever he prefers', '他喜欢哪个就哪个', '好きな打順')}}, '9': {'q': ('El jugador que salió, ¿puede reingresar?', 'Can the player who left re-enter?', '下场的球员能再次上场吗？', '出た選手は再出場できる？'), 'opts': {'a': ('Depende de la regla de reingreso de mi liga: pregúntale a tu coach', "It depends on my league's re-entry rule: ask your coach", '要看我们联赛的再次上场规定：问问你的教练', 'リーグの再出場の決まりによる：コーチに聞こう'), 'b': ('Siempre puede', 'He always can', '永远可以', 'いつでもできる'), 'c': ('Está prohibido en todas las ligas', "It's banned in every league", '所有联赛都禁止', '全部のリーグで禁止されている')}}, '10': {'q': ('Un jugador bateó en el turno de otro. ¿Cómo se llama ese error?', "A player batted in another player's turn. What is that mistake called?", '一名球员在别人的棒次上打击。这个错误叫什么？', 'ある選手がほかの人の打順で打った。そのミスの名前は？'), 'opts': {'a': ('Batear fuera de turno (batting out of order)', 'Batting out of order', '打错棒次（batting out of order）', '打順まちがい（batting out of order）'), 'b': ('Balk', 'Balk', '投手犯规', 'ボーク'), 'c': ('Foul tip', 'Foul tip', '擦棒球', 'ファウルチップ')}}, '11': {'q': ('El corredor especial (courtesy runner) corre por…', 'The courtesy runner runs for…', '礼貌跑者（courtesy runner）替……跑', 'コーテシーランナー（courtesy runner）が走るのは……'), 'opts': {'a': ('El catcher, para que pueda ponerse la armadura (si la liga lo permite)', 'The catcher, so he can put on his armor (if the league allows it)', '捕手，让他能穿上护具（如果联赛允许）', 'キャッチャー。よろいをつけられるように（リーグがみとめていれば）'), 'b': ('Cualquier jugador cansado, siempre', 'Any tired player, always', '任何累了的球员，永远可以', 'つかれた選手ならだれでも、いつでも'), 'c': ('El bateador que falló', 'The batter who missed', '打失败的击球员', '打てなかったバッター')}}, '12': {'q': ('Si tu liga no permite corredor especial, el catcher en base…', "If your league doesn't allow a courtesy runner, the catcher on base…", '如果你们联赛不允许礼貌跑者，在垒上的捕手……', '君のリーグがコーテシーランナーをみとめていなければ、塁にいるキャッチャーは……'), 'opts': {'a': ('Corre él mismo, como cualquier jugador', 'Runs himself, like any player', '自己跑，和其他球员一样', '自分で走る、ほかの選手と同じように'), 'b': ('No puede seguir jugando', "Can't keep playing", '不能继续比赛', '試合を続けられない'), 'c': ('Lo reemplaza el umpire corriendo', 'The umpire replaces him, running', '裁判替他跑', '審判がかわりに走る')}}}
