lesson('20.1', ('Repaso Novato: el campo y tu turno', 'Rookie review: the field and your turn', '新秀复习：球场和你的打席', 'ルーキーの復習：グラウンドと君の打席'), ('REPASO de los niveles 1 a 4, marcado como repaso: el diamante y sus bases, las posiciones con sus números, strike, bola, foul, ponche y base por bolas, todo mezclado como en un juego real.', 'Final review of levels 1 to 4, marked as review: the diamond and its bases, the positions with their numbers, strike, ball, foul, strikeout and walk, all mixed up like in a real game.', '第1到第4级的总复习，标明是复习：钻石形球场和垒包、各个位置和它们的号码、好球、坏球、界外球、三振和四坏球保送，像真正的比赛一样混在一起。', 'レベル1から4の総復習（復習と書いてあるよ）：ダイヤモンドと塁、ポジションと番号、ストライク、ボール、ファウル、三振、四球。本当の試合みたいに、まぜて出てくる。'), [('Gran repaso, parte uno: vuelve a tu primer día.', 'Big final review, part one: go back to your first day.', '总复习，第一部分：回到你的第一天。', '総復習、パート1：最初の日にもどろう。'), ('El diamante, tus cuatro bases en orden, las posiciones y su número de anotador.', "The diamond, your four bases in order, the positions and their scorer's numbers.", '钻石形球场、按顺序的四个垒、各个位置和它们的记录号码。', 'ダイヤモンド、じゅんばんどおりの4つの塁、ポジションとスコアの番号。'), ('En home: strike si pasa por la zona o le tiras y fallas, bola si va fuera y no le tiras, foul si la desvías fuera.', "At home plate: strike if it goes through the zone or you swing and miss, ball if it's outside and you don't swing, foul if you knock it out of play.", '在本垒：球穿过好球区，或你挥棒落空，是好球；球在外面而你没挥棒，是坏球；你把球打到界外，是界外球。', 'ホームでは：ゾーンを通るか、ふってからぶりならストライク。外れていて、ふらなければボール。外へはじいたらファウル。'), ('Tres strikes y es ponche; el conteo completo te aprieta, y si te golpea el lanzamiento, vas a primera.', "Three strikes and it's a strikeout; a full count puts the pressure on, and if the pitch hits you, you go to first.", '三个好球就是三振；满球数让你很紧张；如果投球打到你，你就上一垒。', 'ストライク3つで三振。フルカウントはドキドキする。投球が体に当たったら、一塁へ。'), ('Nada de esto es nuevo, campeón: es el suelo sobre el que construiste todo lo demás.', "None of this is new, champ: it's the ground you built everything else on.", '这些都不是新的，冠军：它们是你建起其他一切的地基。', 'どれも新しくないよ、チャンピオン：ほかの全部をつみ上げた、土台なんだ。'), ('Dilo con orgullo: ¡esto ya lo dominas!', "Say it with pride: you've already got this down!", '骄傲地说出来：这些我已经掌握了！', 'むねをはって言おう：これはもうバッチリ！')], {'1': act(('REPASO: el lanzamiento pasa por la zona y no le tiras. El umpire canta:', "REVIEW: the pitch goes through the zone and you don't swing. The umpire calls:", '复习：投球穿过好球区，你没挥棒。裁判喊：', '復習：投球がゾーンを通って、ふらなかった。審判のコールは：'), ('¡Eso es! Base dominada.', "That's it! Basics mastered.", '对了！基础掌握了。', 'そのとおり！基本はバッチリ。'), ('Strike en la zona, como el primer día.', 'Strike in the zone, like the first day.', '穿过好球区就是好球，和第一天一样。', 'ゾーンならストライク、最初の日と同じ。'), opts={'a': ('Strike', 'Strike', '好球', 'ストライク'), 'b': ('Bola', 'Ball', '坏球', 'ボール'), 'c': ('Safe', 'Safe', '安全上垒', 'セーフ')}), '2': act(('REPASO: las posiciones se anotan con números, y el campocorto es uno de ellos', 'REVIEW: positions are scored with numbers, and the shortstop is one of them', '复习：每个位置都用号码记录，游击手也是其中之一', '復習：ポジションは番号でスコアをつける。ショートもその1つ'), ('¡Bien! Los números siguen ahí.', 'Good! The numbers are still there.', '很好！号码还在。', 'いいね！番号はちゃんとある。'), ('Cada posición tiene su número.', 'Each position has its number.', '每个位置都有自己的号码。', 'どのポジションにも番号がある。')), '3': act(('REPASO: toca la base que sigue después de segunda en el orden de correr', 'REVIEW: tap the base that comes after second in the running order', '复习：点一下跑垒顺序里二垒之后的垒', '復習：走るじゅんばんで、二塁の次の塁をタッチしよう'), ('¡Correcto! El orden de siempre.', 'Correct! The usual order.', '正确！一直以来的顺序。', '正解！いつものじゅんばん。'), ('Primera, segunda, tercera, home.', 'First, second, third, home.', '一垒、二垒、三垒、本垒。', '一塁、二塁、三塁、ホーム。'), answer=('Tercera base', 'Third base', '三垒', '三塁')), '4': act(('REPASO: cuarto lanzamiento malo fuera de la zona y no le tiraste. ¿Qué canta?', "REVIEW: fourth bad pitch outside the zone and you didn't swing. What's the call?", '复习：第四个坏球在好球区外，你没挥棒。裁判喊什么？', '復習：4つ目の悪い球がゾーンの外、ふらなかった。コールは？'), ('¡Eso es! Caminando a primera.', "That's it! Walking to first.", '对了！走上一垒。', 'そのとおり！歩いて一塁へ。'), ('La paciencia también embasa.', 'Patience gets you on base too.', '耐心也能让你上垒。', 'がまんでも塁に出られる。'), opts={'a': ('¡Base por bolas! A primera', 'Walk! To first', '四坏球保送！上一垒', 'フォアボール！一塁へ'), 'b': ('¡Out!', 'Out!', '出局！', 'アウト！'), 'c': ('¡Foul!', 'Foul!', '界外球！', 'ファウル！')}), '5': act(('REPASO: si el lanzamiento te golpea, tú:', 'REVIEW: if the pitch hits you, you:', '复习：如果投球打到你，你：', '復習：投球が当たったら、君は：'), ('¡Correcto! Primera gratis por el golpe.', 'Correct! A free first base for the hit.', '正确！被打到，免费上一垒。', '正解！当たったから、一塁へ。'), ('Regla de Novato, bien recordada.', 'Rookie rule, well remembered.', '新秀规则，记得真好。', 'ルーキーのルール、よく覚えていたね。'), opts={'a': ('Vas a primera', 'Go to first', '上一垒', '一塁へ行く'), 'b': ('Eres out', 'Are out', '出局', 'アウト'), 'c': ('Sigues bateando siempre', 'Always keep batting', '总是继续打击', 'いつも打ちつづける')}), '6': act(('REPASO: arrastra cada concepto a su canto: pasa por la zona sin swing / cuarta bola fuera de la zona / desviada fuera', 'REVIEW: drag each idea to its call: through the zone with no swing / ball four, outside the zone / knocked out of play', '复习：把每个情况拖到它的判定：穿过好球区没挥棒 / 第四个坏球在好球带外 / 打到界外', '復習：それぞれをコールにドラッグしよう：ゾーンを通ってふらない / 4つ目のボールがゾーンの外 / 外へはじいた'), ('¡Perfecto! Fundamentos firmes.', 'Perfect! Solid fundamentals.', '完美！基础很扎实。', 'パーフェクト！基本がしっかり。'), ('La base de todo está sólida.', 'Your foundation for everything is solid.', '你一切的基础都很稳。', '全部の土台はしっかりしている。'), opts={'zone': ('Pasa por la zona sin swing', 'Through the zone, no swing', '穿过好球区，没挥棒', 'ゾーンを通って、ふらない'), 'fourth': ('Cuarto malo fuera', 'Fourth bad one outside', '第四个坏球在外面', '4つ目の悪い球が外'), 'deflect': ('Desviada fuera', 'Knocked out of play', '打到界外', '外へはじいた'), 'strikeSlot': ('Strike', 'Strike', '好球', 'ストライク'), 'walkSlot': ('Base por bolas', 'Walk', '四坏球保送', 'フォアボール'), 'foulSlot': ('Foul', 'Foul', '界外球', 'ファウル')}, answer=('Strike, base por bolas, foul', 'Strike, walk, foul', '好球、四坏球保送、界外球', 'ストライク、フォアボール、ファウル'))})
map_titles['20.1'] = ('Repaso Novato: el campo y tu turno', 'Rookie review: the field and your turn', '新秀复习：球场和你的打席', 'ルーキーの復習：グラウンドと君の打席')
lesson('20.2', ('Repaso Prospecto: batear, outs y bases', 'Prospect review: hitting, outs and bases', '潜力新星复习：击球、出局和垒', 'プロスペクトの復習：打つ、アウト、塁'), ('REPASO de los niveles 5 a 8, marcado como repaso: hit, doble por regla, outs forzado y por tocado, doble play, pisa y corre y el marcador R/H/E.', 'Final review of levels 5 to 8, marked as review: hit, ground-rule double, force out and tag out, double play, tag up and the R/H/E scoreboard.', '第5到第8级的总复习，标明是复习：安打、规则二垒打、封杀和触杀、双杀、触垒再跑，以及 R/H/E 记分板。', 'レベル5から8の総復習（復習と書いてあるよ）：ヒット、エンタイトルツーベース、フォースアウトとタッチアウト、ダブルプレー、タッチアップ、R/H/E のスコアボード。'), [('Gran repaso, parte dos: la etapa Prospecto.', 'Big final review, part two: the Prospect stage.', '总复习，第二部分：潜力新星阶段。', '総復習、パート2：プロスペクトステージ。'), ('Bateaste tu primer hit y aprendiste que sencillo, doble y triple cuentan bases; que si la bola pica y salta la valla es doble por regla;', "You got your first hit and learned that single, double and triple count bases; that if the ball bounces over the fence it's a ground-rule double;", '你打出了第一支安打，学到一垒打、二垒打和三垒打是按垒数算的；球落地后弹过围栏，是规则二垒打；', '初めてのヒットを打って、シングル、ツーベース、スリーベースは塁の数だと学んだ。ボールがはねてフェンスをこえたら、エンタイトルツーベース。'), ('que el out forzado se hace pisando la base y el otro, tocando al corredor con la bola; que dos outs en una jugada son doble play;', 'that the force out is made by stepping on the base and the tag out by tagging the runner; that two outs in one play is a double play;', '封杀是踩垒，触杀是碰到跑垒员；一次比赛拿到两个出局就是双杀；', 'フォースアウトは塁をふんで、タッチアウトはランナーにタッチしてとる。1つのプレーでアウト2つはダブルプレー。'), ('que el elevado se espera con pisa y corre; y que el marcador cuenta carreras, hits y errores.', 'that on a fly ball you wait and tag up; and that the scoreboard counts runs, hits and errors.', '高飞球要等着触垒再跑；记分板记录得分、安打和失误。', 'フライはタッチアップで待つ。そしてスコアボードは得点、ヒット、エラーを数える。'), ('Todo repaso, nada nuevo: es tu caja de herramientas del medio del camino.', "All review, nothing new: it's the toolbox you built halfway through.", '全是复习，没有新东西：这是你旅程中段的工具箱。', '全部復習、新しいことはなし：道のりのまん中で手に入れた道具箱だ。')], {'1': act(('REPASO: la bola pica en territorio fair y salta la valla. Es:', "REVIEW: the fair ball bounces over the fence. It's a:", '复习：界内球落地后弹过围栏。这是：', '復習：フェアの打球がはねて、フェンスをこえた。これは：'), ('¡Eso es! Dos bases.', "That's it! Two bases.", '对了！两个垒。', 'そのとおり！2つの塁。'), ('Picó y salió: doble por regla.', 'It bounced and went out: ground-rule double.', '弹出去了：规则二垒打。', 'はねて出た：エンタイトルツーベース。'), opts={'a': ('Doble por regla', 'Ground-rule double', '规则二垒打', 'エンタイトルツーベース'), 'b': ('Jonrón', 'Home run', '本垒打', 'ホームラン'), 'c': ('Triple', 'Triple', '三垒打', 'スリーベース')}), '2': act(('REPASO: en el out forzado basta pisar la base con la bola antes que el corredor', "REVIEW: on a force out it's enough to step on the base with the ball before the runner", '复习：封杀时，只要在跑垒员之前拿着球踩到垒就行', '復習：フォースアウトは、ランナーより先にボールを持って塁をふめばいい'), ('¡Bien! Forzado es pisar.', 'Good! Force means stepping.', '很好！封杀就是踩垒。', 'いいね！フォースはふむこと。'), ('Forzado: base pisada a tiempo.', 'Force: base stepped on in time.', '封杀：及时踩到垒。', 'フォース：まにあうように塁をふむ。')), '3': act(('REPASO: en el marcador, las letras R/H/E significan:', 'REVIEW: on the scoreboard, the letters R/H/E mean:', '复习：记分板上的 R/H/E 是指：', '復習：スコアボードの R/H/E の意味は：'), ('¡Correcto! Runs, hits, errors.', 'Correct! Runs, hits, errors.', '正确！Runs、hits、errors。', '正解！Runs、hits、errors。'), ('Así se lee una pizarra.', "That's how you read a scoreboard.", '记分板就是这样看的。', 'スコアボードはこう読む。'), opts={'a': ('Carreras, hits y errores', 'Runs, hits and errors', '得分、安打和失误', '得点、ヒット、エラー'), 'b': ('Recta, curva y slider', 'Fastball, curve and slider', '直球、曲球和滑球', 'ストレート、カーブ、スライダー'), 'c': ('Nada, es decoración', "Nothing, it's decoration", '没意思，只是装饰', '意味なし、かざり')}), '4': act(('REPASO: atrapan tu elevado y tu compañero de tercera arrancó antes de la atrapada; la defensa devuelve la bola a tercera. El umpire canta:', 'REVIEW: they catch your fly ball and your teammate on third took off before the catch; the defense throws the ball back to third. The umpire calls:', '复习：你的高飞球被接住了，三垒的队友在接球前就起跑了；防守方把球传回三垒。裁判喊：', '復習：君のフライがとられて、三塁の仲間はキャッチの前に走り出していた。守備が三塁へボールをもどした。審判のコールは：'), ('¡Out! La espera era la jugada.', 'Out! Waiting was the play.', '出局！等待才是正确的做法。', 'アウト！待つのが正しいプレーだった。'), ('Pisa y corre mal hecho cuesta out.', 'A bad tag-up costs an out.', '触垒再跑做错，就会出局。', 'タッチアップをまちがえると、アウトになる。'), opts={'a': ('¡Out! Salió antes del pisa y corre', 'Out! He left before tagging up', '出局！他在触垒再跑前就离垒了', 'アウト！タッチアップの前に出た'), 'b': ('¡Safe! Carrera', 'Safe! Run', '安全！得分', 'セーフ！得点'), 'c': ('¡Foul!', 'Foul!', '界外球！', 'ファウル！')}), '5': act(('REPASO: toca la base donde se hace el primer out del doble play clásico', 'REVIEW: tap the base where the classic double play gets its first out', '复习：点一下经典双杀中拿到第一个出局的垒', '復習：よくあるダブルプレーで、最初のアウトをとる塁をタッチしよう'), ('¡Bien! Segunda y luego primera.', 'Good! Second and then first.', '很好！先二垒，再一垒。', 'いいね！二塁、それから一塁。'), ('El camino corto del doble play.', 'The short path of the double play.', '双杀的捷径。', 'ダブルプレーの近道。'), answer=('Segunda base', 'Second base', '二垒', '二塁')), '6': act(('REPASO: la llegada del bateador porque la defensa eligió otro out se anota como:', 'REVIEW: the batter reaching base because the defense chose another out is scored as:', '复习：击球员因为防守方选择拿别的出局而上垒，这记为：', '復習：守備がほかのアウトを選んだので、バッターが塁に出た。スコアは：'), ("¡Correcto! Fielder's choice.", "Correct! Fielder's choice.", "正确！野手选择（fielder's choice）。", "正解！フィルダースチョイス（fielder's choice）。"), ('La defensa eligió, tú llegaste.', 'The defense chose, you got there.', '防守方做了选择，你上了垒。', '守備が選んで、君は塁に着いた。'), opts={'a': ('Jugada de selección', "Fielder's choice", '野手选择', 'フィルダースチョイス'), 'b': ('Hit', 'Hit', '安打', 'ヒット'), 'c': ('Error siempre', 'Always an error', '总是失误', 'いつもエラー')})})
map_titles['20.2'] = ('Repaso Prospecto: batear, outs y bases', 'Prospect review: hitting, outs and bases', '潜力新星复习：击球、出局和垒', 'プロスペクトの復習：打つ、アウト、塁')
lesson('20.3', ('Repaso Estrella: reglas especiales y tu brazo', 'Star review: special rules and your arm', '明星复习：特殊规则和你的手臂', 'スターの復習：特別なルールと君のうで'), ('REPASO de los niveles 9 a 12, marcado como repaso: robo, balk, tercer strike caído, infield fly, bola viva y muerta, señales y el cuidado del brazo, sin enseñar ninguna regla nueva.', 'Final review of levels 9 to 12, marked as review: steal, balk, dropped third strike, infield fly, live and dead ball, signs and arm care, without teaching any new rule.', '第9到第12级的总复习，标明是复习：盗垒、投手犯规、不死三振、内野高飞球、活球和死球（比赛停止）、暗号以及保护手臂，不教任何新规则。', 'レベル9から12の総復習（復習と書いてあるよ）：盗塁、ボーク、振り逃げ、インフィールドフライ、ボールインプレイとボールデッド、サイン、うでを大事にすること。新しいルールはなし。'), [('Gran repaso, parte tres: la etapa Estrella.', 'Big final review, part three: the Star stage.', '总复习，第三部分：明星阶段。', '総復習、パート3：スターステージ。'), ('Robaste tu primera base mirando a la liga y a tu coach; el balk adelantó corredores, el tercer strike caído te dio una corrida inesperada a primera, y el infield fly protegió a los corredores del engaño.', "You stole your first base after checking your league's rules with your coach; the balk moved runners up, the dropped third strike gave you a surprise run to first, and the infield fly protected the runners from being tricked.", '你看着联赛规定和教练，完成了第一次盗垒；投手犯规让跑垒员前进，不死三振让你意外地跑上一垒，内野高飞球规则保护跑垒员不被骗。', 'リーグとコーチを見て、初めての盗塁をした。ボークでランナーが進み、振り逃げで思いがけず一塁へ走り、インフィールドフライはランナーをだまし打ちから守った。'), ('Aprendiste bola viva y bola muerta, a cubrir y respaldar, y la lección que vale oro: tu brazo se cuida, con recta y cambio primero, y dolor significa parar y avisar.', 'You learned live ball and dead ball, covering and backing up, and the lesson worth gold: your arm is looked after, with fastball and changeup first, and pain means stop and tell.', '你学会了活球和死球（比赛停止）、补位和补防，还有最宝贵的一课：要保护手臂，先练直球和变速球，疼痛就要停下来告诉大人。', 'ボールインプレイとボールデッド、カバーとバックアップを学んだ。そして金のレッスン：うでは大事にする。まずストレートとチェンジアップ。いたいときは、やめて知らせる。'), ('Todo eso es repaso: hoy solo confirmas que sigue siendo tuyo.', "All of that is review: today you're just confirming it's still yours.", '这些全是复习：今天你只是确认它们还是你的。', 'それは全部復習：今日は、まだ自分のものだとたしかめるだけ。')], {'1': act(('REPASO: el pitcher hace un balk con corredor en segunda. El corredor:', 'REVIEW: the pitcher commits a balk with a runner on second. The runner:', '复习：二垒有人时投手犯规。跑垒员：', '復習：二塁にランナーがいるとき、ピッチャーがボーク。ランナーは：'), ('¡Correcto! Una base por el balk.', 'Correct! One base for the balk.', '正确！投手犯规，进一个垒。', '正解！ボークで1つ進む。'), ('Balk canta, corredor avanza.', 'Balk called, runner moves up.', '判投手犯规，跑垒员前进。', 'ボークのコールで、ランナーが進む。'), opts={'a': ('Avanza una base, a tercera', 'Moves up one base, to third', '前进一个垒，到三垒', '1つ進んで、三塁へ'), 'b': ('Vuelve a primera', 'Goes back to first', '回到一垒', '一塁にもどる'), 'c': ('Sale del juego', 'Leaves the game', '离开比赛', '試合から出る')}), '2': act(('REPASO: con el tercer strike caído y primera libre, el bateador puede correr a primera', 'REVIEW: on a dropped third strike with first base open, the batter can run to first', '复习：不死三振、一垒没人时，击球员可以跑向一垒', '復習：振り逃げで一塁があいていれば、バッターは一塁へ走れる'), ('¡Bien! Correr a primera ahí es legal.', 'Good! Running to first there is legal.', '很好！那时跑向一垒是合规的。', 'いいね！そこで一塁へ走るのはルールどおり。'), ('Strike tres caído: a correr.', 'Strike three dropped: run.', '第三个好球没接住：快跑。', 'ストライク3つ目を落とした：走れ。')), '3': act(('REPASO: la bola queda muerta cuando:', 'REVIEW: the ball becomes dead when:', '复习：什么时候是死球（比赛停止）？', '復習：ボールデッドになるのは：'), ('¡Eso es! Bola muerta, todo quieto.', "That's it! Dead ball, everything still.", '对了！死球（比赛停止），一切都停下来。', 'そのとおり！ボールデッド、全部ストップ。'), ('Con bola muerta nadie avanza.', 'With a dead ball, nobody moves up.', '死球（比赛停止）时，没有人能前进。', 'ボールデッドのとき、だれも進めない。'), opts={'a': ('El umpire detiene el juego, por ejemplo en un foul a las gradas o un tiempo pedido', 'The umpire stops play, for example on a foul into the stands or a time-out called', '裁判停止比赛，比如界外球飞进看台，或有人叫暂停', '審判がプレーを止めたとき。たとえば、スタンドへのファウルや、タイムがかかったとき'), 'b': ('El pitcher respira', 'The pitcher breathes', '投手呼吸', 'ピッチャーが息をする'), 'c': ('El público aplaude', 'The crowd claps', '观众鼓掌', 'お客さんが拍手する')}), '4': act(('REPASO: elevado fácil al cuadro con primera y segunda ocupadas y menos de dos outs, cantado desde el aire. El umpire ya cantó:', 'REVIEW: easy pop-up in the infield with first and second occupied and fewer than two outs, called from the air. The umpire already called:', '复习：一垒二垒有人、不到两出局，内野轻松高飞球，球还在空中就判了。裁判已经喊了：', '復習：一塁と二塁にランナー、2アウトより少ない、内野へのかんたんなフライ。ボールが空中にあるうちに、審判はもうコールした：'), ('¡Correcto! Regla de protección.', 'Correct! A protection rule.', '正确！这是保护规则。', '正解！守るためのルール。'), ('Los corredores quedan a su riesgo, protegidos del engaño.', 'The runners advance at their own risk, protected from the trick.', '跑垒员自己承担风险，但不会被骗。', 'ランナーは自分の判断で進む。だまし打ちからは守られている。'), opts={'a': ('¡Infield fly! Bateador out', 'Infield fly! Batter out', '内野高飞球！击球员出局', 'インフィールドフライ！バッターアウト'), 'b': ('¡Jonrón!', 'Home run!', '本垒打！', 'ホームラン！'), 'c': ('¡Balk!', 'Balk!', '投手犯规！', 'ボーク！')}), '5': act(('REPASO: la frase completa del brazo sano es:', 'REVIEW: the full healthy-arm phrase is:', '复习：保护手臂的完整口诀是：', '復習：うでを守る言葉、ぜんぶ言うと：'), ('¡Eso es! Oro puro, campeón.', "That's it! Pure gold, champ.", '对了！真是金玉良言，冠军。', 'そのとおり！金の言葉だ、チャンピオン。'), ('Esa frase te cuida para siempre.', 'That phrase looks after you forever.', '这句话会永远保护你。', 'その言葉がずっと君を守る。'), opts={'a': ('Si duele, paro y aviso a un adulto', 'If it hurts, I stop and tell an adult', '如果痛，我就停下来告诉大人', 'いたかったら、やめて大人に知らせる'), 'b': ('Aguanto callado toda la temporada', 'I put up with it quietly all season', '我整个赛季都默默忍着', 'シーズン中ずっと、だまってがまんする'), 'c': ('Lanzo curvas para que duela menos', 'I throw curves so it hurts less', '我投曲球，这样就没那么痛', 'カーブを投げれば、いたみが少ない')}), '6': act(('REPASO: toca el bullpen, el lugar donde calienta el relevista', 'REVIEW: tap the bullpen, the place where the reliever warms up', '复习：点一下牛棚，替补投手热身的地方', '復習：ブルペンをタッチしよう。リリーフがウォームアップする場所'), ('¡Bien! Ahí se prepara el relevo.', 'Good! The reliever gets ready there.', '很好！替补投手在那里准备。', 'いいね！そこでリリーフがじゅんびする。'), ('El relevo calienta en su corral.', 'The reliever warms up in his pen.', '替补投手在他的“棚”里热身。', 'リリーフは自分の場所でウォームアップする。'), answer=('El bullpen', 'The bullpen', '牛棚', 'ブルペン'))})
map_titles['20.3'] = ('Repaso Estrella: reglas especiales y tu brazo', 'Star review: special rules and your arm', '明星复习：特殊规则和你的手臂', 'スターの復習：特別なルールと君のうで')
lesson('20.4', ('Repaso Leyenda y Salón: detalles, orden y carácter', 'Legend and Hall review: details, order and character', '传奇和名人堂复习：细节、顺序和品格', 'レジェンドと殿堂の復習：細かいこと、順番、人がら'), ('REPASO de los niveles 13 a 19, marcado como repaso: foul tip, swing a medias, tarjeta de alineación, prioridad en el elevado, seguridad ante rayos, estrategia de primera y tercera y liderazgo.', 'Final review of levels 13 to 19, marked as review: foul tip, checked swing, lineup card, priority on the fly ball, lightning safety, first-and-third strategy and leadership.', '第13到第19级的总复习，标明是复习：擦棒球、半挥棒、出场名单卡、高飞球的优先权、打雷时的安全、一三垒有人的战术和领导力。', 'レベル13から19の総復習（復習と書いてあるよ）：ファウルチップ、ハーフスイング、メンバー表、フライの優先順位、かみなりのときの安全、一三塁の作戦、リーダーシップ。'), [('Gran repaso, parte cuatro: lo más fino del camino.', 'Big final review, part four: the finest details of the path.', '总复习，第四部分：旅程中最精细的部分。', '総復習、パート4：道のりのいちばん細かいところ。'), ('El foul tip que el catcher atrapa y cuenta como strike; la tarjeta de alineación que ordena cada turno; el jardinero que pide el elevado con un «¡mía!» que evita choques;', 'The foul tip the catcher catches that counts as a strike; the lineup card that orders every turn; the outfielder who calls for the fly ball with a "Mine!" that prevents crashes;', '捕手接住、算作好球的擦棒球；排好每个棒次的出场名单卡；外野手喊一声“我的！”来要高飞球，避免相撞；', 'キャッチャーがとって、ストライクになるファウルチップ。打順を決めるメンバー表。「オーライ！」とフライを知らせて、ぶつかるのをふせぐ外野手。'), ('el trueno que vacía el campo sin discusión; el pitcher que piensa su recta y su cambio antes de lanzar; y el capitán que manda con el ejemplo.', 'the thunder that clears the field with no arguing; the pitcher who plans his fastball and changeup before throwing; and the captain who leads by example.', '一打雷就毫不争论地清空球场；投球前先想好直球和变速球的投手；还有用榜样带领大家的队长。', 'もんくなしでグラウンドを空にするかみなり。投げる前にストレートとチェンジアップを考えるピッチャー。そして手本でみちびくキャプテン。'), ('Todo esto ya lo viviste en Leyenda y en Salón de la Fama: este repaso solo junta las piezas antes del examen final de toda la app.', 'You already lived all this in Legend and Hall of Fame: this review just puts the pieces together before the final exam of the whole app.', '这些你在传奇和名人堂阶段都经历过了：这次复习只是在整个应用的期末考试前，把拼图拼在一起。', 'これは全部、レジェンドと殿堂でもう体験した：この復習は、アプリ全部の最終テストの前に、ピースを合わせるだけ。')], {'1': act(('REPASO: la bola roza el bate y el catcher la atrapa directo. Es foul tip y cuenta como:', "REVIEW: the ball grazes the bat and the catcher catches it directly. It's a foul tip and it counts as:", '复习：球擦过球棒，捕手直接接住。这是擦棒球，算作：', '復習：ボールがバットにかすって、キャッチャーがそのままとった。ファウルチップで、数えるのは：'), ('¡Correcto! Strike y bola viva.', 'Correct! Strike and live ball.', '正确！好球，而且是活球。', '正解！ストライクで、ボールインプレイ。'), ('El roce atrapado no es foul común.', "A caught graze isn't a regular foul.", '被接住的擦棒球不是普通界外球。', 'とったかすり球は、ふつうのファウルじゃない。'), opts={'a': ('Strike', 'Strike', '好球', 'ストライク'), 'b': ('Bola', 'Ball', '坏球', 'ボール'), 'c': ('Out del catcher', "Catcher's out", '捕手出局', 'キャッチャーのアウト')}), '2': act(('REPASO: la tarjeta de alineación la guarda el umpire y manda el orden al bate', 'REVIEW: the umpire keeps the lineup card and it sets the batting order', '复习：裁判保存出场名单卡，它决定打击顺序', '復習：メンバー表は審判が持っていて、打順を決める'), ('¡Bien! La tarjeta manda.', 'Good! The card rules.', '很好！名单卡说了算。', 'いいね！メンバー表が決める。'), ('Orden escrito, juego claro.', 'Written order, clear game.', '写好的顺序，清楚的比赛。', '書いた順番で、わかりやすい試合。')), '3': act(('REPASO: truena durante tu turno al bate. Lo correcto es:', 'REVIEW: it thunders during your at-bat. The right thing is:', '复习：你打击时打雷了。正确的做法是：', '復習：君の打席中にかみなりが鳴った。正しいのは：'), ('¡Eso es! Seguridad sin negociación.', "That's it! Safety, no negotiating.", '对了！安全第一，没得商量。', 'そのとおり！安全は話し合いなし。'), ('Ningún turno vale más que tu vida.', 'No at-bat is worth more than your life.', '没有哪个打席比你的生命更重要。', '命より大事な打席はない。'), opts={'a': ('Dejar el turno y salir del campo al refugio', 'Leave the at-bat and go off the field to shelter', '离开打席，离开球场去避难', '打席をやめて、グラウンドから出てひなんする'), 'b': ('Terminar el turno rápido', 'Finish the at-bat quickly', '快点打完这个打席', '打席を早く終わらせる'), 'c': ('Seguir si el rayo fue lejos', 'Keep going if the lightning was far away', '如果闪电很远就继续', 'かみなりが遠ければ続ける')}), '4': act(('REPASO: dos defensores van por el mismo elevado, uno grita «¡mía!» y atrapa. El umpire:', 'REVIEW: two fielders go for the same fly ball, one yells "Mine!" and catches it. The umpire:', '复习：两个防守球员去接同一个高飞球，一个喊“我的！”并接住了。裁判：', '復習：二人の守備が同じフライを追って、一人が「オーライ！」と言ってとった。審判は：'), ('¡Correcto! Gritar «¡mía!» es legal y sano.', 'Correct! Yelling "Mine!" is legal and healthy.', '正确！喊“我的！”是合规的，也很好。', '正解！「オーライ！」はルールどおりで、いいこと。'), ('Pedir la bola protege al equipo.', 'Calling for the ball protects the team.', '喊着要球能保护球队。', 'ボールを呼ぶとチームを守れる。'), opts={'a': ('No canta nada especial: jugada normal con buena comunicación', 'Calls nothing special: a normal play with good communication', '不做特别判定：沟通良好的正常比赛', '特別なコールはなし：声をかけ合ったふつうのプレー'), 'b': ('Canta falta por gritar', 'Calls a foul for yelling', '因为喊叫判犯规', 'さけんだので反則をコール'), 'c': ('Detiene el juego', 'Stops the game', '停止比赛', '試合を止める')}), '5': act(('REPASO: con corredores en primera y tercera, toca la base del corredor que puede sellar un walk-off si anota', 'REVIEW: with runners on first and third, tap the base of the runner who can seal a walk-off if he scores', '复习：一垒和三垒有人，点一下得分后就能完成再见安打的跑垒员所在的垒', '復習：一塁と三塁にランナー。サヨナラヒットで帰ってくれば勝ちになるランナーの塁をタッチしよう'), ('¡Bien! Su carrera puede ser la que gana.', 'Good! His run can be the winning one.', '很好！他的得分可能就是赢球的一分。', 'いいね！そのランナーの得点で勝てる。'), ('El de tercera es la carrera del cierre.', 'The runner on third is the closing run.', '三垒的跑垒员就是结束比赛的那一分。', '三塁のランナーが、試合を決める点。'), answer=('Tercera base', 'Third base', '三垒', '三塁')), '6': act(('REPASO: el capitán lidera sobre todo con:', 'REVIEW: the captain leads above all with:', '复习：队长最主要靠什么带领大家：', '復習：キャプテンがいちばんみちびくのは：'), ('¡Correcto! Ejemplo primero, siempre.', 'Correct! Example first, always.', '正确！永远是榜样第一。', '正解！いつも手本が先。'), ('La C de capitán se gana con actos.', "The captain's C is earned with actions.", '队长的“C”要靠行动赢得。', 'キャプテンの「C」は行動で手に入れるんだ。'), opts={'a': ('Su ejemplo', 'His example', '他的榜样', '自分の手本'), 'b': ('Sus discursos largos', 'His long speeches', '他的长篇大论', '長いスピーチ'), 'c': ('Sus castigos', 'His punishments', '他的惩罚', 'ばつ')})})
